SELECT to_regclass('public.subscribers') IS NOT NULL AND (SELECT count(*) = 6 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'subscribers' AND column_name IN ('source_detail', 'consent_text', 'status', 'is_active', 'unsubscribe_token', 'unsubscribed_at')) AS contacts, to_regclass('public.email_segments') IS NOT NULL AS segments, (SELECT count(*) = 5 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_campaigns' AND column_name IN ('last_error', 'completed_at', 'send_idempotency_key', 'track_opens', 'rendered_html')) AS campaigns, (SELECT count(*) = 3 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'campaign_recipients' AND column_name IN ('attempts', 'next_attempt_at', 'claimed_at')) AS recipients, (SELECT count(*) = 2 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_events' AND column_name IN ('email', 'recipient_id')) AS events, to_regprocedure('public.increment_email_usage(uuid, integer)') IS NOT NULL AS usage_count, to_regclass('public.email_flows') IS NOT NULL AND to_regclass('public.scheduled_flow_emails') IS NOT NULL AS automations, to_regclass('public.email_flow_runs') IS NOT NULL AND to_regclass('public.email_flow_jobs') IS NOT NULL AND to_regclass('public.email_flow_sends') IS NOT NULL AS engine_tables, to_regprocedure('public.enroll_email_flow(uuid, uuid, text, text, text, integer, text, text, jsonb, jsonb)') IS NOT NULL AND to_regprocedure('public.claim_email_flow_jobs(text, integer, integer)') IS NOT NULL AND to_regprocedure('public.email_flow_health()') IS NOT NULL AND to_regprocedure('public.email_flow_step_stats(uuid)') IS NOT NULL AND to_regprocedure('public.email_flow_totals()') IS NOT NULL AS engine_functions, to_regclass('public.checkout_starts') IS NOT NULL AS checkout_reminder, to_regclass('public.site_contact_messages') IS NOT NULL AS contact_messages, to_regclass('public.subscribers_creator_email_lower') IS NOT NULL AS one_contact_per_address, NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'subscribers' AND cmd = 'INSERT' AND roles @> ARRAY['public']::name[] AND with_check = 'true') AS no_open_signup_policy;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('46', '46_email_automations_complete.sql', 'cd34414eda36197b71849fe77ee2ea78ef590adca10fdf72e6693d8788231a5a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 47_products_archived_never_published.sql
/* An archived product is never also published. A product has a status (draft, published, archived) and, from an older migration, an archived flag; every page that shows or sells a product asks for status = 'published', so the two have to agree or an archived product stays on sale. Archive writes both and publishing clears the flag, but that was two writes from the browser, and one that failed left a product published and archived at once: on the creator's page and in checkout, while the Products list said Archived. A trigger keeps them in step from now on: status archived sets the flag; publishing a product (its status changed to published) clears the flag; setting the flag on a published product archives it. Then one pass over the products that are published and flagged now (the same pass part 08 made; there were none last time). Changes no other rows. Skips itself where products has no archived column. Run after 08. Until it runs, the app writes both marks as before and reads the flag where it can. */
CREATE OR REPLACE FUNCTION public.products_keep_archive_in_step() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$ BEGIN IF NEW.status = 'archived' THEN NEW.archived := true; ELSIF NEW.archived IS TRUE AND NEW.status = 'published' THEN IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM 'published' THEN NEW.archived := false; ELSE NEW.status := 'archived'; END IF; END IF; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.products_keep_archive_in_step() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'archived') THEN RAISE NOTICE 'products has no archived column here: the trigger is not needed and was not made'; RETURN; END IF; DROP TRIGGER IF EXISTS products_keep_archive_in_step ON public.products; CREATE TRIGGER products_keep_archive_in_step BEFORE INSERT OR UPDATE OF status, archived ON public.products FOR EACH ROW EXECUTE FUNCTION public.products_keep_archive_in_step(); UPDATE public.products SET status = 'archived' WHERE archived IS TRUE AND status = 'published'; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('47', '47_products_archived_never_published.sql', 'c6c298400031dafae3ec7723a091fcd79eab380bcc5ae6355f28ac18e214494a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 48_one_review_per_buyer.sql
/* One review per buyer per product, kept by the database. The review route already refuses a second review (a 409, "You already reviewed this product."), but it checks and then writes, so two presses at the same moment could both pass the check and leave two reviews; with this unique index the second write fails and the route answers the same 409. Makes the index only when no buyer already has two reviews of one product; otherwise it skips itself with a warning that names the query to see them, and changes nothing. Deletes no row, changes no row. Nothing where there is no reviews table. Needs nothing else. Until it runs, reviews work as before. */
DO $$ BEGIN IF to_regclass('public.reviews') IS NULL THEN RAISE NOTICE 'part 48: there is no reviews table, nothing to do.'; ELSIF EXISTS (SELECT 1 FROM public.reviews GROUP BY buyer_id, product_id HAVING count(*) > 1) THEN RAISE WARNING 'part 48 skipped: a buyer has two reviews of one product, so the one review per buyer index was not made. See them with: select buyer_id, product_id, count(*) from public.reviews group by 1, 2 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS reviews_one_per_buyer_product ON public.reviews (buyer_id, product_id); END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('48', '48_one_review_per_buyer.sql', '3f37780bf93f8e7d0a861a5ba0bd7fe64ac72d2082ac47ec60965447b36db891') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 49_payouts_table.sql
/* Payouts: the table every payout the creator is paid is written to. The Stripe webhook's payout events, Cash out and Withdraw all upsert into public.payouts (on stripe_payout_id), and the order timeline, the notifications and the admin console read it; production has no such table, so every one of those writes has been failing quietly (the upsert returns an error the code does not throw) and the admin console logs PGRST205. The table was written on 19 February (supabase/migrations/20260219_payouts_table.sql) and never ran. Same columns as that file, which match the upserts. Creators read their own rows; only the server writes. Adds one table, two indexes, a read policy and an updated_at trigger; changes no rows. Needs creators. */
CREATE TABLE IF NOT EXISTS public.payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, stripe_payout_id text NOT NULL UNIQUE, amount_cents integer NOT NULL, currency text NOT NULL DEFAULT 'usd', status text NOT NULL DEFAULT 'pending', arrival_date timestamptz, description text, destination text, method text, failure_code text, failure_message text, stripe_created timestamptz, webhook_received_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payouts_creator_id_idx ON public.payouts (creator_id);
CREATE INDEX IF NOT EXISTS payouts_creator_created_idx ON public.payouts (creator_id, created_at DESC);
ALTER TABLE public.payouts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "creators can view own payouts" ON public.payouts;
CREATE POLICY "creators can view own payouts" ON public.payouts FOR SELECT USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
REVOKE INSERT, UPDATE, DELETE ON public.payouts FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.update_payouts_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS set_payouts_updated_at ON public.payouts;
CREATE TRIGGER set_payouts_updated_at BEFORE UPDATE ON public.payouts FOR EACH ROW EXECUTE FUNCTION public.update_payouts_updated_at();
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('49', '49_payouts_table.sql', '7235c012da6902540a0a304d2d8a189788745b0109590909ec51e650110257ab') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 50_signup_abuse.sql
/* Sign up protection: the scores the sign up guard writes and the admin console reads. app/api/auth/signup-guard and the before-user-created hook record each attempt in public.signup_attempts and mark suspect accounts on profiles.spam_score and profiles.spam_state; the admin console's accounts and creator views select spam_state, and production has no such column (the console logs 42703 "column profiles.spam_state does not exist"). Written on 15 August (supabase/migrations/20260815_signup_abuse.sql) and never ran. Adds one server only table and its prune function, two nullable columns on profiles with a check on the state's three values and a partial index, and the storefront_indexability view where products and creators exist. Changes no rows. */
CREATE TABLE IF NOT EXISTS public.signup_attempts (id bigserial PRIMARY KEY, ip_hash text NOT NULL, email_domain text, handle text, score integer NOT NULL DEFAULT 0, verdict text NOT NULL DEFAULT 'allowed', reasons text[], created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS signup_attempts_ip_recent_idx ON public.signup_attempts (ip_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS signup_attempts_created_idx ON public.signup_attempts (created_at DESC);
ALTER TABLE public.signup_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.signup_attempts FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.prune_signup_attempts() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ DELETE FROM public.signup_attempts WHERE created_at < now() - interval '30 days'; $$;
REVOKE EXECUTE ON FUNCTION public.prune_signup_attempts() FROM PUBLIC, anon, authenticated;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS spam_score integer;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS spam_state text;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_spam_state_check') THEN ALTER TABLE public.profiles ADD CONSTRAINT profiles_spam_state_check CHECK (spam_state IS NULL OR spam_state IN ('clear', 'suspect', 'confirmed')); END IF; END $$;
CREATE INDEX IF NOT EXISTS profiles_spam_state_idx ON public.profiles (spam_state) WHERE spam_state IS NOT NULL;
DO $$ BEGIN IF to_regclass('public.products') IS NULL OR to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'storefront_indexability skipped: public.products or public.creators is missing'; RETURN; END IF; EXECUTE 'CREATE OR REPLACE VIEW public.storefront_indexability AS SELECT p.id, p.username, p.created_at, p.spam_score, p.spam_state, coalesce(pub.published_count, 0) AS published_products, (coalesce(pub.published_count, 0) > 0 AND coalesce(p.spam_state, '''') <> ''confirmed'') AS indexable FROM public.profiles p LEFT JOIN LATERAL (SELECT count(*) AS published_count FROM public.products pr JOIN public.creators c ON c.id = pr.creator_id WHERE c.user_id = p.id AND pr.status = ''published'') pub ON true WHERE p.username IS NOT NULL'; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('50', '50_signup_abuse.sql', '9b2adab74bb76e44d5df295d6a29d4b0ed7152464d9cac3d77e3a9ac3f112fe3') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 51_email_flows_trigger_rules.sql
/* Automations: "Could not create the flow" (Postgres 23514, a check refused the row). The live email_flows table carries a check on trigger_type or status that no file in this repository made, from before the First order and Leaves checkout triggers existed, so choosing either template was refused. This drops every check on email_flows that names trigger_type or status, whatever it is called, and adds the two the app writes against: the four triggers (lib/automations/flow-model.ts TriggerType) plus the two older names rows may still carry, and draft, active or paused. NOT VALID: a new or changed row is checked, rows already there are left alone. Safe to run again. */
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND contype = 'c' AND (pg_get_constraintdef(oid) ILIKE '%trigger_type%' OR pg_get_constraintdef(oid) ILIKE '%status%') LOOP EXECUTE format('ALTER TABLE public.email_flows DROP CONSTRAINT %I', c.conname); RAISE NOTICE 'email_flows: dropped the old check %', c.conname; END LOOP; END $$;
ALTER TABLE public.email_flows ADD CONSTRAINT email_flows_trigger_type_check CHECK (trigger_type IN ('new_subscriber', 'purchase', 'first_purchase', 'abandoned_checkout', 'tag_added', 'manual')) NOT VALID;
ALTER TABLE public.email_flows ADD CONSTRAINT email_flows_status_check CHECK (status IN ('draft', 'active', 'paused')) NOT VALID;
NOTIFY pgrst, 'reload schema';
/* One row: both read true, and the old check is gone. */
SELECT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND conname = 'email_flows_trigger_type_check' AND pg_get_constraintdef(oid) ILIKE '%abandoned_checkout%' AND pg_get_constraintdef(oid) ILIKE '%first_purchase%') AS triggers_allowed, EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND conname = 'email_flows_status_check') AS statuses_allowed, (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND contype = 'c') AS checks_on_email_flows;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('51', '51_email_flows_trigger_rules.sql', 'c5774898a2e913bb687f426dd5c3fbea92c46ce1693ffea7323ae9fb3ddad829') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 52_reviews_replies_reports_guests.sql
/* Reviews, complete: what the review card on the receipt and in the library, the product page, the seller's Reviews list in the app and the Storelib admin read and write. A review can be left from a receipt link without an account (it then belongs to its order and carries the name the buyer gave), so buyer_id may be empty when order_id is not, and one order has at most one review. A review is published or hidden: a seller who reports one hides it until Storelib looks (review_reports, server only, one open report a review), and a seller answers a review once, in public (seller_reply). The product and creator ratings (reviews_count, reviews_average) count published reviews only, kept by the trigger on every write and counted again once now. The public API reads published reviews and a buyer their own; nobody writes reviews from the browser any more, since every write goes through the server, which checks the purchase. A review request email's unsubscribe is its own suppression scope, so turning those off leaves every other email as it was. Changes no review. Makes the one review an order index only when no order already has two reviews; otherwise it skips that index with a warning naming the query to see them. Needs nothing else; the suppression scope is added only where part 40 ran. Until it runs, reviews post and show as before, reported reviews stay hidden only in the app's own reads, and a guest cannot post without signing in. */
CREATE TABLE IF NOT EXISTS public.reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, buyer_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL, rating integer NOT NULL CHECK (rating >= 1 AND rating <= 5), content text NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now() );
ALTER TABLE public.reviews ALTER COLUMN buyer_id DROP NOT NULL;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS reviewer_name text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'published';
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS hidden_at timestamptz;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS hidden_reason text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS edited_at timestamptz;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS seller_reply text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS seller_reply_at timestamptz;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_status_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_status_check CHECK (status IN ('published', 'hidden')) NOT VALID;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_buyer_or_order_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_buyer_or_order_check CHECK (buyer_id IS NOT NULL OR order_id IS NOT NULL) NOT VALID;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_lengths_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_lengths_check CHECK (char_length(coalesce(seller_reply, '')) <= 1000 AND char_length(coalesce(reviewer_name, '')) <= 80) NOT VALID;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.reviews WHERE order_id IS NOT NULL GROUP BY order_id HAVING count(*) > 1) THEN RAISE WARNING 'part 52: an order has two reviews, so the one review an order index was not made. Everything else ran. See them with: select order_id, count(*) from public.reviews where order_id is not null group by 1 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS reviews_one_per_order ON public.reviews (order_id) WHERE order_id IS NOT NULL; END IF; END $$;
CREATE INDEX IF NOT EXISTS reviews_product_published ON public.reviews (product_id, created_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS reviews_creator_recent ON public.reviews (creator_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.review_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES public.reviews(id) ON DELETE CASCADE, creator_id uuid, reported_by uuid, reason text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolution text, resolved_by text );
ALTER TABLE public.review_reports DROP CONSTRAINT IF EXISTS review_reports_values_check;
ALTER TABLE public.review_reports ADD CONSTRAINT review_reports_values_check CHECK (reason IN ('abusive', 'spam', 'not_a_buyer', 'personal_info', 'off_topic', 'other') AND (resolution IS NULL OR resolution IN ('restored', 'kept_hidden')) AND char_length(coalesce(note, '')) <= 500) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS review_reports_one_open ON public.review_reports (review_id) WHERE resolved_at IS NULL;
CREATE INDEX IF NOT EXISTS review_reports_open ON public.review_reports (created_at DESC) WHERE resolved_at IS NULL;
ALTER TABLE public.review_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_reports FROM anon, authenticated;
GRANT ALL ON public.review_reports TO service_role;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS reviews_count integer DEFAULT 0;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS reviews_average numeric(2,1) DEFAULT 0;
ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS reviews_count integer DEFAULT 0;
ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS reviews_average numeric(2,1) DEFAULT 0;
CREATE OR REPLACE FUNCTION public.update_product_review_stats() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_old_product uuid; v_new_product uuid; v_old_creator uuid; v_new_creator uuid; v_id uuid; BEGIN IF TG_OP <> 'INSERT' THEN v_old_product := OLD.product_id; v_old_creator := OLD.creator_id; END IF; IF TG_OP <> 'DELETE' THEN v_new_product := NEW.product_id; v_new_creator := NEW.creator_id; END IF; FOREACH v_id IN ARRAY ARRAY[v_old_product, CASE WHEN v_new_product IS DISTINCT FROM v_old_product THEN v_new_product END] LOOP IF v_id IS NOT NULL THEN UPDATE public.products SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.product_id = v_id AND r.status = 'published'), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.product_id = v_id AND r.status = 'published') WHERE id = v_id; END IF; END LOOP; FOREACH v_id IN ARRAY ARRAY[v_old_creator, CASE WHEN v_new_creator IS DISTINCT FROM v_old_creator THEN v_new_creator END] LOOP IF v_id IS NOT NULL THEN UPDATE public.creators SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.creator_id = v_id AND r.status = 'published'), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.creator_id = v_id AND r.status = 'published') WHERE id = v_id; END IF; END LOOP; RETURN NULL; END $fn$;
REVOKE ALL ON FUNCTION public.update_product_review_stats() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS trigger_update_product_review_stats ON public.reviews;
CREATE TRIGGER trigger_update_product_review_stats AFTER INSERT OR UPDATE OR DELETE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.update_product_review_stats();
UPDATE public.products p SET reviews_count = s.n, reviews_average = s.a FROM (SELECT pr.id, count(r.id) FILTER (WHERE r.status = 'published')::integer AS n, coalesce(round(avg(r.rating) FILTER (WHERE r.status = 'published'), 1), 0) AS a FROM public.products pr LEFT JOIN public.reviews r ON r.product_id = pr.id GROUP BY pr.id) s WHERE p.id = s.id AND (coalesce(p.reviews_count, 0) <> s.n OR coalesce(p.reviews_average, 0) <> s.a);
UPDATE public.creators c SET reviews_count = s.n, reviews_average = s.a FROM (SELECT cr.id, count(r.id) FILTER (WHERE r.status = 'published')::integer AS n, coalesce(round(avg(r.rating) FILTER (WHERE r.status = 'published'), 1), 0) AS a FROM public.creators cr LEFT JOIN public.reviews r ON r.creator_id = cr.id GROUP BY cr.id) s WHERE c.id = s.id AND (coalesce(c.reviews_count, 0) <> s.n OR coalesce(c.reviews_average, 0) <> s.a);
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Reviews are viewable by everyone" ON public.reviews;
DROP POLICY IF EXISTS "Published reviews are public" ON public.reviews;
CREATE POLICY "Published reviews are public" ON public.reviews FOR SELECT USING (status = 'published' OR buyer_id = (select auth.uid()));
DROP POLICY IF EXISTS "Buyers can insert reviews for purchased products" ON public.reviews;
DROP POLICY IF EXISTS "Buyers can update their own reviews" ON public.reviews;
DROP POLICY IF EXISTS "Buyers can delete their own reviews" ON public.reviews;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.reviews FROM anon, authenticated;
GRANT ALL ON public.reviews TO service_role;
DO $$ BEGIN IF to_regclass('public.email_suppressions') IS NOT NULL THEN ALTER TABLE public.email_suppressions DROP CONSTRAINT IF EXISTS email_suppressions_scope_check; ALTER TABLE public.email_suppressions ADD CONSTRAINT email_suppressions_scope_check CHECK (scope IN ('all', 'optional', 'review_requests') AND email = lower(email)) NOT VALID; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('52', '52_reviews_replies_reports_guests.sql', 'fd8b4421ddfecbd50df04b54e5b23bb62eeaeeeb21cde3af8c77a1010032f53e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 53_one_profile_photo.sql
/* One profile photo, everywhere. profiles.avatar_url is the creator's face and every other row keeps a copy of it: onepages.avatar_url and the copy taken when the page was published, creators.avatar_url, and the creator page header's avatarUrl in store_builder_configs and product_page_configs. Part 44 moved a copy only while it still held the value the profile used to hold, so the first editor to write a copy made it 'chosen' and it never followed again: one owner had three different faces at once, one on his creator page, one in Settings and one on his OnePage. A name can honestly differ from page to page; a face cannot. This makes every copy of the PHOTO take whatever the profile says, leaves the name rule exactly as it was, and brings the copies already apart back onto one photo. An account whose profile has no photo but whose pages do, and which never chose or removed a photo itself, keeps that face: it is lifted into the profile first. Run after part 44, whose trigger and helpers it reuses. Adds no table and grants nothing. Until it runs, the app does the same work from its own routes (lib/account/profile-follow), which covers Settings, the OnePage editor, the creator page builder, the storefront's Edit profile and both onboarding flows. */
/* The photo half of part 44's follow, replaced by a mirror: a copy takes the profile's photo whatever it holds. Part 44's storelib_follow_config and its trigger both call this, so replacing it here changes every copy the trigger writes without touching the name rule (storelib_follow_text), which still leaves a page title somebody typed alone. */
CREATE OR REPLACE FUNCTION public.storelib_follow_photo(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT now_value $$;
/* The trigger again, in case part 44's was dropped by hand; skipped when part 44 has not run, because its function is what the trigger calls. */
DO $do$ BEGIN IF to_regprocedure('public.profiles_identity_follows()') IS NOT NULL THEN DROP TRIGGER IF EXISTS profiles_identity_follows ON public.profiles; CREATE TRIGGER profiles_identity_follows AFTER UPDATE OF display_name, avatar_url ON public.profiles FOR EACH ROW WHEN (old.display_name IS DISTINCT FROM new.display_name OR old.avatar_url IS DISTINCT FROM new.avatar_url) EXECUTE FUNCTION public.profiles_identity_follows(); END IF; END $do$;
/* Part 44's test for the account picture a sign in provider sent, again, word for word, so this part stands on its own where part 44 has not run. Replacing it with the same body changes nothing where it has. */
CREATE OR REPLACE FUNCTION public.storelib_provider_photo(url text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(btrim(url) ~* '^https?://(([a-z0-9-]+\.)*googleusercontent\.com/(a|a-)/|([a-z0-9-]+\.)*googleusercontent\.com/-[^/]+/AAAAAAAAAAI/|graph\.facebook\.com/(v[0-9.]+/)?[^/]+/picture([/?]|$)|platform-lookaside\.fbsbx\.com/platform/profilepic/|pbs\.twimg\.com/profile_images/|avatars\.githubusercontent\.com/|cdn\.discordapp\.com/avatars/|media(-exp[0-9])?\.licdn\.com/dms/image/[^?]*profile-displayphoto)', false) $$;
/* The best face an account already has outside its profile: the creator page header first, because onboarding writes it and the creator page shows it, then the OnePage's. A picture a sign in provider sent is not one anybody chose and is passed over. */
CREATE OR REPLACE FUNCTION public.storelib_best_photo(uid uuid) RETURNS text LANGUAGE sql STABLE AS $$ SELECT q.photo FROM (SELECT coalesce(nullif(btrim(coalesce((SELECT s.published_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT s.draft_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT o.avatar_url FROM public.onepages o WHERE o.owner_id = uid LIMIT 1), '')), '')) AS photo) q WHERE q.photo IS NOT NULL AND NOT public.storelib_provider_photo(q.photo) $$;
/* An account with no photo in its profile and a face on its pages keeps that face, rather than losing it to the mirror below. Only for an account that never chose or removed a photo itself: the mark the app keeps on the account (storelib_avatar_chosen, lib/account/avatar) is what stops a photo somebody deleted in Settings being lifted back in from a leftover copy. */
UPDATE public.profiles p SET avatar_url = public.storelib_best_photo(p.id) WHERE nullif(btrim(coalesce(p.avatar_url, '')), '') IS NULL AND public.storelib_best_photo(p.id) IS NOT NULL AND NOT coalesce((SELECT u.raw_user_meta_data->>'storelib_avatar_chosen' = 'true' FROM auth.users u WHERE u.id = p.id), false);
/* The OnePage: its own copy and the copy taken at the last publish, which is what the live page, the tab icon and the share card are built from. */
UPDATE public.onepages o SET avatar_url = p.avatar_url, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(o.published_profile, '{avatar_url}', coalesce(to_jsonb(p.avatar_url), 'null'::jsonb)) ELSE o.published_profile END FROM public.profiles p WHERE p.id = o.owner_id AND (o.avatar_url IS DISTINCT FROM p.avatar_url OR (jsonb_typeof(o.published_profile) = 'object' AND o.published_profile->>'avatar_url' IS DISTINCT FROM p.avatar_url));
/* The creator row, which the product page and the website's name read. */
UPDATE public.creators c SET avatar_url = p.avatar_url FROM public.profiles p WHERE p.id = c.user_id AND c.avatar_url IS DISTINCT FROM p.avatar_url;
/* The creator page header, draft and published alike. A header that never kept a photo of its own already draws the profile's and is left absent; '' is the creator page's way of saying 'show my initials', which is what a profile with no photo means. */
UPDATE public.store_builder_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')));
/* And a product page's own header, where that table exists. */
DO $do$ BEGIN IF to_regclass('public.product_page_configs') IS NOT NULL THEN EXECUTE $q$ UPDATE public.product_page_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, ''))) $q$; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('53', '53_one_profile_photo.sql', '508a664e2b5e766728b8103a9f73b14a215927936344eb8fe2c8d22943ab937b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 54_onepage_address_any_case.sql
/* One OnePage address in any case. A OnePage is served at storelib.me/{address}, and storelib.me sends /Mara to /mara, so two pages whose addresses differ only in case (Mara and mara) would be one address with two owners. The app already refuses a new address that another page holds in any case (lib/onepage/name-availability); this is the database's own guard for two saves at the same moment: a unique index on lower(slug), so the second save fails and the editor says the address is taken. Made only when no two pages already share an address in different case; otherwise it skips itself with a warning naming the query to see them, and changes nothing. Changes no row. Nothing where there is no onepages table. Needs nothing else. Until it runs, addresses are checked by the app as before. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 54: there is no onepages table, nothing to do.'; ELSIF EXISTS (SELECT 1 FROM public.onepages WHERE slug IS NOT NULL GROUP BY lower(slug) HAVING count(*) > 1) THEN RAISE WARNING 'part 54 skipped: two OnePages share an address in different case, so the one address in any case index was not made. See them with: select lower(slug), array_agg(slug), array_agg(id) from public.onepages where slug is not null group by 1 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS onepages_slug_lower_unique ON public.onepages (lower(slug)); END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('54', '54_onepage_address_any_case.sql', 'bcf36b19bda9370cf09da402cc4036cbf4286cc514f9ec257ade9f4daedb4d2c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 55_file_scans.sql
/* Malware scanning: public.file_scans, one row per file the Storelib file scanner (ClamAV) looked at: where it came from, the verdict, the threat's name, the size, the SHA-256, how long it took, and what Storelib did with the file (kept, removed, refused, pending). Never the file's contents. /admin/scanner reads it and only the server writes it: row level security on, no policy, nothing granted to the browser. Also makes sure digital_assets has the scan_status and scan_result columns the scan writes (they are there on any database that ran the upload migrations; this only adds them where they are missing) and indexes the files still waiting for a verdict. Changes no rows. Needs nothing else. Until it runs, scanning works the same and the admin page says the log starts after this part. */
CREATE TABLE IF NOT EXISTS public.file_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), source text NOT NULL, bucket text, path text, asset_id uuid, status text NOT NULL CHECK (status IN ('clean', 'infected', 'error', 'not_scanned')), threat text, reason text, sha256 text, bytes bigint, duration_ms integer, engine_version text, signatures integer, action text, attempts smallint);
CREATE INDEX IF NOT EXISTS file_scans_created_idx ON public.file_scans (created_at DESC);
CREATE INDEX IF NOT EXISTS file_scans_asset_idx ON public.file_scans (asset_id) WHERE asset_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS file_scans_flagged_idx ON public.file_scans (created_at DESC) WHERE status IN ('infected', 'error');
ALTER TABLE public.file_scans ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_scans FROM anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.digital_assets') IS NOT NULL THEN ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_status text DEFAULT 'pending_scan'; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_result jsonb; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'digital_assets' AND column_name = 'updated_at') THEN CREATE INDEX IF NOT EXISTS digital_assets_scan_waiting_idx ON public.digital_assets (updated_at) WHERE scan_status IN ('pending_scan', 'scanning'); END IF; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('55', '55_file_scans.sql', 'a9eac505e810d41088b911c339a3d8202982edc75dc18b2b912478d5dde5cece') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 56_email_logs_seller_message.sql
/* A buyer's message to the seller, from the receipt's Contact seller (app/api/receipt/contact), is an email like the receipt and the sale email, and is recorded the same way: a row in email_logs with email_type 'seller_message', sent or failed, beside the order. The check on email_type listed only buyer_download, seller_notification and receipt_resend, so that row was refused. The check is rebuilt with the fourth name, NOT VALID, so rows already stored are not read again and it cannot fail on old data. Nothing where there is no email_logs table. Needs nothing else. Until it runs, the message is sent exactly as before and the route notes in its log that the row was not written. */
DO $$ BEGIN IF to_regclass('public.email_logs') IS NULL THEN RAISE NOTICE 'email_logs seller_message: there is no email_logs table, nothing to do.'; ELSE ALTER TABLE public.email_logs DROP CONSTRAINT IF EXISTS email_logs_email_type_check; ALTER TABLE public.email_logs ADD CONSTRAINT email_logs_email_type_check CHECK (email_type IN ('buyer_download', 'seller_notification', 'receipt_resend', 'seller_message')) NOT VALID; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('56', '56_email_logs_seller_message.sql', 'ca8136693c11355e9fc0caff6b616a3df6bffbad6513fb477d821ed40085a365') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 57_onepage_share_image.sql
/* The picture a shared OnePage link shows. A OnePage shared in a chat or on social media shows its creator's profile photo by default, as a Linktree or Beacons link does; in the editor (Settings, SEO) the creator can choose the share card Storelib draws from the page, or a picture of their own, and go back to the photo. Adds one column, onepages.share_image_mode: 'profile', 'card' or 'custom', 'profile' unless changed, with a check that it is one of the three. The first run sets every OnePage already there to 'profile', as the owner asked, a choice kept in a page's settings before this ran included; a second run changes nothing, so a choice made after the first run is kept. Nothing where there is no onepages table. Needs nothing else. Until it runs, every page shows its profile photo and a choice made in the editor is kept in the page's settings. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 57: there is no onepages table, nothing to do.'; ELSIF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'share_image_mode') THEN ALTER TABLE public.onepages ADD COLUMN share_image_mode text NOT NULL DEFAULT 'profile'; UPDATE public.onepages SET share_image_mode = 'profile' WHERE share_image_mode IS DISTINCT FROM 'profile'; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'settings' AND data_type = 'jsonb') THEN UPDATE public.onepages SET settings = settings - 'share_image_mode' WHERE settings -> 'share_image_mode' IS NOT NULL; END IF; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.onepages') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('public.onepages') AND conname = 'onepages_share_image_mode_check') THEN ALTER TABLE public.onepages ADD CONSTRAINT onepages_share_image_mode_check CHECK (share_image_mode IN ('profile', 'card', 'custom')); END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('57', '57_onepage_share_image.sql', 'e88338c23b110f6c643faa74427269fee0e5b6b11d7136fc51fcbf5d0eeb0a22') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 58_onepage_old_addresses.sql
/* Old OnePage addresses keep working. A OnePage is served at storelib.me/{address}, and a creator can change that address in the editor; the old one then answered 404, although it may already be in a bio, a QR code or a post. This keeps each address a page leaves behind in a new table, onepage_slug_history, written by a trigger on onepages when the address changes (lower case, the page's id, when), and the page and the old links (lib/onepage/resolve-address.ts) send a visitor from an old address to the one the page has now, with a permanent redirect. An address another page holds now is always that page's. Server only: row level security on and no policy, so only the service role reads it. The trigger never stops a save: if it cannot write, it warns and the save goes on. Changes no row. Nothing where there is no onepages table. Needs nothing else. Until it runs, a page's old address is not followed, as before; a creator's old username is followed either way. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 58: there is no onepages table, nothing to do.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_slug_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), onepage_id uuid NOT NULL REFERENCES public.onepages(id) ON DELETE CASCADE, old_slug text NOT NULL, new_slug text, changed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS onepage_slug_history_old_slug_idx ON public.onepage_slug_history (old_slug, changed_at DESC); ALTER TABLE public.onepage_slug_history ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_slug_history FROM anon, authenticated; END $$;
CREATE OR REPLACE FUNCTION public.onepages_keep_old_slug() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF OLD.slug IS NOT NULL AND btrim(OLD.slug) <> '' AND lower(OLD.slug) IS DISTINCT FROM lower(NEW.slug) THEN INSERT INTO public.onepage_slug_history (onepage_id, old_slug, new_slug) VALUES (OLD.id, lower(btrim(OLD.slug)), lower(btrim(NEW.slug))); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'onepages_keep_old_slug skipped for %: %', OLD.id, SQLERRM; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.onepages_keep_old_slug() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS onepages_keep_old_slug ON public.onepages; CREATE TRIGGER onepages_keep_old_slug AFTER UPDATE OF slug ON public.onepages FOR EACH ROW EXECUTE FUNCTION public.onepages_keep_old_slug(); END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('58', '58_onepage_old_addresses.sql', 'ad3eebdba9f013b747f4996566505c65b2a329bf698f69e934530749ca37954a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 59_file_security_events.sql
/* File security log: public.file_security_events, one row for each thing about an uploaded or downloaded file an admin may want to look back at: an upload refused (which check, what it found), an upload accepted with a note (an encrypted ZIP, a ZIP too large to list in time), a download refused, an upload or download refused for coming too often, an older file checked for the first time, a malware engine's verdict when one is switched on, and the admin test tool. Never a file's contents, never a secret, never a whole IP address (a short one way hash). /admin/security reads it; only the server writes it: row level security on, no policy, nothing granted to the browser. Also makes sure digital_assets has scan_status, scan_result and checksum (they are there on any database that ran the upload migrations or part 55; this only adds them where missing) and indexes the files from before the built-in checks, which the daily storage job checks a few at a time. Changes no rows. Safe after part 55, and safe without it. Needs nothing else. Until it runs, uploads and downloads work the same and the admin page says the log starts after this part. */
CREATE TABLE IF NOT EXISTS public.file_security_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), event text NOT NULL, outcome text NOT NULL, context text, code text, user_id uuid, creator_id uuid, asset_id uuid, bucket text, path text, file_name text, bytes bigint, detected_type text, sha256 text, provider text, detail jsonb, ip_hash text, CONSTRAINT file_security_events_outcome_check CHECK (outcome IN ('accepted', 'noted', 'refused', 'removed', 'denied', 'limited', 'info')));
CREATE INDEX IF NOT EXISTS file_security_events_created_idx ON public.file_security_events (created_at DESC);
CREATE INDEX IF NOT EXISTS file_security_events_outcome_idx ON public.file_security_events (outcome, created_at DESC) WHERE outcome <> 'info';
CREATE INDEX IF NOT EXISTS file_security_events_code_idx ON public.file_security_events (code, created_at DESC);
CREATE INDEX IF NOT EXISTS file_security_events_asset_idx ON public.file_security_events (asset_id) WHERE asset_id IS NOT NULL;
ALTER TABLE public.file_security_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_security_events FROM anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.digital_assets') IS NULL THEN RAISE NOTICE 'part 59: there is no digital_assets table, only the log was made.'; RETURN; END IF; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_status text DEFAULT 'pending_scan'; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_result jsonb; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS checksum text; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'digital_assets' AND column_name = 'created_at') THEN CREATE INDEX IF NOT EXISTS digital_assets_unchecked_idx ON public.digital_assets (created_at) WHERE scan_status IS NULL OR scan_status IN ('pending_scan', 'scanning'); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('59', '59_file_security_events.sql', 'f2fe128eea11df50d95ef8c42ed1bb00d1e0171a283c4af8e23ae70f56e5a0aa') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 60_attribution.sql
/* Attribution: where a buyer or a sign-up came from. On orders, subscribers and started checkouts: the first touch and the last touch (source, referring host, UTM tags, landing page, as jsonb), the property it happened on (creator_page, onepage or website) and that property's id, and on orders and subscribers when it was written (once). Checks on their shape (NOT VALID, old rows are not rechecked) and the indexes the reports group by: orders by creator, property and date, and by first and last touch source. Adds columns and indexes only; no rows change, no money column is touched. Needs orders.creator_id from 32 (skips those indexes without it) and checkout_starts from 13 or 46 (skips that table without it). Until it runs, orders and sign-ups are made exactly as before and simply carry no attribution. docs/analytics/attribution.md. */
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS attributed_at timestamptz;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_property_type_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_touches_are_objects;
ALTER TABLE public.orders ADD CONSTRAINT orders_touches_are_objects CHECK ((first_touch IS NULL OR jsonb_typeof(first_touch) = 'object') AND (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object')) NOT VALID;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS attributed_at timestamptz;
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_property_type_check;
ALTER TABLE public.subscribers ADD CONSTRAINT subscribers_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_touches_are_objects;
ALTER TABLE public.subscribers ADD CONSTRAINT subscribers_touches_are_objects CHECK ((first_touch IS NULL OR jsonb_typeof(first_touch) = 'object') AND (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object')) NOT VALID;
DO $$ BEGIN IF to_regclass('public.checkout_starts') IS NULL THEN RAISE NOTICE 'checkout_starts is not there yet (part 13 or 46): its attribution columns were skipped; run this part again after it.'; RETURN; END IF; ALTER TABLE public.checkout_starts ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid; ALTER TABLE public.checkout_starts DROP CONSTRAINT IF EXISTS checkout_starts_property_type_check; ALTER TABLE public.checkout_starts ADD CONSTRAINT checkout_starts_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID; CREATE INDEX IF NOT EXISTS checkout_starts_creator_property ON public.checkout_starts (creator_id, property_type, created_at) WHERE property_type IS NOT NULL; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN RAISE NOTICE 'orders.creator_id is not there yet (part 32): the report indexes were skipped; run this part again after it.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_creator_property_created ON public.orders (creator_id, property_type, property_id, created_at) WHERE property_type IS NOT NULL; CREATE INDEX IF NOT EXISTS orders_creator_first_source ON public.orders (creator_id, (first_touch ->> 'source'), created_at) WHERE first_touch IS NOT NULL; CREATE INDEX IF NOT EXISTS orders_creator_last_source ON public.orders (creator_id, (last_touch ->> 'source'), created_at) WHERE last_touch IS NOT NULL; END $$;
CREATE INDEX IF NOT EXISTS subscribers_creator_property ON public.subscribers (creator_id, property_type, property_id) WHERE property_type IS NOT NULL;
CREATE INDEX IF NOT EXISTS subscribers_creator_last_source ON public.subscribers (creator_id, (last_touch ->> 'source')) WHERE last_touch IS NOT NULL;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('60', '60_attribution.sql', 'd4c55cc65182810480882ef852e6983e282a65d579c0826afe081484c41b10ca') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 61_analytics_one_pipeline.sql
/* Analytics, one pipeline: every page of the creator page, the OnePage and each website is one event with the property it happened on. analytics_events gets the property (property_type creator_page, onepage or website, and property_id: the website's store_theme_installs id or the OnePage's id), the page's path, and a link's id and destination for the new link_click event, which the event type check now allows (NOT VALID: old rows are not rechecked). Four indexes for the reads the reports and the tracker make. Old page views get their property from the address they were recorded on (the path is left empty: for a visitor who accepted analytics the stored address is the visit's first page, not the page itself); a second run changes nothing. A daily rollup per creator, property and UTC day (analytics_property_daily), the days it holds (analytics_rollup_days) and the function that refreshes a day (analytics_refresh_property_day), which the daily cron calls; server only, creators may read their own rows. analytics_visit_tally and analytics_all_time leave OnePage page views out, so the Storelib view counts them once, as before, in the OnePage view. The reading side: the rollup keeps each day's browsers and the quarter hour each visit began (session_slots), so a visit falls in the right day of any time zone; a day rolled up before those columns existed is forgotten and rolled up again. analytics_property_counts counts one or more UTC days from the events by the rules the rollup is made with, and analytics_report answers the Analytics page for one creator, one property (or all of them) and two periods: unique visitors, page views and link clicks per chart bucket from the events, visits and where they came from from the rollup for whole past days and from the events for the rest, and the top pages, products, links and started checkouts. Both are server only. docs/analytics/events.md is the contract and lib/analytics/reports.ts says what each figure counts. Run after 25 and 32. Can take a minute on a large events table. */
ALTER TABLE public.analytics_events ADD COLUMN IF NOT EXISTS visitor_id text, ADD COLUMN IF NOT EXISTS session_id text, ADD COLUMN IF NOT EXISTS referrer text, ADD COLUMN IF NOT EXISTS referrer_domain text, ADD COLUMN IF NOT EXISTS utm_source text, ADD COLUMN IF NOT EXISTS utm_medium text, ADD COLUMN IF NOT EXISTS utm_campaign text, ADD COLUMN IF NOT EXISTS utm_term text, ADD COLUMN IF NOT EXISTS utm_content text, ADD COLUMN IF NOT EXISTS country_code text, ADD COLUMN IF NOT EXISTS country_name text, ADD COLUMN IF NOT EXISTS region text, ADD COLUMN IF NOT EXISTS city text, ADD COLUMN IF NOT EXISTS device_type text, ADD COLUMN IF NOT EXISTS browser text, ADD COLUMN IF NOT EXISTS os text, ADD COLUMN IF NOT EXISTS page_url text, ADD COLUMN IF NOT EXISTS screen_width integer, ADD COLUMN IF NOT EXISTS screen_height integer, ADD COLUMN IF NOT EXISTS language text, ADD COLUMN IF NOT EXISTS source_category text, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS path text, ADD COLUMN IF NOT EXISTS link_id text, ADD COLUMN IF NOT EXISTS link_url text;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (event_type IN ('view', 'purchase', 'session_start', 'store_view', 'product_view', 'add_to_cart', 'checkout_start', 'buy_click', 'checkout_complete', 'download', 'link_click')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_property_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_path_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_path_check CHECK (path IS NULL OR (char_length(path) <= 300 AND left(path, 1) = '/')) NOT VALID;
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_type_time ON public.analytics_events (creator_id, property_type, property_id, event_type, created_at);
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_path_time ON public.analytics_events (creator_id, property_type, property_id, path, created_at) WHERE event_type = 'view' AND path IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_visitor_time ON public.analytics_events (visitor_id, created_at) WHERE visitor_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_time_brin ON public.analytics_events USING brin (created_at);
CREATE TABLE IF NOT EXISTS public.analytics_property_daily ( creator_id uuid NOT NULL, property_type text NOT NULL, property_id uuid, day date NOT NULL, visitors integer NOT NULL DEFAULT 0, sessions integer NOT NULL DEFAULT 0, bounces integer NOT NULL DEFAULT 0, page_views integer NOT NULL DEFAULT 0, product_views integer NOT NULL DEFAULT 0, link_clicks integer NOT NULL DEFAULT 0, buy_clicks integer NOT NULL DEFAULT 0, checkout_starts integer NOT NULL DEFAULT 0, sources jsonb NOT NULL DEFAULT '{}'::jsonb, referrers jsonb NOT NULL DEFAULT '{}'::jsonb, campaigns jsonb NOT NULL DEFAULT '{}'::jsonb, devices jsonb NOT NULL DEFAULT '{}'::jsonb, countries jsonb NOT NULL DEFAULT '{}'::jsonb, browsers jsonb NOT NULL DEFAULT '{}'::jsonb, paths jsonb NOT NULL DEFAULT '{}'::jsonb, landing_paths jsonb NOT NULL DEFAULT '{}'::jsonb, session_slots jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_property_daily_type_check CHECK (property_type IN ('creator_page', 'onepage', 'website')) );
ALTER TABLE public.analytics_property_daily ADD COLUMN IF NOT EXISTS browsers jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS session_slots jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS analytics_property_daily_key ON public.analytics_property_daily (creator_id, property_type, (coalesce(property_id, '00000000-0000-0000-0000-000000000000'::uuid)), day);
CREATE INDEX IF NOT EXISTS analytics_property_daily_day ON public.analytics_property_daily (day);
ALTER TABLE public.analytics_property_daily ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "creators read own property days" ON public.analytics_property_daily;
CREATE POLICY "creators read own property days" ON public.analytics_property_daily FOR SELECT USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.analytics_property_daily FROM anon, authenticated;
DROP POLICY IF EXISTS "Allow insert analytics" ON public.analytics_events;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.analytics_events FROM anon, authenticated;
CREATE TABLE IF NOT EXISTS public.analytics_rollup_days (day date PRIMARY KEY, refreshed_at timestamptz NOT NULL DEFAULT now(), properties integer NOT NULL DEFAULT 0);
DO $$ BEGIN /* A day rolled up before session_slots existed is forgotten (only the note that it is rolled up, not a row of anybody's), so the reports count it from the events until the daily cron rolls it up again. */ DELETE FROM public.analytics_rollup_days r WHERE EXISTS (SELECT 1 FROM public.analytics_property_daily d WHERE d.day = r.day AND d.sessions > 0 AND d.session_slots = '{}'::jsonb); END $$;
ALTER TABLE public.analytics_rollup_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_rollup_days FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.analytics_property_counts(p_from timestamptz, p_to timestamptz, p_creator_id uuid DEFAULT NULL, p_property_type text DEFAULT NULL, p_property_id uuid DEFAULT NULL, p_default_website uuid DEFAULT NULL, p_product_id uuid DEFAULT NULL) RETURNS TABLE (creator_id uuid, property_type text, property_id uuid, day date, visitors integer, sessions integer, bounces integer, page_views integer, product_views integer, link_clicks integer, buy_clicks integer, checkout_starts integer, sources jsonb, referrers jsonb, campaigns jsonb, devices jsonb, countries jsonb, browsers jsonb, paths jsonb, landing_paths jsonb, session_slots jsonb) LANGUAGE plpgsql STABLE SET search_path = public AS $fn$ DECLARE v_first date; v_last date; v_where text := ''; BEGIN IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN RETURN; END IF; v_first := (p_from AT TIME ZONE 'UTC')::date; v_last := ((p_to - interval '1 microsecond') AT TIME ZONE 'UTC')::date; /* Only the conditions asked for, so each call is planned for its own arguments and reads one creator's rows by their index. */ IF p_creator_id IS NOT NULL THEN v_where := v_where || ' AND e.creator_id = $3'; END IF; IF p_property_type IS NOT NULL THEN v_where := v_where || ' AND e.property_type = $4'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_where := v_where || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $5 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $5' END; END IF; END IF; IF p_product_id IS NOT NULL THEN v_where := v_where || ' AND e.product_id = $6'; END IF; RETURN QUERY EXECUTE format($q$ WITH ev AS (SELECT e.id, e.creator_id, e.property_type, e.property_id, e.event_type, e.product_id, e.created_at, (e.created_at AT TIME ZONE 'UTC')::date AS d, coalesce(e.path, '(unknown)') AS path, coalesce(nullif(e.source_category, ''), 'direct') AS source, coalesce(nullif(lower(regexp_replace(coalesce(e.referrer_domain, ''), '^www\.', '')), ''), 'direct') AS referrer, nullif(e.utm_campaign, '') AS campaign, coalesce(nullif(lower(e.device_type), ''), 'unknown') AS device, coalesce(nullif(upper(e.country_code), ''), 'unknown') AS country, coalesce(nullif(lower(e.browser), ''), 'unknown') AS browser, e.property_type || ':' || coalesce(e.property_id::text, '') AS pk, coalesce(nullif(e.visitor_id::text, ''), nullif(e.session_id::text, ''), 'e:' || e.id::text) AS vkey, CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') ELSE 'e:' || e.id::text END AS skey FROM public.analytics_events e WHERE e.created_at >= $7 AND e.created_at < $2 AND e.property_type IS NOT NULL AND e.event_type IN ('view', 'link_click', 'buy_click', 'checkout_start') %s), today AS (SELECT * FROM ev WHERE created_at >= $1), looked AS (SELECT v.*, v.d AS for_day FROM ev v WHERE v.event_type = 'view' AND v.d >= $8 UNION ALL SELECT v.*, v.d + 1 AS for_day FROM ev v WHERE v.event_type = 'view' AND v.d + 1 >= $8 AND v.d + 1 <= $9), firsts AS (SELECT DISTINCT ON (creator_id, pk, skey, for_day) creator_id, pk, skey, for_day, created_at, path, source, referrer, campaign, device, country, browser FROM looked ORDER BY creator_id, pk, skey, for_day, created_at, id), pages AS (SELECT creator_id, pk, skey, for_day, count(*) AS n FROM looked GROUP BY 1, 2, 3, 4), starts AS (SELECT f.creator_id, f.pk, f.for_day AS day, f.path, f.source, f.referrer, f.campaign, f.device, f.country, f.browser, p.n AS pages, (floor(extract(epoch FROM f.created_at - (f.for_day::timestamp AT TIME ZONE 'UTC')) / 900))::int::text AS slot FROM firsts f JOIN pages p USING (creator_id, pk, skey, for_day) WHERE f.created_at >= $1 AND (f.created_at AT TIME ZONE 'UTC')::date = f.for_day), keys AS (SELECT DISTINCT creator_id, pk, property_type, property_id, d AS day FROM today), counts AS (SELECT creator_id, pk, d AS day, count(*) FILTER (WHERE event_type = 'view') AS page_views, count(*) FILTER (WHERE event_type = 'view' AND product_id IS NOT NULL) AS product_views, count(DISTINCT vkey) FILTER (WHERE event_type = 'view') AS visitors, count(*) FILTER (WHERE event_type = 'link_click') AS link_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'buy_click') AS buy_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'checkout_start') AS checkout_starts FROM today GROUP BY 1, 2, 3), sess AS (SELECT creator_id, pk, day, count(*) AS sessions, count(*) FILTER (WHERE pages = 1) AS bounces FROM starts GROUP BY 1, 2, 3), dims AS (SELECT creator_id, pk, day, 'source' AS kind, source AS k, count(*) AS n FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'referrer', referrer, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'campaign', campaign, count(*) FROM starts WHERE campaign IS NOT NULL GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'device', device, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'country', country, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'browser', browser, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'landing', path, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'slot', slot, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, d, 'path', path, count(*) FROM today WHERE event_type = 'view' GROUP BY 1, 2, 3, 5), ranked AS (SELECT creator_id, pk, day, kind, k, n, row_number() OVER (PARTITION BY creator_id, pk, day, kind ORDER BY n DESC, k) AS rn FROM dims), capped AS (SELECT creator_id, pk, day, kind, CASE WHEN rn <= CASE kind WHEN 'country' THEN 300 WHEN 'path' THEN 200 WHEN 'landing' THEN 200 WHEN 'slot' THEN 96 ELSE 100 END THEN k ELSE '(other)' END AS k, sum(n) AS n FROM ranked GROUP BY 1, 2, 3, 4, 5), maps AS (SELECT creator_id, pk, day, jsonb_object_agg(kind, m) AS m FROM (SELECT creator_id, pk, day, kind, jsonb_object_agg(k, n) AS m FROM capped GROUP BY 1, 2, 3, 4) x GROUP BY 1, 2, 3) SELECT k.creator_id, k.property_type, k.property_id, k.day, coalesce(c.visitors, 0)::int, coalesce(s.sessions, 0)::int, coalesce(s.bounces, 0)::int, coalesce(c.page_views, 0)::int, coalesce(c.product_views, 0)::int, coalesce(c.link_clicks, 0)::int, coalesce(c.buy_clicks, 0)::int, coalesce(c.checkout_starts, 0)::int, coalesce(m.m -> 'source', '{}'::jsonb), coalesce(m.m -> 'referrer', '{}'::jsonb), coalesce(m.m -> 'campaign', '{}'::jsonb), coalesce(m.m -> 'device', '{}'::jsonb), coalesce(m.m -> 'country', '{}'::jsonb), coalesce(m.m -> 'browser', '{}'::jsonb), coalesce(m.m -> 'path', '{}'::jsonb), coalesce(m.m -> 'landing', '{}'::jsonb), coalesce(m.m -> 'slot', '{}'::jsonb) FROM keys k LEFT JOIN counts c ON c.creator_id = k.creator_id AND c.pk = k.pk AND c.day = k.day LEFT JOIN sess s ON s.creator_id = k.creator_id AND s.pk = k.pk AND s.day = k.day LEFT JOIN maps m ON m.creator_id = k.creator_id AND m.pk = k.pk AND m.day = k.day $q$, v_where) USING p_from, p_to, p_creator_id, p_property_type, p_property_id, p_product_id, (v_first - 1)::timestamp AT TIME ZONE 'UTC', v_first, v_last; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_property_counts(timestamptz, timestamptz, uuid, text, uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_property_counts(timestamptz, timestamptz, uuid, text, uuid, uuid, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_refresh_property_day(p_day date, p_creator_id uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_rows integer; BEGIN IF p_day IS NULL THEN RAISE EXCEPTION 'analytics_refresh_property_day: a day is needed'; END IF; PERFORM pg_advisory_xact_lock(hashtext('analytics_property_daily:' || p_day::text)); DELETE FROM public.analytics_property_daily WHERE day = p_day AND (p_creator_id IS NULL OR creator_id = p_creator_id); INSERT INTO public.analytics_property_daily (creator_id, property_type, property_id, day, visitors, sessions, bounces, page_views, product_views, link_clicks, buy_clicks, checkout_starts, sources, referrers, campaigns, devices, countries, browsers, paths, landing_paths, session_slots, updated_at) SELECT c.creator_id, c.property_type, c.property_id, c.day, c.visitors, c.sessions, c.bounces, c.page_views, c.product_views, c.link_clicks, c.buy_clicks, c.checkout_starts, c.sources, c.referrers, c.campaigns, c.devices, c.countries, c.browsers, c.paths, c.landing_paths, c.session_slots, now() FROM public.analytics_property_counts(p_day::timestamp AT TIME ZONE 'UTC', (p_day + 1)::timestamp AT TIME ZONE 'UTC', p_creator_id) c; GET DIAGNOSTICS v_rows = ROW_COUNT; IF p_creator_id IS NULL THEN INSERT INTO public.analytics_rollup_days (day, refreshed_at, properties) VALUES (p_day, now(), v_rows) ON CONFLICT (day) DO UPDATE SET refreshed_at = excluded.refreshed_at, properties = excluded.properties; END IF; RETURN v_rows; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_refresh_property_day(date, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_refresh_property_day(date, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_visit_tally( p_creator_id uuid, p_product_id uuid, p_time_zone text, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_detail boolean DEFAULT true ) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH bounds AS ( SELECT timestamptz 'epoch' + p_cur_start * interval '1 millisecond' AS cs, timestamptz 'epoch' + p_cur_end * interval '1 millisecond' AS ce, timestamptz 'epoch' + p_prev_start * interval '1 millisecond' AS ps, timestamptz 'epoch' + p_prev_end * interval '1 millisecond' AS pe, coalesce(cardinality(p_cur_starts), 0) AS n ), win AS ( SELECT 'cur'::text AS w, b.cs AS ws, b.ce AS we, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_cur_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) AS starts FROM bounds b UNION ALL SELECT 'prev'::text, b.ps, b.pe, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_prev_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) FROM bounds b ), raw AS ( SELECT e.id, e.created_at, e.session_id::text AS session_id, e.visitor_id::text AS visitor_id, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.cs AND e.created_at < b.ce UNION ALL SELECT e.id, e.created_at, e.session_id::text, e.visitor_id::text, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.ps AND e.created_at < b.pe AND NOT (e.created_at >= b.cs AND e.created_at < b.ce) ), wrows AS ( SELECT w.w, r.id, r.created_at, CASE WHEN cardinality(w.starts) > 0 THEN width_bucket(r.created_at, w.starts) - 1 END AS bucket, (CASE WHEN coalesce(r.session_id, '') <> '' THEN 's:' || r.session_id WHEN coalesce(r.visitor_id, '') <> '' THEN 'v:' || r.visitor_id || ':' || ( floor(extract(epoch FROM r.created_at))::bigint - floor(extract(epoch FROM (r.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || r.id::text END) COLLATE "C" AS skey FROM raw r JOIN win w ON r.created_at >= w.ws AND r.created_at < w.we ), firsts AS ( SELECT DISTINCT ON (w, skey) w, skey, created_at, id, bucket FROM wrows ORDER BY w, skey, created_at, id ), ranked AS ( SELECT f.w, row_number() OVER (PARTITION BY f.w ORDER BY f.created_at, f.id) AS rank, r.source_category, r.referrer_domain, r.utm_campaign, r.country_code, r.country_name, r.city, r.device_type, r.browser, r.os, split_part(split_part(r.page_url, '#', 1), '?', 1) AS page_url FROM firsts f JOIN raw r ON r.id = f.id WHERE p_detail ), view_b AS (SELECT w, bucket, count(*) AS c FROM wrows GROUP BY w, bucket), session_b AS (SELECT w, bucket, count(*) AS c FROM firsts GROUP BY w, bucket), buckets AS ( SELECT w.w, coalesce((SELECT sum(v.c) FROM view_b v WHERE v.w = w.w), 0) AS views, coalesce((SELECT sum(s.c) FROM session_b s WHERE s.w = w.w), 0) AS sessions, coalesce((SELECT jsonb_agg(coalesce(v.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN view_b v ON v.w = w.w AND v.bucket = g.i), '[]'::jsonb) AS view_buckets, coalesce((SELECT jsonb_agg(coalesce(s.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN session_b s ON s.w = w.w AND s.bucket = g.i), '[]'::jsonb) AS session_buckets FROM win w ), steps AS ( SELECT w.w, s.event_type, count(DISTINCT s.skey) AS c FROM ( SELECT e.event_type, e.created_at, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || ( floor(extract(epoch FROM e.created_at))::bigint - floor(extract(epoch FROM (e.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || e.created_at::text END) COLLATE "C" AS skey FROM public.analytics_events e, bounds b WHERE p_detail AND e.creator_id = p_creator_id AND e.event_type IN ('buy_click', 'checkout_start') AND (p_product_id IS NULL OR e.product_id = p_product_id) AND ((e.created_at >= b.cs AND e.created_at < b.ce) OR (e.created_at >= b.ps AND e.created_at < b.pe)) ) s JOIN win w ON s.created_at >= w.ws AND s.created_at < w.we GROUP BY w.w, s.event_type ), grouped AS ( SELECT w, CASE WHEN GROUPING(source_category) = 0 THEN 'source' WHEN GROUPING(referrer_domain) = 0 THEN 'referrer' WHEN GROUPING(utm_campaign) = 0 THEN 'campaign' WHEN GROUPING(city) = 0 THEN 'city' WHEN GROUPING(country_code) = 0 THEN 'country' WHEN GROUPING(device_type) = 0 THEN 'device' WHEN GROUPING(browser) = 0 THEN 'browser' WHEN GROUPING(os) = 0 THEN 'os' ELSE 'page' END AS kind, CASE WHEN GROUPING(source_category) = 0 THEN jsonb_build_array(source_category) WHEN GROUPING(referrer_domain) = 0 THEN jsonb_build_array(referrer_domain) WHEN GROUPING(utm_campaign) = 0 THEN jsonb_build_array(utm_campaign) WHEN GROUPING(city) = 0 THEN jsonb_build_array(city, country_code, country_name) WHEN GROUPING(country_code) = 0 THEN jsonb_build_array(country_code, country_name) WHEN GROUPING(device_type) = 0 THEN jsonb_build_array(device_type) WHEN GROUPING(browser) = 0 THEN jsonb_build_array(browser) WHEN GROUPING(os) = 0 THEN jsonb_build_array(os) ELSE jsonb_build_array(page_url) END AS cols, count(*) AS n, min(rank) AS r FROM ranked GROUP BY w, GROUPING SETS ((source_category), (referrer_domain), (utm_campaign), (country_code, country_name), (city, country_code, country_name), (device_type), (browser), (os), (page_url)) ), groups AS ( SELECT w, jsonb_object_agg(kind, rows) AS groups FROM (SELECT w, kind, jsonb_agg(cols || jsonb_build_array(n, r) ORDER BY r) AS rows FROM grouped GROUP BY w, kind) k GROUP BY w ), tallies AS ( SELECT w.w, jsonb_build_object( 'views', bk.views, 'view_buckets', bk.view_buckets, 'sessions', bk.sessions, 'session_buckets', bk.session_buckets, 'steps', CASE WHEN p_detail THEN jsonb_build_object( 'buy', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'buy_click'), 0), 'checkout', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'checkout_start'), 0) ) END, 'groups', CASE WHEN p_detail THEN coalesce((SELECT g.groups FROM groups g WHERE g.w = w.w), '{}'::jsonb) END ) AS t FROM win w JOIN buckets bk ON bk.w = w.w ) SELECT jsonb_object_agg(w, t) FROM tallies$fn$;
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status, 'pending') = 'pending') AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_report(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_part text DEFAULT 'all', p_now timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public SET work_mem = '64MB' AS $fn$ DECLARE v_today date := (coalesce(p_now, now()) AT TIME ZONE 'UTC')::date; v_pred text := ''; v_pred_d text := ''; v_out jsonb := '{}'::jsonb; v_one jsonb; v_part jsonb; v_w text; v_ws timestamptz; v_we timestamptz; v_starts timestamptz[]; v_rolled date[]; v_from timestamptz[]; v_to timestamptz[]; v_run_from timestamptz; v_day date; v_d0 timestamptz; v_d1 timestamptz; BEGIN IF p_creator_id IS NULL OR p_cur_start IS NULL OR p_cur_end IS NULL OR p_cur_end <= p_cur_start THEN RAISE EXCEPTION 'analytics_report: a creator and a period are needed'; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_report: unknown property type %', p_property_type; END IF; IF coalesce(p_part, '') NOT IN ('all', 'figures', 'detail') THEN RAISE EXCEPTION 'analytics_report: unknown part %', p_part; END IF; /* Every read below is given the same arguments: $1 the creator, $2 the property type, $3 the property id, $4 the product, $5 and $6 the period, $7 its buckets, $8 the rolled up days, $9 and $10 the stretches read from the events, $11 the live website. The property and the product are conditions of their own, so each read is planned for what it is asked. A website row that never knew its install is the live website's. */ IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; v_pred_d := replace(v_pred, 'e.', 'd.'); IF p_product_id IS NOT NULL THEN v_pred := v_pred || ' AND e.product_id = $4'; END IF; FOREACH v_w IN ARRAY ARRAY['cur', 'prev'] LOOP v_ws := timestamptz 'epoch' + (CASE v_w WHEN 'cur' THEN p_cur_start ELSE coalesce(p_prev_start, p_cur_start) END) * interval '1 millisecond'; v_we := greatest(v_ws, timestamptz 'epoch' + (CASE v_w WHEN 'cur' THEN p_cur_end ELSE coalesce(p_prev_end, p_cur_start) END) * interval '1 millisecond'); v_starts := ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(CASE v_w WHEN 'cur' THEN p_cur_starts ELSE p_prev_starts END, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i); v_one := '{}'::jsonb; IF p_part IN ('all', 'figures') THEN /* VISITORS: distinct in the period and in each bucket of the chart, counted from the page views themselves (visitors are never added up from days): one read, a count per bucket and visitor, and the period's visitors from those. */ EXECUTE format($q$ WITH bv AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket(e.created_at, $7::timestamptz[]) - 1 ELSE -1 END AS b, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n, count(e.product_id) AS pn FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2), people AS (SELECT v, sum(pn) AS pn FROM bv GROUP BY v), per_b AS (SELECT b, count(*) AS visitors, sum(n) AS views FROM bv GROUP BY b) SELECT jsonb_build_object('visitors', (SELECT count(*) FROM people), 'product_visitors', (SELECT count(*) FROM people WHERE pn > 0), 'product_views', coalesce((SELECT sum(pn) FROM people), 0), 'views', coalesce((SELECT sum(views) FROM per_b), 0), 'visitor_buckets', coalesce((SELECT jsonb_agg(coalesce(p.visitors, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN per_b p ON p.b = g.i), '[]'::jsonb), 'view_buckets', coalesce((SELECT jsonb_agg(coalesce(p.views, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN per_b p ON p.b = g.i), '[]'::jsonb)) $q$, v_pred) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; /* LINK CLICKS in each bucket. A link is nobody's product: none when a product is chosen. */ EXECUTE format($q$ WITH c AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket(e.created_at, $7::timestamptz[]) - 1 ELSE -1 END AS b, count(*) AS n FROM public.analytics_events e WHERE $4::uuid IS NULL AND e.creator_id = $1 AND e.event_type = 'link_click' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1) SELECT jsonb_build_object('clicks', coalesce((SELECT sum(n) FROM c), 0), 'click_buckets', coalesce((SELECT jsonb_agg(coalesce(c.n, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN c ON c.b = g.i), '[]'::jsonb)) $q$, replace(v_pred, ' AND e.product_id = $4', '')) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; END IF; IF p_part IN ('all', 'detail') AND v_w = 'cur' THEN /* PAGES and PRODUCTS: their page views, and how many visitors saw each. The period itself only: the lists are not compared. */ EXECUTE format($q$ WITH pv AS (SELECT e.property_type AS pt, e.property_id AS pid, e.path COLLATE "C" AS path, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n, count(e.product_id) AS pn FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2, 3, 4), prv AS (SELECT e.product_id, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.product_id IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2) SELECT jsonb_build_object('pages', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.path, t.views, t.visitors) ORDER BY t.views DESC, t.visitors DESC, t.path) FROM (SELECT pt, pid, path, sum(n) AS views, count(*) AS visitors FROM pv GROUP BY 1, 2, 3 ORDER BY 4 DESC, 5 DESC, 3 LIMIT 50) t), '[]'::jsonb), 'products', coalesce((SELECT jsonb_agg(jsonb_build_array(t.product_id, t.views, t.visitors) ORDER BY t.views DESC, t.product_id) FROM (SELECT product_id, sum(n) AS views, count(*) AS visitors FROM prv GROUP BY 1) t), '[]'::jsonb)) $q$, v_pred) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; /* STARTED CHECKOUTS, for the funnel: the visitors with a checkout_start. LINKS: clicks per link, and who clicked. */ EXECUTE format($q$ SELECT jsonb_build_object('checkouts', (SELECT count(DISTINCT (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C")) FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'checkout_start' AND e.created_at >= $5 AND e.created_at < $6 %1$s), 'links', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.link, t.clicks, t.visitors) ORDER BY t.clicks DESC, t.link) FROM (SELECT e.property_type AS pt, e.property_id AS pid, coalesce(e.link_id, e.link_url, '') COLLATE "C" AS link, count(*) AS clicks, count(DISTINCT (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C")) AS visitors FROM public.analytics_events e WHERE $4::uuid IS NULL AND e.creator_id = $1 AND e.event_type = 'link_click' AND e.created_at >= $5 AND e.created_at < $6 %2$s GROUP BY 1, 2, 3 ORDER BY 4 DESC, 3 LIMIT 50) t), '[]'::jsonb)) $q$, v_pred, replace(v_pred, ' AND e.product_id = $4', '')) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; END IF; IF p_part IN ('all', 'detail') THEN /* VISITS AND WHERE THEY CAME FROM. Every UTC day wholly inside the period that the daily rollup holds, and that is over, is read from analytics_property_daily; the rest (the part days at either edge, today, a day not rolled up yet) is counted from the events by analytics_property_counts, the very function the rollup is made with, so the two cannot disagree. A visit is counted in the quarter hour it began (session_slots), which lies wholly inside one bucket of any time zone's chart. With a product chosen, all of it from the events. */ v_rolled := '{}'; v_from := '{}'; v_to := '{}'; v_run_from := NULL; IF v_we > v_ws THEN FOR v_day IN SELECT g::date FROM generate_series((v_ws AT TIME ZONE 'UTC')::date, ((v_we - interval '1 microsecond') AT TIME ZONE 'UTC')::date, interval '1 day') g LOOP v_d0 := v_day::timestamp AT TIME ZONE 'UTC'; v_d1 := (v_day + 1)::timestamp AT TIME ZONE 'UTC'; IF p_product_id IS NULL AND v_d0 >= v_ws AND v_d1 <= v_we AND v_day < v_today AND EXISTS (SELECT 1 FROM public.analytics_rollup_days r WHERE r.day = v_day) THEN v_rolled := v_rolled || v_day; IF v_run_from IS NOT NULL THEN v_from := v_from || v_run_from; v_to := v_to || v_d0; v_run_from := NULL; END IF; ELSIF v_run_from IS NULL THEN v_run_from := greatest(v_d0, v_ws); END IF; END LOOP; IF v_run_from IS NOT NULL THEN v_from := v_from || v_run_from; v_to := v_to || v_we; END IF; END IF; EXECUTE format($q$ WITH parts AS (SELECT d.day, d.sessions, d.sources, d.referrers, d.campaigns, d.devices, d.countries, d.browsers, d.session_slots FROM public.analytics_property_daily d WHERE d.creator_id = $1 AND d.day = ANY ($8) %1$s UNION ALL SELECT c.day, c.sessions, c.sources, c.referrers, c.campaigns, c.devices, c.countries, c.browsers, c.session_slots FROM unnest($9::timestamptz[], $10::timestamptz[]) AS r(f, t), LATERAL public.analytics_property_counts(r.f, r.t, $1, $2, $3, $11, $4) c), pairs AS (SELECT 'source' AS kind, x.k, x.v::bigint AS n FROM parts p, jsonb_each_text(p.sources) x(k, v) UNION ALL SELECT 'referrer', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.referrers) x(k, v) UNION ALL SELECT 'campaign', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.campaigns) x(k, v) UNION ALL SELECT 'device', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.devices) x(k, v) UNION ALL SELECT 'country', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.countries) x(k, v) UNION ALL SELECT 'browser', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.browsers) x(k, v)), slots AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket((p.day::timestamp AT TIME ZONE 'UTC') + x.k::int * interval '15 minutes', $7::timestamptz[]) - 1 ELSE -1 END AS b, sum(x.v::bigint) AS n FROM parts p, jsonb_each_text(p.session_slots) x(k, v) GROUP BY 1) SELECT jsonb_build_object('sessions', coalesce((SELECT sum(sessions) FROM parts), 0), 'session_buckets', coalesce((SELECT jsonb_agg(coalesce(s.n, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN slots s ON s.b = g.i), '[]'::jsonb), 'rolled_days', cardinality($8::date[]), 'raw_runs', cardinality($9::timestamptz[]), 'maps', coalesce((SELECT jsonb_object_agg(kind, m) FROM (SELECT kind, jsonb_object_agg(k, n) AS m FROM (SELECT kind, k, sum(n) AS n FROM pairs GROUP BY 1, 2) s GROUP BY 1) y), '{}'::jsonb)) $q$, v_pred_d) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, v_rolled, v_from, v_to, p_default_website; v_one := v_one || v_part; END IF; v_out := v_out || jsonb_build_object(v_w, v_one); END LOOP; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_report(uuid, text, uuid, uuid, uuid, bigint, bigint, bigint, bigint, bigint[], bigint[], text, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_report(uuid, text, uuid, uuid, uuid, bigint, bigint, bigint, bigint, bigint[], bigint[], text, timestamptz) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('61', '61_analytics_one_pipeline.sql', '376d5017517a0abc39564d9b08d6171ee083a3dd105ecbff775a61a0ae4b3551') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 62_money_rows_server_only.sql
/* Money rows are written by the server only. Orders, library entries (entitlements), refunds, the seller ledger and its events, payouts, Storelib plan subscriptions and invoices were writable from the browser by old rules: "Anyone can create orders" (anon included) and "System can insert entitlements" let a signed in person write a completed order or a library row for any product and download it without paying. Every write in the app already goes through the server's service role, so signed in users and visitors lose INSERT, UPDATE, DELETE and TRUNCATE on these tables, every write policy on them is dropped, and a policy that allowed everything (FOR ALL) is kept as a read only copy of itself before it goes, so nobody loses a read. Buyers read their own orders and library, creators the orders and library rows of their products, as before. Reads are unchanged. Safe to run again. */
DO $do$ DECLARE t text; pol record; BEGIN FOREACH t IN ARRAY ARRAY['orders','entitlements','refunds','seller_ledger','ledger_events','payouts','subscriptions','invoices'] LOOP IF to_regclass('public.' || t) IS NULL THEN RAISE NOTICE 'money rows: public.% does not exist here, skipped', t; CONTINUE; END IF; EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.%I FROM anon, authenticated', t); FOR pol IN SELECT policyname, cmd, roles, qual FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND cmd <> 'SELECT' AND NOT (roles <@ ARRAY['service_role']::name[]) LOOP IF pol.cmd = 'ALL' AND pol.qual IS NOT NULL AND pol.qual NOT ILIKE '%service_role%' AND NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND policyname = left(pol.policyname, 56) || ' (read)') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO %s USING (%s)', left(pol.policyname, 56) || ' (read)', t, array_to_string(ARRAY(SELECT quote_ident(r) FROM unnest(pol.roles) r), ', '), pol.qual); END IF; EXECUTE format('DROP POLICY %I ON public.%I', pol.policyname, t); END LOOP; END LOOP; END $do$;
DO $do$ BEGIN IF to_regclass('public.orders') IS NOT NULL THEN DROP POLICY IF EXISTS "storelib buyer reads own orders" ON public.orders; CREATE POLICY "storelib buyer reads own orders" ON public.orders FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid())); DROP POLICY IF EXISTS "storelib creator reads product orders" ON public.orders; CREATE POLICY "storelib creator reads product orders" ON public.orders FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.products p JOIN public.creators c ON c.id = p.creator_id WHERE p.id = orders.product_id AND c.user_id = (SELECT auth.uid()))); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.entitlements') IS NOT NULL THEN DROP POLICY IF EXISTS "storelib buyer reads own library" ON public.entitlements; CREATE POLICY "storelib buyer reads own library" ON public.entitlements FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid())); DROP POLICY IF EXISTS "storelib creator reads product library rows" ON public.entitlements; CREATE POLICY "storelib creator reads product library rows" ON public.entitlements FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.products p JOIN public.creators c ON c.id = p.creator_id WHERE p.id = entitlements.product_id AND c.user_id = (SELECT auth.uid()))); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('62', '62_money_rows_server_only.sql', '60d76b7f686af5f1d5899b59d6ee780398832a20d55cc4c51ffe79003e16ad77') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 63_private_columns.sql
/* Private columns stay private, and server owned columns stay the server's. Until now anyone with the public key could read every column of profiles and creators: every account's email and role, home address fields, spam flags and time zone, and every creator's Stripe ids, plan, payout settings, statement descriptor and ban reason. Visitors and signed in users now read only the public columns of those two tables (name, handle, photo, bio, links, the storefront's settings, the support email a creator publishes); the server reads everything as before, and the app reads a person's own private columns through the server. public.storelib_share_public_columns() does the granting from one list of private columns (public.storelib_private_columns), so a column added later is public unless it is on that list; run it again after adding a column to either table (the check after says whether every column is shared or listed). It also rebuilds public.creators_public and public.profiles_public, the same tables with the public columns only, read with the reader's own rights, for pages that want every public column. Signed in users can no longer change what only the server may: a creator's Stripe account, plan, payouts switch, ban and review counts; a profile's role, spam state and official, verified and staff marks. The trigger keeps the old value on an update and the column's default on an insert, and profiles.email always follows the sign in email. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
CREATE OR REPLACE FUNCTION public.storelib_share_public_columns() RETURNS void LANGUAGE plpgsql AS $f$ DECLARE t text; col record; cols text; BEGIN FOREACH t IN ARRAY ARRAY['creators','profiles'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('REVOKE SELECT ON public.%I FROM anon, authenticated', t); FOR col IN SELECT a.attname FROM pg_attribute a WHERE a.attrelid = ('public.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped LOOP IF col.attname::text = ANY (public.storelib_private_columns(t)) THEN EXECUTE format('REVOKE SELECT (%I) ON public.%I FROM anon, authenticated', col.attname, t); ELSE EXECUTE format('GRANT SELECT (%I) ON public.%I TO anon, authenticated', col.attname, t); END IF; END LOOP; SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid = ('public.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped AND NOT (a.attname::text = ANY (public.storelib_private_columns(t))); EXECUTE format('DROP VIEW IF EXISTS public.%I', t || '_public'); EXECUTE format('CREATE VIEW public.%I WITH (security_invoker = true) AS SELECT %s FROM public.%I', t || '_public', cols, t); EXECUTE format('GRANT SELECT ON public.%I TO anon, authenticated, service_role', t || '_public'); END LOOP; END $f$;
REVOKE ALL ON FUNCTION public.storelib_share_public_columns() FROM PUBLIC, anon, authenticated;
SELECT public.storelib_share_public_columns();
CREATE OR REPLACE FUNCTION public.storelib_sign_in_email(p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT u.email::text FROM auth.users u WHERE u.id = p_user AND p_user = auth.uid() $f$;
REVOKE ALL ON FUNCTION public.storelib_sign_in_email(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_sign_in_email(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.storelib_keep_server_columns() RETURNS trigger LANGUAGE plpgsql AS $f$ DECLARE col text; newj jsonb; oldj jsonb; expr text; v jsonb; mail text; BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; newj := to_jsonb(NEW); IF TG_OP = 'UPDATE' THEN oldj := to_jsonb(OLD); END IF; FOREACH col IN ARRAY TG_ARGV LOOP IF NOT (newj ? col) THEN CONTINUE; END IF; IF TG_OP = 'UPDATE' THEN newj := jsonb_set(newj, ARRAY[col], coalesce(oldj -> col, 'null'::jsonb)); ELSIF col <> 'user_id' THEN expr := NULL; SELECT pg_get_expr(d.adbin, d.adrelid) INTO expr FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.attrelid = TG_RELID AND a.attname = col; IF expr IS NULL THEN v := 'null'::jsonb; ELSE EXECUTE 'SELECT to_jsonb(' || expr || ')' INTO v; END IF; newj := jsonb_set(newj, ARRAY[col], v); END IF; END LOOP; IF TG_TABLE_NAME = 'profiles' AND (newj ? 'email') THEN mail := public.storelib_sign_in_email((newj ->> 'id')::uuid); IF mail IS NOT NULL THEN newj := jsonb_set(newj, ARRAY['email'], to_jsonb(mail)); ELSIF TG_OP = 'UPDATE' THEN newj := jsonb_set(newj, ARRAY['email'], coalesce(oldj -> 'email', 'null'::jsonb)); END IF; END IF; NEW := jsonb_populate_record(NEW, newj); RETURN NEW; END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at'); END IF; IF to_regclass('public.profiles') IS NOT NULL THEN DROP TRIGGER IF EXISTS profiles_keep_server_columns ON public.profiles; CREATE TRIGGER profiles_keep_server_columns BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('role', 'spam_state', 'spam_score', 'is_official', 'is_verified', 'is_staff'); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('63', '63_private_columns.sql', 'bead2309f2d218b66274c1bed02fa8191bdb5d067d180d1dfd68beb372901525') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 64_ledger_once_and_atomic.sql
/* The seller balance, changed in one place, once per event. Every change to a creator's balance (a sale, a refund, a dispute opened or won, a payout paid or returned, a hold released) was read, added to in the app and written back, so two changes at the same moment lost one of them, and Stripe sending payout.paid again counted the payout twice. public.ledger_post() now makes each change inside the database: it locks the creator's balance row, writes the event row under an idempotency key (ledger_events.idempotency_key, unique), and changes the balance by the same amounts, all or nothing, and a key already written changes nothing. public.ledger_release_due() releases every sale whose hold has ended the same way, creator by creator. Old events get their keys (the first sale row of an order, a payout's completion or return, a dispute's opening or closing), so events already recorded are not counted again. public.stripe_webhook_events records every Stripe event the webhook has finished, so a delivery Stripe repeats after it was handled is answered without doing anything twice. All three are the server's only. Until this runs the app changes balances as before. Run after `62`. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL OR to_regclass('public.seller_ledger') IS NULL THEN RAISE NOTICE 'ledger skipped: public.ledger_events or public.seller_ledger does not exist here'; RETURN; END IF; ALTER TABLE public.ledger_events ADD COLUMN IF NOT EXISTS idempotency_key text; END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL THEN RETURN; END IF; UPDATE public.ledger_events e SET idempotency_key = 'sale:' || e.order_id WHERE e.event_type = 'sale' AND e.order_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = 'sale' AND x.order_id = e.order_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'sale:' || e.order_id); UPDATE public.ledger_events e SET idempotency_key = 'payout:' || e.stripe_payout_id || ':' || e.event_type WHERE e.event_type IN ('cashout_completed', 'cashout_failed') AND e.stripe_payout_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = e.event_type AND x.stripe_payout_id = e.stripe_payout_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'payout:' || e.stripe_payout_id || ':' || e.event_type); UPDATE public.ledger_events e SET idempotency_key = 'dispute:' || e.stripe_dispute_id || ':' || e.event_type WHERE e.event_type IN ('dispute_created', 'dispute_closed') AND e.stripe_dispute_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = e.event_type AND x.stripe_dispute_id = e.stripe_dispute_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'dispute:' || e.stripe_dispute_id || ':' || e.event_type); END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL THEN RETURN; END IF; CREATE UNIQUE INDEX IF NOT EXISTS ledger_events_once ON public.ledger_events (idempotency_key) WHERE idempotency_key IS NOT NULL; END $do$;
CREATE TABLE IF NOT EXISTS public.stripe_webhook_events (event_id text PRIMARY KEY, type text NOT NULL, account text, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, attempts integer NOT NULL DEFAULT 1, last_error text);
CREATE INDEX IF NOT EXISTS stripe_webhook_events_unfinished_idx ON public.stripe_webhook_events (received_at) WHERE processed_at IS NULL;
ALTER TABLE public.stripe_webhook_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.stripe_webhook_events FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.ledger_post(p_creator uuid, p_key text, p_op text, p_amount bigint, p_event jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE l public.seller_ledger%ROWTYPE; d_p bigint := 0; d_a bigint := 0; d_t bigint := 0; d_n bigint := 0; rem bigint; take bigint; ev uuid; BEGIN IF p_creator IS NULL OR p_amount IS NULL OR p_amount < 0 THEN RAISE EXCEPTION 'ledger_post: a creator and an amount of zero or more are needed'; END IF; INSERT INTO public.seller_ledger (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT * INTO l FROM public.seller_ledger WHERE creator_id = p_creator FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.ledger_events WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false); END IF; IF p_op = 'sale' THEN take := least(p_amount, l.negative_balance); d_n := -take; d_p := p_amount - take; ELSIF p_op = 'credit_available' THEN take := least(p_amount, l.negative_balance); d_n := -take; d_a := p_amount - take; ELSIF p_op IN ('debit_pending_first', 'debit_available_first') THEN rem := p_amount; IF p_op = 'debit_pending_first' THEN take := least(rem, l.pending_amount); d_p := -take; rem := rem - take; take := least(rem, l.available_amount); d_a := -take; rem := rem - take; ELSE take := least(rem, l.available_amount); d_a := -take; rem := rem - take; take := least(rem, l.pending_amount); d_p := -take; rem := rem - take; END IF; d_n := rem; ELSIF p_op = 'payout_paid' THEN d_t := -least(p_amount, l.in_transit_amount); ELSIF p_op = 'payout_returned' THEN d_t := -least(p_amount, l.in_transit_amount); d_a := p_amount; ELSIF p_op = 'record' THEN NULL; ELSE RAISE EXCEPTION 'ledger_post: unknown change %', p_op; END IF; INSERT INTO public.ledger_events (creator_id, event_type, amount_cents, net_seller_cents, fee_cents, currency, pending_delta, available_delta, in_transit_delta, order_id, stripe_payout_id, stripe_refund_id, stripe_dispute_id, hold_until, description, metadata, idempotency_key) VALUES (p_creator, p_event ->> 'event_type', coalesce((p_event ->> 'amount_cents')::integer, p_amount::integer), coalesce((p_event ->> 'net_seller_cents')::integer, p_amount::integer), coalesce((p_event ->> 'fee_cents')::integer, 0), coalesce(p_event ->> 'currency', 'usd'), d_p, d_a, d_t, (p_event ->> 'order_id')::uuid, p_event ->> 'stripe_payout_id', p_event ->> 'stripe_refund_id', p_event ->> 'stripe_dispute_id', (p_event ->> 'hold_until')::timestamptz, p_event ->> 'description', coalesce(p_event -> 'metadata', '{}'::jsonb), p_key) ON CONFLICT DO NOTHING RETURNING id INTO ev; IF ev IS NULL THEN RETURN jsonb_build_object('applied', false); END IF; UPDATE public.seller_ledger SET pending_amount = pending_amount + d_p, available_amount = available_amount + d_a, in_transit_amount = in_transit_amount + d_t, negative_balance = negative_balance + d_n, lifetime_earnings = lifetime_earnings + coalesce((p_event ->> 'add_lifetime_earnings')::integer, 0), lifetime_fees = lifetime_fees + coalesce((p_event ->> 'add_lifetime_fees')::integer, 0), lifetime_refunds = lifetime_refunds + coalesce((p_event ->> 'add_lifetime_refunds')::integer, 0), lifetime_paid_out = lifetime_paid_out + CASE WHEN p_op = 'payout_paid' THEN p_amount::integer ELSE 0 END WHERE creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'event_id', ev, 'pending_delta', d_p, 'available_delta', d_a, 'in_transit_delta', d_t, 'negative_delta', d_n); END $f$;
CREATE OR REPLACE FUNCTION public.ledger_release_due(p_now timestamptz DEFAULT now()) RETURNS TABLE (creator_id uuid, released bigint, to_available bigint, events integer) LANGUAGE plpgsql SET search_path = public AS $f$ #variable_conflict use_column DECLARE c uuid; ids uuid[]; amt bigint; take bigint; l public.seller_ledger%ROWTYPE; BEGIN FOR c IN SELECT DISTINCT e.creator_id FROM public.ledger_events e WHERE e.event_type = 'sale' AND e.released_at IS NULL AND e.hold_until <= p_now LOOP INSERT INTO public.seller_ledger (creator_id) VALUES (c) ON CONFLICT (creator_id) DO NOTHING; SELECT * INTO l FROM public.seller_ledger s WHERE s.creator_id = c FOR UPDATE; SELECT array_agg(x.id ORDER BY x.id) INTO ids FROM (SELECT e.id FROM public.ledger_events e WHERE e.creator_id = c AND e.event_type = 'sale' AND e.released_at IS NULL AND e.hold_until <= p_now FOR UPDATE SKIP LOCKED) x; IF ids IS NULL THEN CONTINUE; END IF; SELECT coalesce(sum(greatest(0, coalesce(s.net_seller_cents, 0) - coalesce((SELECT sum(greatest(0, -coalesce(r.pending_delta, 0))) FROM public.ledger_events r WHERE r.event_type = 'refund' AND r.order_id = s.order_id), 0))), 0) INTO amt FROM public.ledger_events s WHERE s.id = ANY (ids); UPDATE public.ledger_events e SET released_at = p_now WHERE e.id = ANY (ids); take := least(amt, l.negative_balance); UPDATE public.seller_ledger s SET pending_amount = greatest(0, s.pending_amount - amt), available_amount = s.available_amount + (amt - take), negative_balance = s.negative_balance - take WHERE s.creator_id = c; INSERT INTO public.ledger_events (creator_id, event_type, amount_cents, net_seller_cents, currency, pending_delta, available_delta, description, idempotency_key) VALUES (c, 'hold_release', amt::integer, (amt - take)::integer, 'usd', (-least(amt, l.pending_amount))::integer, (amt - take)::integer, 'Hold released: $' || to_char(amt / 100.0, 'FM999999990.00') || ' cleared', 'release:' || c || ':' || md5(array_to_string(ids, ','))); creator_id := c; released := amt; to_available := amt - take; events := array_length(ids, 1); RETURN NEXT; END LOOP; END $f$;
REVOKE ALL ON FUNCTION public.ledger_post(uuid, text, text, bigint, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ledger_post(uuid, text, text, bigint, jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.ledger_release_due(timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ledger_release_due(timestamptz) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('64', '64_ledger_once_and_atomic.sql', '6db5fdf4f88574dae5720a435336b9fda6b43324e2e3bd991c010f5d7deee874') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 65_account_deletion_keeps_records.sql
/* Deleting an account keeps what belongs to other people. A deleted buyer's orders were deleted with the account (orders.buyer_id cascaded off auth.users), and those orders are also the seller's sales records: orders.buyer_id may now be empty and the link to the account is cleared on delete instead of taking the order. creators.deleted_at marks a store whose owner deleted their account and was retired rather than wiped because buyers or money records hang off it (lib/account/delete-account): the store is closed, its products archived for sale and still in every buyer's library. public.account_deletions records every deletion: whose, removed or retired, who asked (the person, an admin, the spam purge, a business owner), when, and every step that failed, so a half finished deletion is seen and can be run again. Server only. Run after `63`. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders skipped: public.orders does not exist here'; RETURN; END IF; ALTER TABLE public.orders ALTER COLUMN buyer_id DROP NOT NULL; END $do$;
DO $do$ DECLARE c record; BEGIN IF to_regclass('public.orders') IS NULL THEN RETURN; END IF; FOR c IN SELECT con.conname FROM pg_constraint con JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND a.attname = 'buyer_id' AND con.confrelid = 'auth.users'::regclass AND con.confdeltype <> 'n' LOOP EXECUTE format('ALTER TABLE public.orders DROP CONSTRAINT %I', c.conname); END LOOP; IF NOT EXISTS (SELECT 1 FROM pg_constraint con JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND a.attname = 'buyer_id') THEN ALTER TABLE public.orders ADD CONSTRAINT orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES auth.users (id) ON DELETE SET NULL NOT VALID; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RETURN; END IF; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS deleted_at timestamptz; END $do$;
CREATE TABLE IF NOT EXISTS public.account_deletions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, creator_id uuid, mode text NOT NULL CHECK (mode IN ('removed', 'retired')), requested_by text NOT NULL CHECK (requested_by IN ('self', 'admin', 'spam_purge', 'business_owner')), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, failures jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE INDEX IF NOT EXISTS account_deletions_user_idx ON public.account_deletions (user_id, started_at DESC);
CREATE INDEX IF NOT EXISTS account_deletions_failed_idx ON public.account_deletions (started_at DESC) WHERE jsonb_array_length(failures) > 0;
ALTER TABLE public.account_deletions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.account_deletions FROM anon, authenticated;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('65', '65_account_deletion_keeps_records.sql', '4bb97cf40c3db666fbaffefc7e6dcff2ee6ff889cd1b2914b5b5d811a409a553') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 66_deleted_rows_kept.sql
/* A deleted row can be put back. Whatever deletes a row from the tables that hold creators' and buyers' work and money (products and their files, variants and courses, orders, library entries, refunds, payouts, the balance and its history, plans and invoices, creators and profiles, OnePages, store and website settings and pages, domains and addresses, discount codes, email lists, flows and campaigns, reviews), whether a person, the app, a bug or a cascade, a copy of the row is kept first in public.deleted_rows, with the table, the row's id, when, and by which database role. public.storelib_restore_deleted_row(id) puts one back (ON CONFLICT DO NOTHING, so a row that exists again is left alone), and public.storelib_purge_deleted_rows() forgets copies older than 90 days, which the daily cron runs. This is the first layer under the backups (docs/operations/backups.md): an undo for the last three months, row by row, without restoring the whole database. Server and editor only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.deleted_rows (id bigserial PRIMARY KEY, table_name text NOT NULL, row_id text, row_data jsonb NOT NULL, deleted_at timestamptz NOT NULL DEFAULT now(), deleted_by text NOT NULL DEFAULT current_user, tx bigint NOT NULL DEFAULT txid_current());
CREATE INDEX IF NOT EXISTS deleted_rows_row_idx ON public.deleted_rows (table_name, row_id);
CREATE INDEX IF NOT EXISTS deleted_rows_when_idx ON public.deleted_rows (deleted_at);
CREATE INDEX IF NOT EXISTS deleted_rows_tx_idx ON public.deleted_rows (tx);
ALTER TABLE public.deleted_rows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.deleted_rows FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_keep_deleted_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE j jsonb := to_jsonb(OLD); BEGIN INSERT INTO public.deleted_rows (table_name, row_id, row_data, deleted_by) VALUES (TG_TABLE_NAME, coalesce(j ->> 'id', j ->> 'creator_id', j ->> 'user_id'), j, session_user || '/' || current_setting('role', true)); RETURN OLD; END $f$;
REVOKE ALL ON FUNCTION public.storelib_keep_deleted_row() FROM PUBLIC, anon, authenticated;
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products', 'product_variants', 'product_variant_files', 'digital_assets', 'courses', 'orders', 'entitlements', 'refunds', 'payouts', 'ledger_events', 'seller_ledger', 'invoices', 'subscriptions', 'creators', 'profiles', 'onepages', 'store_builder_configs', 'store_theme_installs', 'sites', 'site_files', 'site_versions', 'site_collections', 'site_collection_items', 'site_forms', 'custom_domains', 'website_addresses', 'coupons', 'subscribers', 'email_flows', 'email_campaigns', 'email_templates', 'reviews'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_keep_deleted', t); EXECUTE format('CREATE TRIGGER %I AFTER DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row()', t || '_keep_deleted', t); END LOOP; END $do$;
CREATE OR REPLACE FUNCTION public.storelib_restore_deleted_row(p_id bigint) RETURNS boolean LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE r public.deleted_rows%ROWTYPE; n integer; BEGIN SELECT * INTO r FROM public.deleted_rows WHERE id = p_id; IF NOT FOUND OR to_regclass('public.' || r.table_name) IS NULL THEN RETURN false; END IF; EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_record(NULL::public.%I, $1) ON CONFLICT DO NOTHING', r.table_name, r.table_name) USING r.row_data; GET DIAGNOSTICS n = ROW_COUNT; RETURN n > 0; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_purge_deleted_rows(p_keep interval DEFAULT interval '90 days') RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE n integer; BEGIN DELETE FROM public.deleted_rows WHERE id IN (SELECT id FROM public.deleted_rows WHERE deleted_at < now() - p_keep ORDER BY id LIMIT 50000); GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END $f$;
REVOKE ALL ON FUNCTION public.storelib_restore_deleted_row(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_restore_deleted_row(bigint) TO service_role;
REVOKE ALL ON FUNCTION public.storelib_purge_deleted_rows(interval) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_purge_deleted_rows(interval) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('66', '66_deleted_rows_kept.sql', '8360d280e70a0d23896c61c02a4c7f631988513ef2540a055483c430261f1f64') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 67_applied_parts.sql
/* Which SQL parts this database has run, recorded by the database itself. Every run-now part was run by hand in the SQL editor and nothing kept a record, so nobody could say which of them a database had, and the code carried workarounds for columns that "may not exist here". public.storelib_applied_parts holds one row per part: its number, its file, the SHA-256 of the text that ran, when and by which role. The files built from run-now (run-four, all-in-three) write that row right after each part, so running them is the record; the admin's Health view compares it with the parts in the repository (lib/admin/sql-parts.generated.ts) and names any part missing, or changed since it ran. Server and editor only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.storelib_applied_parts (part text PRIMARY KEY, file text NOT NULL, sha256 text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now(), applied_by text NOT NULL DEFAULT current_user);
ALTER TABLE public.storelib_applied_parts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.storelib_applied_parts FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('67', '67_applied_parts.sql', '08d9290e042ca7e3d9b63c2efcbcb5f0e3115a656b5f43202451fdc925e1bf06') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 68_errors_and_job_runs.sql
/* Something breaking is written down and told, once. Errors only reached the Vercel log, which nobody reads at 3am and which forgets within days, and no scheduled job left a record that it ran. public.error_events keeps one row per kind of error (a fingerprint of where and what): how often, first and last seen, the newest context. public.storelib_note_error() counts one and answers whether to tell the owner now: the first time, and again at most once an hour while it keeps happening (lib/observability/report.ts sends the email and the webhook). public.cron_runs records every run of every scheduled job: when it started and finished, whether it worked, what it said; the admin's Health view and /api/health read it to say a job is late or failing. public.storelib_purge_ops_logs() forgets job runs older than 30 days and errors not seen for 90 (the daily storage cleanup runs it). Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.error_events (fingerprint text PRIMARY KEY, source text NOT NULL, location text NOT NULL, message text NOT NULL, count bigint NOT NULL DEFAULT 1, first_seen timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), last_context jsonb NOT NULL DEFAULT '{}'::jsonb, last_alerted_at timestamptz, resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS error_events_last_seen_idx ON public.error_events (last_seen DESC);
ALTER TABLE public.error_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.error_events FROM anon, authenticated;
CREATE TABLE IF NOT EXISTS public.cron_runs (id bigserial PRIMARY KEY, job text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, ok boolean, status integer, detail text);
CREATE INDEX IF NOT EXISTS cron_runs_job_idx ON public.cron_runs (job, started_at DESC);
ALTER TABLE public.cron_runs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cron_runs FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_note_error(p_fingerprint text, p_source text, p_location text, p_message text, p_context jsonb DEFAULT '{}'::jsonb, p_alert_every interval DEFAULT interval '1 hour') RETURNS boolean LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE told boolean; BEGIN INSERT INTO public.error_events AS e (fingerprint, source, location, message, last_context) VALUES (p_fingerprint, left(p_source, 40), left(p_location, 300), left(p_message, 2000), coalesce(p_context, '{}'::jsonb)) ON CONFLICT (fingerprint) DO UPDATE SET count = e.count + 1, last_seen = now(), message = excluded.message, last_context = excluded.last_context, resolved_at = NULL; UPDATE public.error_events SET last_alerted_at = now() WHERE fingerprint = p_fingerprint AND (last_alerted_at IS NULL OR last_alerted_at < now() - p_alert_every) RETURNING true INTO told; RETURN coalesce(told, false); END $f$;
CREATE OR REPLACE FUNCTION public.storelib_purge_ops_logs() RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE a integer; b integer; BEGIN DELETE FROM public.cron_runs WHERE started_at < now() - interval '30 days'; GET DIAGNOSTICS a = ROW_COUNT; DELETE FROM public.error_events WHERE last_seen < now() - interval '90 days'; GET DIAGNOSTICS b = ROW_COUNT; RETURN a + b; END $f$;
REVOKE ALL ON FUNCTION public.storelib_note_error(text, text, text, text, jsonb, interval) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_note_error(text, text, text, text, jsonb, interval) TO service_role;
REVOKE ALL ON FUNCTION public.storelib_purge_ops_logs() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_purge_ops_logs() TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('68', '68_errors_and_job_runs.sql', '728471bf45c353e66c251814848c70ae05d2f959652c6cf350cf36852ec5b476') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 69_stripe_requirements.sql
/* What Stripe is still asking a creator for, kept on their row so a reminder days later can read it: stripe_requirements (Stripe's own keys, like individual.verification.document), stripe_requirements_due_at (the date Stripe gave, when it gave one) and stripe_requirements_updated_at (when the account.updated webhook last wrote them). Only that webhook writes them, with the service role; an account Stripe has cleared gets an empty list, which is what ends a reminder sequence. Storelib knew this only for the seconds an account.updated webhook was being handled, so a notice could be sent once and never followed up; now lib/notify reads it again in the seconds before each follow-up sends (conditions.ts verification_still_needed), and says what is outstanding today instead of what a webhook said last week. Three columns on creators and nothing else: no row changes, no policy changes, no index. Nothing where there is no creators table. Needs nothing else. Until it runs, Stripe's asks are told once as before (PAYOUT_ACTION_REQUIRED, by email and in the bell) and the two follow-up reminders are planned and then skipped when they come due, because there is nothing recorded for them to read. Safe to run again. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'stripe requirements: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements text[]; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements_due_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements_updated_at timestamptz; END IF; END $$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('69', '69_stripe_requirements.sql', 'bffe5658dcf65f1dfda09ff1b45cc2814862aad1a97ad618e78ea47622599ab3') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 70_public_upload_safety.sql
/* The public buckets a browser writes into directly get a size ceiling, and the hourly file pass gets a list of what landed in them. A signed upload URL cannot limit what is sent through it, so a page could ask for "freebie.pdf, 1 KB" and PUT half a gigabyte: `lead-form-files-v2` (link page lead magnets), `product-videos`, `onepage-assets` and `store-builder-images` had no file_size_limit at all, and now they have the one their kind of file needs. Also adds storage_recent_public_objects, which lists what was written into those buckets lately and is NOT a picture the metadata pass already reads, so /api/cron/strip-image-metadata can check videos, lead magnets and anything else the same way it checks pictures (lib/security/uploads/direct.ts). Server only: the function is revoked from anon and authenticated and granted to the service role. Changes no rows in any table; only bucket settings, and only where they were empty or larger. Needs nothing else, and is safe to run twice. Until it runs, uploads and downloads work the same and the hourly pass reads pictures only, as before. */
DO $do$ BEGIN IF to_regclass('storage.buckets') IS NULL THEN RAISE NOTICE 'part 70: there is no storage.buckets here, nothing to set.'; RETURN; END IF; UPDATE storage.buckets SET file_size_limit = 1073741824 WHERE id IN ('lead-form-files-v2', 'lead-form-files') AND (file_size_limit IS NULL OR file_size_limit > 1073741824); UPDATE storage.buckets SET file_size_limit = 2000000000 WHERE id IN ('product-videos', 'onepage-assets', 'store-builder-images') AND (file_size_limit IS NULL OR file_size_limit > 2000000000); END $do$;
CREATE OR REPLACE FUNCTION public.storage_recent_public_objects(p_since_minutes integer DEFAULT 150, p_limit integer DEFAULT 200) RETURNS TABLE (bucket_id text, name text, size bigint, mimetype text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, storage AS $fn$ SELECT o.bucket_id::text, o.name::text, coalesce((o.metadata->>'size')::bigint, 0), coalesce(o.metadata->>'mimetype', '') FROM storage.objects o WHERE o.bucket_id IN ('avatars', 'covers', 'product-images', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'product-videos') AND o.created_at > now() - make_interval(mins => greatest(p_since_minutes, 1)) AND NOT (lower(coalesce(o.metadata->>'mimetype', '')) IN ('image/jpeg', 'image/jpg', 'image/png', 'image/webp') AND coalesce((o.metadata->>'size')::bigint, 0) BETWEEN 1 AND 26214400) ORDER BY o.created_at LIMIT greatest(p_limit, 1); $fn$;
REVOKE ALL ON FUNCTION public.storage_recent_public_objects(integer, integer) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storage_recent_public_objects(integer, integer) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('70', '70_public_upload_safety.sql', '3384ef6721be0e6841e2220692713b58c3d89e6fa5ef7e8ad21d3e644b9cecf9') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 74_course_player.sql
/* Courses that play, remember where each buyer is, and stay private. A course belongs to a product (public.courses), holds modules (public.course_modules) and lessons (public.course_lessons), and each lesson now has its own video kept in the private digital-products bucket (video_path, video_size, video_mime, video_name; the server writes these, a signed in editor cannot point a lesson at somebody else's file), a captions file (captions_path), a free preview switch (is_preview), a running time (duration_seconds) and its downloads (public.lesson_attachments, written by the server only). Each buyer's place is kept per lesson (public.course_progress: completed_at, last_position_seconds) and per course (public.course_enrollments: the last lesson opened, when, how far through, when it was finished, and the progress emails already sent, so a reminder goes at most once a week and never after the course is done). Who may read what is decided in one place, public.storelib_product_access(): the creator reads and edits their own course; a buyer (an entitlement, or a completed order) reads its modules, lessons and downloads and their own progress; anybody reads module titles and the lessons marked as a free preview of a published course. Progress and enrollments are written by the server only. public.course_outline() gives the product page the titles, running times and preview marks of a published course in one call. Every policy these tables had before is replaced. Tables that already exist keep their rows. Needs part 63 for the guard on the video columns (without it the guard is skipped and the server still refuses a path that is not the creator's own). Safe to run again. */
CREATE TABLE IF NOT EXISTS public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL UNIQUE REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz DEFAULT now());
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS public.course_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL, position integer NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.course_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.course_modules(id) ON DELETE CASCADE, title text NOT NULL, position integer NOT NULL DEFAULT 0, content_text text, video_url text, created_at timestamptz DEFAULT now());
ALTER TABLE public.course_lessons ADD COLUMN IF NOT EXISTS video_path text, ADD COLUMN IF NOT EXISTS video_size bigint, ADD COLUMN IF NOT EXISTS video_mime text, ADD COLUMN IF NOT EXISTS video_name text, ADD COLUMN IF NOT EXISTS captions_path text, ADD COLUMN IF NOT EXISTS is_preview boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS duration_seconds integer, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS public.lesson_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.course_lessons(id) ON DELETE CASCADE, file_path text NOT NULL, file_name text NOT NULL, created_at timestamptz DEFAULT now());
ALTER TABLE public.lesson_attachments ADD COLUMN IF NOT EXISTS file_size bigint, ADD COLUMN IF NOT EXISTS mime_type text, ADD COLUMN IF NOT EXISTS position integer NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS public.course_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, lesson_id uuid NOT NULL REFERENCES public.course_lessons(id) ON DELETE CASCADE, completed boolean DEFAULT false, completed_at timestamptz, created_at timestamptz DEFAULT now(), CONSTRAINT unique_buyer_lesson UNIQUE (buyer_id, lesson_id));
ALTER TABLE public.course_progress ADD COLUMN IF NOT EXISTS course_id uuid REFERENCES public.courses(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS last_position_seconds real NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS duration_seconds real, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = 'public.course_progress'::regclass AND i.indisunique AND (SELECT array_agg(a.attname::text ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)) = ARRAY['buyer_id', 'lesson_id']) THEN IF EXISTS (SELECT 1 FROM public.course_progress GROUP BY buyer_id, lesson_id HAVING count(*) > 1) THEN RAISE WARNING 'part 74: a buyer has two progress rows for one lesson, so the one-row-per-lesson key was not added. See them with: select buyer_id, lesson_id, count(*) from public.course_progress group by 1, 2 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX course_progress_buyer_lesson ON public.course_progress (buyer_id, lesson_id); END IF; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.course_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, last_lesson_id uuid REFERENCES public.course_lessons(id) ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), last_opened_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), completed_lessons integer NOT NULL DEFAULT 0, total_lessons integer NOT NULL DEFAULT 0, percent integer NOT NULL DEFAULT 0 CHECK (percent BETWEEN 0 AND 100), completed_at timestamptz, emails_off boolean NOT NULL DEFAULT false, last_nudge_at timestamptz, nudges_sent integer NOT NULL DEFAULT 0, completion_emailed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (buyer_id, course_id));
CREATE INDEX IF NOT EXISTS idx_course_modules_course ON public.course_modules (course_id, position);
CREATE INDEX IF NOT EXISTS idx_course_lessons_module ON public.course_lessons (module_id, position);
CREATE INDEX IF NOT EXISTS idx_lesson_attachments_lesson ON public.lesson_attachments (lesson_id, position);
CREATE INDEX IF NOT EXISTS idx_course_progress_buyer_course ON public.course_progress (buyer_id, course_id);
CREATE INDEX IF NOT EXISTS idx_course_progress_lesson ON public.course_progress (lesson_id);
CREATE INDEX IF NOT EXISTS course_enrollments_buyer_idx ON public.course_enrollments (buyer_id, last_opened_at DESC);
CREATE INDEX IF NOT EXISTS course_enrollments_nudge_idx ON public.course_enrollments (last_activity_at) WHERE completed_at IS NULL AND emails_off = false;
CREATE INDEX IF NOT EXISTS course_enrollments_finished_idx ON public.course_enrollments (completed_at) WHERE completed_at IS NOT NULL AND completion_emailed_at IS NULL;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_modules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_lessons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lesson_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_enrollments ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.storelib_product_access(p_product_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT CASE WHEN (SELECT auth.uid()) IS NOT NULL AND c.user_id = (SELECT auth.uid()) THEN 'creator' WHEN (SELECT auth.uid()) IS NOT NULL AND (EXISTS (SELECT 1 FROM public.entitlements e WHERE e.product_id = p.id AND e.buyer_id = (SELECT auth.uid())) OR EXISTS (SELECT 1 FROM public.orders o WHERE o.product_id = p.id AND o.buyer_id = (SELECT auth.uid()) AND o.status = 'completed')) THEN 'owner' WHEN p.status = 'published' THEN 'public' ELSE 'none' END FROM public.products p LEFT JOIN public.creators c ON c.id = p.creator_id WHERE p.id = p_product_id $f$;
CREATE OR REPLACE FUNCTION public.storelib_course_access(p_course_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT public.storelib_product_access(co.product_id) FROM public.courses co WHERE co.id = p_course_id), 'none') $f$;
CREATE OR REPLACE FUNCTION public.storelib_module_access(p_module_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT public.storelib_course_access(m.course_id) FROM public.course_modules m WHERE m.id = p_module_id), 'none') $f$;
CREATE OR REPLACE FUNCTION public.storelib_lesson_access(p_lesson_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT CASE WHEN a.level IN ('creator', 'owner') THEN a.level WHEN l.is_preview AND a.level = 'public' THEN 'preview' ELSE 'none' END FROM public.course_lessons l CROSS JOIN LATERAL (SELECT public.storelib_module_access(l.module_id) AS level) a WHERE l.id = p_lesson_id), 'none') $f$;
REVOKE ALL ON FUNCTION public.storelib_product_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_course_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_module_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_lesson_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.storelib_product_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_course_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_module_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_lesson_access(uuid) TO anon, authenticated, service_role;
DO $do$ DECLARE p record; BEGIN FOR p IN SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('courses', 'course_modules', 'course_lessons', 'lesson_attachments', 'course_progress', 'course_enrollments') LOOP EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, p.tablename); END LOOP; END $do$;
CREATE POLICY courses_read ON public.courses FOR SELECT TO anon, authenticated USING (public.storelib_course_access(id) IN ('creator', 'owner', 'public'));
CREATE POLICY courses_creator_insert ON public.courses FOR INSERT TO authenticated WITH CHECK (public.storelib_product_access(product_id) = 'creator');
CREATE POLICY courses_creator_update ON public.courses FOR UPDATE TO authenticated USING (public.storelib_course_access(id) = 'creator') WITH CHECK (public.storelib_product_access(product_id) = 'creator');
CREATE POLICY courses_creator_delete ON public.courses FOR DELETE TO authenticated USING (public.storelib_course_access(id) = 'creator');
CREATE POLICY course_modules_read ON public.course_modules FOR SELECT TO anon, authenticated USING (public.storelib_course_access(course_id) IN ('creator', 'owner', 'public'));
CREATE POLICY course_modules_creator_insert ON public.course_modules FOR INSERT TO authenticated WITH CHECK (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_modules_creator_update ON public.course_modules FOR UPDATE TO authenticated USING (public.storelib_course_access(course_id) = 'creator') WITH CHECK (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_modules_creator_delete ON public.course_modules FOR DELETE TO authenticated USING (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_lessons_read ON public.course_lessons FOR SELECT TO anon, authenticated USING (public.storelib_module_access(module_id) IN ('creator', 'owner') OR (is_preview AND public.storelib_module_access(module_id) = 'public'));
CREATE POLICY course_lessons_creator_insert ON public.course_lessons FOR INSERT TO authenticated WITH CHECK (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY course_lessons_creator_update ON public.course_lessons FOR UPDATE TO authenticated USING (public.storelib_module_access(module_id) = 'creator') WITH CHECK (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY course_lessons_creator_delete ON public.course_lessons FOR DELETE TO authenticated USING (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY lesson_attachments_read ON public.lesson_attachments FOR SELECT TO authenticated USING (public.storelib_lesson_access(lesson_id) IN ('creator', 'owner'));
CREATE POLICY course_progress_own ON public.course_progress FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid()));
CREATE POLICY course_enrollments_own ON public.course_enrollments FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid()));
REVOKE INSERT, UPDATE, DELETE ON public.lesson_attachments, public.course_progress, public.course_enrollments FROM anon, authenticated;
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_server_columns()') IS NULL THEN RAISE NOTICE 'part 74: part 63 has not run, so the lesson video columns are guarded by the server only.'; ELSE DROP TRIGGER IF EXISTS course_lessons_keep_server_columns ON public.course_lessons; CREATE TRIGGER course_lessons_keep_server_columns BEFORE INSERT OR UPDATE ON public.course_lessons FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('video_path', 'video_size', 'video_mime', 'video_name', 'captions_path'); END IF; END $do$;
CREATE OR REPLACE FUNCTION public.course_outline(p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'title', m.title, 'lessons', coalesce((SELECT jsonb_agg(jsonb_build_object('id', l.id, 'title', l.title, 'module_id', l.module_id, 'duration_seconds', l.duration_seconds, 'is_preview', l.is_preview, 'has_video', l.video_path IS NOT NULL OR coalesce(l.video_url, '') <> '') ORDER BY l.position, l.created_at) FROM public.course_lessons l WHERE l.module_id = m.id), '[]'::jsonb)) ORDER BY m.position, m.created_at), '[]'::jsonb) FROM public.courses co JOIN public.products p ON p.id = co.product_id JOIN public.course_modules m ON m.course_id = co.id WHERE co.product_id = p_product_id AND (p.status = 'published' OR public.storelib_product_access(p.id) = 'creator') $f$;
REVOKE ALL ON FUNCTION public.course_outline(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.course_outline(uuid) TO anon, authenticated, service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('74', '74_course_player.sql', '90bc906507a3c7edf3a4090ed627ea8c1ec4c5e9198899f0c21d927d0d252071') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 75_memberships.sql
/* Memberships: a product a buyer pays for every month or every year, with posts only its members read. `products.type` takes `membership` (every value it already allows is kept). `membership_plans` is a membership's monthly and yearly price, free trial days, what members get and the products included with it, one row per product; the Stripe price ids on it are the server's. `memberships` is one buyer's subscription as Stripe last said it (active, trialing, past_due, canceled with the period still running, expired), its period end, cancel at period end and card, kept in step by the Stripe webhook; `membership_invoices` is each payment, once per Stripe invoice. `membership_posts` are the creator's updates (text, pictures, files, linked products), `membership_post_reads` which posts a member has opened, `membership_post_emails` one row per member per update so each email goes once. `entitlements.membership_id` marks a library row that a membership granted, so it goes when the membership ends. `membership_grants_access` is the one rule for access (active, trialing, canceled until the period ends, past_due for 7 days) and `membership_access(product)` answers it for the signed in person, by account or by their confirmed email; row level security on posts uses it. Members read their own memberships, invoices and reads; creators read their members and posts; every write is the server's. Needs nothing else. Until it runs, the membership pages say memberships are not set up and nothing else changes. Safe to run again. */
DO $do$ DECLARE def text; BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'memberships: there is no products table, nothing to do.'; RETURN; END IF; SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conname = 'products_type_check' AND conrelid = 'public.products'::regclass; IF def IS NULL OR def LIKE '%''membership''%' THEN RETURN; END IF; ALTER TABLE public.products DROP CONSTRAINT products_type_check; IF def LIKE '%ARRAY[%' THEN EXECUTE 'ALTER TABLE public.products ADD CONSTRAINT products_type_check ' || replace(def, 'ARRAY[', 'ARRAY[''membership''::text, ') || ' NOT VALID'; ELSE ALTER TABLE public.products ADD CONSTRAINT products_type_check CHECK (type IN ('digital', 'course', 'community', 'physical', 'membership')) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.membership_plans (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, monthly_price_cents integer, yearly_price_cents integer, trial_days integer NOT NULL DEFAULT 0, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, included_product_ids uuid[] NOT NULL DEFAULT '{}', currency text NOT NULL DEFAULT 'usd', stripe_product_id text, stripe_monthly_price_id text, stripe_monthly_price_cents integer, stripe_yearly_price_id text, stripe_yearly_price_cents integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_plans_prices CHECK ((monthly_price_cents IS NULL OR monthly_price_cents BETWEEN 100 AND 1000000) AND (yearly_price_cents IS NULL OR yearly_price_cents BETWEEN 100 AND 10000000)), CONSTRAINT membership_plans_trial CHECK (trial_days BETWEEN 0 AND 90), CONSTRAINT membership_plans_benefits CHECK (jsonb_typeof(benefits) = 'array'));
CREATE INDEX IF NOT EXISTS membership_plans_creator_idx ON public.membership_plans (creator_id);
CREATE TABLE IF NOT EXISTS public.memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, buyer_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, buyer_email text NOT NULL, buyer_name text, title text, stripe_subscription_id text NOT NULL, stripe_customer_id text, stripe_price_id text, billing_interval text NOT NULL DEFAULT 'month', amount_cents integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'usd', status text NOT NULL DEFAULT 'incomplete', stripe_status text, trial_end timestamptz, current_period_start timestamptz, current_period_end timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, canceled_at timestamptz, ended_at timestamptz, past_due_since timestamptz, started_at timestamptz, card_brand text, card_last4 text, email_updates boolean NOT NULL DEFAULT true, synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT memberships_subscription_once UNIQUE (stripe_subscription_id), CONSTRAINT memberships_status_check CHECK (status IN ('incomplete', 'trialing', 'active', 'past_due', 'canceled', 'expired')), CONSTRAINT memberships_interval_check CHECK (billing_interval IN ('month', 'year')), CONSTRAINT memberships_email_lower CHECK (buyer_email = lower(buyer_email)));
CREATE INDEX IF NOT EXISTS memberships_buyer_idx ON public.memberships (buyer_id) WHERE buyer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS memberships_email_idx ON public.memberships (buyer_email);
CREATE INDEX IF NOT EXISTS memberships_product_status_idx ON public.memberships (product_id, status);
CREATE INDEX IF NOT EXISTS memberships_creator_idx ON public.memberships (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS memberships_renewing_idx ON public.memberships (current_period_end) WHERE status IN ('active', 'trialing') AND cancel_at_period_end = false;
CREATE TABLE IF NOT EXISTS public.membership_invoices (stripe_invoice_id text PRIMARY KEY, membership_id uuid NOT NULL REFERENCES public.memberships(id) ON DELETE CASCADE, order_id uuid, amount_cents integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'usd', status text NOT NULL DEFAULT 'paid', billing_reason text, period_start timestamptz, period_end timestamptz, paid_at timestamptz, hosted_invoice_url text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_invoices_status_check CHECK (status IN ('paid', 'failed', 'open', 'void')));
CREATE INDEX IF NOT EXISTS membership_invoices_membership_idx ON public.membership_invoices (membership_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.membership_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', images jsonb NOT NULL DEFAULT '[]'::jsonb, attachments jsonb NOT NULL DEFAULT '[]'::jsonb, linked_product_ids uuid[] NOT NULL DEFAULT '{}', published_at timestamptz NOT NULL DEFAULT now(), email_status text NOT NULL DEFAULT 'none', emailed_count integer NOT NULL DEFAULT 0, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT membership_posts_title_len CHECK (char_length(title) <= 200), CONSTRAINT membership_posts_body_len CHECK (char_length(body) <= 20000), CONSTRAINT membership_posts_email_status_check CHECK (email_status IN ('none', 'queued', 'sending', 'sent')), CONSTRAINT membership_posts_shape CHECK (jsonb_typeof(images) = 'array' AND jsonb_typeof(attachments) = 'array'));
CREATE INDEX IF NOT EXISTS membership_posts_feed_idx ON public.membership_posts (product_id, published_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS public.membership_post_reads (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES public.membership_posts(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id));
CREATE INDEX IF NOT EXISTS membership_post_reads_post_idx ON public.membership_post_reads (post_id);
CREATE TABLE IF NOT EXISTS public.membership_post_emails (post_id uuid NOT NULL REFERENCES public.membership_posts(id) ON DELETE CASCADE, membership_id uuid NOT NULL REFERENCES public.memberships(id) ON DELETE CASCADE, email text NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (post_id, membership_id), CONSTRAINT membership_post_emails_status_check CHECK (status IN ('pending', 'sent', 'skipped', 'failed')));
CREATE INDEX IF NOT EXISTS membership_post_emails_pending_idx ON public.membership_post_emails (created_at) WHERE status = 'pending';
DO $do$ BEGIN IF to_regclass('public.entitlements') IS NULL THEN RAISE NOTICE 'memberships: there is no entitlements table, included products are not granted here.'; RETURN; END IF; ALTER TABLE public.entitlements ADD COLUMN IF NOT EXISTS membership_id uuid REFERENCES public.memberships(id) ON DELETE CASCADE; CREATE INDEX IF NOT EXISTS entitlements_membership_idx ON public.entitlements (membership_id) WHERE membership_id IS NOT NULL; END $do$;
CREATE OR REPLACE FUNCTION public.membership_grants_access(p_status text, p_period_end timestamptz, p_past_due_since timestamptz, p_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = public AS $f$ SELECT CASE WHEN p_status IN ('active', 'trialing') THEN true WHEN p_status = 'canceled' THEN p_period_end IS NOT NULL AND p_period_end > p_at WHEN p_status = 'past_due' THEN p_past_due_since IS NULL OR p_past_due_since > p_at - interval '7 days' ELSE false END $f$;
CREATE OR REPLACE FUNCTION public.membership_access(p_product_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT auth.uid() IS NOT NULL AND (EXISTS (SELECT 1 FROM public.products p JOIN public.creators c ON c.id = p.creator_id WHERE p.id = p_product_id AND c.user_id = auth.uid()) OR EXISTS (SELECT 1 FROM public.memberships m WHERE m.product_id = p_product_id AND public.membership_grants_access(m.status, m.current_period_end, m.past_due_since, now()) AND (m.buyer_id = auth.uid() OR m.buyer_email = (SELECT lower(u.email::text) FROM auth.users u WHERE u.id = auth.uid() AND u.email_confirmed_at IS NOT NULL)))) $f$;
REVOKE ALL ON FUNCTION public.membership_access(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.membership_access(uuid) TO authenticated, service_role;
ALTER TABLE public.membership_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_post_reads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.membership_post_emails ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.membership_plans, public.memberships, public.membership_invoices, public.membership_posts, public.membership_post_reads, public.membership_post_emails FROM anon, authenticated;
GRANT SELECT (product_id, creator_id, monthly_price_cents, yearly_price_cents, trial_days, benefits, included_product_ids, currency, updated_at) ON public.membership_plans TO anon, authenticated;
GRANT SELECT ON public.memberships, public.membership_invoices, public.membership_posts, public.membership_post_reads TO authenticated;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib plan of a published membership" ON public.membership_plans; CREATE POLICY "storelib plan of a published membership" ON public.membership_plans FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id = membership_plans.product_id AND p.status = 'published')); DROP POLICY IF EXISTS "storelib creator reads own plan" ON public.membership_plans; CREATE POLICY "storelib creator reads own plan" ON public.membership_plans FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = membership_plans.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member reads own membership" ON public.memberships; CREATE POLICY "storelib member reads own membership" ON public.memberships FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid())); DROP POLICY IF EXISTS "storelib creator reads members" ON public.memberships; CREATE POLICY "storelib creator reads members" ON public.memberships FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = memberships.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member or creator reads invoices" ON public.membership_invoices; CREATE POLICY "storelib member or creator reads invoices" ON public.membership_invoices FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.memberships m WHERE m.id = membership_invoices.membership_id AND (m.buyer_id = (SELECT auth.uid()) OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = m.creator_id AND c.user_id = (SELECT auth.uid()))))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read posts" ON public.membership_posts; CREATE POLICY "storelib members read posts" ON public.membership_posts FOR SELECT TO authenticated USING (deleted_at IS NULL AND public.membership_access(product_id)); DROP POLICY IF EXISTS "storelib creator reads own posts" ON public.membership_posts; CREATE POLICY "storelib creator reads own posts" ON public.membership_posts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = membership_posts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member reads own post reads" ON public.membership_post_reads; CREATE POLICY "storelib member reads own post reads" ON public.membership_post_reads FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid())); END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS memberships_keep_deleted ON public.memberships; CREATE TRIGGER memberships_keep_deleted BEFORE DELETE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS membership_posts_keep_deleted ON public.membership_posts; CREATE TRIGGER membership_posts_keep_deleted BEFORE DELETE ON public.membership_posts FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS membership_plans_keep_deleted ON public.membership_plans; CREATE TRIGGER membership_plans_keep_deleted BEFORE DELETE ON public.membership_plans FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('75', '75_memberships.sql', 'a310dc6e996f85f4e598ecd2fadd0ddee081dcd16fb36c752b2e8ce2fb40c819') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 76_storelib_payments.sql
/* Storelib Payments on Airwallex, alongside Stripe and switched off until a creator is put on it. `payment_accounts` is a creator's Airwallex connected account as Airwallex last described it: the account id, individual or business, the lifecycle status exactly as Airwallex sent it (CREATED, SUBMITTED, ACTION_REQUIRED, ACTIVE, SUSPENDED, DORMANT, CLOSED, or a newer value kept as sent), the onboarding form's own status apart from it, what Airwallex is asking for (codes only, nothing personal), and a masked payout destination (bank name, country, currency, last four). `payment_webhook_events` is every Airwallex event id once, so a retried or repeated delivery changes nothing, with no payload kept. `payment_audit_log` is every change of payment or payout state and who caused it. `payment_fee_records` is each Airwallex payment: the total, Storelib's fee, the creator's share, and what was refunded or taken back. `payment_balances` is the creator's wallet balances as Airwallex last reported them, per currency. `payment_payouts` is each payout Storelib asked Airwallex for, under its own id so a retry cannot pay twice. `orders.provider_payment_id` is the Airwallex payment an order came from (`orders.provider` already says which provider), held unique. Every table is the server's alone: row level security on, no policy, and no grant to the public or signed in keys. Changes nothing for Stripe creators. Needs nothing else. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.payment_accounts (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('airwallex')), provider_account_id text UNIQUE CHECK (provider_account_id IS NULL OR provider_account_id ~ '^acct_[A-Za-z0-9_-]+$'), account_kind text CHECK (account_kind IN ('individual', 'business')), country text CHECK (country IS NULL OR country ~ '^[A-Z]{2}$'), lifecycle_status text CHECK (lifecycle_status IS NULL OR length(lifecycle_status) <= 40), form_status text CHECK (form_status IS NULL OR form_status IN ('INIT', 'SUBMITTED', 'SUCCESS', 'FAILURE')), next_action_type text CHECK (next_action_type IS NULL OR length(next_action_type) <= 80), requirements jsonb, hosted_flow_id text, payout_beneficiary_id text, payout_destination jsonb, consent_at timestamptz, status_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (creator_id, provider));
CREATE TABLE IF NOT EXISTS public.payment_webhook_events (provider text NOT NULL, event_id text NOT NULL CHECK (length(event_id) BETWEEN 1 AND 200), name text NOT NULL CHECK (length(name) <= 120), account_id text, object_id text, event_created_at timestamptz, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, outcome text NOT NULL DEFAULT 'processing' CHECK (outcome IN ('processing', 'done', 'ignored', 'failed')), error text CHECK (error IS NULL OR length(error) <= 500), attempts integer NOT NULL DEFAULT 1, PRIMARY KEY (provider, event_id));
CREATE TABLE IF NOT EXISTS public.payment_audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, provider text NOT NULL, kind text NOT NULL CHECK (length(kind) <= 60), from_state text CHECK (from_state IS NULL OR length(from_state) <= 60), to_state text CHECK (to_state IS NULL OR length(to_state) <= 60), ref text CHECK (ref IS NULL OR length(ref) <= 200), actor text NOT NULL CHECK (actor IN ('creator', 'webhook', 'system', 'admin')));
CREATE TABLE IF NOT EXISTS public.payment_fee_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_payment_id text NOT NULL, checkout_id text NOT NULL, creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), gross_minor bigint NOT NULL CHECK (gross_minor >= 0), platform_fee_minor bigint NOT NULL CHECK (platform_fee_minor >= 0), creator_share_minor bigint NOT NULL CHECK (creator_share_minor >= 0), refunded_minor bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0), clawed_back_minor bigint NOT NULL DEFAULT 0 CHECK (clawed_back_minor >= 0), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'succeeded', 'failed', 'cancelled', 'refunded', 'partially_refunded', 'disputed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT payment_fee_records_split CHECK (platform_fee_minor + creator_share_minor = gross_minor), UNIQUE (provider, provider_payment_id));
CREATE TABLE IF NOT EXISTS public.payment_balances (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), available_minor bigint NOT NULL DEFAULT 0, pending_minor bigint NOT NULL DEFAULT 0, reserved_minor bigint NOT NULL DEFAULT 0, fetched_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (creator_id, provider, currency));
CREATE TABLE IF NOT EXISTS public.payment_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, provider_transfer_id text UNIQUE, amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), status text NOT NULL DEFAULT 'requested' CHECK (length(status) <= 60), destination jsonb, failure_reason text CHECK (failure_reason IS NULL OR length(failure_reason) <= 300), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_webhook_events_account_idx ON public.payment_webhook_events (account_id, received_at DESC) WHERE account_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS payment_webhook_events_unfinished_idx ON public.payment_webhook_events (received_at) WHERE outcome IN ('processing', 'failed');
CREATE INDEX IF NOT EXISTS payment_audit_log_creator_idx ON public.payment_audit_log (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payment_fee_records_creator_idx ON public.payment_fee_records (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payment_payouts_creator_idx ON public.payment_payouts (creator_id, created_at DESC);
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'storelib payments: there is no orders table, orders are not linked here.'; RETURN; END IF; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS provider_payment_id text; CREATE UNIQUE INDEX IF NOT EXISTS orders_provider_payment_id_key ON public.orders (provider_payment_id) WHERE provider_payment_id IS NOT NULL; END $do$;
ALTER TABLE public.payment_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_fee_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_payouts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.payment_accounts, public.payment_webhook_events, public.payment_audit_log, public.payment_fee_records, public.payment_balances, public.payment_payouts FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('76', '76_storelib_payments.sql', 'a85ad8d952206216837306de057aeb9770e79b86dd1fd91f22d35a65ac698c66') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 77_payments_status.sql
/* Storelib Payments status, cached on the creator's row: payments_status (NOT_STARTED, INCOMPLETE, VERIFYING, ACTION_REQUIRED, BANK_REQUIRED, ACTIVE, RESTRICTED, PAYOUT_FAILED or SUSPENDED, worked out from the Stripe account by lib/payments/stripe/status.ts) and last_stripe_sync_at (when the server last read the account from Stripe). Only the server writes them, after reading Stripe; Stripe stays the judge and the app re-reads it whenever the payments page opens. Private, like the other Stripe columns (part 63). Safe to run more than once. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'payments status: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS payments_status text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS last_stripe_sync_at timestamptz; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_payments_status_check; ALTER TABLE public.creators ADD CONSTRAINT creators_payments_status_check CHECK (payments_status IS NULL OR payments_status IN ('NOT_STARTED','INCOMPLETE','VERIFYING','ACTION_REQUIRED','BANK_REQUIRED','ACTIVE','RESTRICTED','PAYOUT_FAILED','SUSPENDED')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('77', '77_payments_status.sql', '32c90d1654fc73a5e1c1358ffc60f1d8a41d5ee2b513a4649ba0ab38c08e5c7f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 78_physical_commerce.sql
/* Storelib physical commerce, complete. Paste all of it into the Supabase SQL editor and press Run. Safe to run again and safe on a database that ran an earlier version of this part: every step checks before it changes anything, nothing existing is dropped or rewritten, and a second run changes nothing. Off until an admin turns it on in /admin (platform_settings physical_commerce_enabled, seeded false). What it adds: physical products (products.type 'physical') with shipping weight and size, units, tax, how each product or variant is fulfilled (shipped by the seller, a warehouse or 3PL, a dropshipping supplier, print on demand), up to three options (Size, Color, Material) whose combinations are the existing product_variants with their own price, stock, SKU (optional), weight and image; stock per variant and location with a history of every change and holds that can never oversell; locations that can offer local pickup with instructions and a preparation time; shipping profiles (one general, any number of custom) with zones of countries or states and rates that are flat, free, by order price, by order weight or by item weight, each with a delivery estimate; tax rates; physical checkouts (shipped or picked up) whose lines become ordinary orders; orders that move Unfulfilled, Processing, Shipped, Delivered with several shipments each carrying carrier and tracking; returns, transfers, collections, integrations (secrets encrypted by the app), a job queue for emails and low stock alerts, and an append only order timeline. Row level security is on for every table: creators read their own rows, buyers read published options and collections, and only the server writes. */
/* 1. The switch, off until /admin turns it on */
CREATE TABLE IF NOT EXISTS public.platform_settings (
  key text PRIMARY KEY,
  value jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);
ALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.platform_settings FROM anon, authenticated;
INSERT INTO public.platform_settings (key, value) VALUES ('physical_commerce_enabled', 'false'::jsonb) ON CONFLICT (key) DO NOTHING;
/* 2. Products: the physical type and its shipping, stock, tax and fulfilment fields */
DO $do$
DECLARE def text;
BEGIN
  SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conname = 'products_type_check' AND conrelid = 'public.products'::regclass;
  IF def IS NULL OR def LIKE '%''physical''%' THEN RETURN; END IF;
  def := regexp_replace(def, '\s+NOT VALID\s*$', '');
  ALTER TABLE public.products DROP CONSTRAINT products_type_check;
  IF def LIKE '%ARRAY[%' THEN
    EXECUTE 'ALTER TABLE public.products ADD CONSTRAINT products_type_check ' || replace(def, 'ARRAY[', 'ARRAY[''physical''::text, ') || ' NOT VALID';
  ELSE
    ALTER TABLE public.products ADD CONSTRAINT products_type_check CHECK (type IN ('membership', 'digital', 'course', 'community', 'physical', 'service')) NOT VALID;
  END IF;
END $do$;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS vendor text CHECK (vendor IS NULL OR length(vendor) <= 120);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS tags text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality(tags) <= 50);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS requires_shipping boolean NOT NULL DEFAULT false;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS weight_grams integer CHECK (weight_grams IS NULL OR weight_grams BETWEEN 0 AND 1000000);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS length_mm integer CHECK (length_mm IS NULL OR length_mm BETWEEN 0 AND 10000);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS width_mm integer CHECK (width_mm IS NULL OR width_mm BETWEEN 0 AND 10000);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS height_mm integer CHECK (height_mm IS NULL OR height_mm BETWEEN 0 AND 10000);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS weight_unit text NOT NULL DEFAULT 'kg' CHECK (weight_unit IN ('g', 'kg', 'oz', 'lb'));
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS dimension_unit text NOT NULL DEFAULT 'cm' CHECK (dimension_unit IN ('cm', 'in'));
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS origin_country text CHECK (origin_country IS NULL OR origin_country ~ '^[A-Z]{2}$');
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS hs_code text CHECK (hs_code IS NULL OR hs_code ~ '^[0-9.]{4,14}$');
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS taxable boolean NOT NULL DEFAULT true;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS tax_category text CHECK (tax_category IS NULL OR length(tax_category) <= 60);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS track_inventory boolean NOT NULL DEFAULT true;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS continue_selling boolean NOT NULL DEFAULT false;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS low_stock_threshold integer CHECK (low_stock_threshold IS NULL OR low_stock_threshold BETWEEN 0 AND 1000000);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS fulfillment_method text NOT NULL DEFAULT 'self' CHECK (fulfillment_method IN ('self', 'warehouse', 'dropship', 'print_on_demand'));
CREATE INDEX IF NOT EXISTS products_physical_creator_idx ON public.products (creator_id, created_at DESC) WHERE type = 'physical';
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'tags' AND data_type = 'ARRAY') THEN
    CREATE INDEX IF NOT EXISTS products_tags_idx ON public.products USING gin (tags);
  END IF;
END $do$;
/* 3. Integrations: the services that can fulfil or ship, secrets encrypted by the app before they are stored */
CREATE TABLE IF NOT EXISTS public.commerce_integrations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost')),
  category text NOT NULL CHECK (category IN ('fulfillment', 'print_on_demand', 'dropshipping', 'supplier', 'shipping')),
  status text NOT NULL DEFAULT 'disconnected' CHECK (status IN ('connected', 'disconnected', 'error', 'needs_setup')),
  account_label text CHECK (account_label IS NULL OR length(account_label) <= 120),
  config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object' AND pg_column_size(config) <= 8192),
  secret_ciphertext text CHECK (secret_ciphertext IS NULL OR length(secret_ciphertext) <= 4096),
  webhook_secret_ciphertext text CHECK (webhook_secret_ciphertext IS NULL OR length(webhook_secret_ciphertext) <= 4096),
  last_sync_at timestamptz,
  last_error text CHECK (last_error IS NULL OR length(last_error) <= 500),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (creator_id, provider)
);
/* 4. Locations: where stock is kept, where orders ship from, and where buyers can pick up */
CREATE TABLE IF NOT EXISTS public.inventory_locations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  kind text NOT NULL DEFAULT 'home' CHECK (kind IN ('home', 'warehouse', 'print_on_demand', 'dropshipper', 'supplier', 'third_party_logistics', 'retail', 'custom')),
  address_line1 text CHECK (address_line1 IS NULL OR length(address_line1) <= 200),
  address_line2 text CHECK (address_line2 IS NULL OR length(address_line2) <= 200),
  city text CHECK (city IS NULL OR length(city) <= 120),
  region text CHECK (region IS NULL OR length(region) <= 120),
  postal_code text CHECK (postal_code IS NULL OR length(postal_code) <= 20),
  country text CHECK (country IS NULL OR country ~ '^[A-Z]{2}$'),
  phone text CHECK (phone IS NULL OR length(phone) <= 40),
  email text CHECK (email IS NULL OR length(email) <= 254),
  active boolean NOT NULL DEFAULT true,
  fulfills_orders boolean NOT NULL DEFAULT true,
  holds_inventory boolean NOT NULL DEFAULT true,
  priority integer NOT NULL DEFAULT 0,
  forwarding text NOT NULL DEFAULT 'none' CHECK (forwarding IN ('none', 'email', 'webhook', 'provider')),
  integration_id uuid REFERENCES public.commerce_integrations(id) ON DELETE SET NULL,
  notes text CHECK (notes IS NULL OR length(notes) <= 1000),
  pickup_enabled boolean NOT NULL DEFAULT false,
  pickup_instructions text CHECK (pickup_instructions IS NULL OR length(pickup_instructions) <= 1000),
  pickup_ready text NOT NULL DEFAULT '24h' CHECK (pickup_ready IN ('1h', '2h', '4h', '24h', '2_4d', '5d')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS pickup_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS pickup_instructions text CHECK (pickup_instructions IS NULL OR length(pickup_instructions) <= 1000);
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS pickup_ready text NOT NULL DEFAULT '24h' CHECK (pickup_ready IN ('1h', '2h', '4h', '24h', '2_4d', '5d'));
CREATE UNIQUE INDEX IF NOT EXISTS inventory_locations_name_key ON public.inventory_locations (creator_id, lower(name));
CREATE INDEX IF NOT EXISTS inventory_locations_creator_idx ON public.inventory_locations (creator_id, priority DESC, created_at);
CREATE INDEX IF NOT EXISTS inventory_locations_pickup_idx ON public.inventory_locations (creator_id) WHERE pickup_enabled AND active;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS fulfillment_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL;
/* 5. Shipping profiles, zones and rates */
CREATE TABLE IF NOT EXISTS public.shipping_profiles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  is_default boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS shipping_profiles_one_default ON public.shipping_profiles (creator_id) WHERE is_default;
CREATE INDEX IF NOT EXISTS shipping_profiles_creator_idx ON public.shipping_profiles (creator_id, created_at);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS shipping_profile_id uuid REFERENCES public.shipping_profiles(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS public.shipping_zones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.shipping_profiles(id) ON DELETE CASCADE,
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  countries text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality(countries) <= 250),
  regions text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality(regions) <= 500),
  rest_of_world boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.shipping_zones ADD COLUMN IF NOT EXISTS regions text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality(regions) <= 500);
ALTER TABLE public.shipping_zones DROP CONSTRAINT IF EXISTS shipping_zones_has_destination;
ALTER TABLE public.shipping_zones ADD CONSTRAINT shipping_zones_has_destination CHECK (rest_of_world OR cardinality(countries) > 0 OR cardinality(regions) > 0);
CREATE INDEX IF NOT EXISTS shipping_zones_profile_idx ON public.shipping_zones (profile_id);
CREATE INDEX IF NOT EXISTS shipping_zones_countries_idx ON public.shipping_zones USING gin (countries);
CREATE TABLE IF NOT EXISTS public.shipping_rates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  zone_id uuid NOT NULL REFERENCES public.shipping_zones(id) ON DELETE CASCADE,
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  kind text NOT NULL DEFAULT 'flat',
  price_cents integer NOT NULL DEFAULT 0 CHECK (price_cents BETWEEN 0 AND 10000000),
  min_value integer CHECK (min_value IS NULL OR min_value >= 0),
  max_value integer CHECK (max_value IS NULL OR max_value >= 0),
  tiers jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(tiers) = 'array' AND jsonb_array_length(tiers) <= 20),
  free_over_cents integer CHECK (free_over_cents IS NULL OR free_over_cents >= 0),
  min_days smallint CHECK (min_days IS NULL OR min_days BETWEEN 0 AND 365),
  max_days smallint CHECK (max_days IS NULL OR max_days BETWEEN 0 AND 365),
  carrier text CHECK (carrier IS NULL OR length(carrier) <= 60),
  service_code text CHECK (service_code IS NULL OR length(service_code) <= 60),
  active boolean NOT NULL DEFAULT true,
  position integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT shipping_rates_days CHECK (min_days IS NULL OR max_days IS NULL OR min_days <= max_days),
  CONSTRAINT shipping_rates_range CHECK (min_value IS NULL OR max_value IS NULL OR min_value <= max_value)
);
ALTER TABLE public.shipping_rates ADD COLUMN IF NOT EXISTS tiers jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(tiers) = 'array' AND jsonb_array_length(tiers) <= 20);
ALTER TABLE public.shipping_rates DROP CONSTRAINT IF EXISTS shipping_rates_kind_check;
ALTER TABLE public.shipping_rates ADD CONSTRAINT shipping_rates_kind_check CHECK (kind IN ('flat', 'free', 'price', 'weight', 'item_weight', 'quantity', 'carrier'));
CREATE INDEX IF NOT EXISTS shipping_rates_zone_idx ON public.shipping_rates (zone_id, position);
/* 6. Packages, the shop's commerce settings and its tax rates */
CREATE TABLE IF NOT EXISTS public.shipping_packages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  kind text NOT NULL DEFAULT 'box' CHECK (kind IN ('box', 'envelope', 'soft_package')),
  length_mm integer NOT NULL CHECK (length_mm BETWEEN 1 AND 10000),
  width_mm integer NOT NULL CHECK (width_mm BETWEEN 1 AND 10000),
  height_mm integer NOT NULL CHECK (height_mm BETWEEN 0 AND 10000),
  weight_grams integer NOT NULL DEFAULT 0 CHECK (weight_grams BETWEEN 0 AND 1000000),
  is_default boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS shipping_packages_one_default ON public.shipping_packages (creator_id) WHERE is_default;
CREATE TABLE IF NOT EXISTS public.commerce_settings (
  creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE,
  fulfillment_model text CHECK (fulfillment_model IS NULL OR fulfillment_model IN ('self', 'warehouse', 'print_on_demand', 'dropshipping', 'supplier', 'third_party_logistics', 'hybrid')),
  default_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  default_package_id uuid REFERENCES public.shipping_packages(id) ON DELETE SET NULL,
  unit_system text NOT NULL DEFAULT 'metric' CHECK (unit_system IN ('metric', 'imperial')),
  returns_enabled boolean NOT NULL DEFAULT true,
  return_window_days integer NOT NULL DEFAULT 30 CHECK (return_window_days BETWEEN 0 AND 365),
  tax_mode text NOT NULL DEFAULT 'none' CHECK (tax_mode IN ('none', 'manual', 'provider')),
  prices_include_tax boolean NOT NULL DEFAULT false,
  tax_on_shipping boolean NOT NULL DEFAULT false,
  low_stock_default integer NOT NULL DEFAULT 5 CHECK (low_stock_default BETWEEN 0 AND 1000000),
  low_stock_alerts boolean NOT NULL DEFAULT true,
  onboarded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.commerce_settings ADD COLUMN IF NOT EXISTS unit_system text NOT NULL DEFAULT 'metric' CHECK (unit_system IN ('metric', 'imperial'));
ALTER TABLE public.commerce_settings ADD COLUMN IF NOT EXISTS low_stock_alerts boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.commerce_tax_rates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  country text NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
  region text CHECK (region IS NULL OR length(region) <= 120),
  name text NOT NULL DEFAULT 'Tax' CHECK (length(btrim(name)) BETWEEN 1 AND 60),
  rate_bps integer NOT NULL CHECK (rate_bps BETWEEN 0 AND 10000),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS commerce_tax_rates_place_key ON public.commerce_tax_rates (creator_id, country, coalesce(lower(region), ''));
/* 7. Options and variants: the existing product_variants, each one combination of up to three options */
CREATE TABLE IF NOT EXISTS public.product_options (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  position smallint NOT NULL CHECK (position BETWEEN 1 AND 3),
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 40),
  "values" text[] NOT NULL DEFAULT '{}'::text[] CHECK (cardinality("values") BETWEEN 1 AND 100),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, position)
);
CREATE UNIQUE INDEX IF NOT EXISTS product_options_name_key ON public.product_options (product_id, lower(name));
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS option1 text CHECK (option1 IS NULL OR length(option1) BETWEEN 1 AND 100);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS option2 text CHECK (option2 IS NULL OR length(option2) BETWEEN 1 AND 100);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS option3 text CHECK (option3 IS NULL OR length(option3) BETWEEN 1 AND 100);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS sku text CHECK (sku IS NULL OR length(sku) BETWEEN 1 AND 64);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS barcode text CHECK (barcode IS NULL OR length(barcode) BETWEEN 1 AND 64);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS weight_grams integer CHECK (weight_grams IS NULL OR weight_grams BETWEEN 0 AND 1000000);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS length_mm integer CHECK (length_mm IS NULL OR length_mm BETWEEN 0 AND 10000);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS width_mm integer CHECK (width_mm IS NULL OR width_mm BETWEEN 0 AND 10000);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS height_mm integer CHECK (height_mm IS NULL OR height_mm BETWEEN 0 AND 10000);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS image_url text CHECK (image_url IS NULL OR length(image_url) <= 2048);
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS track_inventory boolean;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS inventory_policy text NOT NULL DEFAULT 'deny' CHECK (inventory_policy IN ('deny', 'continue'));
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS requires_shipping boolean;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS taxable boolean;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS fulfillment_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS fulfillment_method text CHECK (fulfillment_method IS NULL OR fulfillment_method IN ('self', 'warehouse', 'dropship', 'print_on_demand'));
CREATE UNIQUE INDEX IF NOT EXISTS product_variants_options_key ON public.product_variants (product_id, coalesce(option1, ''), coalesce(option2, ''), coalesce(option3, '')) WHERE option1 IS NOT NULL;
CREATE INDEX IF NOT EXISTS product_variants_sku_idx ON public.product_variants (lower(sku)) WHERE sku IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.product_variant_costs (
  variant_id uuid PRIMARY KEY REFERENCES public.product_variants(id) ON DELETE CASCADE,
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  cost_cents integer NOT NULL CHECK (cost_cents BETWEEN 0 AND 100000000),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS product_variant_costs_creator_idx ON public.product_variant_costs (creator_id);
/* 8. Stock: per variant and location, and every change written down */
CREATE TABLE IF NOT EXISTS public.inventory_levels (
  variant_id uuid NOT NULL REFERENCES public.product_variants(id) ON DELETE CASCADE,
  location_id uuid NOT NULL REFERENCES public.inventory_locations(id) ON DELETE CASCADE,
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  on_hand integer NOT NULL DEFAULT 0 CHECK (on_hand BETWEEN -1000000000 AND 1000000000),
  committed integer NOT NULL DEFAULT 0 CHECK (committed BETWEEN 0 AND 1000000000),
  incoming integer NOT NULL DEFAULT 0 CHECK (incoming BETWEEN 0 AND 1000000000),
  available integer GENERATED ALWAYS AS (on_hand - committed) STORED,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (variant_id, location_id)
);
CREATE INDEX IF NOT EXISTS inventory_levels_creator_idx ON public.inventory_levels (creator_id, available);
CREATE INDEX IF NOT EXISTS inventory_levels_location_idx ON public.inventory_levels (location_id);
CREATE TABLE IF NOT EXISTS public.inventory_movements (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  variant_id uuid REFERENCES public.product_variants(id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  delta_on_hand integer NOT NULL DEFAULT 0,
  delta_committed integer NOT NULL DEFAULT 0,
  delta_incoming integer NOT NULL DEFAULT 0,
  on_hand_after integer,
  committed_after integer,
  incoming_after integer,
  reason text NOT NULL CHECK (reason IN ('initial', 'received', 'correction', 'count', 'damaged', 'theft_or_loss', 'promotion_or_donation', 'returned_restock', 'sale_fulfilled', 'order_reserved', 'reservation_released', 'order_cancelled', 'transfer_out', 'transfer_in', 'incoming_added', 'incoming_cancelled', 'provider_sync')),
  ref_type text CHECK (ref_type IS NULL OR length(ref_type) <= 40),
  ref_id text CHECK (ref_id IS NULL OR length(ref_id) <= 120),
  note text CHECK (note IS NULL OR length(note) <= 500),
  actor text NOT NULL DEFAULT 'system' CHECK (actor IN ('creator', 'buyer', 'system', 'webhook', 'admin')),
  idempotency_key text UNIQUE CHECK (idempotency_key IS NULL OR length(idempotency_key) <= 200),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS inventory_movements_creator_idx ON public.inventory_movements (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS inventory_movements_variant_idx ON public.inventory_movements (variant_id, created_at DESC);
/* 9. Physical checkouts: shipped or picked up, and their stock holds */
CREATE TABLE IF NOT EXISTS public.commerce_checkouts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  buyer_id uuid,
  buyer_email text CHECK (buyer_email IS NULL OR length(buyer_email) <= 254),
  buyer_name text CHECK (buyer_name IS NULL OR length(buyer_name) <= 200),
  buyer_phone text CHECK (buyer_phone IS NULL OR length(buyer_phone) <= 40),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'failed', 'expired', 'cancelled', 'refunded', 'partially_refunded')),
  fulfillment_status text NOT NULL DEFAULT 'unfulfilled',
  return_status text NOT NULL DEFAULT 'none' CHECK (return_status IN ('none', 'requested', 'in_progress', 'partially_returned', 'returned')),
  delivery_method text NOT NULL DEFAULT 'ship' CHECK (delivery_method IN ('ship', 'pickup', 'none')),
  pickup_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  pickup jsonb CHECK (pickup IS NULL OR (jsonb_typeof(pickup) = 'object' AND pg_column_size(pickup) <= 4096)),
  currency text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'),
  items_subtotal_cents integer NOT NULL DEFAULT 0 CHECK (items_subtotal_cents >= 0),
  discount_cents integer NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
  shipping_cents integer NOT NULL DEFAULT 0 CHECK (shipping_cents >= 0),
  shipping_discount_cents integer NOT NULL DEFAULT 0 CHECK (shipping_discount_cents >= 0),
  tax_cents integer NOT NULL DEFAULT 0 CHECK (tax_cents >= 0),
  total_cents integer NOT NULL DEFAULT 0 CHECK (total_cents >= 0),
  platform_fee_cents integer NOT NULL DEFAULT 0 CHECK (platform_fee_cents >= 0),
  refunded_cents integer NOT NULL DEFAULT 0 CHECK (refunded_cents >= 0),
  shipping_address jsonb CHECK (shipping_address IS NULL OR (jsonb_typeof(shipping_address) = 'object' AND pg_column_size(shipping_address) <= 4096)),
  shipping_rate jsonb CHECK (shipping_rate IS NULL OR (jsonb_typeof(shipping_rate) = 'object' AND pg_column_size(shipping_rate) <= 4096)),
  lines jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(lines) = 'array' AND jsonb_array_length(lines) <= 50 AND pg_column_size(lines) <= 65536),
  coupon_id uuid,
  coupon_code text CHECK (coupon_code IS NULL OR length(coupon_code) <= 64),
  coupon_holder text CHECK (coupon_holder IS NULL OR length(coupon_holder) <= 200),
  provider text NOT NULL DEFAULT 'stripe' CHECK (provider IN ('stripe', 'free')),
  stripe_payment_intent_id text UNIQUE CHECK (stripe_payment_intent_id IS NULL OR stripe_payment_intent_id ~ '^pi_[A-Za-z0-9_]+$'),
  stripe_session_id text UNIQUE CHECK (stripe_session_id IS NULL OR stripe_session_id ~ '^cs_[A-Za-z0-9_]+$'),
  client_key text CHECK (client_key IS NULL OR length(client_key) BETWEEN 8 AND 120),
  receipt_token text,
  session_fingerprint text,
  origin jsonb CHECK (origin IS NULL OR (jsonb_typeof(origin) = 'object' AND pg_column_size(origin) <= 4096)),
  attribution jsonb CHECK (attribution IS NULL OR (jsonb_typeof(attribution) = 'object' AND pg_column_size(attribution) <= 4096)),
  buyer_note text CHECK (buyer_note IS NULL OR length(buyer_note) <= 1000),
  merchant_note text CHECK (merchant_note IS NULL OR length(merchant_note) <= 4000),
  cancel_reason text CHECK (cancel_reason IS NULL OR length(cancel_reason) <= 300),
  expires_at timestamptz,
  paid_at timestamptz,
  processing_at timestamptz,
  cancelled_at timestamptz,
  fulfilled_at timestamptz,
  delivered_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (creator_id, client_key)
);
ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS delivery_method text NOT NULL DEFAULT 'ship' CHECK (delivery_method IN ('ship', 'pickup', 'none'));
ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS pickup_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL;
ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS pickup jsonb CHECK (pickup IS NULL OR (jsonb_typeof(pickup) = 'object' AND pg_column_size(pickup) <= 4096));
ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS processing_at timestamptz;
ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS delivered_at timestamptz;
ALTER TABLE public.commerce_checkouts DROP CONSTRAINT IF EXISTS commerce_checkouts_fulfillment_status_check;
ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_fulfillment_status_check CHECK (fulfillment_status IN ('unfulfilled', 'processing', 'partially_fulfilled', 'fulfilled', 'delivered', 'cancelled', 'not_required'));
CREATE INDEX IF NOT EXISTS commerce_checkouts_creator_idx ON public.commerce_checkouts (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS commerce_checkouts_open_idx ON public.commerce_checkouts (creator_id, fulfillment_status, paid_at) WHERE status = 'paid';
CREATE INDEX IF NOT EXISTS commerce_checkouts_pending_idx ON public.commerce_checkouts (expires_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS commerce_checkouts_buyer_idx ON public.commerce_checkouts (creator_id, lower(buyer_email)) WHERE buyer_email IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.inventory_reservations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  variant_id uuid REFERENCES public.product_variants(id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 100000),
  status text NOT NULL DEFAULT 'held' CHECK (status IN ('held', 'sold', 'released', 'fulfilled')),
  fulfilled_quantity integer NOT NULL DEFAULT 0 CHECK (fulfilled_quantity >= 0),
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (checkout_id, variant_id, location_id)
);
CREATE INDEX IF NOT EXISTS inventory_reservations_expiry_idx ON public.inventory_reservations (expires_at) WHERE status = 'held';
/* 10. Orders: each line of a physical checkout is an ordinary orders row */
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS checkout_id uuid REFERENCES public.commerce_checkouts(id) ON DELETE SET NULL;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS quantity integer CHECK (quantity IS NULL OR quantity BETWEEN 1 AND 100000);
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS unit_price_cents integer CHECK (unit_price_cents IS NULL OR unit_price_cents >= 0);
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS shipping_cents integer CHECK (shipping_cents IS NULL OR shipping_cents >= 0);
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS requires_shipping boolean;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS fulfillment_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS fulfillment_method text CHECK (fulfillment_method IS NULL OR fulfillment_method IN ('self', 'warehouse', 'dropship', 'print_on_demand'));
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS product_snapshot jsonb CHECK (product_snapshot IS NULL OR (jsonb_typeof(product_snapshot) = 'object' AND pg_column_size(product_snapshot) <= 8192));
CREATE INDEX IF NOT EXISTS orders_checkout_idx ON public.orders (checkout_id) WHERE checkout_id IS NOT NULL;
/* 11. Shipments (fulfillments): one order can have several, each with its items, carrier, tracking and history */
CREATE TABLE IF NOT EXISTS public.fulfillments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'submitted', 'shipped', 'in_transit', 'out_for_delivery', 'delivered', 'failed', 'cancelled')),
  provider text NOT NULL DEFAULT 'manual' CHECK (length(provider) BETWEEN 1 AND 40),
  provider_ref text CHECK (provider_ref IS NULL OR length(provider_ref) <= 200),
  carrier text CHECK (carrier IS NULL OR length(carrier) <= 60),
  service text CHECK (service IS NULL OR length(service) <= 80),
  tracking_number text CHECK (tracking_number IS NULL OR length(tracking_number) <= 120),
  tracking_url text CHECK (tracking_url IS NULL OR length(tracking_url) <= 2048),
  label_url text CHECK (label_url IS NULL OR length(label_url) <= 2048),
  package_id uuid REFERENCES public.shipping_packages(id) ON DELETE SET NULL,
  notify_buyer boolean NOT NULL DEFAULT true,
  error text CHECK (error IS NULL OR length(error) <= 500),
  idempotency_key text UNIQUE CHECK (idempotency_key IS NULL OR length(idempotency_key) <= 200),
  shipped_at timestamptz,
  delivered_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS fulfillments_checkout_idx ON public.fulfillments (checkout_id, created_at);
CREATE INDEX IF NOT EXISTS fulfillments_creator_idx ON public.fulfillments (creator_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS fulfillments_provider_ref_key ON public.fulfillments (provider, provider_ref) WHERE provider_ref IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.fulfillment_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fulfillment_id uuid NOT NULL REFERENCES public.fulfillments(id) ON DELETE CASCADE,
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 100000),
  UNIQUE (fulfillment_id, order_id)
);
CREATE INDEX IF NOT EXISTS fulfillment_items_order_idx ON public.fulfillment_items (order_id);
CREATE TABLE IF NOT EXISTS public.fulfillment_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fulfillment_id uuid NOT NULL REFERENCES public.fulfillments(id) ON DELETE CASCADE,
  status text NOT NULL CHECK (length(status) BETWEEN 1 AND 40),
  message text CHECK (message IS NULL OR length(message) <= 300),
  location text CHECK (location IS NULL OR length(location) <= 200),
  source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'provider', 'webhook', 'system')),
  external_id text CHECK (external_id IS NULL OR length(external_id) <= 200),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS fulfillment_events_external_key ON public.fulfillment_events (fulfillment_id, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS fulfillment_events_fulfillment_idx ON public.fulfillment_events (fulfillment_id, occurred_at);
/* 12. Returns and stock transfers */
CREATE TABLE IF NOT EXISTS public.commerce_returns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'approved', 'rejected', 'in_transit', 'received', 'completed', 'cancelled')),
  reason text NOT NULL DEFAULT 'other' CHECK (reason IN ('size', 'damaged', 'defective', 'not_as_described', 'wrong_item', 'changed_mind', 'other')),
  method text NOT NULL DEFAULT 'ship_back' CHECK (method IN ('ship_back', 'drop_off', 'no_return_needed')),
  requested_by text NOT NULL DEFAULT 'creator' CHECK (requested_by IN ('creator', 'buyer')),
  customer_note text CHECK (customer_note IS NULL OR length(customer_note) <= 1000),
  merchant_note text CHECK (merchant_note IS NULL OR length(merchant_note) <= 1000),
  carrier text CHECK (carrier IS NULL OR length(carrier) <= 60),
  tracking_number text CHECK (tracking_number IS NULL OR length(tracking_number) <= 120),
  tracking_url text CHECK (tracking_url IS NULL OR length(tracking_url) <= 2048),
  refunded_cents integer NOT NULL DEFAULT 0 CHECK (refunded_cents >= 0),
  received_at timestamptz,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS commerce_returns_checkout_idx ON public.commerce_returns (checkout_id);
CREATE INDEX IF NOT EXISTS commerce_returns_creator_idx ON public.commerce_returns (creator_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.commerce_return_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  return_id uuid NOT NULL REFERENCES public.commerce_returns(id) ON DELETE CASCADE,
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 100000),
  restock boolean NOT NULL DEFAULT true,
  restock_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  restocked_quantity integer NOT NULL DEFAULT 0 CHECK (restocked_quantity >= 0),
  condition text CHECK (condition IS NULL OR condition IN ('new', 'opened', 'damaged')),
  UNIQUE (return_id, order_id),
  CONSTRAINT commerce_return_items_restocked CHECK (restocked_quantity <= quantity)
);
CREATE INDEX IF NOT EXISTS commerce_return_items_order_idx ON public.commerce_return_items (order_id);
CREATE TABLE IF NOT EXISTS public.inventory_transfers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  origin_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  destination_location_id uuid REFERENCES public.inventory_locations(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'in_transit', 'partially_received', 'received', 'cancelled')),
  reference text CHECK (reference IS NULL OR length(reference) <= 120),
  note text CHECK (note IS NULL OR length(note) <= 1000),
  expected_at date,
  shipped_at timestamptz,
  received_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inventory_transfers_two_places CHECK (origin_location_id IS NULL OR destination_location_id IS NULL OR origin_location_id <> destination_location_id)
);
CREATE INDEX IF NOT EXISTS inventory_transfers_creator_idx ON public.inventory_transfers (creator_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.inventory_transfer_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transfer_id uuid NOT NULL REFERENCES public.inventory_transfers(id) ON DELETE CASCADE,
  variant_id uuid REFERENCES public.product_variants(id) ON DELETE SET NULL,
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 1000000),
  received_quantity integer NOT NULL DEFAULT 0 CHECK (received_quantity >= 0),
  UNIQUE (transfer_id, variant_id),
  CONSTRAINT inventory_transfer_items_received CHECK (received_quantity <= quantity)
);
/* 13. Collections */
CREATE TABLE IF NOT EXISTS public.product_collections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 120),
  slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
  description text CHECK (description IS NULL OR length(description) <= 5000),
  image_url text CHECK (image_url IS NULL OR length(image_url) <= 2048),
  kind text NOT NULL DEFAULT 'manual' CHECK (kind IN ('manual', 'smart')),
  rules jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(rules) = 'array' AND jsonb_array_length(rules) <= 20),
  match text NOT NULL DEFAULT 'all' CHECK (match IN ('all', 'any')),
  sort text NOT NULL DEFAULT 'manual' CHECK (sort IN ('manual', 'newest', 'price_asc', 'price_desc', 'title', 'best_selling')),
  published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (creator_id, slug)
);
CREATE TABLE IF NOT EXISTS public.product_collection_items (
  collection_id uuid NOT NULL REFERENCES public.product_collections(id) ON DELETE CASCADE,
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  position integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (collection_id, product_id)
);
CREATE INDEX IF NOT EXISTS product_collection_items_product_idx ON public.product_collection_items (product_id);
/* 14. The order timeline (append only) and the job queue (emails, supplier emails, webhooks, low stock alerts) */
CREATE TABLE IF NOT EXISTS public.commerce_order_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  kind text NOT NULL CHECK (kind ~ '^[a-z_.]{2,60}$'),
  message text CHECK (message IS NULL OR length(message) <= 300),
  detail jsonb CHECK (detail IS NULL OR (jsonb_typeof(detail) = 'object' AND pg_column_size(detail) <= 4096)),
  actor text NOT NULL DEFAULT 'system' CHECK (actor IN ('creator', 'buyer', 'system', 'webhook', 'admin')),
  idempotency_key text UNIQUE CHECK (idempotency_key IS NULL OR length(idempotency_key) <= 200),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS commerce_order_events_checkout_idx ON public.commerce_order_events (checkout_id, created_at);
CREATE OR REPLACE FUNCTION public.commerce_order_events_append_only() RETURNS trigger LANGUAGE plpgsql AS $f$
BEGIN
  RAISE EXCEPTION 'commerce_order_events is append only';
END $f$;
DROP TRIGGER IF EXISTS commerce_order_events_no_update ON public.commerce_order_events;
CREATE TRIGGER commerce_order_events_no_update BEFORE UPDATE ON public.commerce_order_events FOR EACH ROW EXECUTE FUNCTION public.commerce_order_events_append_only();
CREATE TABLE IF NOT EXISTS public.commerce_jobs (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL,
  kind text NOT NULL CHECK (kind IN ('forward_fulfillment', 'supplier_email', 'webhook_delivery', 'tracking_sync', 'inventory_sync', 'send_email')),
  payload jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(payload) = 'object' AND pg_column_size(payload) <= 32768),
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed', 'dead')),
  attempts integer NOT NULL DEFAULT 0,
  max_attempts integer NOT NULL DEFAULT 6 CHECK (max_attempts BETWEEN 1 AND 50),
  run_after timestamptz NOT NULL DEFAULT now(),
  locked_until timestamptz,
  last_error text CHECK (last_error IS NULL OR length(last_error) <= 500),
  idempotency_key text UNIQUE CHECK (idempotency_key IS NULL OR length(idempotency_key) <= 200),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz
);
CREATE INDEX IF NOT EXISTS commerce_jobs_due_idx ON public.commerce_jobs (run_after) WHERE status IN ('queued', 'failed');
CREATE INDEX IF NOT EXISTS commerce_jobs_creator_idx ON public.commerce_jobs (creator_id, created_at DESC);
/* 15. Discount codes: free shipping, a limit per customer, collections, physical only */
DO $do$
BEGIN
  IF to_regclass('public.coupons') IS NULL THEN RETURN; END IF;
  ALTER TABLE public.coupons ADD COLUMN IF NOT EXISTS free_shipping boolean NOT NULL DEFAULT false;
  ALTER TABLE public.coupons ADD COLUMN IF NOT EXISTS per_customer_limit integer CHECK (per_customer_limit IS NULL OR per_customer_limit BETWEEN 1 AND 1000);
  ALTER TABLE public.coupons ADD COLUMN IF NOT EXISTS collection_ids uuid[];
  ALTER TABLE public.coupons ADD COLUMN IF NOT EXISTS physical_only boolean NOT NULL DEFAULT false;
END $do$;
/* 16. The stock engine: every change locks the rows it touches, is written down, and is keyed so a retry changes nothing */
CREATE OR REPLACE FUNCTION public.physical_inventory_apply(p_creator uuid, p_variant uuid, p_location uuid, p_on_hand integer, p_committed integer, p_incoming integer, p_reason text, p_ref_type text, p_ref_id text, p_key text, p_actor text, p_note text, p_guard boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  lvl public.inventory_levels%ROWTYPE;
  owner uuid;
  loc_owner uuid;
  new_on_hand integer;
  new_committed integer;
  new_incoming integer;
BEGIN
  IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = p_key) THEN
    SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location;
    RETURN jsonb_build_object('applied', false, 'repeat', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.available);
  END IF;
  SELECT p.creator_id INTO owner FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = p_variant;
  SELECT creator_id INTO loc_owner FROM public.inventory_locations WHERE id = p_location;
  IF owner IS NULL OR owner <> p_creator OR loc_owner IS NULL OR loc_owner <> p_creator THEN
    RETURN jsonb_build_object('applied', false, 'error', 'not_found');
  END IF;
  INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (p_variant, p_location, p_creator) ON CONFLICT (variant_id, location_id) DO NOTHING;
  SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location FOR UPDATE;
  new_on_hand := lvl.on_hand + coalesce(p_on_hand, 0);
  new_committed := lvl.committed + coalesce(p_committed, 0);
  new_incoming := lvl.incoming + coalesce(p_incoming, 0);
  IF new_committed < 0 THEN new_committed := 0; END IF;
  IF new_incoming < 0 THEN new_incoming := 0; END IF;
  IF p_guard AND (new_on_hand - new_committed) < 0 AND (coalesce(p_on_hand, 0) < 0 OR coalesce(p_committed, 0) > 0) THEN
    RETURN jsonb_build_object('applied', false, 'error', 'insufficient', 'available', lvl.available);
  END IF;
  UPDATE public.inventory_levels SET on_hand = new_on_hand, committed = new_committed, incoming = new_incoming, updated_at = now() WHERE variant_id = p_variant AND location_id = p_location;
  INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_on_hand, delta_committed, delta_incoming, on_hand_after, committed_after, incoming_after, reason, ref_type, ref_id, note, actor, idempotency_key)
  VALUES (p_creator, p_variant, p_location, new_on_hand - lvl.on_hand, new_committed - lvl.committed, new_incoming - lvl.incoming, new_on_hand, new_committed, new_incoming, p_reason, p_ref_type, p_ref_id, left(p_note, 500), coalesce(p_actor, 'system'), p_key);
  RETURN jsonb_build_object('applied', true, 'on_hand', new_on_hand, 'committed', new_committed, 'incoming', new_incoming, 'available', new_on_hand - new_committed);
END $f$;
CREATE OR REPLACE FUNCTION public.physical_reserve(p_checkout uuid, p_lines jsonb, p_expires timestamptz) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  co public.commerce_checkouts%ROWTYPE;
  ln record;
  lvl public.inventory_levels%ROWTYPE;
  held integer := 0;
BEGIN
  SELECT * INTO co FROM public.commerce_checkouts WHERE id = p_checkout FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF;
  IF EXISTS (SELECT 1 FROM public.inventory_reservations WHERE checkout_id = p_checkout) THEN RETURN jsonb_build_object('applied', false, 'repeat', true); END IF;
  FOR ln IN
    SELECT (e->>'variant_id')::uuid AS variant_id, (e->>'location_id')::uuid AS location_id, (e->>'quantity')::integer AS quantity, coalesce((e->>'oversell')::boolean, false) AS oversell
    FROM jsonb_array_elements(p_lines) e
    ORDER BY 1, 2
  LOOP
    IF ln.quantity IS NULL OR ln.quantity < 1 THEN RAISE EXCEPTION 'physical_reserve: bad quantity'; END IF;
    INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (ln.variant_id, ln.location_id, co.creator_id) ON CONFLICT (variant_id, location_id) DO NOTHING;
    SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = ln.variant_id AND location_id = ln.location_id FOR UPDATE;
    IF lvl.creator_id <> co.creator_id THEN RAISE EXCEPTION 'physical_reserve: not this shop'; END IF;
    IF NOT ln.oversell AND lvl.available < ln.quantity THEN
      RAISE EXCEPTION 'out_of_stock:%:%', ln.variant_id, greatest(lvl.available, 0) USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.inventory_levels SET committed = committed + ln.quantity, updated_at = now() WHERE variant_id = ln.variant_id AND location_id = ln.location_id;
    INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_committed, on_hand_after, committed_after, incoming_after, reason, ref_type, ref_id, actor, idempotency_key)
    VALUES (co.creator_id, ln.variant_id, ln.location_id, ln.quantity, lvl.on_hand, lvl.committed + ln.quantity, lvl.incoming, 'order_reserved', 'checkout', p_checkout::text, 'buyer', 'reserve:' || p_checkout || ':' || ln.variant_id || ':' || ln.location_id);
    INSERT INTO public.inventory_reservations (checkout_id, creator_id, variant_id, location_id, quantity, status, expires_at) VALUES (p_checkout, co.creator_id, ln.variant_id, ln.location_id, ln.quantity, 'held', p_expires);
    held := held + 1;
  END LOOP;
  RETURN jsonb_build_object('applied', true, 'held', held);
END $f$;
CREATE OR REPLACE FUNCTION public.physical_release(p_checkout uuid, p_reason text) RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  r record;
  released integer := 0;
BEGIN
  FOR r IN SELECT * FROM public.inventory_reservations WHERE checkout_id = p_checkout AND status = 'held' ORDER BY variant_id, location_id FOR UPDATE LOOP
    IF r.variant_id IS NOT NULL AND r.location_id IS NOT NULL THEN
      UPDATE public.inventory_levels SET committed = greatest(committed - r.quantity, 0), updated_at = now() WHERE variant_id = r.variant_id AND location_id = r.location_id;
      INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_committed, reason, ref_type, ref_id, actor, idempotency_key)
      VALUES (r.creator_id, r.variant_id, r.location_id, -r.quantity, 'reservation_released', 'checkout', p_checkout::text, 'system', 'release:' || r.id)
      ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;
    UPDATE public.inventory_reservations SET status = 'released', updated_at = now() WHERE id = r.id;
    released := released + 1;
  END LOOP;
  RETURN released;
END $f$;
CREATE OR REPLACE FUNCTION public.physical_mark_sold(p_checkout uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  r record;
  again integer := 0;
BEGIN
  FOR r IN SELECT * FROM public.inventory_reservations WHERE checkout_id = p_checkout ORDER BY variant_id, location_id FOR UPDATE LOOP
    IF r.status = 'held' THEN
      UPDATE public.inventory_reservations SET status = 'sold', expires_at = NULL, updated_at = now() WHERE id = r.id;
    ELSIF r.status = 'released' AND r.variant_id IS NOT NULL AND r.location_id IS NOT NULL THEN
      UPDATE public.inventory_levels SET committed = committed + r.quantity, updated_at = now() WHERE variant_id = r.variant_id AND location_id = r.location_id;
      INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_committed, reason, ref_type, ref_id, note, actor, idempotency_key)
      VALUES (r.creator_id, r.variant_id, r.location_id, r.quantity, 'order_reserved', 'checkout', p_checkout::text, 'Paid after the hold expired', 'system', 'resold:' || r.id)
      ON CONFLICT (idempotency_key) DO NOTHING;
      UPDATE public.inventory_reservations SET status = 'sold', expires_at = NULL, updated_at = now() WHERE id = r.id;
      again := again + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('applied', true, 'recommitted', again);
END $f$;
CREATE OR REPLACE FUNCTION public.physical_fulfill(p_fulfillment uuid) RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  f public.fulfillments%ROWTYPE;
  it record;
  lvl public.inventory_levels%ROWTYPE;
  moved integer := 0;
BEGIN
  SELECT * INTO f FROM public.fulfillments WHERE id = p_fulfillment FOR UPDATE;
  IF NOT FOUND THEN RETURN 0; END IF;
  FOR it IN
    SELECT fi.quantity, o.id AS order_id, o.variant_id, coalesce(o.fulfillment_location_id, f.location_id) AS location_id, coalesce(v.track_inventory, p.track_inventory, true) AS tracked
    FROM public.fulfillment_items fi
    JOIN public.orders o ON o.id = fi.order_id
    LEFT JOIN public.product_variants v ON v.id = o.variant_id
    LEFT JOIN public.products p ON p.id = o.product_id
    WHERE fi.fulfillment_id = p_fulfillment
    ORDER BY o.variant_id
  LOOP
    IF it.variant_id IS NULL OR it.location_id IS NULL OR NOT it.tracked THEN CONTINUE; END IF;
    IF EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = 'fulfill:' || p_fulfillment || ':' || it.order_id) THEN CONTINUE; END IF;
    INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (it.variant_id, it.location_id, f.creator_id) ON CONFLICT (variant_id, location_id) DO NOTHING;
    SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = it.variant_id AND location_id = it.location_id FOR UPDATE;
    UPDATE public.inventory_levels SET on_hand = on_hand - it.quantity, committed = greatest(committed - it.quantity, 0), updated_at = now() WHERE variant_id = it.variant_id AND location_id = it.location_id;
    INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_on_hand, delta_committed, on_hand_after, committed_after, incoming_after, reason, ref_type, ref_id, actor, idempotency_key)
    VALUES (f.creator_id, it.variant_id, it.location_id, -it.quantity, -least(it.quantity, lvl.committed), lvl.on_hand - it.quantity, greatest(lvl.committed - it.quantity, 0), lvl.incoming, 'sale_fulfilled', 'fulfillment', p_fulfillment::text, 'creator', 'fulfill:' || p_fulfillment || ':' || it.order_id);
    UPDATE public.inventory_reservations
    SET fulfilled_quantity = least(quantity, fulfilled_quantity + it.quantity), status = CASE WHEN fulfilled_quantity + it.quantity >= quantity THEN 'fulfilled' ELSE status END, updated_at = now()
    WHERE checkout_id = f.checkout_id AND variant_id = it.variant_id AND location_id = it.location_id AND status IN ('held', 'sold');
    moved := moved + 1;
  END LOOP;
  RETURN moved;
END $f$;
CREATE OR REPLACE FUNCTION public.physical_cancel_unfulfilled(p_checkout uuid) RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  r record;
  left_qty integer;
  done integer := 0;
BEGIN
  FOR r IN SELECT * FROM public.inventory_reservations WHERE checkout_id = p_checkout AND status IN ('held', 'sold') ORDER BY variant_id, location_id FOR UPDATE LOOP
    left_qty := r.quantity - r.fulfilled_quantity;
    IF left_qty > 0 AND r.variant_id IS NOT NULL AND r.location_id IS NOT NULL THEN
      UPDATE public.inventory_levels SET committed = greatest(committed - left_qty, 0), updated_at = now() WHERE variant_id = r.variant_id AND location_id = r.location_id;
      INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_committed, reason, ref_type, ref_id, actor, idempotency_key)
      VALUES (r.creator_id, r.variant_id, r.location_id, -left_qty, 'order_cancelled', 'checkout', p_checkout::text, 'creator', 'cancel:' || r.id)
      ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;
    UPDATE public.inventory_reservations SET status = 'released', updated_at = now() WHERE id = r.id;
    done := done + 1;
  END LOOP;
  RETURN done;
END $f$;
CREATE OR REPLACE FUNCTION public.physical_expire_holds(p_limit integer) RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$
DECLARE
  c record;
  n integer := 0;
BEGIN
  FOR c IN
    SELECT DISTINCT r.checkout_id
    FROM public.inventory_reservations r
    JOIN public.commerce_checkouts k ON k.id = r.checkout_id
    WHERE r.status = 'held' AND r.expires_at < now() AND k.status <> 'paid'
    LIMIT greatest(coalesce(p_limit, 100), 1)
  LOOP
    PERFORM public.physical_release(c.checkout_id, 'expired');
    UPDATE public.commerce_checkouts SET status = 'expired', updated_at = now() WHERE id = c.checkout_id AND status = 'pending';
    n := n + 1;
  END LOOP;
  RETURN n;
END $f$;
CREATE OR REPLACE FUNCTION public.commerce_claim_jobs(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.commerce_jobs LANGUAGE plpgsql SET search_path = public AS $f$
BEGIN
  RETURN QUERY
  UPDATE public.commerce_jobs j
  SET status = 'running', attempts = j.attempts + 1, locked_until = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 120), 30)), updated_at = now()
  WHERE j.id IN (
    SELECT id FROM public.commerce_jobs
    WHERE (status IN ('queued', 'failed') AND run_after <= now()) OR (status = 'running' AND locked_until < now())
    ORDER BY run_after
    LIMIT greatest(coalesce(p_limit, 20), 1)
    FOR UPDATE SKIP LOCKED
  )
  RETURNING j.*;
END $f$;
REVOKE ALL ON FUNCTION public.physical_inventory_apply(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_inventory_apply(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, text, boolean) TO service_role;
REVOKE ALL ON FUNCTION public.physical_reserve(uuid, jsonb, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_reserve(uuid, jsonb, timestamptz) TO service_role;
REVOKE ALL ON FUNCTION public.physical_release(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_release(uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.physical_mark_sold(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_mark_sold(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_fulfill(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_fulfill(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_cancel_unfulfilled(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_cancel_unfulfilled(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_expire_holds(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_expire_holds(integer) TO service_role;
REVOKE ALL ON FUNCTION public.commerce_claim_jobs(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.commerce_claim_jobs(integer, integer) TO service_role;
/* 17. updated_at kept current on every table that has it */
DO $do$
DECLARE t text;
BEGIN
  IF to_regprocedure('public.update_updated_at_column()') IS NULL THEN
    CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END $fn$;
  END IF;
  FOREACH t IN ARRAY ARRAY['commerce_integrations', 'inventory_locations', 'shipping_profiles', 'shipping_zones', 'shipping_rates', 'shipping_packages', 'commerce_settings', 'commerce_tax_rates', 'product_options', 'product_variant_costs', 'commerce_checkouts', 'inventory_reservations', 'fulfillments', 'commerce_returns', 'inventory_transfers', 'product_collections', 'commerce_jobs'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_touch', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()', t || '_touch', t);
  END LOOP;
END $do$;
/* 18. Row level security: on everywhere, creators read their own rows, buyers read published options and collections, only the server writes */
ALTER TABLE public.commerce_integrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shipping_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shipping_zones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shipping_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shipping_packages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commerce_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commerce_tax_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_options ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_variant_costs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_levels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commerce_checkouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fulfillments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fulfillment_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fulfillment_events ENABLE ROW LEVEL SECURITY;
