ALTER TABLE public.commerce_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.commerce_integrations, public.inventory_locations, public.shipping_profiles, public.shipping_zones, public.shipping_rates, public.shipping_packages, public.commerce_settings, public.commerce_tax_rates, public.product_options, public.product_variant_costs, public.inventory_levels, public.inventory_movements, public.commerce_checkouts, public.inventory_reservations, public.fulfillments, public.fulfillment_items, public.fulfillment_events, public.commerce_returns, public.commerce_return_items, public.inventory_transfers, public.inventory_transfer_items, public.product_collections, public.product_collection_items, public.commerce_order_events, public.commerce_jobs FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.commerce_integrations, public.inventory_locations, public.shipping_profiles, public.shipping_zones, public.shipping_rates, public.shipping_packages, public.commerce_settings, public.commerce_tax_rates, public.product_options, public.product_variant_costs, public.inventory_levels, public.inventory_movements, public.commerce_checkouts, public.inventory_reservations, public.fulfillments, public.fulfillment_items, public.fulfillment_events, public.commerce_returns, public.commerce_return_items, public.inventory_transfers, public.inventory_transfer_items, public.product_collections, public.product_collection_items, public.commerce_order_events, public.commerce_jobs FROM authenticated;
REVOKE ALL ON public.commerce_integrations, public.commerce_jobs FROM authenticated;
