DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads inventory_reservations" ON public.inventory_reservations; CREATE POLICY "storelib owner reads inventory_reservations" ON public.inventory_reservations FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = inventory_reservations.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads fulfillments" ON public.fulfillments; CREATE POLICY "storelib owner reads fulfillments" ON public.fulfillments FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = fulfillments.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads commerce_returns" ON public.commerce_returns; CREATE POLICY "storelib owner reads commerce_returns" ON public.commerce_returns FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = commerce_returns.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads inventory_transfers" ON public.inventory_transfers; CREATE POLICY "storelib owner reads inventory_transfers" ON public.inventory_transfers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = inventory_transfers.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
