DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads commerce_order_events" ON public.commerce_order_events; CREATE POLICY "storelib owner reads commerce_order_events" ON public.commerce_order_events FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = commerce_order_events.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads fulfillment_items" ON public.fulfillment_items; CREATE POLICY "storelib owner reads fulfillment_items" ON public.fulfillment_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.fulfillments f JOIN public.creators c ON c.id = f.creator_id WHERE f.id = fulfillment_items.fulfillment_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads fulfillment_events" ON public.fulfillment_events; CREATE POLICY "storelib owner reads fulfillment_events" ON public.fulfillment_events FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.fulfillments f JOIN public.creators c ON c.id = f.creator_id WHERE f.id = fulfillment_events.fulfillment_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads commerce_return_items" ON public.commerce_return_items; CREATE POLICY "storelib owner reads commerce_return_items" ON public.commerce_return_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.commerce_returns r JOIN public.creators c ON c.id = r.creator_id WHERE r.id = commerce_return_items.return_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads inventory_transfer_items" ON public.inventory_transfer_items; CREATE POLICY "storelib owner reads inventory_transfer_items" ON public.inventory_transfer_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.inventory_transfers x JOIN public.creators c ON c.id = x.creator_id WHERE x.id = inventory_transfer_items.transfer_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib reads options" ON public.product_options; CREATE POLICY "storelib reads options" ON public.product_options FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id = product_options.product_id AND (p.status = 'published' OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = p.creator_id AND c.user_id = (SELECT auth.uid()))))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib reads published collection items" ON public.product_collection_items; CREATE POLICY "storelib reads published collection items" ON public.product_collection_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.product_collections pc WHERE pc.id = product_collection_items.collection_id AND (pc.published OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = pc.creator_id AND c.user_id = (SELECT auth.uid()))))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib reads published collections" ON public.product_collections; CREATE POLICY "storelib reads published collections" ON public.product_collections FOR SELECT TO authenticated USING (published); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('78', '78_physical_commerce.sql', 'd1e07fc004eaec6dc45c5c5279cce50fef9c5942112a12687c980333b99e252f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 79_stripe_account_reset.sql
/* A creator's payments connection can be reset without losing what it was: stripe_previous_account_id (the connected account Storelib was linked to before), stripe_account_reset_at (when that link was let go) and stripe_account_reset_reason (legacy_platform when Stripe says the account is not reachable from the current platform, which is what happens to every creator linked before Storelib moved to its new Stripe Connect platform; creator_disconnect when the creator chose Start over; incomplete_replaced when an unfinished account was swapped for one that stays inside Storelib). The live link stays stripe_account_id, which is cleared so the creator can set up a fresh account under the current platform instead of being stuck on one Storelib can no longer read. Orders, payouts, refunds and the ledger are never touched: each keeps the Stripe ids it was written with. Only the server writes these three, and they are private like the other Stripe columns (parts 63 and 77): the private list and the guard trigger are restated in full with them added. Safe to run more than once. Until it runs, a reset still happens and the old account id is written to the server log instead. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'stripe account reset: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_previous_account_id text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_reason text; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_stripe_account_reset_reason_check; ALTER TABLE public.creators ADD CONSTRAINT creators_stripe_account_reset_reason_check CHECK (stripe_account_reset_reason IS NULL OR stripe_account_reset_reason IN ('legacy_platform','creator_disconnect','incomplete_replaced')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('79', '79_stripe_account_reset.sql', 'db884bc84c36f58f1a9b50865612dbba59e10f8fac42619634b73cde48ce427b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 80_free_plan_fee_5pct.sql
/* The Storelib fee on the Free plan is 5% (it was 6%), and on small orders 11.25% (it was 12.25%). Checkout reads its fee rules from the active row of storelib_fee_rule_versions when there is one and from the code when there is not (lib/payments/fees/active.ts); the code says 5% now, and this makes the database say the same, so production moves whichever it is reading. The small-order rate moves with the standard one because it is not a separate price: under the threshold the fixed fee is dropped and the percentage carries it, so both move by the same point or the fee would fall as a price rose past the threshold ($3.99 would pay 49c and $4.00 45c). A new version is written and made the active one; the version that was active is retired, not changed, and everything it held is carried forward except the two Free rates: the per-currency thresholds and fixed fees, and the paid plan rates, which stay exactly as they were. Orders already paid keep the fee and the rule version they were charged under (each order row has its own). Stripe's processing fee is not set here. Nothing where the table does not exist (the code is then the rule, and says 5%). Safe to run more than once: once this version exists it is never written again, so a later version an admin activates is never overwritten by running this again. */
DO $$ DECLARE v_old_cfg jsonb; v_old_key text; v_cfg jsonb; BEGIN IF to_regclass('public.storelib_fee_rule_versions') IS NULL THEN RAISE NOTICE 'free plan fee: there are no fee versions in this database, so the code rule applies, and it is 5%%.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM public.storelib_fee_rule_versions WHERE version_key = '2026-10-storelib-v3-free-5pct') THEN RAISE NOTICE 'free plan fee: version 2026-10-storelib-v3-free-5pct is already written, nothing to do.'; RETURN; END IF; SELECT config, version_key INTO v_old_cfg, v_old_key FROM public.storelib_fee_rule_versions WHERE status = 'active' LIMIT 1; v_cfg := COALESCE(v_old_cfg, '{"versionKey":"2026-10-storelib-v3-free-5pct","freeStandardRate":0.05,"freeMicroRate":0.1125,"paidStandardRate":0.03,"paidMicroRate":0.0925,"currencies":[{"currency":"USD","microThresholdMinor":400,"fixedFeeMinor":25,"enabled":true},{"currency":"RON","microThresholdMinor":1840,"fixedFeeMinor":115,"enabled":true},{"currency":"EUR","microThresholdMinor":368,"fixedFeeMinor":23,"enabled":true},{"currency":"GBP","microThresholdMinor":316,"fixedFeeMinor":20,"enabled":true},{"currency":"CAD","microThresholdMinor":544,"fixedFeeMinor":34,"enabled":true},{"currency":"AUD","microThresholdMinor":600,"fixedFeeMinor":38,"enabled":true},{"currency":"JPY","microThresholdMinor":600,"fixedFeeMinor":40,"enabled":true}]}'::jsonb) || jsonb_build_object('versionKey', '2026-10-storelib-v3-free-5pct', 'freeStandardRate', 0.05, 'freeMicroRate', 0.1125); UPDATE public.storelib_fee_rule_versions SET status = 'retired' WHERE status = 'active'; INSERT INTO public.storelib_fee_rule_versions (version_key, status, config, created_by, change_summary) VALUES ('2026-10-storelib-v3-free-5pct', 'active', v_cfg, 'run-now part 80', 'Free plan Storelib fee 6% to 5% (small orders 12.25% to 11.25%). Currencies and paid plan rates carried forward unchanged.'); IF to_regclass('public.admin_payments_audit_log') IS NOT NULL THEN INSERT INTO public.admin_payments_audit_log (action, actor, before_state, after_state) VALUES ('fee_version_activated', 'run-now part 80', CASE WHEN v_old_key IS NULL THEN NULL ELSE jsonb_build_object('version_key', v_old_key) END, jsonb_build_object('version_key', '2026-10-storelib-v3-free-5pct', 'freeStandardRate', 0.05, 'freeMicroRate', 0.1125)); END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('80', '80_free_plan_fee_5pct.sql', 'a547e31745975933c58c7d9b9a0e44c34b17923e441a9ec625d5ff39084d450e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 81_communities.sql
/* Storelib Communities: a creator's own community with spaces, posts, comments, reactions, polls, chat, events, a classroom of course products, members with roles and tiers, points and levels, invites, reports, an append only audit log, an in app inbox per member and a job queue, all switched off until an admin turns them on. `platform_flags` holds platform switches, seeded with `communities` off. `communities` is one community (its address, name, who may join and how, what it shows); `community_tiers` the ways to belong (free, or sold by a membership or community product, prices stay on the product); `community_access_products` the products whose owners get a tier; `products.community_id` marks a product that sells a tier. `community_members` is one row per person per community with status, role, tier, where access came from, points and level; member_count counts active rows only and a trigger keeps it. Posts, comments, reactions, bookmarks, polls and votes, reports, invites and their uses, attached courses, events and RSVPs, chat messages and read marks, levels, point events, badges, activity, notifications, daily stats, videos and video webhook events each get their table, with counters kept by triggers and every repeatable action keyed so it happens once. Functions do the parts that must be atomic: a vote (one choice unless the poll allows more), an RSVP (a full event puts you on the waitlist), an invite redeemed (each person once, never past its limit), points awarded once per key, jobs claimed without two workers taking one, and a leaderboard summed over the last days. Every table is server only (row level security on, nothing granted to visitors) except three reads: a published public or unlisted community's public columns, chat messages of a space a signed in member may read (for realtime), and a member's own notifications. Needs parts 66 and 75 for the kept rows and the membership link. Until it runs, community pages say communities are not set up and nothing else changes. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.platform_flags (key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, note text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by text, CONSTRAINT platform_flags_key_shape CHECK (key ~ '^[a-z][a-z0-9_]{1,62}$'));
INSERT INTO public.platform_flags (key, enabled, note) VALUES ('communities', false, 'Communities, memberships in them, member feeds, events and community discovery across Storelib.') ON CONFLICT (key) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, slug text NOT NULL, name text NOT NULL, tagline text, description text, logo_url text, cover_url text, cover_video_id uuid, visibility text NOT NULL DEFAULT 'public', access text NOT NULL DEFAULT 'free', status text NOT NULL DEFAULT 'draft', category text, language text NOT NULL DEFAULT 'en', member_count integer NOT NULL DEFAULT 0, post_count integer NOT NULL DEFAULT 0, discovery_enabled boolean NOT NULL DEFAULT true, approval_required boolean NOT NULL DEFAULT false, default_role text NOT NULL DEFAULT 'member', directory_enabled boolean NOT NULL DEFAULT true, classroom_enabled boolean NOT NULL DEFAULT true, events_enabled boolean NOT NULL DEFAULT true, chat_enabled boolean NOT NULL DEFAULT true, gamification_enabled boolean NOT NULL DEFAULT false, rules jsonb NOT NULL DEFAULT '[]'::jsonb, faq jsonb NOT NULL DEFAULT '[]'::jsonb, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, links jsonb NOT NULL DEFAULT '[]'::jsonb, onboarding jsonb NOT NULL DEFAULT '{}'::jsonb, seo_title text, seo_description text, trending_score numeric NOT NULL DEFAULT 0, trending_at timestamptz, platform_hidden boolean NOT NULL DEFAULT false, suspended_at timestamptz, suspended_reason text, archived_at timestamptz, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT communities_slug_key UNIQUE (slug), CONSTRAINT communities_slug_shape CHECK (char_length(slug) BETWEEN 3 AND 48 AND slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'), CONSTRAINT communities_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT communities_tagline_len CHECK (tagline IS NULL OR char_length(tagline) <= 160), CONSTRAINT communities_description_len CHECK (description IS NULL OR char_length(description) <= 20000), CONSTRAINT communities_seo_len CHECK ((seo_title IS NULL OR char_length(seo_title) <= 200) AND (seo_description IS NULL OR char_length(seo_description) <= 500)), CONSTRAINT communities_visibility_check CHECK (visibility IN ('public', 'private', 'unlisted')), CONSTRAINT communities_access_check CHECK (access IN ('free', 'paid', 'invite_only', 'product', 'custom')), CONSTRAINT communities_status_check CHECK (status IN ('draft', 'published', 'archived', 'suspended')), CONSTRAINT communities_default_role_check CHECK (default_role IN ('member')), CONSTRAINT communities_counts_check CHECK (member_count >= 0 AND post_count >= 0), CONSTRAINT communities_json_shape CHECK (jsonb_typeof(rules) = 'array' AND jsonb_typeof(faq) = 'array' AND jsonb_typeof(benefits) = 'array' AND jsonb_typeof(links) = 'array' AND jsonb_typeof(onboarding) = 'object'));
CREATE INDEX IF NOT EXISTS communities_creator_idx ON public.communities (creator_id);
CREATE INDEX IF NOT EXISTS communities_owner_idx ON public.communities (owner_user_id);
CREATE INDEX IF NOT EXISTS communities_discover_idx ON public.communities (status, visibility, discovery_enabled, trending_score DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS communities_category_idx ON public.communities (category);
CREATE TABLE IF NOT EXISTS public.community_tiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, description text, position integer NOT NULL DEFAULT 0, kind text NOT NULL DEFAULT 'free', billing text, product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, is_default boolean NOT NULL DEFAULT false, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_tiers_product_key UNIQUE (product_id), CONSTRAINT community_tiers_name_len CHECK (char_length(name) BETWEEN 1 AND 60), CONSTRAINT community_tiers_description_len CHECK (description IS NULL OR char_length(description) <= 500), CONSTRAINT community_tiers_kind_check CHECK (kind IN ('free', 'paid')), CONSTRAINT community_tiers_billing_check CHECK (billing IS NULL OR billing IN ('recurring', 'one_time')), CONSTRAINT community_tiers_benefits_shape CHECK (jsonb_typeof(benefits) = 'array'));
CREATE INDEX IF NOT EXISTS community_tiers_community_idx ON public.community_tiers (community_id, position);
CREATE UNIQUE INDEX IF NOT EXISTS community_tiers_one_default ON public.community_tiers (community_id) WHERE is_default;
CREATE TABLE IF NOT EXISTS public.community_access_products (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, tier_id uuid NOT NULL REFERENCES public.community_tiers(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tier_id, product_id));
CREATE INDEX IF NOT EXISTS community_access_products_product_idx ON public.community_access_products (product_id);
CREATE INDEX IF NOT EXISTS community_access_products_community_idx ON public.community_access_products (community_id);
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'communities: there is no products table, products.community_id is not added.'; RETURN; END IF; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS community_id uuid REFERENCES public.communities(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS products_community_idx ON public.products (community_id) WHERE community_id IS NOT NULL; END $do$;
CREATE TABLE IF NOT EXISTS public.community_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'active', role text NOT NULL DEFAULT 'member', tier_id uuid REFERENCES public.community_tiers(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'free', source_membership_id uuid REFERENCES public.memberships(id) ON DELETE SET NULL, source_product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, source_order_id uuid, invite_id uuid, invited_by uuid, request_note text, requested_at timestamptz, approved_by uuid, joined_at timestamptz, last_active_at timestamptz, expires_at timestamptz, points integer NOT NULL DEFAULT 0, level integer NOT NULL DEFAULT 1, muted_until timestamptz, ban_reason text, banned_at timestamptz, banned_by uuid, removed_at timestamptz, notify_level text NOT NULL DEFAULT 'important', email_announcements boolean NOT NULL DEFAULT true, email_events boolean NOT NULL DEFAULT true, onboarded_at timestamptz, bio text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_members_once UNIQUE (community_id, user_id), CONSTRAINT community_members_status_check CHECK (status IN ('pending', 'active', 'paused', 'cancelled', 'expired', 'banned', 'removed')), CONSTRAINT community_members_role_check CHECK (role IN ('owner', 'admin', 'moderator', 'member')), CONSTRAINT community_members_source_check CHECK (source IN ('owner', 'free', 'subscription', 'purchase', 'product', 'invite', 'manual', 'platform')), CONSTRAINT community_members_notify_check CHECK (notify_level IN ('all', 'important', 'mentions', 'none')), CONSTRAINT community_members_level_check CHECK (level BETWEEN 1 AND 20), CONSTRAINT community_members_note_len CHECK (request_note IS NULL OR char_length(request_note) <= 500), CONSTRAINT community_members_bio_len CHECK (bio IS NULL OR char_length(bio) <= 280));
