DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL THEN RAISE NOTICE 'communities: part 66 has not run, deleted community rows are not kept.'; RETURN; END IF; DROP TRIGGER IF EXISTS communities_keep_deleted ON public.communities; CREATE TRIGGER communities_keep_deleted AFTER DELETE ON public.communities FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_tiers_keep_deleted ON public.community_tiers; CREATE TRIGGER community_tiers_keep_deleted AFTER DELETE ON public.community_tiers FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_members_keep_deleted ON public.community_members; CREATE TRIGGER community_members_keep_deleted AFTER DELETE ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_feed_posts_keep_deleted ON public.community_feed_posts; CREATE TRIGGER community_feed_posts_keep_deleted AFTER DELETE ON public.community_feed_posts FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_events_keep_deleted ON public.community_events; CREATE TRIGGER community_events_keep_deleted AFTER DELETE ON public.community_events FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); END $do$;
REVOKE ALL ON FUNCTION public.community_touch_updated_at(), public.community_member_count(), public.community_post_count(), public.community_comment_count(), public.community_reaction_count(), public.community_going_count(), public.community_vote_count(), public.community_points_apply(), public.community_audit_append_only(), public.community_cast_vote(uuid, uuid, uuid[]), public.community_rsvp(uuid, uuid, boolean), public.community_redeem_invite(text, uuid), public.community_award_points(uuid, uuid, integer, text, text, uuid), public.community_claim_jobs(integer, integer), public.community_leaderboard(uuid, timestamptz, integer), public.community_role_of(uuid, uuid), public.community_can_read_space(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_touch_updated_at(), public.community_member_count(), public.community_post_count(), public.community_comment_count(), public.community_reaction_count(), public.community_going_count(), public.community_vote_count(), public.community_points_apply(), public.community_audit_append_only(), public.community_cast_vote(uuid, uuid, uuid[]), public.community_rsvp(uuid, uuid, boolean), public.community_redeem_invite(text, uuid), public.community_award_points(uuid, uuid, integer, text, text, uuid), public.community_claim_jobs(integer, integer), public.community_leaderboard(uuid, timestamptz, integer), public.community_role_of(uuid, uuid), public.community_can_read_space(uuid) TO service_role;
