DO $do$ BEGIN DROP POLICY IF EXISTS "storelib public community reads" ON public.communities; CREATE POLICY "storelib public community reads" ON public.communities FOR SELECT TO anon, authenticated USING (status = 'published' AND visibility IN ('public', 'unlisted') AND deleted_at IS NULL AND suspended_at IS NULL); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read chat" ON public.community_messages; CREATE POLICY "storelib members read chat" ON public.community_messages FOR SELECT TO authenticated USING (public.community_can_read_space(space_id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib member reads own community notifications" ON public.community_notifications; CREATE POLICY "storelib member reads own community notifications" ON public.community_notifications FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid())); END $do$;
DO $do$ DECLARE v_owner oid; v_table text; BEGIN SELECT pubowner INTO v_owner FROM pg_publication WHERE pubname = 'supabase_realtime'; IF NOT FOUND THEN RAISE NOTICE 'communities: there is no supabase_realtime publication, chat and the bell update on reload only.'; RETURN; END IF; IF NOT pg_has_role(current_user, v_owner, 'MEMBER') THEN RAISE NOTICE 'communities: this role does not own supabase_realtime, add community_messages and community_notifications to it in Database, Publications.'; RETURN; END IF; FOREACH v_table IN ARRAY ARRAY['community_messages', 'community_notifications'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_table) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table); END IF; END LOOP; END $do$;
