-- part 82_payment_disputes.sql
/* Chargebacks and inquiries, one row per Stripe dispute, so a creator can see their open cases on Payouts and Storelib can follow each one to the end. A sale paid through Storelib is charged on Storelib's own Stripe account (destination charges), so a dispute is opened against Storelib, not the creator, and Stripe takes the money from Storelib. This keeps what Storelib did about it: the money taken back from the creator's share of that sale while the case is open (a reversal of the transfer, never more than the creator received for it), and the money given back if the buyer's bank decides for the creator. A creator can add what proves the sale (delivery, messages) from Payouts, kept here for Storelib to send to the bank. An inquiry (Stripe's warning_ statuses) takes no money from anyone and is only recorded. Orders, payouts and the ledger are not changed here; the order keeps its own disputed status. Private and server only: only the server reads it, and only for the signed in creator's own rows. Safe to run more than once. */
CREATE TABLE IF NOT EXISTS public.payment_disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stripe_dispute_id text NOT NULL UNIQUE CHECK (stripe_dispute_id ~ '^(du|dp)_[A-Za-z0-9_]+$'), creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, order_id uuid, payment_intent_id text, charge_id text, amount_minor bigint NOT NULL DEFAULT 0 CHECK (amount_minor >= 0), currency text NOT NULL DEFAULT 'usd' CHECK (currency ~ '^[a-z]{3}$'), reason text CHECK (reason IS NULL OR length(reason) <= 60), status text NOT NULL CHECK (length(status) BETWEEN 1 AND 40), inquiry boolean NOT NULL DEFAULT false, evidence_due_by timestamptz, product_title text CHECK (product_title IS NULL OR length(product_title) <= 300), reversed_minor bigint NOT NULL DEFAULT 0 CHECK (reversed_minor >= 0), reversal_id text, restored_minor bigint NOT NULL DEFAULT 0 CHECK (restored_minor >= 0), restore_transfer_id text, recovery text NOT NULL DEFAULT 'none' CHECK (recovery IN ('none', 'not_needed', 'reversed', 'reversal_failed', 'restored', 'restore_failed')), outcome text CHECK (outcome IS NULL OR outcome IN ('won', 'lost', 'inquiry_closed')), creator_note text CHECK (creator_note IS NULL OR length(creator_note) <= 4000), creator_note_at timestamptz, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.payment_disputes ADD COLUMN IF NOT EXISTS creator_note text, ADD COLUMN IF NOT EXISTS creator_note_at timestamptz;
CREATE INDEX IF NOT EXISTS payment_disputes_creator_idx ON public.payment_disputes (creator_id, opened_at DESC);
CREATE INDEX IF NOT EXISTS payment_disputes_open_idx ON public.payment_disputes (evidence_due_by) WHERE closed_at IS NULL;
ALTER TABLE public.payment_disputes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.payment_disputes FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.payment_disputes TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('82', '82_payment_disputes.sql', 'f7019d8e65972bf1c78104160ec9f19abc2c03585118aa77a9bb9bcc19bf3512') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 83_community_direct_messages.sql
/* Messages between two members of the same community, the way people chat on Skool or Circle: one conversation per pair of members per community, and its messages. Storelib's server writes every row after checking both people are active members and the community has chat switched on; a member's browser only listens. Realtime streams a conversation and its messages to its two members and nobody else (public.community_in_conversation), and stops the moment either of them leaves or is banned. A deleted message has its words blanked in the same update, so nothing travels with it. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_a uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, user_b uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, started_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, last_message_at timestamptz, last_author_id uuid, last_body text NOT NULL DEFAULT '', a_read_at timestamptz, b_read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_conversations_pair_order CHECK (user_a < user_b), CONSTRAINT community_conversations_last_body_len CHECK (char_length(last_body) <= 200), CONSTRAINT community_conversations_pair_key UNIQUE (community_id, user_a, user_b));
CREATE TABLE IF NOT EXISTS public.community_direct_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.community_conversations(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz, CONSTRAINT community_direct_messages_body_len CHECK (char_length(body) <= 4000), CONSTRAINT community_direct_messages_status CHECK (status IN ('published', 'deleted', 'removed')));
CREATE INDEX IF NOT EXISTS community_direct_messages_conversation_idx ON public.community_direct_messages (conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_conversations_a_idx ON public.community_conversations (community_id, user_a, last_message_at DESC);
CREATE INDEX IF NOT EXISTS community_conversations_b_idx ON public.community_conversations (community_id, user_b, last_message_at DESC);
CREATE OR REPLACE FUNCTION public.community_in_conversation(p_conversation uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT EXISTS (SELECT 1 FROM public.community_conversations c JOIN public.community_members m ON m.community_id = c.community_id AND m.user_id = auth.uid() JOIN public.communities k ON k.id = c.community_id WHERE c.id = p_conversation AND auth.uid() IN (c.user_a, c.user_b) AND m.status = 'active' AND m.banned_at IS NULL AND k.deleted_at IS NULL AND k.suspended_at IS NULL) $f$;
ALTER TABLE public.community_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_direct_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_conversations, public.community_direct_messages FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.community_conversations, public.community_direct_messages TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_conversations, public.community_direct_messages TO service_role;
REVOKE ALL ON FUNCTION public.community_in_conversation(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.community_in_conversation(uuid) TO authenticated, service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their conversations" ON public.community_conversations; CREATE POLICY "storelib members read their conversations" ON public.community_conversations FOR SELECT TO authenticated USING (public.community_in_conversation(id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their messages" ON public.community_direct_messages; CREATE POLICY "storelib members read their messages" ON public.community_direct_messages FOR SELECT TO authenticated USING (public.community_in_conversation(conversation_id)); END $do$;
DO $do$ DECLARE v_owner oid; v_table text; BEGIN SELECT pubowner INTO v_owner FROM pg_publication WHERE pubname = 'supabase_realtime'; IF NOT FOUND THEN RAISE NOTICE 'community messages: there is no supabase_realtime publication, new messages show when the chat is opened again.'; RETURN; END IF; IF NOT pg_has_role(current_user, v_owner, 'MEMBER') THEN RAISE NOTICE 'community messages: this role does not own supabase_realtime, add community_conversations and community_direct_messages to it in Database, Publications.'; RETURN; END IF; FOREACH v_table IN ARRAY ARRAY['community_conversations', 'community_direct_messages'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_table) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table); END IF; END LOOP; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('83', '83_community_direct_messages.sql', 'ba9016c02f12b9e1d60393dde90bccc6b097505a8896922f514b6c2eb4f9fa27') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 84_seller_payment_state.sql
/* What Stripe last said about each creator's payments account, kept on the creator so checkout, Home, the reminders and the admin screens all read one answer without asking Stripe on a buyer's Pay. Only the server writes these, after reading the account from Stripe (lib/payments/stripe/connect.ts syncStripeAccountFull, run by the account.updated and capability.updated webhooks and when Payouts is opened with a stale copy). can_accept_payments is Storelib's single answer to may checkout take money for this creator (lib/payments/stripe/readiness.ts): it follows Storelib's charge model, so an account that can only receive transfers counts once its transfers are active. payout_destination is the masked bank only (bank name, last four, country, currency), never a full account number, and the check below refuses anything else. Stripe's requirement codes are kept for support and debugging, never shown to buyers. Private, like the other Stripe columns. Safe to run more than once. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'seller payment state: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS can_accept_payments boolean; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_disabled_reason text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_country text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_business_type text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_pending_verification text[]; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_eventually_due text[]; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirement_errors text[]; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_transfers_status text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS payout_destination jsonb; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements_cleared_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS last_stripe_event_id text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS last_stripe_event_type text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS last_stripe_event_at timestamptz; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_payout_destination_masked; ALTER TABLE public.creators ADD CONSTRAINT creators_payout_destination_masked CHECK (payout_destination IS NULL OR (jsonb_typeof(payout_destination) = 'object' AND NOT (payout_destination ? 'iban') AND NOT (payout_destination ? 'account_number') AND NOT (payout_destination ? 'routing_number') AND coalesce(length(payout_destination->>'last4'), 0) <= 4)); END IF; END $$;
CREATE INDEX IF NOT EXISTS creators_payments_status_idx ON public.creators (payments_status) WHERE stripe_account_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason', 'can_accept_payments', 'stripe_disabled_reason', 'stripe_account_country', 'stripe_business_type', 'stripe_pending_verification', 'stripe_eventually_due', 'stripe_requirement_errors', 'stripe_transfers_status', 'payout_destination', 'stripe_requirements_cleared_at', 'last_stripe_event_id', 'last_stripe_event_type', 'last_stripe_event_at'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason', 'can_accept_payments', 'stripe_disabled_reason', 'stripe_account_country', 'stripe_business_type', 'stripe_pending_verification', 'stripe_eventually_due', 'stripe_requirement_errors', 'stripe_transfers_status', 'payout_destination', 'stripe_requirements_cleared_at', 'last_stripe_event_id', 'last_stripe_event_type', 'last_stripe_event_at'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('84', '84_seller_payment_state.sql', 'ee90bafab9f3b7e0aa77eeef248e32084b54a1742c7cfcdebf697bc0083b088c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 85_profiles_follows_notifications.sql
/* Profiles, follows and notifications for everybody, run after part 81. Every account gets an inbox of its own, `user_notifications`, for what is not a community notification: a new follower, a new product or community from a creator they follow, a new post in a membership they pay for, a new product from a creator they bought from. Each person reads only their own rows (realtime streams them to the bell); Storelib's server writes them, once per dedupe key. `follows` is made where it is missing, in the shape the follow button already writes, with the indexes the follower and following lists read in date order. `profiles` gains two privacy switches anyone may read (show_activity, show_communities: hide my activity and my communities on my profile) and `notifications_seen_at`, kept private like the email. `communities.gallery` holds the pictures and videos of a community's about page (at most 12), and `community_members.last_seen_at` the member's last heartbeat, which the online count and the app's start screen read. The community job queue takes two more kinds of job, `fanout_followers` and `fanout_membership_post`, and keeps every kind it had. Follows kept in the older profile_follows table are copied into follows once, so nobody loses who they followed. Safe to run again. */
ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS gallery jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.communities DROP CONSTRAINT IF EXISTS communities_gallery_check, ADD CONSTRAINT communities_gallery_check CHECK (jsonb_typeof(gallery) = 'array' AND jsonb_array_length(gallery) <= 12);
GRANT SELECT (gallery) ON public.communities TO anon, authenticated;
ALTER TABLE public.community_members ADD COLUMN IF NOT EXISTS last_seen_at timestamptz;
CREATE INDEX IF NOT EXISTS community_members_last_seen_idx ON public.community_members (community_id, last_seen_at DESC);
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS show_activity boolean NOT NULL DEFAULT true;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS show_communities boolean NOT NULL DEFAULT true;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS notifications_seen_at timestamptz;
CREATE TABLE IF NOT EXISTS public.follows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), follower_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, following_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT follows_no_self CHECK (follower_id <> following_id), CONSTRAINT follows_unique UNIQUE (follower_id, following_id));
ALTER TABLE public.follows ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
CREATE INDEX IF NOT EXISTS follows_following_created_idx ON public.follows (following_id, created_at DESC);
CREATE INDEX IF NOT EXISTS follows_follower_created_idx ON public.follows (follower_id, created_at DESC);
DO $do$ BEGIN IF to_regclass('public.profile_follows') IS NULL THEN RETURN; END IF; INSERT INTO public.follows (follower_id, following_id, created_at) SELECT pf.follower_id, pf.following_id, pf.created_at FROM public.profile_follows pf WHERE pf.follower_id <> pf.following_id ON CONFLICT (follower_id, following_id) DO NOTHING; END $do$;
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'follows' AND cmd = 'SELECT') THEN CREATE POLICY "follows are readable by everyone" ON public.follows FOR SELECT USING (true); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'follows' AND cmd = 'INSERT') THEN CREATE POLICY "users insert their own follows" ON public.follows FOR INSERT WITH CHECK (auth.uid() = follower_id); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'follows' AND cmd = 'DELETE') THEN CREATE POLICY "users delete their own follows" ON public.follows FOR DELETE USING (auth.uid() = follower_id); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.user_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL, source text NOT NULL, actor_id uuid, creator_id uuid, title text NOT NULL, body text, url text NOT NULL, image_url text, read_at timestamptz, dedupe_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT user_notifications_dedupe_key UNIQUE (dedupe_key), CONSTRAINT user_notifications_kind_check CHECK (kind IN ('new_follower', 'followed_new_product', 'followed_new_community', 'membership_post', 'purchased_creator_new_product', 'system')), CONSTRAINT user_notifications_source_check CHECK (source IN ('following', 'purchases', 'communities', 'system')), CONSTRAINT user_notifications_title_len CHECK (char_length(title) BETWEEN 1 AND 200), CONSTRAINT user_notifications_body_len CHECK (body IS NULL OR char_length(body) <= 500), CONSTRAINT user_notifications_url_local CHECK (url LIKE '/%' AND url NOT LIKE '//%' AND char_length(url) <= 500), CONSTRAINT user_notifications_image_len CHECK (image_url IS NULL OR char_length(image_url) <= 1000), CONSTRAINT user_notifications_dedupe_len CHECK (char_length(dedupe_key) <= 300));
CREATE INDEX IF NOT EXISTS user_notifications_user_idx ON public.user_notifications (user_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS user_notifications_unread_idx ON public.user_notifications (user_id) WHERE read_at IS NULL;
ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_notifications FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.user_notifications TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_notifications TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib user reads own notifications" ON public.user_notifications; CREATE POLICY "storelib user reads own notifications" ON public.user_notifications FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid())); END $do$;
DO $do$ DECLARE v_owner oid; BEGIN SELECT pubowner INTO v_owner FROM pg_publication WHERE pubname = 'supabase_realtime'; IF NOT FOUND THEN RAISE NOTICE 'notifications: there is no supabase_realtime publication, the bell updates when it is opened.'; RETURN; END IF; IF NOT pg_has_role(current_user, v_owner, 'MEMBER') THEN RAISE NOTICE 'notifications: this role does not own supabase_realtime, add user_notifications to it in Database, Publications.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'user_notifications') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.user_notifications; END IF; END $do$;
ALTER TABLE public.community_jobs DROP CONSTRAINT IF EXISTS community_jobs_kind_check, ADD CONSTRAINT community_jobs_kind_check CHECK (kind IN ('fanout_announcement', 'fanout_event', 'event_reminder', 'recount', 'rollup', 'trending', 'video_poll', 'fanout_followers', 'fanout_membership_post', 'push_digest')) NOT VALID;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason', 'can_accept_payments', 'stripe_disabled_reason', 'stripe_account_country', 'stripe_business_type', 'stripe_pending_verification', 'stripe_eventually_due', 'stripe_requirement_errors', 'stripe_transfers_status', 'payout_destination', 'stripe_requirements_cleared_at', 'last_stripe_event_id', 'last_stripe_event_type', 'last_stripe_event_at'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id', 'notifications_seen_at'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason', 'can_accept_payments', 'stripe_disabled_reason', 'stripe_account_country', 'stripe_business_type', 'stripe_pending_verification', 'stripe_eventually_due', 'stripe_requirement_errors', 'stripe_transfers_status', 'payout_destination', 'stripe_requirements_cleared_at', 'last_stripe_event_id', 'last_stripe_event_type', 'last_stripe_event_at'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('85', '85_profiles_follows_notifications.sql', 'e513aa7cbd06febf13267983ff39fb4c4990752923924d5a6ce5a4a016503a8b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 86_push_notifications.sql
/* Push notifications from communities and people, run after parts 40, 81 and 85. What happens in a person's communities and from creators they follow or bought from can also reach their phone (the Storelib app) and any browser they turned notifications on for. Two checks take one more value each and keep every value they had: the community job queue takes `push_digest` (the likes, comments and new followers held back while a five minute push window was open, sent as one push when it closes), and `notification_preferences` takes the category `social`, where each person's push switch for communities and people is kept (channel `push`; no row means on). The windows themselves are counted in `rate_limit_hits` from part 01, so no table is added. No rows change. Until it runs, the first push of a window still goes and the rest stay in the bell, and the switch in account settings says it is not available yet. Safe to run again. */
ALTER TABLE public.community_jobs DROP CONSTRAINT IF EXISTS community_jobs_kind_check, ADD CONSTRAINT community_jobs_kind_check CHECK (kind IN ('fanout_announcement', 'fanout_event', 'event_reminder', 'recount', 'rollup', 'trending', 'video_poll', 'fanout_followers', 'fanout_membership_post', 'push_digest')) NOT VALID;
ALTER TABLE public.notification_preferences DROP CONSTRAINT IF EXISTS notification_preferences_category_check, ADD CONSTRAINT notification_preferences_category_check CHECK (category IN ('sales', 'payouts_and_payments', 'product_and_store', 'account', 'security', 'lifecycle', 'tips', 'marketing', 'social')) NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('86', '86_push_notifications.sql', '585aa50a478fe994fb4dba85164cdde6b0d1dad741068d23611b2825038ce6b0') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 87_community_views.sql
/* Community views, run after part 81. Each community gets an all time view count, `communities.view_count`, readable by anyone like its member count, shown on its card in Explore. A view is one visitor on one community on one UTC day: the server records it through `community_record_view(community, visitor)`, which writes one row to the new server only table `community_view_days` and adds one to the count only when that row is new, so a reload or a second visit the same day does not count again and the next day does. The visitor is a hash the server makes (of the signed in account, or of a first party browser id); no address, name or IP is stored. Only the service role can call it. Day rows older than three days are deleted by the community cron. No existing rows change. Until it runs, cards show no view count and pages open as before. Safe to run again. */
ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS view_count bigint NOT NULL DEFAULT 0;
ALTER TABLE public.communities DROP CONSTRAINT IF EXISTS communities_view_count_check, ADD CONSTRAINT communities_view_count_check CHECK (view_count >= 0);
GRANT SELECT (view_count) ON public.communities TO anon, authenticated;
CREATE TABLE IF NOT EXISTS public.community_view_days (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, visitor_key text NOT NULL, day date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_view_days_pkey PRIMARY KEY (community_id, visitor_key, day), CONSTRAINT community_view_days_key_check CHECK (char_length(visitor_key) BETWEEN 16 AND 128));
CREATE INDEX IF NOT EXISTS community_view_days_day_idx ON public.community_view_days (day);
ALTER TABLE public.community_view_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_view_days FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.community_view_days TO service_role;
CREATE OR REPLACE FUNCTION public.community_record_view(p_community uuid, p_visitor text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_new integer; BEGIN IF p_community IS NULL OR p_visitor IS NULL OR char_length(p_visitor) NOT BETWEEN 16 AND 128 THEN RETURN false; END IF; INSERT INTO public.community_view_days (community_id, visitor_key, day) SELECT c.id, p_visitor, (now() AT TIME ZONE 'UTC')::date FROM public.communities c WHERE c.id = p_community ON CONFLICT (community_id, visitor_key, day) DO NOTHING; GET DIAGNOSTICS v_new = ROW_COUNT; IF v_new = 0 THEN RETURN false; END IF; UPDATE public.communities SET view_count = view_count + 1 WHERE id = p_community; RETURN true; END $f$;
REVOKE ALL ON FUNCTION public.community_record_view(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_record_view(uuid, text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('87', '87_community_views.sql', '353ad2a64a343e68c0cac11103203e2335d4f5ef2419449912d74dc004bef2cc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 88_download_events_buyer_lookup.sql
/* Faster "Recently opened" in the navigator, run after the download_events table exists (its later shape with created_at, from the upload safety work). The navigator's recent list (GET /api/me/places) reads a buyer's last downloads by the ids of their own entitlements and orders, newest first; download_events only had indexes on the asset, the token and the time, so that read scanned the table. Two partial indexes, one per id, newest first. No rows change. Until it runs the list still works, only slower. Where download_events or one of its columns is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.download_events') IS NULL THEN RAISE NOTICE 'download lookup: there is no download_events table, nothing to do.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'created_at') THEN RAISE NOTICE 'download lookup: download_events has no created_at, nothing to do.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'entitlement_id') THEN CREATE INDEX IF NOT EXISTS idx_download_events_entitlement_recent ON public.download_events (entitlement_id, created_at DESC) WHERE entitlement_id IS NOT NULL; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'order_id') THEN CREATE INDEX IF NOT EXISTS idx_download_events_order_recent ON public.download_events (order_id, created_at DESC) WHERE order_id IS NOT NULL; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('88', '88_download_events_buyer_lookup.sql', 'b85c7ac3d7f2c5b02443288615a2226cf21d8bd2eab2f96079d252a0495177a9') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 89_community_feed_activity_index.sql
/* Faster community feeds in the Default order, run after part 81. The feed's Default order (pinned first, then the posts with the newest activity, a new comment counting as activity) reads community_feed_posts by community and last_activity_at, newest first; that column had no index, so a large community's feed sorted every post. One partial index on published posts, newest activity first, with the id as the tie breaker the feed's cursor uses. No rows change. Until it runs the feed works, only slower on big communities. Where community_feed_posts is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_feed_posts') IS NULL THEN RAISE NOTICE 'feed activity index: there is no community_feed_posts table, run part 81 first.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS community_feed_posts_activity_idx ON public.community_feed_posts (community_id, last_activity_at DESC, id DESC) WHERE status = 'published'; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('89', '89_community_feed_activity_index.sql', '20154f9dc2140e1956ed20602054d384a54d0b6cc5942f5f6f388d92d72f0f6c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 93_store_menus.sql
/* The store's navigation menus, kept once per store instead of inside each theme. Shopify keeps menus in the store's Navigation and every theme reads the same ones; Storelib kept them in a theme's settings, so a second theme started with none and a menu edited in one theme did not change the others. store_menus holds, per creator, every menu as one JSON object keyed by handle ("main-menu", "footer"), the same shape the theme setting had. Server only: row level security on, no policies, nothing granted to visitors or signed in users; the editor writes it through /api/website-builder/menus, which checks the creator. Until this runs, each theme keeps its own menus exactly as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_menus ( creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, menus jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT store_menus_is_object CHECK (jsonb_typeof(menus) = 'object'), CONSTRAINT store_menus_size CHECK (pg_column_size(menus) < 262144) );
ALTER TABLE public.store_menus ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_menus FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_menus TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('93', '93_store_menus.sql', 'ad8e1c333efaa1e56cf9454d26902e7459c952925e4c95f6f8472786361fe183') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 94_community_slug_history.sql
/* A community's old addresses keep working, run after part 81. When a community's address (its slug) changes, the address it had is kept in the new server only table `community_slug_history` (one row per old address, naming the community it now belongs to), written by a trigger on `communities` in the same step as the change, so no path that renames a community can forget it; a community that takes back one of its old addresses drops that row. The pages read it to send an old link (/community/<old>/..., with the rest of the address and its query) on to the new address with a permanent redirect. Only the service role reads or writes it. No existing rows change. Until it runs, an old address answers not found, as it does now. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_slug_history (slug text NOT NULL, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, changed_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_slug_history_pkey PRIMARY KEY (slug));
CREATE INDEX IF NOT EXISTS community_slug_history_community_idx ON public.community_slug_history (community_id);
ALTER TABLE public.community_slug_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_slug_history FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_slug_history TO service_role;
CREATE OR REPLACE FUNCTION public.community_slug_history_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF OLD.slug IS NOT NULL AND NEW.slug IS DISTINCT FROM OLD.slug THEN INSERT INTO public.community_slug_history (slug, community_id, changed_at) VALUES (OLD.slug, NEW.id, now()) ON CONFLICT (slug) DO UPDATE SET community_id = excluded.community_id, changed_at = excluded.changed_at; DELETE FROM public.community_slug_history WHERE slug = NEW.slug; END IF; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.community_slug_history_record() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS communities_slug_history ON public.communities;
CREATE TRIGGER communities_slug_history AFTER UPDATE OF slug ON public.communities FOR EACH ROW WHEN (OLD.slug IS DISTINCT FROM NEW.slug) EXECUTE FUNCTION public.community_slug_history_record();
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('94', '94_community_slug_history.sql', '3fe4df47b386491b1448004c812ee04ddf092985bf919113f222a0409943988e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 95_navigation_and_collections.sql
/* Everything the Navigation page and collections need, in one file. store_menus holds the store's navigation menus once per store instead of inside each theme, so every theme shows the same ones and /app/website-builder/navigation can save them (the same table as part 93: if that was run, this part does nothing). product_collections and product_collection_items hold groups of products, by hand or by rules; they were made with the physical commerce tables, but collections now work for every kind of product, downloads, courses, memberships, services and physical goods alike, so a shop with physical commerce off needs these two tables and nothing else from that file (the same tables as part 78, so that too does nothing twice). Row level security is on everywhere: visitors (anon) are granted nothing, a signed in person reads their own collections, anybody signed in reads a published collection and the products in it, which is what /collections/<slug> needs, and only the server writes, through the owner checks in /api/collections and /api/website-builder/menus. Additive: nothing is dropped, nothing is renamed, no row is touched. Safe to run again. */
/* 1. The store's menus, shared by every theme */
CREATE TABLE IF NOT EXISTS public.store_menus (
  creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE,
  menus jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT store_menus_is_object CHECK (jsonb_typeof(menus) = 'object'),
  CONSTRAINT store_menus_size CHECK (pg_column_size(menus) < 262144)
);
ALTER TABLE public.store_menus ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_menus FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_menus TO service_role;
/* 2. Collections, for every kind of product */
CREATE TABLE IF NOT EXISTS public.product_collections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 120),
  slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
  description text CHECK (description IS NULL OR length(description) <= 5000),
  image_url text CHECK (image_url IS NULL OR length(image_url) <= 2048),
  kind text NOT NULL DEFAULT 'manual' CHECK (kind IN ('manual', 'smart')),
  rules jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(rules) = 'array' AND jsonb_array_length(rules) <= 20),
  match text NOT NULL DEFAULT 'all' CHECK (match IN ('all', 'any')),
  sort text NOT NULL DEFAULT 'manual' CHECK (sort IN ('manual', 'newest', 'price_asc', 'price_desc', 'title', 'best_selling')),
  published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (creator_id, slug)
);
CREATE TABLE IF NOT EXISTS public.product_collection_items (
  collection_id uuid NOT NULL REFERENCES public.product_collections(id) ON DELETE CASCADE,
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  position integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (collection_id, product_id)
);
CREATE INDEX IF NOT EXISTS product_collection_items_product_idx ON public.product_collection_items (product_id);
/* A shop's published collections, which the storefront and the sitemap read together */
CREATE INDEX IF NOT EXISTS product_collections_creator_published_idx ON public.product_collections (creator_id, published);
/* 3. updated_at keeps itself current */
DO $do$
BEGIN
  IF to_regprocedure('public.update_updated_at_column()') IS NULL THEN
    CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END $fn$;
  END IF;
  DROP TRIGGER IF EXISTS product_collections_touch ON public.product_collections;
  CREATE TRIGGER product_collections_touch BEFORE UPDATE ON public.product_collections FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
END $do$;
/* 4. Who can read what: the owner their own, anybody signed in a published collection, the server alone writes */
ALTER TABLE public.product_collections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_collection_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.product_collections, public.product_collection_items FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.product_collections, public.product_collection_items FROM authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_collections, public.product_collection_items TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads product_collections" ON public.product_collections; CREATE POLICY "storelib owner reads product_collections" ON public.product_collections FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = product_collections.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib reads published collections" ON public.product_collections; CREATE POLICY "storelib reads published collections" ON public.product_collections FOR SELECT TO authenticated USING (published); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib reads published collection items" ON public.product_collection_items; CREATE POLICY "storelib reads published collection items" ON public.product_collection_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.product_collections pc WHERE pc.id = product_collection_items.collection_id AND (pc.published OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = pc.creator_id AND c.user_id = (SELECT auth.uid()))))); END $do$;
/* 5. Did it work? Three rows, all saying true */
SELECT 'store_menus' AS table_name, to_regclass('public.store_menus') IS NOT NULL AS exists
UNION ALL SELECT 'product_collections', to_regclass('public.product_collections') IS NOT NULL
UNION ALL SELECT 'product_collection_items', to_regclass('public.product_collection_items') IS NOT NULL;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('95', '95_navigation_and_collections.sql', 'fcd5e10c321b98b566430f5df4220205cea24ae2533f8018644e0852129ba163') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 96_community_comment_media.sql
/* Pictures, a GIF and files under a community comment, run after part 81. One column on community_feed_comments, `media` (a JSON list, empty by default, at most four things), the same shape a post keeps its media in; the server decides what may go in it (only the commenter's own uploads for that community, and Giphy GIFs) and nothing else writes it. No rows change: every comment there now gets an empty list. Until it runs, comments work as before and one with a picture, a GIF or a file is refused with a sentence. Where community_feed_comments is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_feed_comments') IS NULL THEN RAISE NOTICE 'comment media: there is no community_feed_comments table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_feed_comments ADD COLUMN IF NOT EXISTS media jsonb NOT NULL DEFAULT '[]'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_feed_comments_media_shape' AND conrelid = 'public.community_feed_comments'::regclass) THEN ALTER TABLE public.community_feed_comments ADD CONSTRAINT community_feed_comments_media_shape CHECK (CASE WHEN jsonb_typeof(media) = 'array' THEN jsonb_array_length(media) <= 4 ELSE false END); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('96', '96_community_comment_media.sql', '34f5255622c1791735326810dd62444d9f573445f0c8a4bd2448215cdd8ac575') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 97_profile_provider_photos.sql
/* The photo a person signed in with, for everybody who has none, run after nothing else. An account that signed in with Google (or any provider that sends a picture) and has no profile photo gets that picture as its photo, once, from the account Supabase keeps (`auth.users.raw_user_meta_data`: `avatar_url`, else `picture`, an https address only). Never over a photo that is there, and never for somebody who chose or removed a photo themselves (`storelib_avatar_chosen` on the account, lib/account/avatar), so a removed photo stays removed. From now on the app does the same on every sign in (lib/profile/provider-photo.ts), on the web and in the app. Changes only `profiles.avatar_url` where it is empty; adds no table, column or trigger. Skips itself with a notice where `auth.users` cannot be read. Safe to run again: a second run finds nobody left to change. */
DO $$ BEGIN IF to_regclass('auth.users') IS NULL OR to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profile provider photos skipped: auth.users or profiles is not there'; RETURN; END IF; UPDATE public.profiles p SET avatar_url = x.photo FROM (SELECT u.id, CASE WHEN btrim(coalesce(u.raw_user_meta_data ->> 'avatar_url', '')) ~ '^https://[^[:space:]]+$' AND position('placeholder.svg' in u.raw_user_meta_data ->> 'avatar_url') = 0 THEN btrim(u.raw_user_meta_data ->> 'avatar_url') WHEN btrim(coalesce(u.raw_user_meta_data ->> 'picture', '')) ~ '^https://[^[:space:]]+$' AND position('placeholder.svg' in u.raw_user_meta_data ->> 'picture') = 0 THEN btrim(u.raw_user_meta_data ->> 'picture') END AS photo FROM auth.users u WHERE coalesce(u.raw_user_meta_data ->> 'storelib_avatar_chosen', '') <> 'true') x WHERE x.id = p.id AND x.photo IS NOT NULL AND (p.avatar_url IS NULL OR btrim(p.avatar_url) = '' OR position('placeholder.svg' in p.avatar_url) > 0); EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'profile provider photos skipped: this role may not read auth.users, so photos are kept from the next sign in only'; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('97', '97_profile_provider_photos.sql', '120b7b95a33c9b2a567711a87fafa5ddaeb52b7c597143253b7109a45e2aa83b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 98_community_leave_reasons_and_location.sql
/* Why somebody left a community, and where a person is from, run after parts 81 and 85. A new server only table `community_leave_reasons` keeps the reason a member gave when they left (one of a short list, and an optional note of at most 500 characters), for the community's owner and admins to read in their dashboard; only the service role reads or writes it. Two new optional columns on `profiles`, `location_city` (at most 80 characters) and `location_country` (a two letter country code), so members can say where they are from and others in their communities can see it; they are public like the rest of a profile, and empty until the person fills them. No existing rows change. Until it runs, leaving works as before without asking why, and the location fields are not offered. Where part 81 or profiles is missing that half skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'leave reasons: there is no communities table, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_leave_reasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, reason text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_leave_reasons_reason_check CHECK (reason IN ('not_for_me', 'too_busy', 'too_expensive', 'content', 'people', 'other')), CONSTRAINT community_leave_reasons_note_check CHECK (note IS NULL OR char_length(note) <= 500)); CREATE INDEX IF NOT EXISTS community_leave_reasons_community_idx ON public.community_leave_reasons (community_id, created_at DESC); ALTER TABLE public.community_leave_reasons ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_leave_reasons FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, DELETE ON public.community_leave_reasons TO service_role; END $do$;
DO $do$ BEGIN IF to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profile location: there is no profiles table.'; RETURN; END IF; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS location_city text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS location_country text; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_location_city_length' AND conrelid = 'public.profiles'::regclass) THEN ALTER TABLE public.profiles ADD CONSTRAINT profiles_location_city_length CHECK (location_city IS NULL OR char_length(location_city) BETWEEN 1 AND 80); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_location_country_code' AND conrelid = 'public.profiles'::regclass) THEN ALTER TABLE public.profiles ADD CONSTRAINT profiles_location_country_code CHECK (location_country IS NULL OR location_country ~ '^[A-Z]{2}$'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('98', '98_community_leave_reasons_and_location.sql', 'b128f52ea3b0b9a937c3633ac205e46dd2a1bdf10993c8285d11f5fa59b58461') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 100_community_role_permissions.sql
/* What a community's admins and moderators may do, run after part 81. One new column on `communities`, `role_permissions` (a JSON object, empty by default), where the owner keeps what they changed from the defaults: for `admin` and `moderator`, a group of actions turned on or off (removing and pinning posts, muting and banning members, reports, the audit log, announcements, invites and roles, spaces, Learn, the calendar, settings, analytics). Money, deleting the community and handing it over always stay with the owner, whatever is stored. An empty object means the roles as they were: admins do everything but money and deleting, moderators keep posts, comments and members in order. Server only: it is not one of the columns members and visitors can read, and only the service role writes it, after the owner check in the app. No existing rows change. Until it runs, every community keeps the default roles and the Roles settings say the update is needed. Where part 81 is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'role permissions: there is no communities table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS role_permissions jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_role_permissions_shape' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_role_permissions_shape CHECK (jsonb_typeof(role_permissions) = 'object' AND pg_column_size(role_permissions) <= 4096); END IF; REVOKE SELECT (role_permissions), INSERT (role_permissions), UPDATE (role_permissions) ON public.communities FROM PUBLIC, anon, authenticated; GRANT SELECT (role_permissions), UPDATE (role_permissions) ON public.communities TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('100', '100_community_role_permissions.sql', '7f20889ff537d55f061eb4793044e4f19c9dd729c30010de900ac8c9e28415be') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 101_community_membership_lifecycle.sql
/* Paid community memberships: cancelling, refunds and contacting the owner, run after part 81. Three new columns on `communities` that the owner sets in Settings: `refund_policy` (plain text of at most 2000 characters, shown at checkout and on the member's Membership page), `contact_email` (an address for community messages, never shown unless the owner chooses) and `contact_email_public` (off by default). None of the three is readable with the public key; the server reads them. Three new server only tables: `community_cancellations` (one row per scheduled end of a paid membership, with the reason the member picked from the same six as leaving and an optional note, and when it was resumed if it was), `community_refunds` (one row per Stripe refund an owner made from the community, so the member is emailed once) and `community_contact_messages` (what a member wrote to the owner through the contact form, which also caps how many a day). No existing rows change. Until it runs, cancelling and refunds work and are emailed as before but no reason is kept, the contact form is not offered, and the refund policy and contact settings are not saved. Skips itself with a notice where part 81 has not run. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'membership lifecycle: there is no communities table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS refund_policy text; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS contact_email text; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS contact_email_public boolean NOT NULL DEFAULT false; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_refund_policy_length' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_refund_policy_length CHECK (refund_policy IS NULL OR char_length(refund_policy) <= 2000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_contact_email_shape' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_contact_email_shape CHECK (contact_email IS NULL OR (char_length(contact_email) <= 254 AND contact_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][A-Za-z]{2,24}$')); END IF; REVOKE SELECT (refund_policy, contact_email, contact_email_public), UPDATE (refund_policy, contact_email, contact_email_public) ON public.communities FROM anon, authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'community cancellations: there is no communities table, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_cancellations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, membership_id uuid, cancel_key text NOT NULL, reason text, note text, ends_at timestamptz, resumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_cancellations_key_unique UNIQUE (cancel_key), CONSTRAINT community_cancellations_key_length CHECK (char_length(cancel_key) BETWEEN 1 AND 200), CONSTRAINT community_cancellations_reason_check CHECK (reason IS NULL OR reason IN ('not_for_me', 'too_busy', 'too_expensive', 'content', 'people', 'other')), CONSTRAINT community_cancellations_note_check CHECK (note IS NULL OR char_length(note) <= 500)); CREATE INDEX IF NOT EXISTS community_cancellations_community_idx ON public.community_cancellations (community_id, created_at DESC); ALTER TABLE public.community_cancellations ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_cancellations FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE ON public.community_cancellations TO service_role; END $do$;
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'community refunds: there is no communities table, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, order_id uuid NOT NULL, stripe_refund_id text NOT NULL, member_user_id uuid, amount_cents integer NOT NULL, currency text NOT NULL DEFAULT 'usd', full_refund boolean NOT NULL DEFAULT false, reason text, refunded_by uuid, ended_membership boolean NOT NULL DEFAULT false, emailed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_refunds_stripe_unique UNIQUE (stripe_refund_id), CONSTRAINT community_refunds_amount_check CHECK (amount_cents > 0), CONSTRAINT community_refunds_currency_check CHECK (currency ~ '^[a-z]{3}$'), CONSTRAINT community_refunds_reason_check CHECK (reason IS NULL OR char_length(reason) <= 500)); CREATE INDEX IF NOT EXISTS community_refunds_community_idx ON public.community_refunds (community_id, created_at DESC); CREATE INDEX IF NOT EXISTS community_refunds_order_idx ON public.community_refunds (order_id); ALTER TABLE public.community_refunds ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_refunds FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE ON public.community_refunds TO service_role; END $do$;
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'community contact messages: there is no communities table, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, sender_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, subject text NOT NULL, body text NOT NULL, delivered boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_contact_messages_subject_check CHECK (char_length(subject) BETWEEN 1 AND 120), CONSTRAINT community_contact_messages_body_check CHECK (char_length(body) BETWEEN 1 AND 2000)); CREATE INDEX IF NOT EXISTS community_contact_messages_sender_idx ON public.community_contact_messages (community_id, sender_id, created_at DESC); ALTER TABLE public.community_contact_messages ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_contact_messages FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_contact_messages TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('101', '101_community_membership_lifecycle.sql', '85ea0190839586904572635654e5092aa09c3356aa0179700fcf70b3b27605f2') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 102_community_programs.sql
/* Learn: programs in a community, run after parts 74 and 81. A community's Classroom becomes Learn, and what it holds are programs made of modules and lessons. The existing `community_courses` table becomes the program row, so every course already attached keeps working: it gains its own `id` (filled for every row, and the primary key from now on, with the old pair `community_id, product_id` kept unique), a `title`, `summary` and `cover_url` for a program made inside the community, a `status` (draft or published, every existing row published), an optional `price_cents` and `currency` for a program sold on its own, a `course_id` pointing at the program's own modules and lessons in the existing `courses` tables, and `updated_at`; `product_id` may now be empty, because a program made in the community is not a Storelib product. `courses.product_id` and `course_enrollments.product_id` may be empty for the same reason; every existing row keeps its product. A new server only table `community_program_access` records who bought a program (or was given it), once per person and program, with the Stripe checkout session that paid for it kept unique so a payment is counted once. No existing rows change apart from the new id and the default status. Until it runs, the Learn page shows the attached courses as before and programs cannot be made or sold. Where part 74 or 81 is missing that half skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_courses') IS NULL THEN RAISE NOTICE 'programs: there is no community_courses table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS id uuid NOT NULL DEFAULT gen_random_uuid(); ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS title text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS summary text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS cover_url text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'published'; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS price_cents integer; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS currency text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS course_id uuid; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now(); IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_community_product_key' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_community_product_key UNIQUE (community_id, product_id); END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_pkey' AND conrelid = 'public.community_courses'::regclass AND cardinality(conkey) = 2) THEN ALTER TABLE public.community_courses DROP CONSTRAINT community_courses_pkey; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.community_courses'::regclass AND contype = 'p') THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_pkey PRIMARY KEY (id); END IF; ALTER TABLE public.community_courses ALTER COLUMN product_id DROP NOT NULL; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_status_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_status_check CHECK (status IN ('draft', 'published')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_title_length' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_title_length CHECK (title IS NULL OR char_length(title) BETWEEN 1 AND 120); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_summary_length' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_summary_length CHECK (summary IS NULL OR char_length(summary) <= 2000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_price_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_price_check CHECK (price_cents IS NULL OR price_cents BETWEEN 50 AND 99999999); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_currency_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_currency_check CHECK (currency IS NULL OR currency ~ '^[a-z]{3}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_source_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_source_check CHECK (product_id IS NOT NULL OR title IS NOT NULL); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_course_key' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_course_key UNIQUE (course_id); END IF; IF to_regclass('public.courses') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_course_id_fkey' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.courses(id) ON DELETE SET NULL; END IF; CREATE INDEX IF NOT EXISTS community_courses_community_position_idx ON public.community_courses (community_id, position); END $do$;
DO $do$ BEGIN IF to_regclass('public.courses') IS NULL THEN RAISE NOTICE 'programs: there is no courses table, run part 74 first.'; RETURN; END IF; ALTER TABLE public.courses ALTER COLUMN product_id DROP NOT NULL; IF to_regclass('public.course_enrollments') IS NOT NULL THEN ALTER TABLE public.course_enrollments ALTER COLUMN product_id DROP NOT NULL; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_courses') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_courses' AND column_name = 'id') THEN RAISE NOTICE 'program access: community_courses has no id yet, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_program_access (program_id uuid NOT NULL REFERENCES public.community_courses(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, source text NOT NULL DEFAULT 'purchase', checkout_session_id text, payment_intent_id text, amount_cents integer, currency text, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, PRIMARY KEY (program_id, user_id), CONSTRAINT community_program_access_source_check CHECK (source IN ('purchase', 'grant')), CONSTRAINT community_program_access_session_key UNIQUE (checkout_session_id), CONSTRAINT community_program_access_amount_check CHECK (amount_cents IS NULL OR amount_cents >= 0)); CREATE INDEX IF NOT EXISTS community_program_access_user_idx ON public.community_program_access (user_id, community_id); ALTER TABLE public.community_program_access ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_program_access FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_program_access TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('102', '102_community_programs.sql', 'c35f28cb0e8b6f17eba426fabb8eee5ba46b2c45fa5e96ac24cdbd416ce2fc36') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 103_profile_display_names.sql
/* The name a person goes by, for every account that has a made up one, run after nothing else. Nobody is "Your profile", "Creator" or "Unknown" (lib/profile/display-name.ts). The new user trigger read a `display_name` Google and Apple never send, so every account made with them got the letters of its email before the @ as its name. First: an account whose provider sent a name (`auth.users.raw_user_meta_data`: `full_name`, else `name`, else the given and family names) and whose profile name is empty, a placeholder word, or exactly those email letters gets the provider's name. Then: a profile name still empty or a placeholder word gets words from the handle ("maya-prints" is "Maya Prints"). A name somebody typed is never touched. From now on every sign in does the same (lib/profile/keep-name.ts) and a new account is asked "What should we call you?". Changes only `profiles.display_name`; adds no table, column or trigger. The first step skips itself with a notice where `auth.users` cannot be read. Safe to run again: a second run finds nobody left to change. */
DO $$ BEGIN IF to_regclass('auth.users') IS NULL OR to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profile display names from the provider skipped: auth.users or profiles is not there'; RETURN; END IF; UPDATE public.profiles p SET display_name = x.name FROM (SELECT u.id, u.email, left(btrim(regexp_replace(coalesce(nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''), nullif(btrim(u.raw_user_meta_data ->> 'name'), ''), nullif(btrim(coalesce(u.raw_user_meta_data ->> 'given_name', '') || ' ' || coalesce(u.raw_user_meta_data ->> 'family_name', '')), '')), '[[:space:][:cntrl:]]+', ' ', 'g')), 60) AS name FROM auth.users u) x, auth.users u WHERE u.id = p.id AND x.id = p.id AND length(x.name) >= 2 and position('@' in x.name) = 0 and lower(x.name) not in ('your profile', 'creator', 'unknown', 'user', 'member', 'anonymous', 'someone', 'null', 'undefined', 'new user', 'storelib user', 'storelib member') AND (p.display_name is null or btrim(p.display_name) = '' or lower(btrim(p.display_name)) in ('your profile', 'creator', 'unknown', 'user', 'member', 'anonymous', 'someone', 'null', 'undefined', 'new user', 'storelib user', 'storelib member') or lower(btrim(p.display_name)) = lower(split_part(coalesce(p.email, u.email, ''), '@', 1)) or lower(btrim(p.display_name)) = lower(split_part(split_part(coalesce(p.email, u.email, ''), '@', 1), '+', 1))) AND p.display_name IS DISTINCT FROM x.name; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'profile display names from the provider skipped: this role may not read auth.users, so names are kept from the next sign in only'; END $$;
DO $$ BEGIN IF to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profile display names from the handle skipped: profiles is not there'; RETURN; END IF; UPDATE public.profiles p SET display_name = initcap(btrim(regexp_replace(regexp_replace(p.username, '[0-9]+', ' ', 'g'), '[._[:space:]-]+', ' ', 'g'))) WHERE p.username IS NOT NULL AND (p.display_name is null or btrim(p.display_name) = '' or lower(btrim(p.display_name)) in ('your profile', 'creator', 'unknown', 'user', 'member', 'anonymous', 'someone', 'null', 'undefined', 'new user', 'storelib user', 'storelib member')) AND length(initcap(btrim(regexp_replace(regexp_replace(p.username, '[0-9]+', ' ', 'g'), '[._[:space:]-]+', ' ', 'g')))) >= 2 and lower(initcap(btrim(regexp_replace(regexp_replace(p.username, '[0-9]+', ' ', 'g'), '[._[:space:]-]+', ' ', 'g')))) not in ('your profile', 'creator', 'unknown', 'user', 'member', 'anonymous', 'someone', 'null', 'undefined', 'new user', 'storelib user', 'storelib member') and lower(initcap(btrim(regexp_replace(regexp_replace(p.username, '[0-9]+', ' ', 'g'), '[._[:space:]-]+', ' ', 'g')))) not like '% member'; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('103', '103_profile_display_names.sql', '27eef081507c7f64bbf7e8cc53869e3a61b6295c8e8d72d8c6f96b2e8faf4dfb') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 104_community_deleted_rows_kept.sql
/* A deleted community row can be put back, like a product or an order, run after parts 66 and 81. Part 66 keeps a copy of every deleted row of the tables that hold creators' and buyers' work in public.deleted_rows for 90 days, with public.storelib_restore_deleted_row(id) to put one back; none of the community tables were on its list. This adds them: a community, its spaces, tiers, levels, badges, courses, events, access products, posts, comments, members and invite links, and the videos of the media library, so a mistake, a bug or a cascade (deleting a community deletes everything in it) can be undone row by row without restoring the whole database. The same trigger and the same function as part 66; nothing else changes. Where part 66 has not run, or a table is not there yet, that table is skipped. Safe to run again. */
DO $do$ DECLARE t text; BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL OR to_regclass('public.deleted_rows') IS NULL THEN RAISE NOTICE 'community deleted rows: part 66 has not run, so there is nothing to keep copies in yet.'; RETURN; END IF; FOREACH t IN ARRAY ARRAY['communities', 'community_spaces', 'community_tiers', 'community_levels', 'community_badges', 'community_courses', 'community_events', 'community_access_products', 'community_feed_posts', 'community_feed_comments', 'community_members', 'community_invites', 'media_videos'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_keep_deleted', t); EXECUTE format('CREATE TRIGGER %I AFTER DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row()', t || '_keep_deleted', t); END LOOP; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('104', '104_community_deleted_rows_kept.sql', '140184506fa105728521677c94de617c4800355fcc6c1ce23873f1c6028f89ae') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 105_community_paid_events.sql
/* Paid events: a ticket somebody buys, run after part 81. An event can have a price, and then its details are only for people who hold a ticket. New columns on `community_events`: `price_cents` (empty means free, as every event is today), `currency`, `sales_close_at` (empty means tickets stop at the start), `refund_window_hours` (empty means no refund button for the holder; a number lets them refund themselves until that many hours before the start), `refund_policy` (this event's own words, at most 2000 characters, falling back to the community's from part 101) and `tickets_sold`, which the functions below keep. A new server only table `community_event_tickets`: one row per person and event, with how it was come by (bought, invited or given), the Stripe checkout session (unique, so one payment is one ticket), the payment, what was paid and the platform's fee, a hold while a payment is being made, and when it was paid, refunded or cancelled. Five functions do the counting in one locked statement each, the way `community_rsvp` does: `community_event_ticket_hold` keeps a seat for the minutes a checkout takes (never past the capacity), `community_event_ticket_pay` turns a paid session into the ticket (and is safe to call twice, since the webhook and the page both call it), `community_event_ticket_grant` gives a free ticket to somebody invited, `community_event_ticket_release` refunds or gives up a ticket and frees the seat, and `community_event_release_holds` tidies holds nobody paid. A paid ticket also writes the person's "going" answer, so the reminders, the attendee avatars and the calendar keep working as they do for a free event. No existing rows change: every event stays free until somebody sets a price. Until it runs, events work exactly as before and no price can be set. Needs part 81; skips itself with a notice without it. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_events') IS NULL THEN RAISE NOTICE 'paid events: there is no community_events table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS price_cents integer; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS currency text; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS sales_close_at timestamptz; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS refund_window_hours integer; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS refund_policy text; ALTER TABLE public.community_events ADD COLUMN IF NOT EXISTS tickets_sold integer NOT NULL DEFAULT 0; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_events_price_check' AND conrelid = 'public.community_events'::regclass) THEN ALTER TABLE public.community_events ADD CONSTRAINT community_events_price_check CHECK (price_cents IS NULL OR price_cents BETWEEN 50 AND 99999999); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_events_currency_check' AND conrelid = 'public.community_events'::regclass) THEN ALTER TABLE public.community_events ADD CONSTRAINT community_events_currency_check CHECK (currency IS NULL OR currency ~ '^[a-z]{3}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_events_refund_window_check' AND conrelid = 'public.community_events'::regclass) THEN ALTER TABLE public.community_events ADD CONSTRAINT community_events_refund_window_check CHECK (refund_window_hours IS NULL OR refund_window_hours BETWEEN 0 AND 8760); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_events_refund_policy_length' AND conrelid = 'public.community_events'::regclass) THEN ALTER TABLE public.community_events ADD CONSTRAINT community_events_refund_policy_length CHECK (refund_policy IS NULL OR char_length(refund_policy) <= 2000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_events_tickets_sold_check' AND conrelid = 'public.community_events'::regclass) THEN ALTER TABLE public.community_events ADD CONSTRAINT community_events_tickets_sold_check CHECK (tickets_sold >= 0); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_events') IS NULL THEN RAISE NOTICE 'event tickets: there is no community_events table, run part 81 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.community_event_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.community_events(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'held', source text NOT NULL DEFAULT 'purchase', checkout_session_id text, payment_intent_id text, amount_cents integer, currency text, platform_fee_cents integer, held_until timestamptz, paid_at timestamptz, refunded_at timestamptz, cancelled_at timestamptz, refund_reason text, invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, invite_email text, attended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_event_tickets_person_unique UNIQUE (event_id, user_id), CONSTRAINT community_event_tickets_session_unique UNIQUE (checkout_session_id), CONSTRAINT community_event_tickets_status_check CHECK (status IN ('held', 'paid', 'refunded', 'cancelled')), CONSTRAINT community_event_tickets_source_check CHECK (source IN ('purchase', 'invite', 'grant')), CONSTRAINT community_event_tickets_amount_check CHECK (amount_cents IS NULL OR amount_cents >= 0), CONSTRAINT community_event_tickets_currency_check CHECK (currency IS NULL OR currency ~ '^[a-z]{3}$'), CONSTRAINT community_event_tickets_reason_check CHECK (refund_reason IS NULL OR char_length(refund_reason) <= 500), CONSTRAINT community_event_tickets_email_check CHECK (invite_email IS NULL OR char_length(invite_email) <= 254)); CREATE INDEX IF NOT EXISTS community_event_tickets_event_idx ON public.community_event_tickets (event_id, status); CREATE INDEX IF NOT EXISTS community_event_tickets_user_idx ON public.community_event_tickets (user_id, created_at DESC); CREATE INDEX IF NOT EXISTS community_event_tickets_community_idx ON public.community_event_tickets (community_id, created_at DESC); CREATE INDEX IF NOT EXISTS community_event_tickets_intent_idx ON public.community_event_tickets (payment_intent_id) WHERE payment_intent_id IS NOT NULL; ALTER TABLE public.community_event_tickets ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_event_tickets FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_event_tickets TO service_role; END $do$;
CREATE OR REPLACE FUNCTION public.community_event_seats_taken(p_event uuid, p_except uuid DEFAULT NULL) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT count(*)::integer FROM public.community_event_tickets WHERE event_id = p_event AND (p_except IS NULL OR user_id <> p_except) AND (status = 'paid' OR (status = 'held' AND held_until IS NOT NULL AND held_until > now())) $f$;
CREATE OR REPLACE FUNCTION public.community_event_ticket_hold(p_event uuid, p_user uuid, p_session text, p_minutes integer DEFAULT 30) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_event public.community_events%ROWTYPE; v_ticket public.community_event_tickets%ROWTYPE; v_taken integer; v_minutes integer := greatest(5, least(180, coalesce(p_minutes, 30))); BEGIN SELECT * INTO v_event FROM public.community_events WHERE id = p_event FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_event.status <> 'scheduled' THEN RETURN jsonb_build_object('ok', false, 'reason', 'closed'); END IF; IF coalesce(v_event.price_cents, 0) <= 0 THEN RETURN jsonb_build_object('ok', false, 'reason', 'free'); END IF; IF coalesce(v_event.sales_close_at, v_event.starts_at) <= now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'sales_closed'); END IF; SELECT * INTO v_ticket FROM public.community_event_tickets WHERE event_id = p_event AND user_id = p_user; IF v_ticket.id IS NOT NULL AND v_ticket.status = 'paid' THEN RETURN jsonb_build_object('ok', false, 'reason', 'already_paid', 'ticket_id', v_ticket.id); END IF; v_taken := public.community_event_seats_taken(p_event, p_user); IF v_event.capacity IS NOT NULL AND v_taken >= v_event.capacity THEN RETURN jsonb_build_object('ok', false, 'reason', 'full', 'seats_left', 0); END IF; INSERT INTO public.community_event_tickets (event_id, community_id, user_id, status, source, checkout_session_id, amount_cents, currency, held_until) VALUES (p_event, v_event.community_id, p_user, 'held', 'purchase', p_session, v_event.price_cents, coalesce(v_event.currency, 'usd'), now() + make_interval(mins => v_minutes)) ON CONFLICT (event_id, user_id) DO UPDATE SET status = 'held', source = 'purchase', checkout_session_id = EXCLUDED.checkout_session_id, amount_cents = EXCLUDED.amount_cents, currency = EXCLUDED.currency, held_until = EXCLUDED.held_until, cancelled_at = NULL, refunded_at = NULL, refund_reason = NULL, updated_at = now() RETURNING * INTO v_ticket; RETURN jsonb_build_object('ok', true, 'ticket_id', v_ticket.id, 'held_until', v_ticket.held_until, 'amount_cents', v_ticket.amount_cents, 'currency', v_ticket.currency, 'seats_left', CASE WHEN v_event.capacity IS NULL THEN NULL ELSE greatest(0, v_event.capacity - v_taken - 1) END); END $f$;
CREATE OR REPLACE FUNCTION public.community_event_ticket_pay(p_session text, p_event uuid, p_user uuid, p_intent text, p_amount integer, p_currency text, p_fee integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_event public.community_events%ROWTYPE; v_ticket public.community_event_tickets%ROWTYPE; BEGIN SELECT * INTO v_event FROM public.community_events WHERE id = p_event FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF p_session IS NOT NULL THEN SELECT * INTO v_ticket FROM public.community_event_tickets WHERE checkout_session_id = p_session; END IF; IF v_ticket.id IS NULL THEN SELECT * INTO v_ticket FROM public.community_event_tickets WHERE event_id = p_event AND user_id = p_user; END IF; IF v_ticket.id IS NOT NULL AND v_ticket.status = 'paid' THEN RETURN jsonb_build_object('ok', true, 'created', false, 'ticket_id', v_ticket.id, 'event_id', v_event.id, 'user_id', v_ticket.user_id); END IF; INSERT INTO public.community_event_tickets (event_id, community_id, user_id, status, source, checkout_session_id, payment_intent_id, amount_cents, currency, platform_fee_cents, held_until, paid_at) VALUES (p_event, v_event.community_id, p_user, 'paid', 'purchase', p_session, p_intent, p_amount, coalesce(p_currency, v_event.currency, 'usd'), p_fee, NULL, now()) ON CONFLICT (event_id, user_id) DO UPDATE SET status = 'paid', source = 'purchase', checkout_session_id = coalesce(EXCLUDED.checkout_session_id, community_event_tickets.checkout_session_id), payment_intent_id = coalesce(EXCLUDED.payment_intent_id, community_event_tickets.payment_intent_id), amount_cents = coalesce(EXCLUDED.amount_cents, community_event_tickets.amount_cents), currency = coalesce(EXCLUDED.currency, community_event_tickets.currency), platform_fee_cents = coalesce(EXCLUDED.platform_fee_cents, community_event_tickets.platform_fee_cents), held_until = NULL, cancelled_at = NULL, refunded_at = NULL, refund_reason = NULL, paid_at = coalesce(community_event_tickets.paid_at, now()), updated_at = now() RETURNING * INTO v_ticket; UPDATE public.community_events SET tickets_sold = (SELECT count(*) FROM public.community_event_tickets WHERE event_id = p_event AND status = 'paid') WHERE id = p_event; IF to_regclass('public.community_event_rsvps') IS NOT NULL THEN INSERT INTO public.community_event_rsvps (event_id, user_id, community_id, status) VALUES (p_event, p_user, v_event.community_id, 'going') ON CONFLICT (event_id, user_id) DO UPDATE SET status = 'going'; END IF; RETURN jsonb_build_object('ok', true, 'created', true, 'ticket_id', v_ticket.id, 'event_id', v_event.id, 'user_id', v_ticket.user_id, 'amount_cents', v_ticket.amount_cents, 'currency', v_ticket.currency); END $f$;
CREATE OR REPLACE FUNCTION public.community_event_ticket_grant(p_event uuid, p_user uuid, p_source text DEFAULT 'invite', p_by uuid DEFAULT NULL, p_email text DEFAULT NULL, p_force boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_event public.community_events%ROWTYPE; v_ticket public.community_event_tickets%ROWTYPE; v_taken integer; v_source text := CASE WHEN p_source IN ('invite', 'grant') THEN p_source ELSE 'invite' END; BEGIN SELECT * INTO v_event FROM public.community_events WHERE id = p_event FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; SELECT * INTO v_ticket FROM public.community_event_tickets WHERE event_id = p_event AND user_id = p_user; IF v_ticket.id IS NOT NULL AND v_ticket.status = 'paid' THEN RETURN jsonb_build_object('ok', true, 'created', false, 'ticket_id', v_ticket.id); END IF; v_taken := public.community_event_seats_taken(p_event, p_user); IF NOT p_force AND v_event.capacity IS NOT NULL AND v_taken >= v_event.capacity THEN RETURN jsonb_build_object('ok', false, 'reason', 'full'); END IF; INSERT INTO public.community_event_tickets (event_id, community_id, user_id, status, source, amount_cents, currency, held_until, paid_at, invited_by, invite_email) VALUES (p_event, v_event.community_id, p_user, 'paid', v_source, 0, coalesce(v_event.currency, 'usd'), NULL, now(), p_by, p_email) ON CONFLICT (event_id, user_id) DO UPDATE SET status = 'paid', source = v_source, amount_cents = 0, held_until = NULL, cancelled_at = NULL, refunded_at = NULL, refund_reason = NULL, paid_at = coalesce(community_event_tickets.paid_at, now()), invited_by = coalesce(EXCLUDED.invited_by, community_event_tickets.invited_by), invite_email = coalesce(EXCLUDED.invite_email, community_event_tickets.invite_email), updated_at = now() RETURNING * INTO v_ticket; UPDATE public.community_events SET tickets_sold = (SELECT count(*) FROM public.community_event_tickets WHERE event_id = p_event AND status = 'paid') WHERE id = p_event; IF to_regclass('public.community_event_rsvps') IS NOT NULL THEN INSERT INTO public.community_event_rsvps (event_id, user_id, community_id, status) VALUES (p_event, p_user, v_event.community_id, 'going') ON CONFLICT (event_id, user_id) DO UPDATE SET status = 'going'; END IF; RETURN jsonb_build_object('ok', true, 'created', true, 'ticket_id', v_ticket.id, 'source', v_source); END $f$;
CREATE OR REPLACE FUNCTION public.community_event_ticket_release(p_ticket uuid, p_status text DEFAULT 'refunded', p_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_ticket public.community_event_tickets%ROWTYPE; v_status text := CASE WHEN p_status IN ('refunded', 'cancelled') THEN p_status ELSE 'refunded' END; v_next uuid; BEGIN SELECT * INTO v_ticket FROM public.community_event_tickets WHERE id = p_ticket FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_ticket.status = v_status THEN RETURN jsonb_build_object('ok', true, 'changed', false, 'event_id', v_ticket.event_id, 'user_id', v_ticket.user_id, 'payment_intent_id', v_ticket.payment_intent_id, 'amount_cents', v_ticket.amount_cents); END IF; UPDATE public.community_event_tickets SET status = v_status, refunded_at = CASE WHEN v_status = 'refunded' THEN now() ELSE refunded_at END, cancelled_at = CASE WHEN v_status = 'cancelled' THEN now() ELSE cancelled_at END, refund_reason = coalesce(left(p_reason, 500), refund_reason), held_until = NULL, updated_at = now() WHERE id = p_ticket; UPDATE public.community_events SET tickets_sold = (SELECT count(*) FROM public.community_event_tickets WHERE event_id = v_ticket.event_id AND status = 'paid') WHERE id = v_ticket.event_id; IF to_regclass('public.community_event_rsvps') IS NOT NULL THEN UPDATE public.community_event_rsvps SET status = 'cancelled' WHERE event_id = v_ticket.event_id AND user_id = v_ticket.user_id; SELECT user_id INTO v_next FROM public.community_event_rsvps WHERE event_id = v_ticket.event_id AND status = 'waitlist' ORDER BY updated_at, user_id LIMIT 1; END IF; RETURN jsonb_build_object('ok', true, 'changed', true, 'event_id', v_ticket.event_id, 'user_id', v_ticket.user_id, 'payment_intent_id', v_ticket.payment_intent_id, 'amount_cents', v_ticket.amount_cents, 'next_waiting', v_next); END $f$;
CREATE OR REPLACE FUNCTION public.community_event_release_holds() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_count integer; BEGIN WITH gone AS (UPDATE public.community_event_tickets SET status = 'cancelled', cancelled_at = now(), held_until = NULL, updated_at = now() WHERE status = 'held' AND held_until IS NOT NULL AND held_until <= now() RETURNING 1) SELECT count(*)::integer INTO v_count FROM gone; RETURN coalesce(v_count, 0); END $f$;
DO $do$ DECLARE f text; BEGIN FOREACH f IN ARRAY ARRAY['community_event_seats_taken(uuid, uuid)', 'community_event_ticket_hold(uuid, uuid, text, integer)', 'community_event_ticket_pay(text, uuid, uuid, text, integer, text, integer)', 'community_event_ticket_grant(uuid, uuid, text, uuid, text, boolean)', 'community_event_ticket_release(uuid, text, text)', 'community_event_release_holds()'] LOOP IF to_regprocedure('public.' || f) IS NULL THEN CONTINUE; END IF; EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC, anon, authenticated', f); EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO service_role', f); END LOOP; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL OR to_regclass('public.community_event_tickets') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS community_event_tickets_keep_deleted ON public.community_event_tickets; CREATE TRIGGER community_event_tickets_keep_deleted AFTER DELETE ON public.community_event_tickets FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('105', '105_community_paid_events.sql', '379bffb7680beb1ebcb6bd134bf90f6ffe76d1d0a100855904af03aa42e0246a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 106_ai_memory.sql
/* AI Memory, run after the creators and website tables exist. One table, `ai_memories`: what a creator asked Storelib AI to remember, for their whole account (install_id empty) or for one website, up to 500 characters each, written by the creator or by the assistant when asked. Row level security: a signed in person reads, adds and deletes only their own, and a website's memory only for a website of theirs; nobody can change one in place. No rows change. Until it runs, Storelib AI keeps only each website's own notes. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL OR to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'ai memory: the creators or website tables are not there yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.ai_memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, install_id uuid REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, content text NOT NULL CHECK (length(btrim(content)) BETWEEN 1 AND 500), source text NOT NULL DEFAULT 'creator' CHECK (source IN ('creator', 'assistant')), created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS ai_memories_creator_idx ON public.ai_memories (creator_id, created_at DESC); ALTER TABLE public.ai_memories ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS ai_memories_select_own ON public.ai_memories; CREATE POLICY ai_memories_select_own ON public.ai_memories FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = auth.uid())); DROP POLICY IF EXISTS ai_memories_insert_own ON public.ai_memories; CREATE POLICY ai_memories_insert_own ON public.ai_memories FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = auth.uid()) AND (install_id IS NULL OR install_id IN (SELECT i.id FROM public.store_theme_installs i WHERE i.creator_id = ai_memories.creator_id))); DROP POLICY IF EXISTS ai_memories_delete_own ON public.ai_memories; CREATE POLICY ai_memories_delete_own ON public.ai_memories FOR DELETE TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = auth.uid())); REVOKE UPDATE ON public.ai_memories FROM authenticated, anon; REVOKE ALL ON public.ai_memories FROM anon; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('106', '106_ai_memory.sql', 'b3c17e6371b0769c5bd5150d385999bfce3dad333675c8f2a983950246629d00') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 107_product_custom_fields.sql
/* Product custom fields, run after the products table exists. One column on `products`, `custom_fields`: up to twenty named plain values a creator writes in the product editor (Material, Care, ISBN) and a website section prints as fields.material. An object, under 16 KB; NOT VALID, so no old row is rechecked. No rows change: every product starts with none. Until it runs, the editor saves products as before and leaves the fields unsaved. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'product custom fields: the products table is not there yet.'; RETURN; END IF; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS custom_fields jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_custom_fields_shape, ADD CONSTRAINT products_custom_fields_shape CHECK (jsonb_typeof(custom_fields) = 'object' AND pg_column_size(custom_fields) < 16384) NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('107', '107_product_custom_fields.sql', '8f12fbc7812e39e9e15f89a0eda8f825bf475a02840acd373d9ea32713cdc295') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 108_default_collections.sql
/* Part 108. Every store starts with two collections, as on Shopify: All products (smart, every product, newest first) and Home page (picked by hand). A server only table default_collections_given marks a store that has been given them, so a store that deletes them keeps them deleted, and every existing store with no collections at all gets the two now. Needs product_collections (part 78 or 95). Additive: nothing is dropped or renamed. Safe to run again. */
DO $$
BEGIN
  IF to_regclass('public.creators') IS NULL OR to_regclass('public.product_collections') IS NULL THEN
    RAISE NOTICE 'default collections: run part 95 (collections) first, nothing to do.';
    RETURN;
  END IF;
  CREATE TABLE IF NOT EXISTS public.default_collections_given (
    creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE,
    given_at timestamptz NOT NULL DEFAULT now()
  );
  ALTER TABLE public.default_collections_given ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON public.default_collections_given FROM anon, authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public.default_collections_given TO service_role;
  INSERT INTO public.product_collections (creator_id, title, slug, description, kind, rules, match, sort, published)
  SELECT c.id, d.title, d.slug, d.description, d.kind, d.rules, 'all', d.sort, true
  FROM public.creators c
  CROSS JOIN (VALUES
    ('All products', 'all-products', 'Every product in the store.', 'smart', '[{"field":"price","op":"greater_than","value":"-1"}]'::jsonb, 'newest'),
    ('Home page', 'home-page', 'Products picked for the home page.', 'manual', '[]'::jsonb, 'manual')
  ) AS d(title, slug, description, kind, rules, sort)
  WHERE NOT EXISTS (SELECT 1 FROM public.default_collections_given g WHERE g.creator_id = c.id)
    AND NOT EXISTS (SELECT 1 FROM public.product_collections pc WHERE pc.creator_id = c.id)
  ON CONFLICT (creator_id, slug) DO NOTHING;
  INSERT INTO public.default_collections_given (creator_id) SELECT c.id FROM public.creators c ON CONFLICT (creator_id) DO NOTHING;
END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('108', '108_default_collections.sql', '4e3c82d18ae578d903822630d1b5b3e5bdb79800918efe3d9f2a9ac65abf1f38') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 109_store_settings.sql
/* Store settings, reasons and sales channels, run after part 78 (physical commerce). Three things a store keeps beside its products. `store_settings`, one row a store: the name and phone receipts and order emails show, the country it is based in (new locations and tax start there), and how checkout behaves (accounts, marketing consent, which fields are asked for), as one small object. `commerce_reasons`: the reasons a buyer picks when asking for a return and the shop picks when refunding, each a short value kept on the return and a label people see; a return now accepts any such value rather than seven fixed ones, and keeps the label it was asked with. `sales_channels` with `product_channel_listings`: where products are sold, the Storefront channel being the online store; a listing row only records a product taken off a channel, so every product stays on every channel until someone takes it off. All three are read by the owner and written by the server. Until it runs, Settings shows these sections with their defaults and saving says the database needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_settings (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, store_name text CHECK (store_name IS NULL OR length(btrim(store_name)) BETWEEN 1 AND 80), phone text CHECK (phone IS NULL OR phone ~ '^\+[0-9][0-9 ]{5,23}$'), phone_country text CHECK (phone_country IS NULL OR phone_country ~ '^[A-Z]{2}$'), default_country text CHECK (default_country IS NULL OR default_country ~ '^[A-Z]{2}$'), checkout jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(checkout) = 'object' AND pg_column_size(checkout) < 8192), default_sales_channel_id uuid, reasons_seeded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS store_settings_owner_read ON public.store_settings;
CREATE POLICY store_settings_owner_read ON public.store_settings FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = store_settings.creator_id AND c.user_id = auth.uid()));
CREATE TABLE IF NOT EXISTS public.commerce_reasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('return', 'refund')), value text NOT NULL CHECK (value ~ '^[a-z0-9_]{1,40}$'), label text NOT NULL CHECK (length(btrim(label)) BETWEEN 1 AND 60), description text CHECK (description IS NULL OR length(description) <= 200), position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS commerce_reasons_value_key ON public.commerce_reasons (creator_id, kind, value);
CREATE INDEX IF NOT EXISTS commerce_reasons_list_idx ON public.commerce_reasons (creator_id, kind, position);
ALTER TABLE public.commerce_reasons ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS commerce_reasons_owner_read ON public.commerce_reasons;
CREATE POLICY commerce_reasons_owner_read ON public.commerce_reasons FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = commerce_reasons.creator_id AND c.user_id = auth.uid()));
DO $do$ BEGIN IF to_regclass('public.commerce_returns') IS NULL THEN RAISE NOTICE 'reasons: commerce_returns is not there yet (part 78).'; RETURN; END IF; ALTER TABLE public.commerce_returns DROP CONSTRAINT IF EXISTS commerce_returns_reason_check; ALTER TABLE public.commerce_returns DROP CONSTRAINT IF EXISTS commerce_returns_reason_code, ADD CONSTRAINT commerce_returns_reason_code CHECK (reason ~ '^[a-z0-9_]{1,40}$') NOT VALID; ALTER TABLE public.commerce_returns ADD COLUMN IF NOT EXISTS reason_label text CHECK (reason_label IS NULL OR length(reason_label) <= 60); END $do$;
CREATE TABLE IF NOT EXISTS public.sales_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80), description text CHECK (description IS NULL OR length(description) <= 300), is_storefront boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS sales_channels_one_storefront ON public.sales_channels (creator_id) WHERE is_storefront;
CREATE INDEX IF NOT EXISTS sales_channels_list_idx ON public.sales_channels (creator_id, position);
ALTER TABLE public.sales_channels ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS sales_channels_owner_read ON public.sales_channels;
CREATE POLICY sales_channels_owner_read ON public.sales_channels FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = sales_channels.creator_id AND c.user_id = auth.uid()));
CREATE TABLE IF NOT EXISTS public.product_channel_listings (channel_id uuid NOT NULL REFERENCES public.sales_channels(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, listed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (channel_id, product_id));
CREATE INDEX IF NOT EXISTS product_channel_listings_creator_idx ON public.product_channel_listings (creator_id, channel_id);
ALTER TABLE public.product_channel_listings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS product_channel_listings_owner_read ON public.product_channel_listings;
CREATE POLICY product_channel_listings_owner_read ON public.product_channel_listings FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = product_channel_listings.creator_id AND c.user_id = auth.uid()));
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NOT NULL AND to_regclass('public.sales_channels') IS NOT NULL THEN ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_default_channel_fk, ADD CONSTRAINT store_settings_default_channel_fk FOREIGN KEY (default_sales_channel_id) REFERENCES public.sales_channels(id) ON DELETE SET NULL; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'checkout consent: commerce_checkouts is not there yet (part 78).'; RETURN; END IF; ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS email_opt_in boolean NOT NULL DEFAULT false; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('109', '109_store_settings.sql', '8787d9aab0ebef5974c5cd465f40b15936230a41f4b65c7b95ce70bb48e3eddc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 110_taxes.sql
/* Taxes for every store, run after parts 78 and 109. Settings › Taxes now belongs to every store, not only one that ships. `commerce_settings.tax_digital`: whether downloads, courses and memberships are taxed too, off for every store so nothing anybody pays changes until they turn it on. `commerce_tax_overrides`: one product's own rate inside one tax region ("books are 5% in Romania"), removed with its region or its product. `orders.tax_cents` and `orders.tax_country`: the tax inside a digital order and where it was charged, for receipts and reports; physical orders keep theirs on the checkout as before. Read by the owner, written by the server. Until it runs, Taxes shows its switches and regions, product rates cannot be added, and digital products are never taxed. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.commerce_settings') IS NULL THEN RAISE NOTICE 'taxes: commerce_settings is not there yet (part 78).'; RETURN; END IF; ALTER TABLE public.commerce_settings ADD COLUMN IF NOT EXISTS tax_digital boolean NOT NULL DEFAULT false; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_tax_rates') IS NULL THEN RAISE NOTICE 'taxes: commerce_tax_rates is not there yet (part 78).'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.commerce_tax_overrides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, tax_rate_id uuid NOT NULL REFERENCES public.commerce_tax_rates(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Reduced rate' CHECK (length(btrim(name)) BETWEEN 1 AND 60), rate_bps integer NOT NULL CHECK (rate_bps BETWEEN 0 AND 10000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS commerce_tax_overrides_place_key ON public.commerce_tax_overrides (tax_rate_id, product_id); CREATE INDEX IF NOT EXISTS commerce_tax_overrides_creator_idx ON public.commerce_tax_overrides (creator_id); ALTER TABLE public.commerce_tax_overrides ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS commerce_tax_overrides_owner_read ON public.commerce_tax_overrides; CREATE POLICY commerce_tax_overrides_owner_read ON public.commerce_tax_overrides FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = commerce_tax_overrides.creator_id AND c.user_id = auth.uid())); END $do$;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tax_cents integer NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tax_country text;
DO $do$ BEGIN ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_tax_cents_range, ADD CONSTRAINT orders_tax_cents_range CHECK (tax_cents >= 0) NOT VALID; ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_tax_country_code, ADD CONSTRAINT orders_tax_country_code CHECK (tax_country IS NULL OR tax_country ~ '^[A-Z]{2}$') NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('110', '110_taxes.sql', 'd92087784da56763e0a0488b19bff9fdf6e481de515eabae4a61dd221baddd0c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 111_sales_channel_kinds.sql
/* Sales channels by kind, run after part 109. A store sells in three places Storelib runs, and now each is a channel a product can be taken off: `storefront` (the store's website, its collections and its search), `creator_page` (storelib.com/name and the one page) and `marketplace` (Explore). Any other channel a store makes is `custom`: a name and a note for its own use, such as a market stall or a wholesale list. A store has at most one channel of each built-in kind; the old `is_storefront` row becomes the `storefront` one. Nothing is hidden by this part: a product leaves a channel only when someone takes it off. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.sales_channels') IS NULL THEN RAISE NOTICE 'sales channel kinds: sales_channels is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.sales_channels ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'custom'; ALTER TABLE public.sales_channels DROP CONSTRAINT IF EXISTS sales_channels_kind_check, ADD CONSTRAINT sales_channels_kind_check CHECK (kind IN ('storefront', 'creator_page', 'marketplace', 'custom')); UPDATE public.sales_channels SET kind = 'storefront' WHERE is_storefront AND kind <> 'storefront'; END $do$;
DO $do$ BEGIN IF to_regclass('public.sales_channels') IS NULL THEN RETURN; END IF; CREATE UNIQUE INDEX IF NOT EXISTS sales_channels_one_of_kind ON public.sales_channels (creator_id, kind) WHERE kind <> 'custom'; END $do$;
DO $do$ BEGIN IF to_regclass('public.product_channel_listings') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS product_channel_listings_off_idx ON public.product_channel_listings (creator_id, product_id) WHERE NOT listed; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('111', '111_sales_channel_kinds.sql', 'ee72c9fa10eaab15a95d7dda664d605d3403375a3fb369a0d87dc72fcd714093') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 112_integrations.sql
/* Integrations for every store, run after part 109. `store_settings.tracking`: the analytics and ad pixel IDs a store adds in Settings › Integrations (Google Analytics, Tag Manager, Google Ads, Meta, TikTok, Pinterest), as one small object of IDs; the website loads each service's own tag with its ID and nothing else, and every ID is checked against its service's format on the way in and on the way out. `integration_requests`: the service a store asks Storelib to support, read by Storelib in /admin, at most five a day a store. Owner read, server written. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'integrations: store_settings is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS tracking jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_tracking_shape, ADD CONSTRAINT store_settings_tracking_shape CHECK (jsonb_typeof(tracking) = 'object' AND pg_column_size(tracking) < 2048); END $do$;
CREATE TABLE IF NOT EXISTS public.integration_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80), note text CHECK (note IS NULL OR length(note) <= 600), status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'planned', 'done', 'declined')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS integration_requests_creator_idx ON public.integration_requests (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS integration_requests_new_idx ON public.integration_requests (created_at DESC) WHERE status = 'new';
ALTER TABLE public.integration_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS integration_requests_owner_read ON public.integration_requests;
CREATE POLICY integration_requests_owner_read ON public.integration_requests FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = integration_requests.creator_id AND c.user_id = auth.uid()));
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('112', '112_integrations.sql', '7371730a1431d3fd321261788577261fcfbc1e75b39fbb014af7f94f5d27454c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 113_store_activity.sql
/* A store's activity log. `store_activity_log` is one row for each change made to a store: who made it (the signed in person, Storelib itself, or a buyer, such as a return they opened), what it was (an action like `product.created`, `settings.checkout` or `order.fulfilled`), what it was about (a product, an order, a tax region, as its id and its name at the time) and a few details (from and to for a status). Settings, orders and files write their rows from the server; products write theirs from a trigger, because a product is saved straight from the editor: created, deleted, renamed, its price or its status changed, and nothing for any other edit. A row that can't be written is skipped and never stops the change it was about. The owner can read their own rows; nobody can write or change one but the server. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_activity_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, actor text NOT NULL DEFAULT 'person' CHECK (actor IN ('person', 'system', 'buyer')), action text NOT NULL CHECK (length(action) BETWEEN 3 AND 60), subject_type text CHECK (subject_type IS NULL OR length(subject_type) <= 40), subject_id text CHECK (subject_id IS NULL OR length(subject_id) <= 100), subject_label text CHECK (subject_label IS NULL OR length(subject_label) <= 200), meta jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(meta) = 'object' AND pg_column_size(meta) <= 4000));
CREATE INDEX IF NOT EXISTS store_activity_log_creator_idx ON public.store_activity_log (creator_id, created_at DESC, id DESC);
ALTER TABLE public.store_activity_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS store_activity_log_owner_read ON public.store_activity_log;
CREATE POLICY store_activity_log_owner_read ON public.store_activity_log FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = store_activity_log.creator_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.store_activity_log FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.store_activity_products() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE n jsonb; o jsonb; v_action text; v_meta jsonb := '{}'::jsonb; v_creator uuid; v_uid uuid := auth.uid(); BEGIN n := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END; o := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END; v_creator := nullif(coalesce(n ->> 'creator_id', o ->> 'creator_id'), '')::uuid; IF v_creator IS NULL THEN RETURN NULL; END IF; IF TG_OP = 'INSERT' THEN v_action := 'product.created'; ELSIF TG_OP = 'DELETE' THEN v_action := 'product.deleted'; ELSIF (n ->> 'status') IS DISTINCT FROM (o ->> 'status') THEN v_action := 'product.status'; v_meta := jsonb_build_object('from', o ->> 'status', 'to', n ->> 'status'); ELSIF (n -> 'price') IS DISTINCT FROM (o -> 'price') OR (n -> 'price_cents') IS DISTINCT FROM (o -> 'price_cents') THEN v_action := 'product.price'; ELSIF (n ->> 'title') IS DISTINCT FROM (o ->> 'title') THEN v_action := 'product.renamed'; v_meta := jsonb_build_object('from', left(o ->> 'title', 200)); ELSE RETURN NULL; END IF; INSERT INTO public.store_activity_log (creator_id, actor_user_id, actor, action, subject_type, subject_id, subject_label, meta) VALUES (v_creator, v_uid, CASE WHEN v_uid IS NULL THEN 'system' ELSE 'person' END, v_action, 'product', coalesce(n ->> 'id', o ->> 'id'), left(coalesce(nullif(n ->> 'title', ''), nullif(o ->> 'title', ''), 'Untitled'), 200), v_meta); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.store_activity_products() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS store_activity_products ON public.products;
CREATE TRIGGER store_activity_products AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.store_activity_products();
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('113', '113_store_activity.sql', '3f4c7382ea663baef64d141a1060394cdfd4124cfd038f38a7c33e16e5e78737') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 114_support_tickets.sql
/* Support requests from stores to Storelib, answered in /admin's Resolution center. `support_tickets` is one request: the store it is from, who opened it, its topic (orders, payments, disputes, payouts, shipping, account, website, a bug, or something else), a subject, the order or dispute it is about when there is one, whose turn it is (`open` is Storelib's, `waiting` is the store's, then `resolved`), a priority Storelib sets, and when it last moved. `support_ticket_messages` is the thread: each message from the store or from Storelib, and Storelib's internal notes, which the store never sees. A store reads its own requests and the messages on them that aren't internal notes; only the server writes. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, opened_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, topic text NOT NULL DEFAULT 'other' CHECK (topic IN ('orders', 'payments', 'disputes', 'payouts', 'shipping', 'account', 'website', 'bug', 'other')), subject text NOT NULL CHECK (length(btrim(subject)) BETWEEN 1 AND 150), status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'waiting', 'resolved')), priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')), order_ref text CHECK (order_ref IS NULL OR length(order_ref) <= 60), dispute_id uuid, creator_unread boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_message_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS support_tickets_creator_idx ON public.support_tickets (creator_id, last_message_at DESC);
CREATE INDEX IF NOT EXISTS support_tickets_queue_idx ON public.support_tickets (status, last_message_at DESC);
CREATE TABLE IF NOT EXISTS public.support_ticket_messages (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, ticket_id uuid NOT NULL REFERENCES public.support_tickets(id) ON DELETE CASCADE, author text NOT NULL CHECK (author IN ('creator', 'storelib')), internal boolean NOT NULL DEFAULT false, body text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT support_ticket_messages_note_is_storelib CHECK (NOT internal OR author = 'storelib'));
CREATE INDEX IF NOT EXISTS support_ticket_messages_ticket_idx ON public.support_ticket_messages (ticket_id, id);
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_ticket_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS support_tickets_owner_read ON public.support_tickets;
CREATE POLICY support_tickets_owner_read ON public.support_tickets FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = support_tickets.creator_id AND c.user_id = auth.uid()));
DROP POLICY IF EXISTS support_ticket_messages_owner_read ON public.support_ticket_messages;
CREATE POLICY support_ticket_messages_owner_read ON public.support_ticket_messages FOR SELECT TO authenticated USING (NOT internal AND EXISTS (SELECT 1 FROM public.support_tickets t JOIN public.creators c ON c.id = t.creator_id WHERE t.id = support_ticket_messages.ticket_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.support_tickets, public.support_ticket_messages FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('114', '114_support_tickets.sql', 'dd723d67773fc6094ceb88aa9ea056471da61665414930060e74f4f5cfbb54c7') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 115_integrations_admin_and_marketplace_search.sql
/* Integrations in /admin and physical products out of marketplace search, run after parts 112 to 114. `integration_requests` gains the integration a Coming soon page asked for (`integration_id`), Storelib's own note (`admin_note`) and `updated_at`, so /admin › Integrations can answer each request. `integration_catalog`: how /admin shows each integration in every store's directory (its name, line, icon, category, order; offered, paused or hidden) and the services added from /admin, always Coming soon; server only, never a key. `search_products_ranked` is the same search with physical products left out, so a shipped product never appears in Storelib's marketplace search; they belong to the creator's own website. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.integration_requests') IS NULL THEN RAISE NOTICE 'integrations admin: integration_requests is not there yet (part 112).'; RETURN; END IF; ALTER TABLE public.integration_requests ADD COLUMN IF NOT EXISTS integration_id text CHECK (integration_id IS NULL OR integration_id ~ '^[a-z0-9][a-z0-9-]{1,47}$'); ALTER TABLE public.integration_requests ADD COLUMN IF NOT EXISTS admin_note text CHECK (admin_note IS NULL OR length(admin_note) <= 600); ALTER TABLE public.integration_requests ADD COLUMN IF NOT EXISTS updated_at timestamptz; CREATE INDEX IF NOT EXISTS integration_requests_integration_idx ON public.integration_requests (integration_id, creator_id) WHERE integration_id IS NOT NULL; END $do$;
CREATE TABLE IF NOT EXISTS public.integration_catalog (id text PRIMARY KEY CHECK (id ~ '^[a-z0-9][a-z0-9-]{1,47}$'), name text CHECK (name IS NULL OR length(btrim(name)) BETWEEN 1 AND 60), summary text CHECK (summary IS NULL OR length(summary) <= 160), category text CHECK (category IS NULL OR category IN ('analytics', 'advertising', 'email', 'automation', 'shipping', 'print_on_demand', 'dropshipping', 'fulfillment', 'suppliers')), logo_url text CHECK (logo_url IS NULL OR length(logo_url) <= 500), docs_url text CHECK (docs_url IS NULL OR (docs_url ~ '^https://' AND length(docs_url) <= 500)), availability text NOT NULL DEFAULT 'default' CHECK (availability IN ('default', 'coming_soon', 'hidden')), custom boolean NOT NULL DEFAULT false, physical boolean NOT NULL DEFAULT false, sort integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.integration_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.integration_catalog FROM anon, authenticated;
create or replace function public.search_products_ranked(p_query text, p_category text default null, p_sort text default 'relevance', p_limit integer default 30, p_offset integer default 0) returns setof jsonb language sql stable security invoker set search_path = public as $fn$ select to_jsonb(p) || jsonb_build_object( 'text_rank', ts_rank_cd(p.search_vector, to_tsquery('english', p_query), 32), 'popularity_boost', least(log(greatest(p.sales_count, 1)::numeric + 1) * 0.3, 2.0)::double precision, 'review_boost', (case when coalesce(p.reviews_count, 0) > 0 then (coalesce(p.reviews_average, 0) / 5.0) * least(log((p.reviews_count + 1)::numeric) * 0.2, 1.0) else 0 end)::double precision, 'freshness_boost', (case when p.created_at > now() - interval '7 days' then 0.5 when p.created_at > now() - interval '30 days' then 0.3 when p.created_at > now() - interval '90 days' then 0.1 else 0 end)::double precision, 'completeness_boost', ((case when p.thumbnail_url is not null then 0.2 else 0 end) + (case when length(coalesce(p.description, '')) > 100 then 0.15 else 0 end) + (case when coalesce(array_length(p.gallery_urls, 1), 0) > 0 then 0.1 else 0 end))::double precision, 'creator_slug', c.slug, 'creator_name', c.display_name, 'creator_avatar', c.avatar_url ) from public.products p left join public.creators c on c.id = p.creator_id where p.status = 'published' and coalesce(p.type, '') <> 'physical' and p.search_vector @@ to_tsquery('english', p_query) and (p_category is null or p_category = '' or lower(p_category) = 'all' or lower(coalesce(p.category, '')) = lower(p_category)) order by case when coalesce(p_sort, 'relevance') = 'relevance' then (ts_rank_cd(p.search_vector, to_tsquery('english', p_query), 32) * 2.0)::double precision + least(log(greatest(p.sales_count, 1)::numeric + 1) * 0.3, 2.0)::double precision + (case when coalesce(p.reviews_count, 0) > 0 then (coalesce(p.reviews_average, 0) / 5.0) * least(log((p.reviews_count + 1)::numeric) * 0.2, 1.0) else 0 end)::double precision + (case when p.created_at > now() - interval '7 days' then 0.5 when p.created_at > now() - interval '30 days' then 0.3 when p.created_at > now() - interval '90 days' then 0.1 else 0 end)::double precision + (case when p.thumbnail_url is not null then 0.2 else 0 end)::double precision + (case when length(coalesce(p.description, '')) > 100 then 0.15 else 0 end)::double precision end desc nulls last, case when p_sort = 'newest' then p.created_at end desc nulls last, case when p_sort = 'popular' then p.sales_count end desc nulls last, case when p_sort = 'price-high' then p.price_cents end desc nulls last, case when p_sort = 'price-low' then p.price_cents end asc nulls last, p.id limit greatest(coalesce(p_limit, 30), 0) offset greatest(coalesce(p_offset, 0), 0) $fn$;
do $$ declare r text; begin execute 'revoke all on function public.search_products_ranked(text, text, text, integer, integer) from public'; foreach r in array array['anon', 'authenticated'] loop if exists (select 1 from pg_roles where rolname = r) then execute format('revoke all on function public.search_products_ranked(text, text, text, integer, integer) from %I', r); end if; end loop; if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.search_products_ranked(text, text, text, integer, integer) to service_role'; end if; end; $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('115', '115_integrations_admin_and_marketplace_search.sql', '4dfea02f4d7319acf5b67db776c10d2bbf6e9bb4c4b98245e4100571a02fb67c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 116_store_offers.sql
/* Upsells and bundles. `store_offers` is one offer a store makes: a `bundle` (two to five products bought together, shown on each one's page with Add all to cart) or a `checkout` offer (one product suggested in the checkout, when the cart holds any of its trigger products, or for any order when it names none). Its discount is a percent off (1 to 90), a fixed amount off in cents (per complete bundle, or off the one suggested item), or none; the checkout applies it on the server whenever the cart qualifies, each unit discounted once, before any code. Off when `active` is false. The owner reads their own; only the server writes. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('bundle', 'checkout')), title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 80), product_ids uuid[] NOT NULL, trigger_product_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], discount_type text NOT NULL DEFAULT 'percent' CHECK (discount_type IN ('percent', 'fixed', 'none')), discount_value integer NOT NULL DEFAULT 0 CHECK (discount_value >= 0), active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT store_offers_shape CHECK ((kind = 'bundle' AND cardinality(product_ids) BETWEEN 2 AND 5) OR (kind = 'checkout' AND cardinality(product_ids) = 1)), CONSTRAINT store_offers_triggers CHECK (cardinality(trigger_product_ids) <= 20), CONSTRAINT store_offers_percent CHECK (discount_type <> 'percent' OR discount_value BETWEEN 1 AND 90), CONSTRAINT store_offers_fixed CHECK (discount_type <> 'fixed' OR discount_value BETWEEN 1 AND 10000000));
CREATE INDEX IF NOT EXISTS store_offers_creator_idx ON public.store_offers (creator_id, active, kind, position);
CREATE INDEX IF NOT EXISTS store_offers_products_idx ON public.store_offers USING gin (product_ids);
ALTER TABLE public.store_offers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS store_offers_owner_read ON public.store_offers;
CREATE POLICY store_offers_owner_read ON public.store_offers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = store_offers.creator_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.store_offers FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('116', '116_store_offers.sql', 'c0369e5053de39625af3fd0e48094e373bea4b1042002d7775d5da934b445209') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 117_order_cases.sql
/* Buyers asking for help with an order, the way a marketplace handles it. `order_cases` is one buyer's case about one order: the store it is with, the order (a cart checkout that ships, `checkout_id`, or a digital purchase, `order_id`, and the number the buyer sees), the buyer's email and name as the order holds them, why they ask (not arrived, damaged, wrong item, missing item, return, refund, can't open what they bought, something else), whose turn it is (`store`, `buyer`, `storelib` once Storelib is asked to step in, then `resolved`), who asked Storelib in and when, and the hash of the private link the buyer reads it with. `order_case_messages` is the thread: the buyer, the store and Storelib, and Storelib's internal notes, which nobody else sees. A store reads its own cases and the messages on them that aren't notes; only the server writes. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.order_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, checkout_id uuid REFERENCES public.commerce_checkouts(id) ON DELETE SET NULL, order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL, order_ref text CHECK (order_ref IS NULL OR length(order_ref) <= 60), buyer_email text NOT NULL CHECK (length(buyer_email) BETWEEN 3 AND 254), buyer_name text CHECK (buyer_name IS NULL OR length(buyer_name) <= 120), reason text NOT NULL DEFAULT 'other' CHECK (reason IN ('not_arrived', 'damaged', 'wrong_item', 'missing_item', 'return', 'refund', 'access', 'other')), status text NOT NULL DEFAULT 'store' CHECK (status IN ('store', 'buyer', 'storelib', 'resolved')), escalated boolean NOT NULL DEFAULT false, escalated_by text CHECK (escalated_by IS NULL OR escalated_by IN ('buyer', 'store')), escalated_at timestamptz, access_hash text NOT NULL CHECK (length(access_hash) = 64), store_unread boolean NOT NULL DEFAULT true, buyer_unread boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_message_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolved_by text CHECK (resolved_by IS NULL OR resolved_by IN ('buyer', 'store', 'storelib')), CONSTRAINT order_cases_has_order CHECK (checkout_id IS NOT NULL OR order_id IS NOT NULL));
CREATE INDEX IF NOT EXISTS order_cases_creator_idx ON public.order_cases (creator_id, last_message_at DESC);
CREATE INDEX IF NOT EXISTS order_cases_queue_idx ON public.order_cases (escalated, status, last_message_at DESC);
CREATE INDEX IF NOT EXISTS order_cases_checkout_idx ON public.order_cases (checkout_id) WHERE checkout_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS order_cases_order_idx ON public.order_cases (order_id) WHERE order_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.order_case_messages (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, case_id uuid NOT NULL REFERENCES public.order_cases(id) ON DELETE CASCADE, author text NOT NULL CHECK (author IN ('buyer', 'store', 'storelib')), internal boolean NOT NULL DEFAULT false, body text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT order_case_messages_note_is_storelib CHECK (NOT internal OR author = 'storelib'));
CREATE INDEX IF NOT EXISTS order_case_messages_case_idx ON public.order_case_messages (case_id, id);
ALTER TABLE public.order_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_case_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS order_cases_owner_read ON public.order_cases;
CREATE POLICY order_cases_owner_read ON public.order_cases FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = order_cases.creator_id AND c.user_id = auth.uid()));
DROP POLICY IF EXISTS order_case_messages_owner_read ON public.order_case_messages;
CREATE POLICY order_case_messages_owner_read ON public.order_case_messages FOR SELECT TO authenticated USING (NOT internal AND EXISTS (SELECT 1 FROM public.order_cases oc JOIN public.creators c ON c.id = oc.creator_id WHERE oc.id = order_case_messages.case_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.order_cases, public.order_case_messages FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('117', '117_order_cases.sql', 'db120e575d88556d374de1cfa919b9e92e3516997ecd7e11999523081c1ab73c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 118_store_identity.sql
/* What a store signs its receipts, order emails and buyer cases with. Two more columns on `store_settings` (part 109): `logo_url`, the picture at the top of every receipt and customer email (when empty, the website's logo, then the person's photo), and `contact_email`, where buyers' replies and questions go (when empty, the support email on the creator, then the owner's own). Safe to run again. */
ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS logo_url text;
ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS contact_email text;
ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_logo_url_check;
ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_logo_url_check CHECK (logo_url IS NULL OR length(logo_url) BETWEEN 1 AND 600);
ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_contact_email_check;
ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_contact_email_check CHECK (contact_email IS NULL OR (length(contact_email) BETWEEN 3 AND 254 AND position('@' in contact_email) > 1));
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('118', '118_store_identity.sql', '5e02ca469ad0fefa147e41149c14f5f9ea4975c6d29e7ed6c2e34c8634f77121') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 125_community_member_activity.sql
/* A member's activity board in a community, read in one call. A function `community_member_activity(community, member, first day, time zone)` that counts, per day in that time zone from the first day (at most 400 days back) to today, the member's published posts and comments and the likes they gave in that community, and their published posts and comments there all time, answered as one small JSON object; server only. And one index, `community_feed_comments_author_idx` (author, newest first), so a member's comments are found without reading every comment: building it holds new comments back for the moment it takes, a second or two on a large table. No rows change. Run after `81`. Until it runs, a member's profile shows their level, points, posts and when they joined, without the day grid. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_feed_comments') IS NULL THEN RAISE NOTICE 'member activity: there is no community_feed_comments table, run part 81 first.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS community_feed_comments_author_idx ON public.community_feed_comments (author_id, created_at DESC); END $do$;
CREATE OR REPLACE FUNCTION public.community_member_activity(p_community uuid, p_user uuid, p_from date, p_tz text DEFAULT 'UTC') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_from date; v_since timestamptz; v_days jsonb; v_posts bigint; v_comments bigint; BEGIN IF p_community IS NULL OR p_user IS NULL THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; v_from := greatest(coalesce(p_from, (now() AT TIME ZONE v_tz)::date - 364), (now() AT TIME ZONE v_tz)::date - 400); v_since := v_from::timestamp AT TIME ZONE v_tz; SELECT coalesce(jsonb_agg(jsonb_build_array(d.day, d.posts, d.comments, d.likes) ORDER BY d.day), '[]'::jsonb) INTO v_days FROM (SELECT a.day, sum(a.p)::integer AS posts, sum(a.c)::integer AS comments, sum(a.l)::integer AS likes FROM (SELECT (p.created_at AT TIME ZONE v_tz)::date AS day, 1 AS p, 0 AS c, 0 AS l FROM public.community_feed_posts p WHERE p.author_id = p_user AND p.created_at >= v_since AND p.community_id = p_community AND p.status = 'published' AND p.deleted_at IS NULL UNION ALL SELECT (c.created_at AT TIME ZONE v_tz)::date, 0, 1, 0 FROM public.community_feed_comments c WHERE c.author_id = p_user AND c.created_at >= v_since AND c.community_id = p_community AND c.status = 'published' AND c.deleted_at IS NULL UNION ALL SELECT (r.created_at AT TIME ZONE v_tz)::date, 0, 0, 1 FROM public.community_reactions r WHERE r.user_id = p_user AND r.created_at >= v_since AND r.community_id = p_community) a GROUP BY a.day) d; SELECT count(*) INTO v_posts FROM public.community_feed_posts p WHERE p.author_id = p_user AND p.community_id = p_community AND p.status = 'published' AND p.deleted_at IS NULL; SELECT count(*) INTO v_comments FROM public.community_feed_comments c WHERE c.author_id = p_user AND c.community_id = p_community AND c.status = 'published' AND c.deleted_at IS NULL; RETURN jsonb_build_object('tz', v_tz, 'from', v_from, 'days', v_days, 'posts', v_posts, 'comments', v_comments); END $f$;
REVOKE ALL ON FUNCTION public.community_member_activity(uuid, uuid, date, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_member_activity(uuid, uuid, date, text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('125', '125_community_member_activity.sql', 'f46217b711333c4cb4172790dcbff555d0750c6702c7777932c1b669b2b0c17d') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 126_perf_health.sql
/* Storelib's Performance and Health page (/admin/performance). perf_samples: raw measurements, sampled (one page load in five on storelib.com, one API request in five), at most a capped number of rows a day per source (perf_day_counts), deleted after 8 days. perf_daily: the daily rollup (count, 50th, 75th and 95th percentile and server errors per area, device, route and metric, plus published websites' own Web Vitals from site_web_vitals), kept 120 days. perf_scores: the official Health Index of each day and its sub scores. Functions: perf_ingest (the beacon and the API timings write through it, capped), perf_window (the live figures), perf_rollup_day (the nightly rollup, also the retention), perf_errors (JavaScript errors by message) and perf_slow_queries (pg_stat_statements, empty with a reason where the extension is not there). Every table and function is server only: no policy for visitors or signed in users, execute for service_role alone. Changes no existing row. Needs nothing else; reads site_web_vitals (part 06) only where it exists. Until it runs, the page says each figure has insufficient data and the beacon stops asking for ten minutes at a time. */
CREATE TABLE IF NOT EXISTS public.perf_samples (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, at timestamptz NOT NULL DEFAULT now(), source text NOT NULL CHECK (source IN ('client', 'server')), area text NOT NULL CHECK (area ~ '^[a-z]{2,12}$'), route text NOT NULL CHECK (route ~ '^/[a-z0-9:_/-]{0,95}$'), device text NOT NULL CHECK (device IN ('mobile', 'desktop')), metric text NOT NULL CHECK (metric IN ('lcp', 'inp', 'cls', 'fcp', 'ttfb', 'nav', 'view', 'js_error', 'api')), value real NOT NULL CHECK (value >= 0 AND value <= 600000), status smallint CHECK (status IS NULL OR status BETWEEN 0 AND 999), detail text CHECK (detail IS NULL OR length(detail) <= 200));
CREATE INDEX IF NOT EXISTS perf_samples_at_idx ON public.perf_samples (at);
CREATE TABLE IF NOT EXISTS public.perf_day_counts (day date NOT NULL, source text NOT NULL CHECK (source IN ('client', 'server')), n integer NOT NULL DEFAULT 0, PRIMARY KEY (day, source));
CREATE TABLE IF NOT EXISTS public.perf_daily (day date NOT NULL, area text NOT NULL, device text NOT NULL, route text NOT NULL, metric text NOT NULL, samples integer NOT NULL, p50 real, p75 real, p95 real, bad integer NOT NULL DEFAULT 0, PRIMARY KEY (day, area, device, route, metric));
CREATE TABLE IF NOT EXISTS public.perf_scores (day date PRIMARY KEY, score smallint CHECK (score IS NULL OR score BETWEEN 0 AND 100), subs jsonb NOT NULL DEFAULT '[]'::jsonb, inputs jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.perf_samples ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.perf_samples FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.perf_samples TO service_role;
ALTER TABLE public.perf_day_counts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.perf_day_counts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.perf_day_counts TO service_role;
ALTER TABLE public.perf_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.perf_daily FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.perf_daily TO service_role;
ALTER TABLE public.perf_scores ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.perf_scores FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.perf_scores TO service_role;
CREATE OR REPLACE FUNCTION public.perf_ingest(p_source text, p_rows jsonb, p_cap integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_day date := (now() AT TIME ZONE 'utc')::date; v_k integer; v_n integer; BEGIN IF p_source IS NULL OR p_source NOT IN ('client', 'server') OR p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN RETURN 0; END IF; v_k := jsonb_array_length(p_rows); IF v_k = 0 OR v_k > 100 THEN RETURN 0; END IF; INSERT INTO public.perf_day_counts AS c (day, source, n) VALUES (v_day, p_source, v_k) ON CONFLICT (day, source) DO UPDATE SET n = c.n + excluded.n RETURNING c.n INTO v_n; IF v_n > greatest(coalesce(p_cap, 0), 0) THEN RETURN 0; END IF; INSERT INTO public.perf_samples (source, area, route, device, metric, value, status, detail) SELECT p_source, r.a, r.r, r.d, r.m, r.v, r.s, left(r.x, 200) FROM jsonb_to_recordset(p_rows) AS r(a text, r text, d text, m text, v real, s integer, x text) WHERE r.a ~ '^[a-z]{2,12}$' AND r.r ~ '^/[a-z0-9:_/-]{0,95}$' AND r.d IN ('mobile', 'desktop') AND r.m IN ('lcp', 'inp', 'cls', 'fcp', 'ttfb', 'nav', 'view', 'js_error', 'api') AND r.v >= 0 AND r.v <= 600000 AND (r.s IS NULL OR r.s BETWEEN 0 AND 999); GET DIAGNOSTICS v_k = ROW_COUNT; RETURN v_k; END $f$;
REVOKE ALL ON FUNCTION public.perf_ingest(text, jsonb, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_ingest(text, jsonb, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.perf_window(p_since timestamptz) RETURNS TABLE (area text, device text, route text, metric text, samples bigint, p50 real, p75 real, p95 real, bad bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ BEGIN RETURN QUERY SELECT coalesce(s.area, '*'), coalesce(s.device, '*'), coalesce(s.route, '*'), s.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY s.value), count(*) FILTER (WHERE s.status >= 500) FROM public.perf_samples s WHERE s.at >= p_since GROUP BY GROUPING SETS ((s.area, s.device, s.metric), (s.area, s.metric), (s.device, s.metric), (s.metric), (s.area, s.route, s.metric)); IF to_regclass('public.site_web_vitals') IS NOT NULL THEN RETURN QUERY EXECUTE 'SELECT ''sites''::text, coalesce(v.device, ''*''), ''*''::text, m.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY m.value), 0::bigint FROM public.site_web_vitals v CROSS JOIN LATERAL (VALUES (''lcp'', v.lcp_ms::real), (''inp'', v.inp_ms::real), (''cls'', v.cls::real)) m(metric, value) WHERE v.day >= $1 AND m.value IS NOT NULL GROUP BY GROUPING SETS ((v.device, m.metric), (m.metric))' USING (p_since AT TIME ZONE 'utc')::date; END IF; END $f$;
REVOKE ALL ON FUNCTION public.perf_window(timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_window(timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.perf_rollup_day(p_day date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_n integer := 0; v_m integer := 0; v_today date := (now() AT TIME ZONE 'utc')::date; BEGIN IF p_day IS NULL THEN RETURN 0; END IF; DELETE FROM public.perf_daily WHERE day = p_day; INSERT INTO public.perf_daily (day, area, device, route, metric, samples, p50, p75, p95, bad) SELECT p_day, coalesce(s.area, '*'), coalesce(s.device, '*'), coalesce(s.route, '*'), s.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY s.value), count(*) FILTER (WHERE s.status >= 500) FROM public.perf_samples s WHERE s.at >= (p_day::timestamp AT TIME ZONE 'utc') AND s.at < ((p_day + 1)::timestamp AT TIME ZONE 'utc') GROUP BY GROUPING SETS ((s.area, s.device, s.metric), (s.area, s.metric), (s.device, s.metric), (s.metric), (s.area, s.route, s.metric)); GET DIAGNOSTICS v_n = ROW_COUNT; IF to_regclass('public.site_web_vitals') IS NOT NULL THEN EXECUTE 'INSERT INTO public.perf_daily (day, area, device, route, metric, samples, p50, p75, p95, bad) SELECT $1, ''sites'', coalesce(v.device, ''*''), ''*'', m.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY m.value), 0 FROM public.site_web_vitals v CROSS JOIN LATERAL (VALUES (''lcp'', v.lcp_ms::real), (''inp'', v.inp_ms::real), (''cls'', v.cls::real)) m(metric, value) WHERE v.day = $1 AND m.value IS NOT NULL GROUP BY GROUPING SETS ((v.device, m.metric), (m.metric))' USING p_day; GET DIAGNOSTICS v_m = ROW_COUNT; END IF; DELETE FROM public.perf_samples WHERE at < now() - interval '8 days'; DELETE FROM public.perf_daily WHERE day < v_today - 120; DELETE FROM public.perf_day_counts WHERE day < v_today - 30; RETURN v_n + v_m; END $f$;
REVOKE ALL ON FUNCTION public.perf_rollup_day(date) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_rollup_day(date) TO service_role;
CREATE OR REPLACE FUNCTION public.perf_errors(p_since timestamptz, p_limit integer DEFAULT 30) RETURNS TABLE (detail text, area text, route text, n bigint, last_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT s.detail, s.area, s.route, count(*), max(s.at) FROM public.perf_samples s WHERE s.metric = 'js_error' AND s.at >= p_since AND s.detail IS NOT NULL GROUP BY s.detail, s.area, s.route ORDER BY count(*) DESC, max(s.at) DESC LIMIT greatest(1, least(coalesce(p_limit, 30), 100)) $f$;
REVOKE ALL ON FUNCTION public.perf_errors(timestamptz, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_errors(timestamptz, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.perf_slow_queries(p_limit integer DEFAULT 20, p_slow_ms double precision DEFAULT 200, p_min_calls integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_schema text; v_rows jsonb; v_slow bigint; BEGIN SELECT n.nspname INTO v_schema FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_stat_statements'; IF v_schema IS NULL THEN RETURN jsonb_build_object('available', false, 'reason', 'pg_stat_statements is not enabled'); END IF; EXECUTE format('SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (SELECT left(regexp_replace(s.query, ''\s+'', '' '', ''g''), 400) AS query, s.calls::bigint AS calls, round(s.mean_exec_time::numeric, 2) AS mean_ms, round(s.total_exec_time::numeric, 1) AS total_ms, s.rows::bigint AS rows FROM %I.pg_stat_statements s WHERE s.dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) AND s.calls > 0 AND s.query NOT ILIKE ''%%pg_stat_statements%%'' ORDER BY s.total_exec_time DESC LIMIT %s) t', v_schema, greatest(1, least(coalesce(p_limit, 20), 100))) INTO v_rows; EXECUTE format('SELECT count(*) FROM %I.pg_stat_statements s WHERE s.dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) AND s.calls >= %s AND s.mean_exec_time >= %s AND s.query NOT ILIKE ''%%pg_stat_statements%%''', v_schema, greatest(1, coalesce(p_min_calls, 50)), greatest(0, coalesce(p_slow_ms, 200))) INTO v_slow; RETURN jsonb_build_object('available', true, 'rows', v_rows, 'slow', v_slow); EXCEPTION WHEN others THEN RETURN jsonb_build_object('available', false, 'reason', left(SQLERRM, 200)); END $f$;
REVOKE ALL ON FUNCTION public.perf_slow_queries(integer, double precision, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_slow_queries(integer, double precision, integer) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('126', '126_perf_health.sql', '1d0ed8ad5f10b6509b14db32878baea26f532499e0c43e298fb612ae8f12d10b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 127_checkout_start_basket.sql
/* A started checkout remembers its whole cart. One more column on `checkout_starts` (part 13): `basket`, written by a website's own checkout (app/api/checkout/site) when the buyer presses Pay: the cart's lines (product, option, quantity, at most 50) and the website's address it was started on, so a checkout reminder can bring the buyer back to that same checkout with the same cart, not only to the first product. Server only, like the table. Until it runs, a website checkout still records its start with the first product (the reminder works as before), and only the cart is not kept. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.checkout_starts') IS NULL THEN RAISE NOTICE 'checkout basket: checkout_starts is not there yet (part 13).'; RETURN; END IF; ALTER TABLE public.checkout_starts ADD COLUMN IF NOT EXISTS basket jsonb; ALTER TABLE public.checkout_starts DROP CONSTRAINT IF EXISTS checkout_starts_basket_shape; ALTER TABLE public.checkout_starts ADD CONSTRAINT checkout_starts_basket_shape CHECK (basket IS NULL OR (jsonb_typeof(basket) = 'object' AND pg_column_size(basket) <= 16384)) NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('127', '127_checkout_start_basket.sql', '32b9a40e9f953a9b507f754c1f177d6cc411fcc8d5743314ef9bd5cc56039c17') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 128_plan_cancellations.sql
/* Why a creator cancelled Pro, run after the subscription billing tables (creators, subscriptions). A new server only table `plan_cancellations` keeps one row per cancellation made from Settings > Plan: the creator, the Stripe subscription, the plan it was, the reason chosen (one of a short list, or none) and an optional note of at most 500 characters, the day Pro ends, and when the cancellation was undone with Resume plan. Only the service role reads or writes it: no policy for visitors or signed in users. Changes no existing row. Until it runs, cancelling and resuming work as before and the reason is kept on the Stripe subscription only. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'plan cancellations: there is no creators table, run the billing parts first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.plan_cancellations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, stripe_subscription_id text, plan_id text, reason text, note text, ends_at timestamptz, resumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plan_cancellations_reason_check CHECK (reason IS NULL OR reason IN ('too_expensive', 'not_selling', 'missing_features', 'switching', 'taking_break', 'other')), CONSTRAINT plan_cancellations_note_check CHECK (note IS NULL OR char_length(note) <= 500)); CREATE INDEX IF NOT EXISTS plan_cancellations_creator_idx ON public.plan_cancellations (creator_id, created_at DESC); ALTER TABLE public.plan_cancellations ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.plan_cancellations FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.plan_cancellations TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('128', '128_plan_cancellations.sql', '55d887cf001c2b4b6802988ae1139825368cfb2c59bb6c86876473ab317d4238') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 129_customer_email_words_and_tax_on_receipts.sql
/* Customer emails a store words itself, tax on every receipt, and the way back for a cart left at checkout. `store_settings.customer_emails` (part 109's table): the subject, heading, opening text and button label a store changed in Settings › Customer emails, one small object per email, only what differs from the default; plain text, escaped when the email is drawn. `orders.tax_included`: whether the tax on an order (part 110's `tax_cents`) was part of the price or added on top, so the receipt says "Tax" or "Including tax" and its subtotal adds up; the website basket now records its tax too. `checkout_starts.return_path` (the checkout reminder's table): for a cart left at the physical checkout or the website basket, the path back to that checkout with the same items, for "Finish checkout". Until it runs, every email goes out with its default words (the editor says saving needs this part), receipts show tax as added on top, and a cart's reminder links to the product instead. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'customer emails: store_settings is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS customer_emails jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_customer_emails_check; ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_customer_emails_check CHECK (jsonb_typeof(customer_emails) = 'object' AND pg_column_size(customer_emails) < 65536); END $do$;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tax_included boolean NOT NULL DEFAULT false;
DO $do$ BEGIN IF to_regclass('public.checkout_starts') IS NULL THEN RAISE NOTICE 'checkout reminder: checkout_starts is not there yet (RUN_CHECKOUT_CONTACTS.sql).'; RETURN; END IF; ALTER TABLE public.checkout_starts ADD COLUMN IF NOT EXISTS return_path text; ALTER TABLE public.checkout_starts DROP CONSTRAINT IF EXISTS checkout_starts_return_path_check; ALTER TABLE public.checkout_starts ADD CONSTRAINT checkout_starts_return_path_check CHECK (return_path IS NULL OR (length(return_path) <= 1500 AND return_path ~ '^/checkout/(physical|cart)[?]')); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('129', '129_customer_email_words_and_tax_on_receipts.sql', 'aa1c1c717afd65e39400d26542f3a94f0d35fbe166a8ad1c8898c9547ce2c87b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 130_theme_publish_in_one_step.sql
/* Publishing a website in one step. A new server only function `publish_theme_install(install, creator, settings, settings_draft, pages)`, called by the builder's Publish (app/api/website-builder/themes/[installId]/publish): the settings, every page, every saved section file and the switch of which website is live are written in one transaction, so a publish that fails part way changes nothing, where before it could leave some pages new and some old until Publish was pressed again. It holds a lock per creator while it runs, so two publishes of the same store wait for each other. A draft saved while the publish was running is kept as the draft, never wiped. Only the service role can call it. Changes no existing row. Until it runs, Publish works as before, step by step. Needs the theme tables (RUN_CREATOR_PAGE_AND_SITES, RUN_THEME_FILE_DRAFTS, RUN_THEME_PUBLISHED_AT); without them it is not created. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL OR to_regclass('public.store_theme_pages') IS NULL OR to_regclass('public.store_theme_settings') IS NULL OR to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'publish in one step: the theme tables are not there yet.'; RETURN; END IF; ALTER TABLE public.store_theme_installs ADD COLUMN IF NOT EXISTS published_at timestamptz; ALTER TABLE public.store_theme_custom_files ADD COLUMN IF NOT EXISTS draft_content text; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.publish_theme_install(p_install uuid, p_creator uuid, p_settings jsonb, p_settings_draft jsonb, p_pages jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $body$ DECLARE v_page jsonb; v_files jsonb; v_was jsonb; BEGIN IF NOT EXISTS (SELECT 1 FROM public.store_theme_installs WHERE id = p_install AND creator_id = p_creator) THEN RAISE EXCEPTION 'publish: this website is not this creator''s' USING ERRCODE = 'P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('storelib-publish:' || p_creator::text, 0)); IF p_settings IS NOT NULL THEN UPDATE public.store_theme_settings SET settings = p_settings, draft_settings = CASE WHEN draft_settings IS NOT DISTINCT FROM p_settings_draft THEN NULL ELSE draft_settings END WHERE install_id = p_install; END IF; FOR v_page IN SELECT value FROM jsonb_array_elements(COALESCE(p_pages, '[]'::jsonb)) LOOP UPDATE public.store_theme_pages SET sections = v_page->'sections', draft_sections = CASE WHEN draft_sections IS NOT DISTINCT FROM v_page->'draft' THEN NULL ELSE draft_sections END WHERE id = (v_page->>'id')::uuid AND install_id = p_install; END LOOP; WITH moved AS (UPDATE public.store_theme_custom_files SET content = draft_content, draft_content = NULL WHERE install_id = p_install AND draft_content IS NOT NULL RETURNING path, content) SELECT COALESCE(jsonb_agg(jsonb_build_object('path', path, 'content', content)), '[]'::jsonb) INTO v_files FROM moved; WITH down AS (UPDATE public.store_theme_installs SET status = 'unpublished' WHERE creator_id = p_creator AND status = 'published' AND id <> p_install RETURNING id) SELECT COALESCE(jsonb_agg(id), '[]'::jsonb) INTO v_was FROM down; UPDATE public.store_theme_installs SET status = 'published', published_at = now() WHERE id = p_install; RETURN jsonb_build_object('was_live', v_was, 'files', v_files); END $body$$fn$; REVOKE ALL ON FUNCTION public.publish_theme_install(uuid, uuid, jsonb, jsonb, jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.publish_theme_install(uuid, uuid, jsonb, jsonb, jsonb) TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('130', '130_theme_publish_in_one_step.sql', '20561e14e27f6ea10622df2fa617fed5b86a973f9a4df016943b148ad0134ea8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 131_products_max_per_order.sql
/* Limit sales for things that ship: `products.max_per_order`, the most one order may take of a physical product (a limited drop sold "up to 2 per order"), set under Settings in the product editor. The product page's quantity stops at it and the checkout refuses a cart over it with the reason. A whole number from 1 to 999, or null for no limit; no rows change. Needs nothing else. Until it runs, the editor saves everything else and says a typed limit needs this part, and nothing is limited. Safe to run again. */
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS max_per_order integer;
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_max_per_order_check;
ALTER TABLE public.products ADD CONSTRAINT products_max_per_order_check CHECK (max_per_order IS NULL OR (max_per_order >= 1 AND max_per_order <= 999));
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('131', '131_products_max_per_order.sql', '6d2388941730e3490474a62561f5224313ced2db03639b34684edf4b2c055453') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 132_github_whole_theme_and_agent_keys.sql
/* GitHub sync of the whole theme, and agent connection keys that expire or only read: theme_github_links.sync_state (what GitHub and Storelib last agreed on, file by file, and what the last sync did, so the builder lists each file a push could not bring in with its fix), theme_agent_tokens.expires_at (a key stops working on that day) and theme_agent_tokens.scopes (read, or read and write: a read only key can look at the site and change nothing), and the server only table github_webhook_deliveries (each GitHub webhook delivery id for a day, so a redelivered or replayed push is ignored). Run after part 02. Until it runs, GitHub sync works without the per-file list and every key reads and writes and never expires. Changes no existing row. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.theme_github_links') IS NULL THEN RAISE NOTICE 'github sync state: theme_github_links is not there yet (part 02).'; RETURN; END IF; ALTER TABLE public.theme_github_links ADD COLUMN IF NOT EXISTS sync_state jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.theme_github_links DROP CONSTRAINT IF EXISTS theme_github_links_sync_state_check; ALTER TABLE public.theme_github_links ADD CONSTRAINT theme_github_links_sync_state_check CHECK (jsonb_typeof(sync_state) = 'object' AND pg_column_size(sync_state) < 2000000); END $do$;
DO $do$ BEGIN IF to_regclass('public.theme_agent_tokens') IS NULL THEN RAISE NOTICE 'agent keys: theme_agent_tokens is not there yet (part 02).'; RETURN; END IF; ALTER TABLE public.theme_agent_tokens ADD COLUMN IF NOT EXISTS expires_at timestamptz; ALTER TABLE public.theme_agent_tokens ADD COLUMN IF NOT EXISTS scopes text[] NOT NULL DEFAULT ARRAY['read','write']::text[]; ALTER TABLE public.theme_agent_tokens DROP CONSTRAINT IF EXISTS theme_agent_tokens_scopes_check; ALTER TABLE public.theme_agent_tokens ADD CONSTRAINT theme_agent_tokens_scopes_check CHECK (scopes <@ ARRAY['read','write']::text[] AND 'read' = ANY (scopes)); GRANT SELECT (expires_at, scopes) ON public.theme_agent_tokens TO authenticated; END $do$;
DO $do$ BEGIN CREATE TABLE IF NOT EXISTS public.github_webhook_deliveries (delivery_id text PRIMARY KEY CHECK (char_length(delivery_id) BETWEEN 8 AND 80), received_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS github_webhook_deliveries_received_idx ON public.github_webhook_deliveries (received_at); ALTER TABLE public.github_webhook_deliveries ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.github_webhook_deliveries FROM anon, authenticated; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('132', '132_github_whole_theme_and_agent_keys.sql', '9b2454b668c87a9ea1356281c8b91728258408d32f0899d332a5549fd6711e76') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 133_perf_collect_everywhere.sql
/* Storelib's Performance and Health page collects from everywhere (/admin/performance). Run after part 126. perf_samples takes three more kinds of row: a flow step's time (step: the website editor opening, its canvas painting, a save, the payment form ready, a payment started and confirmed), a flow step that failed (fail, with a short code, never a message) and a scheduled job's run (job, its time and status); the check on perf_samples.metric is made again with them, and perf_ingest takes them. Raw samples are kept 31 days instead of 8, so the page's 30 day window is worked out from real samples (perf_rollup_day, same function, only the retention changes; perf_daily still keeps 120 days). Server only, as part 126. Changes no existing row. Until it runs, the page and the beacons work as before: flow steps and job runs are refused by perf_ingest (the rest of each batch is kept), and the 30 day window reads the 8 days the database still holds. Safe to run again. */
ALTER TABLE public.perf_samples DROP CONSTRAINT IF EXISTS perf_samples_metric_check;
ALTER TABLE public.perf_samples ADD CONSTRAINT perf_samples_metric_check CHECK (metric IN ('lcp', 'inp', 'cls', 'fcp', 'ttfb', 'nav', 'view', 'js_error', 'step', 'fail', 'api', 'job'));
CREATE OR REPLACE FUNCTION public.perf_ingest(p_source text, p_rows jsonb, p_cap integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_day date := (now() AT TIME ZONE 'utc')::date; v_k integer; v_n integer; BEGIN IF p_source IS NULL OR p_source NOT IN ('client', 'server') OR p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN RETURN 0; END IF; v_k := jsonb_array_length(p_rows); IF v_k = 0 OR v_k > 100 THEN RETURN 0; END IF; INSERT INTO public.perf_day_counts AS c (day, source, n) VALUES (v_day, p_source, v_k) ON CONFLICT (day, source) DO UPDATE SET n = c.n + excluded.n RETURNING c.n INTO v_n; IF v_n > greatest(coalesce(p_cap, 0), 0) THEN RETURN 0; END IF; INSERT INTO public.perf_samples (source, area, route, device, metric, value, status, detail) SELECT p_source, r.a, r.r, r.d, r.m, r.v, r.s, left(r.x, 200) FROM jsonb_to_recordset(p_rows) AS r(a text, r text, d text, m text, v real, s integer, x text) WHERE r.a ~ '^[a-z]{2,12}$' AND r.r ~ '^/[a-z0-9:_/-]{0,95}$' AND r.d IN ('mobile', 'desktop') AND r.m IN ('lcp', 'inp', 'cls', 'fcp', 'ttfb', 'nav', 'view', 'js_error', 'step', 'fail', 'api', 'job') AND r.v >= 0 AND r.v <= 600000 AND (r.s IS NULL OR r.s BETWEEN 0 AND 999); GET DIAGNOSTICS v_k = ROW_COUNT; RETURN v_k; END $f$;
REVOKE ALL ON FUNCTION public.perf_ingest(text, jsonb, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_ingest(text, jsonb, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.perf_rollup_day(p_day date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_n integer := 0; v_m integer := 0; v_today date := (now() AT TIME ZONE 'utc')::date; BEGIN IF p_day IS NULL THEN RETURN 0; END IF; DELETE FROM public.perf_daily WHERE day = p_day; INSERT INTO public.perf_daily (day, area, device, route, metric, samples, p50, p75, p95, bad) SELECT p_day, coalesce(s.area, '*'), coalesce(s.device, '*'), coalesce(s.route, '*'), s.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY s.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY s.value), count(*) FILTER (WHERE s.status >= 500) FROM public.perf_samples s WHERE s.at >= (p_day::timestamp AT TIME ZONE 'utc') AND s.at < ((p_day + 1)::timestamp AT TIME ZONE 'utc') GROUP BY GROUPING SETS ((s.area, s.device, s.metric), (s.area, s.metric), (s.device, s.metric), (s.metric), (s.area, s.route, s.metric)); GET DIAGNOSTICS v_n = ROW_COUNT; IF to_regclass('public.site_web_vitals') IS NOT NULL THEN EXECUTE 'INSERT INTO public.perf_daily (day, area, device, route, metric, samples, p50, p75, p95, bad) SELECT $1, ''sites'', coalesce(v.device, ''*''), ''*'', m.metric, count(*), percentile_disc(0.5) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.75) WITHIN GROUP (ORDER BY m.value), percentile_disc(0.95) WITHIN GROUP (ORDER BY m.value), 0 FROM public.site_web_vitals v CROSS JOIN LATERAL (VALUES (''lcp'', v.lcp_ms::real), (''inp'', v.inp_ms::real), (''cls'', v.cls::real)) m(metric, value) WHERE v.day = $1 AND m.value IS NOT NULL GROUP BY GROUPING SETS ((v.device, m.metric), (m.metric))' USING p_day; GET DIAGNOSTICS v_m = ROW_COUNT; END IF; DELETE FROM public.perf_samples WHERE at < now() - interval '31 days'; DELETE FROM public.perf_daily WHERE day < v_today - 120; DELETE FROM public.perf_day_counts WHERE day < v_today - 30; RETURN v_n + v_m; END $f$;
REVOKE ALL ON FUNCTION public.perf_rollup_day(date) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.perf_rollup_day(date) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('133', '133_perf_collect_everywhere.sql', 'd0cb76a717c9b34c4df43f836bf81147699307c932c7fdb8f704a49546d56091') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 134_storelib_reviews.sql
/* Storelib Reviews, the reviews app in Settings › Integrations. Builds on the reviews table (part 52) rather than beside it, so the creator page, Explore, the product page and the website read one set of reviews. On `reviews`: a title, photos (a list of {path, url, status}, shown only while a photo's status is approved), featured, verified (true for a review tied to a purchase, false for one a visitor wrote or one imported), where it came from (`source`: storelib, website, request, site, import), who hid it (`hidden_by`: seller or report), when it was published, and a third status, `pending`, for a review waiting for the store to approve it; the public policy still shows published reviews only, so a pending one is never public. `site_status` (shown, pending, hidden) is the store's own say over its website only: a verified buyer's review keeps Storelib's status (published unless a report or Storelib hid it), so Explore, the product page and the ratings count it whatever the store does, and the store's approval or hide changes `site_status`, which only the website's review sections and its structured data read. A check keeps a verified review from ever being pending or hidden by the store. Only an unverified review (a visitor's, an imported one) is pending, hidden or deleted by the store itself. A visitor's review (source site) and an imported one have neither a buyer nor an order, so the buyer or order check allows those two. `store_settings.reviews`: the app's settings, one small object (on or off, auto publish and the lowest rating that publishes itself, photos, who may write, the review request email and its reminder, star colour, display options). `review_requests`: one row per order line Storelib asked for a review, with when it was due, sent and reminded, and the review it led to; the link in the email is signed from the row's id, so no token is stored. `review_authors`: the address and a hash of the network address a visitor's review was written from, kept away from the public reviews table. Both server only. The `review-photos` bucket: public pictures, 8 MB, written by the server only. `review_requests.last_sent_at`: when a link last went out, so a website form cannot have it sent again and again. `review_drafts`: a review typed into a website's form by somebody who has not bought the product, held until they open the link emailed to them and confirm it, then written as an unverified review; dropped after seven days. `review_uploads` and the private `review-uploads` bucket: a photo is uploaded there first and tied to the link or form it came from; a review claims it once, and only a photo of a review the website shows is moved to the public `review-photos` bucket (a photo the store removed goes back), so nothing waits in public; unclaimed uploads are swept after a day. `reviews.photos` is no longer readable by the public (column privileges: every other column is granted to anon and authenticated, photos is not); the website reads it with the server's key. The ratings trigger from part 52 now counts verified reviews only, so a visitor's or an imported review never moves a Storelib rating, and the ratings of products and creators that have one are counted again. Changes no review, except that a verified review an earlier run of this part left pending or hidden by the store is published again for Storelib and kept pending or hidden on the website. Needs part 52 and part 109. Until it runs, Settings › Integrations › Storelib Reviews says it needs this part, and reviews work as before. */
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS title text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS photos jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS featured boolean NOT NULL DEFAULT false;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS verified boolean NOT NULL DEFAULT true;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'storelib';
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS hidden_by text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS published_at timestamptz;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS site_status text NOT NULL DEFAULT 'shown';
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_status_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_status_check CHECK (status IN ('pending', 'published', 'hidden')) NOT VALID;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_buyer_or_order_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_buyer_or_order_check CHECK (buyer_id IS NOT NULL OR order_id IS NOT NULL OR source IN ('site', 'import')) NOT VALID;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_app_values_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_app_values_check CHECK (source IN ('storelib', 'website', 'request', 'site', 'import') AND (hidden_by IS NULL OR hidden_by IN ('seller', 'report', 'storelib')) AND char_length(coalesce(title, '')) <= 120 AND jsonb_typeof(photos) = 'array' AND jsonb_array_length(photos) <= 6 AND pg_column_size(photos) < 8192) NOT VALID;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_site_status_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_site_status_check CHECK (site_status IN ('shown', 'pending', 'hidden')) NOT VALID;
UPDATE public.reviews SET site_status = CASE WHEN status = 'pending' THEN 'pending' ELSE 'hidden' END, status = 'published', hidden_by = NULL, hidden_at = NULL, hidden_reason = NULL, published_at = coalesce(published_at, created_at) WHERE verified AND (status = 'pending' OR (status = 'hidden' AND hidden_by = 'seller'));
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_verified_kept_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_verified_kept_check CHECK (NOT verified OR (status <> 'pending' AND hidden_by IS DISTINCT FROM 'seller')) NOT VALID;
CREATE INDEX IF NOT EXISTS reviews_creator_status ON public.reviews (creator_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS reviews_creator_featured ON public.reviews (creator_id, created_at DESC) WHERE status = 'published' AND featured;
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'storelib reviews: store_settings is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS reviews jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_reviews_check; ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_reviews_check CHECK (jsonb_typeof(reviews) = 'object' AND pg_column_size(reviews) < 4096); CREATE INDEX IF NOT EXISTS store_settings_reviews_on ON public.store_settings (creator_id) WHERE reviews ->> 'enabled' = 'true'; END $do$;
CREATE TABLE IF NOT EXISTS public.review_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id uuid REFERENCES public.products(id) ON DELETE CASCADE, email text NOT NULL CHECK (length(email) BETWEEN 3 AND 254), first_name text CHECK (first_name IS NULL OR length(first_name) <= 80), origin text CHECK (origin IS NULL OR (length(origin) <= 200 AND origin ~ '^https://[a-z0-9.-]+$')), status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'sent', 'reminded', 'reviewed', 'skipped', 'failed')), due_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, reminded_at timestamptz, review_id uuid REFERENCES public.reviews(id) ON DELETE SET NULL, skip_reason text CHECK (skip_reason IS NULL OR length(skip_reason) <= 40), attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS review_requests_one_per_order ON public.review_requests (order_id);
CREATE INDEX IF NOT EXISTS review_requests_due ON public.review_requests (status, due_at) WHERE status IN ('scheduled', 'sent');
CREATE INDEX IF NOT EXISTS review_requests_creator ON public.review_requests (creator_id, created_at DESC);
ALTER TABLE public.review_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_requests FROM anon, authenticated;
GRANT ALL ON public.review_requests TO service_role;
ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS last_sent_at timestamptz;
CREATE TABLE IF NOT EXISTS public.review_authors (review_id uuid PRIMARY KEY REFERENCES public.reviews(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, product_id uuid, email text CHECK (email IS NULL OR length(email) BETWEEN 3 AND 254), ip_hash text CHECK (ip_hash IS NULL OR length(ip_hash) <= 80), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS review_authors_email ON public.review_authors (creator_id, email, product_id);
ALTER TABLE public.review_authors ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_authors FROM anon, authenticated;
GRANT ALL ON public.review_authors TO service_role;
CREATE TABLE IF NOT EXISTS public.review_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, email text NOT NULL CHECK (length(email) BETWEEN 3 AND 254), ip_hash text CHECK (ip_hash IS NULL OR length(ip_hash) <= 80), rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), title text CHECK (title IS NULL OR char_length(title) <= 120), content text NOT NULL CHECK (char_length(content) BETWEEN 1 AND 2000), reviewer_name text CHECK (reviewer_name IS NULL OR char_length(reviewer_name) <= 80), photos jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(photos) = 'array' AND jsonb_array_length(photos) <= 6), status text NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'confirmed', 'dropped')), review_id uuid REFERENCES public.reviews(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz);
CREATE INDEX IF NOT EXISTS review_drafts_waiting ON public.review_drafts (created_at) WHERE status = 'waiting';
CREATE INDEX IF NOT EXISTS review_drafts_email ON public.review_drafts (email, created_at DESC);
ALTER TABLE public.review_drafts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_drafts FROM anon, authenticated;
GRANT ALL ON public.review_drafts TO service_role;
CREATE TABLE IF NOT EXISTS public.review_uploads (path text PRIMARY KEY CHECK (length(path) <= 200), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, owner text NOT NULL CHECK (length(owner) <= 80), created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz);
CREATE INDEX IF NOT EXISTS review_uploads_unclaimed ON public.review_uploads (created_at) WHERE claimed_at IS NULL;
ALTER TABLE public.review_uploads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_uploads FROM anon, authenticated;
GRANT ALL ON public.review_uploads TO service_role;
DO $do$ DECLARE col record; BEGIN REVOKE SELECT ON public.reviews FROM anon, authenticated; FOR col IN SELECT a.attname FROM pg_attribute a WHERE a.attrelid = 'public.reviews'::regclass AND a.attnum > 0 AND NOT a.attisdropped ORDER BY a.attnum LOOP IF col.attname = 'photos' THEN EXECUTE format('REVOKE SELECT (%I) ON public.reviews FROM anon, authenticated', col.attname); ELSE EXECUTE format('GRANT SELECT (%I) ON public.reviews TO anon, authenticated', col.attname); END IF; END LOOP; END $do$;
CREATE OR REPLACE FUNCTION public.update_product_review_stats() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_old_product uuid; v_new_product uuid; v_old_creator uuid; v_new_creator uuid; v_id uuid; BEGIN IF TG_OP <> 'INSERT' THEN v_old_product := OLD.product_id; v_old_creator := OLD.creator_id; END IF; IF TG_OP <> 'DELETE' THEN v_new_product := NEW.product_id; v_new_creator := NEW.creator_id; END IF; FOREACH v_id IN ARRAY ARRAY[v_old_product, CASE WHEN v_new_product IS DISTINCT FROM v_old_product THEN v_new_product END] LOOP IF v_id IS NOT NULL THEN UPDATE public.products SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.product_id = v_id AND r.status = 'published' AND r.verified), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.product_id = v_id AND r.status = 'published' AND r.verified) WHERE id = v_id; END IF; END LOOP; FOREACH v_id IN ARRAY ARRAY[v_old_creator, CASE WHEN v_new_creator IS DISTINCT FROM v_old_creator THEN v_new_creator END] LOOP IF v_id IS NOT NULL THEN UPDATE public.creators SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.creator_id = v_id AND r.status = 'published' AND r.verified), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.creator_id = v_id AND r.status = 'published' AND r.verified) WHERE id = v_id; END IF; END LOOP; RETURN NULL; END $fn$;
UPDATE public.products p SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.product_id = p.id AND r.status = 'published' AND r.verified), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.product_id = p.id AND r.status = 'published' AND r.verified) WHERE p.id IN (SELECT product_id FROM public.reviews WHERE NOT verified);
UPDATE public.creators c SET reviews_count = (SELECT count(*) FROM public.reviews r WHERE r.creator_id = c.id AND r.status = 'published' AND r.verified), reviews_average = (SELECT coalesce(round(avg(r.rating), 1), 0) FROM public.reviews r WHERE r.creator_id = c.id AND r.status = 'published' AND r.verified) WHERE c.id IN (SELECT creator_id FROM public.reviews WHERE NOT verified);
