INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('134', '134_storelib_reviews.sql', 'eb9e12375cee76a8f92245172d2a83e3593ac83ecf54294fe6ba7e57ce4b83f3') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 135_store_team.sql
/* A store's team. A new server only table `store_team_members`: one row per person the owner invites to their store (Settings > Team), with the email it was sent to, the role (manager or staff), whether they have accepted (invited, then active once they open the link signed in with their own Storelib account, which sets user_id), who sent it and when, and the invite link's token kept only as its SHA-256 (the link itself is in the email and nowhere else). One row per email per store. Only the service role reads or writes it: no policy for visitors or signed in users, so a member can never list a team or change a role from the browser; every check goes through the server (lib/team). Changes no existing row. Until it runs, Settings > Team says the team is not set up yet and everything else works as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'store team: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.store_team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL, status text NOT NULL DEFAULT 'invited', token_hash text, invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, invited_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, accepted_at timestamptz, CONSTRAINT store_team_members_role_check CHECK (role IN ('manager', 'staff')), CONSTRAINT store_team_members_status_check CHECK (status IN ('invited', 'active')), CONSTRAINT store_team_members_email_check CHECK (email = lower(email) AND char_length(email) BETWEEN 3 AND 254 AND position('@' in email) > 1), CONSTRAINT store_team_members_active_user CHECK (status <> 'active' OR user_id IS NOT NULL), CONSTRAINT store_team_members_one_email UNIQUE (creator_id, email)); CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_token_idx ON public.store_team_members (token_hash) WHERE token_hash IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_one_user ON public.store_team_members (creator_id, user_id) WHERE user_id IS NOT NULL; CREATE INDEX IF NOT EXISTS store_team_members_user_idx ON public.store_team_members (user_id) WHERE user_id IS NOT NULL; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('135', '135_store_team.sql', '74bfd159b80d9db8a918ee388de5e53e007e102b24dce63135b4f5a1b3cb0883') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 136_markets_languages.sql
/* Markets and languages for a creator's own website (Settings > Markets and languages; lib/markets). Three new server only tables. `store_localization`: one row per store, the website's default language, its other languages (each published or not) and its markets (groups of countries, each with the currency prices are shown in, the language a visitor starts in, a price adjustment and rounding; one primary market, the store's home, in its own currency), checked whole by the app before it is saved. `site_translations`: one row per piece of text per language (a section's heading, a product's title, a menu label), keyed as lib/markets/translate.ts says, with the text, a fingerprint of the original it was written for (so a changed original shows as outdated and is never overwritten), draft or approved, and whether a person or the AI wrote it. `fx_rates`: the European Central Bank's daily reference rates, one row per day, read only when fresh. Only the service role reads or writes them: every read and write goes through the app's server, which checks the store's owner (or a team member whose role has the area). The creator page, Explore and their prices are not touched. Changes no existing row. Until it runs, Settings > Markets and languages says it is not set up yet and every website works as before, in one language. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'markets: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.store_localization (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, default_language text NOT NULL DEFAULT 'en', languages jsonb NOT NULL DEFAULT '[]'::jsonb, markets jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT store_localization_language_check CHECK (char_length(default_language) BETWEEN 2 AND 35), CONSTRAINT store_localization_languages_array CHECK (jsonb_typeof(languages) = 'array'), CONSTRAINT store_localization_markets_array CHECK (jsonb_typeof(markets) = 'array')); CREATE TABLE IF NOT EXISTS public.site_translations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, locale text NOT NULL, key text NOT NULL, value text NOT NULL, source_hash text NOT NULL, status text NOT NULL DEFAULT 'draft', source text NOT NULL DEFAULT 'manual', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT site_translations_locale_check CHECK (char_length(locale) BETWEEN 2 AND 35), CONSTRAINT site_translations_key_check CHECK (char_length(key) BETWEEN 3 AND 300), CONSTRAINT site_translations_value_check CHECK (char_length(value) <= 20000), CONSTRAINT site_translations_hash_check CHECK (source_hash ~ '^[0-9a-f]{8}$'), CONSTRAINT site_translations_status_check CHECK (status IN ('draft', 'approved')), CONSTRAINT site_translations_source_check CHECK (source IN ('manual', 'ai')), CONSTRAINT site_translations_one UNIQUE (creator_id, locale, key)); CREATE INDEX IF NOT EXISTS site_translations_store_locale ON public.site_translations (creator_id, locale); CREATE TABLE IF NOT EXISTS public.fx_rates (as_of date PRIMARY KEY, base text NOT NULL DEFAULT 'EUR', rates jsonb NOT NULL, source text NOT NULL DEFAULT 'ecb', fetched_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fx_rates_object CHECK (jsonb_typeof(rates) = 'object')); ALTER TABLE public.store_localization ENABLE ROW LEVEL SECURITY; ALTER TABLE public.site_translations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.fx_rates ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_localization FROM PUBLIC, anon, authenticated; REVOKE ALL ON public.site_translations FROM PUBLIC, anon, authenticated; REVOKE ALL ON public.fx_rates FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_localization TO service_role; GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_translations TO service_role; GRANT SELECT, INSERT, UPDATE, DELETE ON public.fx_rates TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('136', '136_markets_languages.sql', '2f619d5a3af1925e8298b157d068c8f2d5e5e7d7db9de14b24baed620ea4b34a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 150_products_sales_limit.sql
/* Limit sales for downloads: `products.sales_limit`, the most copies of a product that can ever be sold (a limited run of 100 sample packs), set under Settings in the product editor. 1 to 1,000,000, or null for no limit; no rows change. A checkout takes a place under the limit before anything is charged, in one statement that locks the product's row (`hold_product_sale`), so two buyers paying for the last copy cannot both pass; the place is given back when the payment will not happen (`release_product_sale`) and otherwise lapses after 35 minutes. Sold is counted from the orders themselves (`product_copies_sold`): paid ones, and partly refunded ones, whose buyer keeps the product; a fully refunded order gives its copy back. `product_sales_status` is what the editor and the shop read. Server only. Needs part 78 (orders.quantity). Until it runs, the editor saves everything else and says a typed limit needs this part, and nothing is limited. Safe to run again. */
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS sales_limit integer;
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_sales_limit_check;
ALTER TABLE public.products ADD CONSTRAINT products_sales_limit_check CHECK (sales_limit IS NULL OR (sales_limit >= 1 AND sales_limit <= 1000000));
CREATE TABLE IF NOT EXISTS public.product_sale_holds ( product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, holder text NOT NULL CHECK (char_length(holder) BETWEEN 1 AND 200), quantity integer NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 1000), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (product_id, holder) );
ALTER TABLE public.product_sale_holds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.product_sale_holds FROM PUBLIC;
REVOKE ALL ON TABLE public.product_sale_holds FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.product_sale_holds TO service_role;
/* Copies sold: paid orders, and orders refunded in part (the buyer keeps the product). An order refunded in full gives its copy back. A basket line of several copies counts each one. */
CREATE OR REPLACE FUNCTION public.product_copies_sold(p_product uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce(sum(greatest(1, coalesce(o.quantity, 1))), 0)::integer FROM public.orders o WHERE o.product_id = p_product AND (o.status = 'completed' OR (o.status = 'refunded' AND coalesce(o.refund_amount_cents, 0) > 0 AND o.refund_amount_cents < coalesce(o.amount_cents, 0))) $$;
/* Takes or refreshes a holder's place for p_quantity copies. The product's row is locked first (FOR NO KEY UPDATE, so orders can still be written beside it), so two calls for one product run one after the other and the second counts the first one's place. Expired places are cleared on the way. True when there is room (always, with no limit, and then nothing is held); false when there is none, or no such product. Called when a payment starts, and again when a paid payment becomes its order, so a place that lapsed in between is taken again only while there is room. */
CREATE OR REPLACE FUNCTION public.hold_product_sale(p_product uuid, p_holder text, p_quantity integer, p_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE lim integer; sold integer; others integer; q integer := greatest(1, least(coalesce(p_quantity, 1), 1000)); BEGIN IF p_holder IS NULL OR char_length(p_holder) NOT BETWEEN 1 AND 200 THEN RETURN false; END IF; SELECT p.sales_limit INTO lim FROM public.products p WHERE p.id = p_product FOR NO KEY UPDATE; IF NOT FOUND THEN RETURN false; END IF; DELETE FROM public.product_sale_holds h WHERE h.product_id = p_product AND h.expires_at < now(); IF lim IS NULL THEN RETURN true; END IF; sold := public.product_copies_sold(p_product); SELECT coalesce(sum(h.quantity), 0) INTO others FROM public.product_sale_holds h WHERE h.product_id = p_product AND h.holder <> p_holder; IF sold + others + q > lim THEN RETURN false; END IF; INSERT INTO public.product_sale_holds (product_id, holder, quantity, expires_at) VALUES (p_product, p_holder, q, now() + make_interval(secs => greatest(60, least(coalesce(p_seconds, 2100), 86400)))) ON CONFLICT (product_id, holder) DO UPDATE SET quantity = excluded.quantity, expires_at = excluded.expires_at; RETURN true; END $$;
/* A place given back: the payment it was for will not happen, or its order now counts the copy. */
CREATE OR REPLACE FUNCTION public.release_product_sale(p_product uuid, p_holder text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ DELETE FROM public.product_sale_holds WHERE product_id = p_product AND holder = p_holder $$;
/* What the editor and the shop show, for the products with a limit among those asked about: the limit, copies sold, and copies held by payments in progress. */
CREATE OR REPLACE FUNCTION public.product_sales_status(p_products uuid[]) RETURNS TABLE (product_id uuid, sales_limit integer, sold integer, held integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id, p.sales_limit, public.product_copies_sold(p.id), (SELECT coalesce(sum(h.quantity), 0)::integer FROM public.product_sale_holds h WHERE h.product_id = p.id AND h.expires_at >= now()) FROM public.products p WHERE p.id = ANY ((coalesce(p_products, '{}'::uuid[]))[1:500]) AND p.sales_limit IS NOT NULL $$;
/* Only the server counts, holds and gives back places. */
REVOKE ALL ON FUNCTION public.product_copies_sold(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.product_copies_sold(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.product_copies_sold(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) TO service_role;
REVOKE ALL ON FUNCTION public.release_product_sale(uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.release_product_sale(uuid, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_product_sale(uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.product_sales_status(uuid[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.product_sales_status(uuid[]) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.product_sales_status(uuid[]) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('150', '150_products_sales_limit.sql', '0ccb84e7c42b7e1e7e8abd3ac09bf139b1d9f233f1b406594962db46509eac18') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 153_store_business_and_tax_names.sql
/* A store's business on its receipts, and each tax named as it was charged. `store_settings.legal` (part 109's table): the business behind the store as Settings › Store details › Business details keeps it, its legal name, address and tax number (VAT number, EIN, ABN), which the receipt page, the order page and the invoice PDF print under "Sold by"; one small object, null until the store fills it in. `orders.tax_label`: what the tax on an order (part 110's `tax_cents`) was called when it was charged, "VAT 19%" or "Sales tax 8.25%", as Settings › Taxes names the region, so the receipt, the PDF and the creator's order say it in the same words; a physical order keeps the same words on its checkout's `shipping_rate`. No rows change. Needs part 109 for the first; skips it with a notice where store_settings is not there. Until it runs, receipts carry the store's name and contact alone, and the tax line reads "Tax". */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'store business: store_settings is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS legal jsonb; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_legal_check; ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_legal_check CHECK (legal IS NULL OR (jsonb_typeof(legal) = 'object' AND pg_column_size(legal) < 4096)); END $do$;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tax_label text;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_tax_label_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_tax_label_check CHECK (tax_label IS NULL OR length(tax_label) BETWEEN 1 AND 80) NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('153', '153_store_business_and_tax_names.sql', '5d22c6d35ab107846df5d617b477ea419082cdac4c83fcdd0fb7d5a24d7abcb4') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 154_local_delivery_and_pickup_hours.sql
/* Local delivery and pickup hours on a location (Settings > Locations): the seller brings orders to buyers whose postal code starts with one of the location's codes, in its country, for its price (free from its free over value, when the order reaches its minimum); and the opening hours buyers can collect in. New columns on inventory_locations only, every one with a default, so no row changes. Server only, as the table already is. Needs part 78. Until it runs, a location saves as before and says local delivery and pickup hours turn on after this part. Safe to run again. */
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS pickup_hours text;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_codes text[] NOT NULL DEFAULT '{}'::text[];
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_price_cents integer NOT NULL DEFAULT 0;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_min_cents integer;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_free_over_cents integer;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_note text;
ALTER TABLE public.inventory_locations DROP CONSTRAINT IF EXISTS inventory_locations_local_delivery_check;
ALTER TABLE public.inventory_locations ADD CONSTRAINT inventory_locations_local_delivery_check CHECK ((pickup_hours IS NULL OR char_length(pickup_hours) <= 300) AND cardinality(local_delivery_codes) <= 500 AND local_delivery_price_cents BETWEEN 0 AND 10000000 AND (local_delivery_min_cents IS NULL OR local_delivery_min_cents BETWEEN 0 AND 10000000) AND (local_delivery_free_over_cents IS NULL OR local_delivery_free_over_cents BETWEEN 0 AND 10000000) AND (local_delivery_note IS NULL OR char_length(local_delivery_note) <= 500)) NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('154', '154_local_delivery_and_pickup_hours.sql', '3d3eceb865c91ddbab84277fe420c41a9ba8a2c87b2a1389dddd0ef6204f8fc2') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 160_courier_tracking.sql
/* Courier tracking: Storelib follows every shipment with a tracking number through a tracking aggregator (AfterShip or 17TRACK), with Storelib's own account for every store or a store's own. New columns on fulfillments, every one with a default or empty, so no row changes: which aggregator and account follow it, the aggregator's id and the number it was registered with, the carrier's code, its state (info received, in transit, out for delivery, ready to collect, delivery attempted, problem, delivered, returned to sender, expired), the finer state, the estimated delivery, when it was read last and is read next, failures and the last error, when following stopped, and the seller's switch to pause it on one shipment. An index on the next look for open shipments only, so the ten minute job reads nothing else. `commerce_tracking_accounts` keeps a store's own AfterShip or 17TRACK key, sealed by the app before it is stored, one row per store, written and read by the server only. The carrier's scans go on fulfillment_events, which already keeps an external id once per shipment. Needs part 78. Until it runs, shipments keep the statuses the seller sets and the carrier's own link, and the job says tracking is not available yet. Safe to run again. */
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_provider text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_account text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_ref text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_ref_number text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_carrier_code text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_status text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_substatus text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS estimated_delivery_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_checked_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_next_check_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_last_event_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_failures integer NOT NULL DEFAULT 0;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_error text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_stopped_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_auto boolean NOT NULL DEFAULT true;
ALTER TABLE public.fulfillments DROP CONSTRAINT IF EXISTS fulfillments_tracking_check;
ALTER TABLE public.fulfillments ADD CONSTRAINT fulfillments_tracking_check CHECK ((tracking_provider IS NULL OR tracking_provider IN ('aftership', '17track')) AND (tracking_account IS NULL OR tracking_account IN ('platform', 'own')) AND (tracking_ref IS NULL OR char_length(tracking_ref) <= 200) AND (tracking_ref_number IS NULL OR char_length(tracking_ref_number) <= 120) AND (tracking_carrier_code IS NULL OR char_length(tracking_carrier_code) <= 60) AND (tracking_status IS NULL OR tracking_status IN ('pending', 'not_found', 'info_received', 'in_transit', 'out_for_delivery', 'available_for_pickup', 'attempt_failed', 'exception', 'delivered', 'returned', 'expired')) AND (tracking_substatus IS NULL OR char_length(tracking_substatus) <= 60) AND tracking_failures BETWEEN 0 AND 1000 AND (tracking_error IS NULL OR char_length(tracking_error) <= 300)) NOT VALID;
CREATE INDEX IF NOT EXISTS fulfillments_tracking_due_idx ON public.fulfillments (tracking_next_check_at NULLS FIRST) WHERE tracking_number IS NOT NULL AND tracking_stopped_at IS NULL AND status IN ('shipped', 'in_transit', 'out_for_delivery', 'failed');
CREATE INDEX IF NOT EXISTS fulfillments_tracking_number_idx ON public.fulfillments (tracking_number) WHERE tracking_number IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.commerce_tracking_accounts (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('aftership', '17track')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'error')), secret_ciphertext text NOT NULL CHECK (length(secret_ciphertext) <= 4096), webhook_secret_ciphertext text CHECK (webhook_secret_ciphertext IS NULL OR length(webhook_secret_ciphertext) <= 4096), last_error text CHECK (last_error IS NULL OR length(last_error) <= 300), verified_at timestamptz, last_webhook_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.commerce_tracking_accounts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.commerce_tracking_accounts FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.commerce_tracking_accounts TO service_role;
