-- part 161_physical_products_ship_by_default.sql
/* A physical product ships unless its seller turns "This product is shipped" off in the product editor: `products.requires_shipping` now defaults to true, as the editor, the shop and the checkout already read a product that never said. It was false since part 78, so a physical product whose row was written without the editor's shipping card (a save that stopped part way, an import, an agent) sold with no address, no shipping and no delivery at checkout. No rows change: a seller's own choice is kept. To see physical products that are not shipped, run: select id, title from public.products where type = 'physical' and requires_shipping = false; and turn "This product is shipped" on for the ones that should ship. Needs part 78. Safe to run again. */
ALTER TABLE public.products ALTER COLUMN requires_shipping SET DEFAULT true;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('161', '161_physical_products_ship_by_default.sql', '2473fb0a27083ca1d23173f7562c2547efa01f70279b20da742a1e042641fe2e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 162_physical_readiness_state.sql
/* What each store selling physical products last looked like to the readiness check (lib/physical/readiness-server.ts): whether something on sale had a gap that stops a checkout or a shipment, how many times it has gone from fine to that (each time is one notice and one reminder, never more), which gaps, and how many products were on sale. One row per store, written by the server only, so a store that breaks after it was ready is told once, and a store that stays broken is not told again. Needs part 40 for the notices. Until it runs the banners and Settings' checklist still show, and nothing is emailed from it. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.physical_readiness_state ( creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, broken boolean NOT NULL DEFAULT false, episode integer NOT NULL DEFAULT 0 CHECK (episode >= 0), signature text NOT NULL DEFAULT '' CHECK (char_length(signature) <= 300), live integer NOT NULL DEFAULT 0 CHECK (live >= 0), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.physical_readiness_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.physical_readiness_state FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('162', '162_physical_readiness_state.sql', '1289f783a1b9a5dea336a917e51864469fe87d9987ecf8718b23ab4520e647cd') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 163_shipping_labels_and_shipstation.sql
/* Shipping apps (Settings > Integrations: Shippo, EasyPost, ShipStation). A label bought from an order with Shippo or EasyPost is kept on that order: the provider's ids, the carrier and service, the tracking number, the label's https PDF, what it cost the seller (never charged to the buyer), test or live, and whether it was voided; one label per quoted provider shipment, so two presses of Buy never buy two. Server only, as the other order tables are. And the job queue takes any well formed job kind, so ShipStation's shipstation_push and shipstation_sync (and other new kinds) are let in: the old fixed list refused them. No rows change. Needs part 78. Until it runs, Buy a label says labels turn on after this part and nothing is bought; ShipStation orders are not sent. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.shipping_labels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE, fulfillment_id uuid REFERENCES public.fulfillments(id) ON DELETE SET NULL, provider text NOT NULL CHECK (provider IN ('shippo', 'easypost')), provider_shipment_id text NOT NULL CHECK (char_length(provider_shipment_id) BETWEEN 1 AND 120), provider_label_id text NOT NULL CHECK (char_length(provider_label_id) BETWEEN 1 AND 120), carrier text CHECK (carrier IS NULL OR char_length(carrier) <= 60), service text CHECK (service IS NULL OR char_length(service) <= 120), tracking_number text CHECK (tracking_number IS NULL OR char_length(tracking_number) <= 80), label_url text CHECK (label_url IS NULL OR (char_length(label_url) <= 2000 AND label_url LIKE 'https://%')), cost_cents integer NOT NULL DEFAULT 0 CHECK (cost_cents BETWEEN 0 AND 100000000), currency text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'), package jsonb CHECK (package IS NULL OR (jsonb_typeof(package) = 'object' AND pg_column_size(package) <= 1024)), test_mode boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'buying' CHECK (status IN ('buying', 'purchased', 'void_pending', 'voided', 'void_rejected')), voided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS shipping_labels_shipment_key ON public.shipping_labels (provider, provider_shipment_id);
CREATE INDEX IF NOT EXISTS shipping_labels_checkout_idx ON public.shipping_labels (checkout_id, created_at);
CREATE INDEX IF NOT EXISTS shipping_labels_creator_idx ON public.shipping_labels (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS shipping_labels_fulfillment_idx ON public.shipping_labels (fulfillment_id) WHERE fulfillment_id IS NOT NULL;
ALTER TABLE public.shipping_labels ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.shipping_labels FROM anon, authenticated;
GRANT ALL ON public.shipping_labels TO service_role;
ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check;
ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind ~ '^[a-z][a-z0-9_]{2,39}$') NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('163', '163_shipping_labels_and_shipstation.sql', '6f9ebfd4c2ce1edbf996aae5eec4959afb25af0de7db86d0f0a318349605d7fc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 164_buyer_contact_and_cart_attributes.sql
/* Buyers reach the shop, and a cart's attributes reach the order. On a case (part 117): three more topics a buyer can write about (a question, changing the address, cancelling) beside the ones there were, and photos with a message (`order_case_messages.photos`, at most four, each the path of a picture in the private `order-case-photos` bucket, never a public address; the server checks every picture and strips its location before it is kept, and shows it through a link that lasts an hour). On an order: `commerce_checkouts.cart_attributes`, what an imported Shopify theme's cart asked the buyer (a gift message, a delivery date) as Shopify's cart.attributes keep it, shown to the seller on the order and in the new order email. On a shipment: `fulfillments.delivery_unconfirmed_at`, set when a tracked parcel was never marked delivered 60 days after it shipped, so the seller follows it up; its index lets the daily pass find those quickly. No rows change; the topic check is rebuilt NOT VALID, so no stored row is read again. Server only, as these tables already are. Needs parts 78 and 117; skips what it needs with a notice where they did not run. Until it runs, a message on one of the new topics is filed under Something else with the topic in its first line, photos say they can't be kept yet, attributes are not kept, and the shipment pass writes the order timeline only. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.order_cases') IS NULL THEN RAISE NOTICE 'part 164: order_cases is missing (part 117), the topics are left.'; RETURN; END IF; ALTER TABLE public.order_cases DROP CONSTRAINT IF EXISTS order_cases_reason_check; ALTER TABLE public.order_cases ADD CONSTRAINT order_cases_reason_check CHECK (reason IN ('question', 'change_address', 'cancel', 'not_arrived', 'damaged', 'wrong_item', 'missing_item', 'return', 'refund', 'access', 'other')) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.order_case_messages') IS NULL THEN RAISE NOTICE 'part 164: order_case_messages is missing (part 117), photos are left.'; RETURN; END IF; ALTER TABLE public.order_case_messages ADD COLUMN IF NOT EXISTS photos jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.order_case_messages DROP CONSTRAINT IF EXISTS order_case_messages_photos_check; ALTER TABLE public.order_case_messages ADD CONSTRAINT order_case_messages_photos_check CHECK (jsonb_typeof(photos) = 'array' AND jsonb_array_length(photos) <= 4 AND pg_column_size(photos) <= 4096) NOT VALID; END $do$;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('order-case-photos', 'order-case-photos', false, 8388608, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif']) ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 8388608, allowed_mime_types = ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'part 164: commerce_checkouts is missing (part 78), cart attributes are left.'; RETURN; END IF; ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS cart_attributes jsonb; ALTER TABLE public.commerce_checkouts DROP CONSTRAINT IF EXISTS commerce_checkouts_cart_attributes_check; ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_cart_attributes_check CHECK (cart_attributes IS NULL OR (jsonb_typeof(cart_attributes) = 'object' AND pg_column_size(cart_attributes) <= 8192)) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.fulfillments') IS NULL THEN RAISE NOTICE 'part 164: fulfillments is missing (part 78), the unconfirmed mark is left.'; RETURN; END IF; ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS delivery_unconfirmed_at timestamptz; CREATE INDEX IF NOT EXISTS fulfillments_unconfirmed_scan_idx ON public.fulfillments (shipped_at) WHERE delivered_at IS NULL AND delivery_unconfirmed_at IS NULL AND status IN ('shipped', 'in_transit', 'out_for_delivery'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('164', '164_buyer_contact_and_cart_attributes.sql', '63b61f7aec70533a994c268b7e42e8a1947e4bc9a995cadbeb7f4b12620272cf') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 165_columns_production_has.sql
/* Columns production has that no file here ever created, so a database built from this repository matches it. They were made in the Supabase dashboard before the repository kept SQL, and the app has read and written them since: creators.support_email (Settings > Store details' contact email, where receipts and seller emails reply to), profiles.welcome_completed (signup and onboarding), the Address card's profiles.address_line1, address_line2, city, state, postal_code, country and the payout form's first_name, last_name, onepages.seller_id (whose store a OnePage subscribes to) and products.inventory_count (a counted product's stock, read by the shop's lists). Each is added only where it is missing, nullable, with no default except welcome_completed's false, so no existing row changes. onepages is skipped where that table is not there. Then the column grants part 63 keeps are applied again (storelib_share_public_columns), as they were when these columns already existed in production. Needs nothing else. Safe to run again. */
ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS support_email text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS welcome_completed boolean DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS first_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS last_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line1 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line2 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS city text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS state text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS postal_code text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS country text;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS inventory_count integer;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'onepages.seller_id skipped: public.onepages does not exist here'; RETURN; END IF; ALTER TABLE public.onepages ADD COLUMN IF NOT EXISTS seller_id uuid; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('165', '165_columns_production_has.sql', '44bbe4e6fbc321a6df1fe59acc3e0000ebba6b91c0316804e1fe386fb0121ef8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 166_marketing_sync.sql
/* Klaviyo and Omnisend connected (Settings > Integrations): a store's private key kept sealed in commerce_integrations (provider klaviyo or omnisend, category marketing), the marketing_sync job on the commerce job queue, and marketing_sync_items, the record of what was sent to each (a subscriber's state, an order event, an unsubscribe read back) so nothing goes twice and the integration card can count it. The three checks are rebuilt with every value they already allow plus the new ones, read from the database (as ARRAY['a'::text] or as '{a,b}'), so a part run before or after this one that added its own values keeps them; rebuilt NOT VALID, no row is read again. A check that is already a pattern (part 163 makes the jobs check one) lets every name in and is left as it is, so running this part again never turns it back into a list. No rows change. Server only. Needs part 78; without it the first three lines say so and change nothing. Until it runs, connecting says it needs this part and the onsite scripts work as before. Safe to run again. */
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_jobs') IS NULL THEN RAISE NOTICE 'commerce_jobs is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_jobs'::regclass AND conname = 'commerce_jobs_kind_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_jobs_kind_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_jobs'::regclass AND c.conname = 'commerce_jobs_kind_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['forward_fulfillment', 'supplier_email', 'webhook_delivery', 'tracking_sync', 'inventory_sync', 'send_email', 'marketing_sync']) AS x ORDER BY x); ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check; EXECUTE format('ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_provider_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_provider_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost', 'klaviyo', 'omnisend']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_provider_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_category_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_category_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_category_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['fulfillment', 'print_on_demand', 'dropshipping', 'supplier', 'shipping', 'marketing']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_category_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_category_check CHECK (category = ANY (%L::text[])) NOT VALID', v); END $do$;
CREATE TABLE IF NOT EXISTS public.marketing_sync_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('klaviyo', 'omnisend')), item_key text NOT NULL CHECK (char_length(item_key) BETWEEN 1 AND 200), state text NOT NULL CHECK (state IN ('subscribed', 'unsubscribed', 'customer', 'sent', 'line', 'pulled')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, provider, item_key));
CREATE INDEX IF NOT EXISTS marketing_sync_items_state_idx ON public.marketing_sync_items (creator_id, provider, state);
ALTER TABLE public.marketing_sync_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.marketing_sync_items FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.marketing_sync_items TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('166', '166_marketing_sync.sql', '26216965ff281ff80206377c69109afdc43aa5dd8c040f791a05bfe149e3c380') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 167_partner_variant_links.sql
/* Gelato and CJ Dropshipping matches (Settings > Integrations > Match products): which of the partner's own products each Storelib variant is, a CJ variant id or a Gelato product UID with its print file, so a paid order is sent with exactly that and never a guess; and, for CJ, whether the product's stock follows CJ's warehouses (the last number read, when, and why a read failed). One new table, server only (row level security on, no policy for anon or signed in users; the app reads and writes it with the service role). Needs part 78. Until it runs, Match products says it turns on after this part, CJ orders go only by a SKU CJ confirms, and Gelato orders are marked to send by hand. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.product_variants') IS NULL OR to_regclass('public.products') IS NULL THEN RAISE NOTICE 'partner variant links: products or product_variants is not there yet, run part 78 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.fulfilment_variant_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES public.product_variants(id) ON DELETE CASCADE, provider_variant_id text NOT NULL, provider_product_id text, provider_sku text, label text, file_url text, stock_sync boolean NOT NULL DEFAULT false, stock_level integer, stock_synced_at timestamptz, stock_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fulfilment_variant_links_once UNIQUE (creator_id, provider, variant_id), CONSTRAINT fulfilment_variant_links_provider_check CHECK (provider IN ('gelato', 'cj_dropshipping', 'printful', 'printify')), CONSTRAINT fulfilment_variant_links_shape CHECK (char_length(provider_variant_id) BETWEEN 1 AND 250 AND (provider_product_id IS NULL OR char_length(provider_product_id) <= 100) AND (provider_sku IS NULL OR char_length(provider_sku) <= 100) AND (label IS NULL OR char_length(label) <= 200) AND (file_url IS NULL OR (char_length(file_url) <= 1000 AND file_url LIKE 'https://%')) AND (stock_level IS NULL OR stock_level BETWEEN 0 AND 1000000000) AND (stock_error IS NULL OR char_length(stock_error) <= 300))); CREATE INDEX IF NOT EXISTS fulfilment_variant_links_product_idx ON public.fulfilment_variant_links (creator_id, provider, product_id); CREATE INDEX IF NOT EXISTS fulfilment_variant_links_stock_idx ON public.fulfilment_variant_links (creator_id, provider, provider_variant_id) WHERE stock_sync; ALTER TABLE public.fulfilment_variant_links ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.fulfilment_variant_links FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.fulfilment_variant_links TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('167', '167_partner_variant_links.sql', '66112769cbeba7a1f5656a8223d4b161f87b3d101ca9808ed3db7428c416e205') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 168_physical_products_ship_once.sql
/* Physical products saved while `products.requires_shipping` defaulted to false (parts 78 to 160) are turned back to shipped, once: a row the product editor's create wrote without the shipping card (the card not mounted, a save that stopped part way, an import, an agent) sold with no address, no delivery and no shipping at checkout, so the order could not be fulfilled. Part 161 changed only the default; this changes the rows, one time only (it does nothing once part 168 is in storelib_applied_parts), so a seller who turns "This product is shipped" off after it ran keeps that choice. Before it has run, those products keep selling with no address. To see what it changed, run: select id, title from public.products where type = 'physical' and requires_shipping = true and updated_at >= (select applied_at from public.storelib_applied_parts where part = '168'); Needs parts 67 and 78. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.storelib_applied_parts') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.storelib_applied_parts WHERE part = '168') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'requires_shipping') THEN UPDATE public.products SET requires_shipping = true, updated_at = now() WHERE type = 'physical' AND requires_shipping = false; END IF; END $do$;
ALTER TABLE public.products ALTER COLUMN requires_shipping SET DEFAULT true;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('168', '168_physical_products_ship_once.sql', '924f750b2d20b00ac189ee281689f155f7b2b3449cbae7844492db5a0cee673f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 173_visitor_language_and_ga_status.sql
/* Show visitors their own language, and whether Google Analytics is receiving data. `store_localization.visitor_language` (part 136's table): Settings › Markets and languages' switch "Show visitors their own language", false unless the store turns it on; with it on, a first visit to the website or the creator page opens in the published language the browser asks for, once, or offers the nearest one. `store_settings.tracking_seen` (part 109's table): for the store's Google Analytics measurement ID, when a visitor's page last saw Google take a hit with it and when the owner's Check in Settings › Integrations last did, so Settings says "Connected, receiving data" with the time; an object, small, nothing about any visitor. Server only, as both tables already are. No rows change. Each step skips itself with a notice where its table is not there (run 136 or 109 first). Until it runs, the switch says it needs this part and stays off, and Google Analytics shows the Check's answer without a last event time. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'visitor language: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS visitor_language boolean NOT NULL DEFAULT false; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'Google Analytics status: store_settings is not there yet, run part 109 first.'; ELSE ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS tracking_seen jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_settings_tracking_seen_small') THEN ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_tracking_seen_small CHECK (jsonb_typeof(tracking_seen) = 'object' AND pg_column_size(tracking_seen) < 4096) NOT VALID; END IF; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('173', '173_visitor_language_and_ga_status.sql', '9554d8d7c34885965cb4fd80ebf573145cb5ac467362bb311798d39d483d5951') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 174_cash_on_delivery.sql
/* Cash on delivery (Settings › Checkout, "Cash on delivery"): a physical order a buyer pays in cash when it is delivered or picked up. commerce_checkouts.provider takes 'cod' beside 'stripe' and 'free' (the column's check is found by what it checks, replaced, and allows every value already in the table too, so no row can fail it), and cod_collected_at is when the seller marked the cash received (null: still to collect). The switch itself is a key of the store's checkout settings, no column. No fee is taken and nothing goes on the payout ledger: the money never passes through Storelib. Safe to run again. */
DO $do$ DECLARE c record; allowed text; BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'cash on delivery: commerce_checkouts is not there yet, run the physical commerce parts first.'; RETURN; END IF; FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.commerce_checkouts'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ~ '\mprovider\M' LOOP EXECUTE format('ALTER TABLE public.commerce_checkouts DROP CONSTRAINT %I', c.conname); END LOOP; SELECT string_agg(quote_literal(v), ', ' ORDER BY v) INTO allowed FROM (SELECT unnest(ARRAY['stripe', 'free', 'cod']) AS v UNION SELECT DISTINCT provider FROM public.commerce_checkouts WHERE provider IS NOT NULL) s; EXECUTE format('ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_provider_check CHECK (provider IN (%s))', allowed); ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS cod_collected_at timestamptz; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('174', '174_cash_on_delivery.sql', '22ac0fb6bf82a00c8b217b62c7d472090d03f211ecdca7c96f5d9352aecc77f8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 175_automatic_translation.sql
/* Translate new text automatically. `store_localization.auto_translate` (part 136's table): Settings › Markets and languages' switch "Translate changes automatically", false unless the store turns it on; with it on, a job each hour (/api/cron/translations) has Storelib AI translate the website's text that is new or changed since it was last translated, into each of the store's languages, and puts it live. A translation the merchant wrote or edited is never replaced. `store_localization.auto_translate_run`: what the last run did (when, how many, how many are left, and a short reason when it could not), an object, small, so the switch can say it. Server only, as the table already is. No rows change. Skips itself with a notice where the table is not there (run 136 first). Until it runs, the switch says it needs this part and stays off. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'automatic translation: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate boolean NOT NULL DEFAULT false; ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate_run jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_localization_auto_translate_run_small') THEN ALTER TABLE public.store_localization ADD CONSTRAINT store_localization_auto_translate_run_small CHECK (jsonb_typeof(auto_translate_run) = 'object' AND pg_column_size(auto_translate_run) < 2048) NOT VALID; END IF; CREATE INDEX IF NOT EXISTS idx_store_localization_auto_translate ON public.store_localization (creator_id) WHERE auto_translate; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('175', '175_automatic_translation.sql', '0d05562cb7156cf271782f0ee76a6e79e699d2f75ba6072aa4b599073b60d978') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 176_store_currency.sql
/* A store's own selling currency (Settings › Store details › Country & Currency). `store_settings.currency`: the currency the store prices its catalog in and its website charges, as a three letter code; empty means the platform's currency, which is what every store sold in before, so nothing changes for a store until it chooses. Changing it goes through one function, `store_change_currency`, in one transaction: either the prices keep their numbers ("keep": 100 EUR becomes 100 USD) or every price the store owns is converted at the rate the merchant was shown ("convert"): products (price, compare-at, pay what you want minimum and suggestion), options (price, compare-at, the older added price), option costs, shipping rates (price, free over, the order value ranges and steps of a rate by order value), local delivery (price, minimum, free over), fixed coupons and their minimums, and the cash on delivery fee. Orders, refunds, invoices, payouts and the wallet keep the currency they were made in and are never touched. `store_currency_changes` records each change once per request key, so a second press or a retry returns the first result instead of converting twice. `store_currency_snapshots` keeps every converted value as it was, so `store_currency_restore` can put the prices back exactly (only the store's latest change, so a later one is never overwritten). All three are server only. Safe to run again. */
ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS currency text;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_settings_currency_code') THEN ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_currency_code CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.store_currency_changes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, from_currency text NOT NULL CHECK (from_currency ~ '^[A-Z]{3}$'), to_currency text NOT NULL CHECK (to_currency ~ '^[A-Z]{3}$'), previous_currency text CHECK (previous_currency IS NULL OR previous_currency ~ '^[A-Z]{3}$'), mode text NOT NULL CHECK (mode IN ('keep', 'convert')), rate numeric(24, 12) CHECK (rate IS NULL OR rate > 0), rate_as_of date, counts jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(counts) = 'object'), request_key text NOT NULL CHECK (length(request_key) BETWEEN 8 AND 120), created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), restored_at timestamptz, CONSTRAINT store_currency_changes_rate_when_converting CHECK (mode = 'keep' OR rate IS NOT NULL), CONSTRAINT store_currency_changes_once UNIQUE (creator_id, request_key) );
ALTER TABLE public.store_currency_changes ADD COLUMN IF NOT EXISTS previous_currency text;
CREATE INDEX IF NOT EXISTS store_currency_changes_creator_idx ON public.store_currency_changes (creator_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.store_currency_snapshots ( change_id uuid NOT NULL REFERENCES public.store_currency_changes(id) ON DELETE CASCADE, table_name text NOT NULL, row_id uuid NOT NULL, before jsonb NOT NULL CHECK (jsonb_typeof(before) = 'object'), PRIMARY KEY (change_id, table_name, row_id) );
ALTER TABLE public.store_currency_changes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_currency_snapshots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_currency_changes FROM anon, authenticated;
REVOKE ALL ON public.store_currency_snapshots FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.store_currency_targets() RETURNS TABLE (table_name text, key_column text, store_filter text, money_columns text[]) LANGUAGE sql IMMUTABLE AS $fn$ VALUES ('products', 'id', 'creator_id = $1', ARRAY['price_cents', 'compare_at_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents']), ('product_variants', 'id', 'product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = $1)', ARRAY['price_cents', 'compare_at_price_cents', 'additional_price_cents']), ('product_variant_costs', 'variant_id', 'creator_id = $1', ARRAY['cost_cents']), ('shipping_rates', 'id', 'creator_id = $1', ARRAY['price_cents', 'free_over_cents']), ('inventory_locations', 'id', 'creator_id = $1', ARRAY['local_delivery_price_cents', 'local_delivery_min_cents', 'local_delivery_free_over_cents']), ('coupons', 'id', 'creator_id = $1', ARRAY['min_purchase_cents']) $fn$;
CREATE OR REPLACE FUNCTION public.store_change_currency(p_creator uuid, p_from text, p_to text, p_mode text, p_rate numeric, p_rate_as_of date, p_key text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_prev public.store_currency_changes%ROWTYPE; v_stored text; v_change uuid := gen_random_uuid(); v_counts jsonb := '{}'::jsonb; v_target record; v_cols text[]; v_set text; v_snap text; v_n integer; BEGIN IF p_creator IS NULL THEN RAISE EXCEPTION 'store_currency: no store' USING ERRCODE = '22023'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from !~ '^[A-Z]{3}$' OR p_to !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'store_currency: a currency is not a code' USING ERRCODE = '22023'; END IF; IF p_from = p_to THEN RAISE EXCEPTION 'store_currency: the store already sells in %', p_to USING ERRCODE = '22023'; END IF; IF p_mode IS NULL OR p_mode NOT IN ('keep', 'convert') THEN RAISE EXCEPTION 'store_currency: mode is keep or convert' USING ERRCODE = '22023'; END IF; IF p_mode = 'convert' AND (p_rate IS NULL OR p_rate <= 0 OR p_rate > 1000000) THEN RAISE EXCEPTION 'store_currency: converting needs a rate' USING ERRCODE = '22023'; END IF; IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 120 THEN RAISE EXCEPTION 'store_currency: a request key is needed' USING ERRCODE = '22023'; END IF; INSERT INTO public.store_settings (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT currency INTO v_stored FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_prev FROM public.store_currency_changes WHERE creator_id = p_creator AND request_key = p_key; IF FOUND THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'id', v_prev.id, 'from', v_prev.from_currency, 'to', v_prev.to_currency, 'mode', v_prev.mode, 'rate', v_prev.rate, 'counts', v_prev.counts); END IF; IF coalesce(v_stored, p_from) <> p_from THEN RAISE EXCEPTION 'store_currency: the store now sells in %', v_stored USING ERRCODE = '40001'; END IF; INSERT INTO public.store_currency_changes (id, creator_id, from_currency, to_currency, previous_currency, mode, rate, rate_as_of, request_key, created_by) VALUES (v_change, p_creator, p_from, p_to, v_stored, p_mode, CASE WHEN p_mode = 'convert' THEN p_rate END, CASE WHEN p_mode = 'convert' THEN p_rate_as_of END, p_key, p_user); IF p_mode = 'convert' THEN FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(c ORDER BY c) INTO v_cols FROM unnest(v_target.money_columns) AS c WHERE EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = v_target.table_name AND ic.column_name = c); IF v_target.table_name = 'shipping_rates' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['min_value', 'max_value', 'tiers', 'kind']; ELSIF v_target.table_name = 'coupons' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; END IF; IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN CONTINUE; END IF; v_snap := format('INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT $2, %L, t.%I, jsonb_build_object(%s) FROM public.%I t WHERE %s', v_target.table_name, v_target.key_column, (SELECT string_agg(format('%L, t.%I', c, c), ', ') FROM unnest(v_cols) AS c), v_target.table_name, v_target.store_filter); EXECUTE v_snap USING p_creator, v_change; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_target.table_name = 'shipping_rates' THEN v_set := concat_ws(', ', CASE WHEN 'price_cents' = ANY (v_cols) THEN 'price_cents = round(price_cents * $2)::integer' END, CASE WHEN 'free_over_cents' = ANY (v_cols) THEN 'free_over_cents = CASE WHEN free_over_cents IS NULL THEN NULL ELSE round(free_over_cents * $2)::integer END' END, 'min_value = CASE WHEN kind = ''price'' AND min_value IS NOT NULL THEN round(min_value * $2)::integer ELSE min_value END', 'max_value = CASE WHEN kind = ''price'' AND max_value IS NOT NULL THEN round(max_value * $2)::integer ELSE max_value END', 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' THEN x || jsonb_strip_nulls(jsonb_build_object(''priceCents'', CASE WHEN x ? ''priceCents'' THEN round((x->>''priceCents'')::numeric * $2)::integer END, ''from'', CASE WHEN kind = ''price'' AND x ? ''from'' THEN round((x->>''from'')::numeric * $2)::integer END)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END'); ELSIF v_target.table_name = 'coupons' THEN v_set := concat_ws(', ', CASE WHEN 'min_purchase_cents' = ANY (v_cols) THEN 'min_purchase_cents = CASE WHEN min_purchase_cents IS NULL THEN NULL ELSE round(min_purchase_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(0.01, round(discount_value * $2, 2)) ELSE discount_value END'); ELSE SELECT string_agg(format('%1$I = CASE WHEN %1$I IS NULL THEN NULL ELSE round(%1$I * $2)::integer END', c), ', ') INTO v_set FROM unnest(v_cols) AS c; END IF; EXECUTE format('UPDATE public.%I SET %s WHERE %s', v_target.table_name, v_set, v_target.store_filter) USING p_creator, p_rate; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT v_change, 'store_settings', s.creator_id, jsonb_build_object('codFeeCents', s.checkout->'codFeeCents') FROM public.store_settings s WHERE s.creator_id = p_creator AND jsonb_typeof(s.checkout->'codFeeCents') = 'number'; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_n > 0 THEN UPDATE public.store_settings SET checkout = jsonb_set(checkout, '{codFeeCents}', to_jsonb(round((checkout->>'codFeeCents')::numeric * p_rate)::integer)) WHERE creator_id = p_creator; v_counts := v_counts || jsonb_build_object('cod_fee', 1); END IF; END IF; UPDATE public.store_settings SET currency = p_to, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET counts = v_counts WHERE id = v_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'id', v_change, 'from', p_from, 'to', p_to, 'mode', p_mode, 'rate', CASE WHEN p_mode = 'convert' THEN p_rate END, 'counts', v_counts); END $fn$;
CREATE OR REPLACE FUNCTION public.store_currency_restore(p_creator uuid, p_change uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_change public.store_currency_changes%ROWTYPE; v_latest uuid; v_target record; v_cols text[]; v_set text; v_counts jsonb := '{}'::jsonb; v_n integer; BEGIN PERFORM 1 FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_change FROM public.store_currency_changes WHERE id = p_change AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'store_currency: no such change' USING ERRCODE = '22023'; END IF; IF v_change.restored_at IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'currency', v_change.from_currency); END IF; SELECT id INTO v_latest FROM public.store_currency_changes WHERE creator_id = p_creator AND restored_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 1; IF v_latest IS DISTINCT FROM p_change THEN RAISE EXCEPTION 'store_currency: only the latest change can be undone' USING ERRCODE = '40001'; END IF; FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(DISTINCT k) INTO v_cols FROM public.store_currency_snapshots s, jsonb_object_keys(s.before) AS k WHERE s.change_id = p_change AND s.table_name = v_target.table_name AND k NOT IN ('kind', 'discount_type'); IF v_cols IS NULL THEN CONTINUE; END IF; SELECT string_agg( CASE c WHEN 'tiers' THEN 'tiers = s.before->''tiers''' WHEN 'discount_value' THEN 'discount_value = (s.before->>''discount_value'')::numeric' ELSE format('%1$I = (s.before->>%1$L)::integer', c) END, ', ') INTO v_set FROM unnest(v_cols) AS c; EXECUTE format('UPDATE public.%I t SET %s FROM public.store_currency_snapshots s WHERE s.change_id = $1 AND s.table_name = %L AND t.%I = s.row_id', v_target.table_name, v_set, v_target.table_name, v_target.key_column) USING p_change; GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; UPDATE public.store_settings t SET checkout = jsonb_set(t.checkout, '{codFeeCents}', s.before->'codFeeCents') FROM public.store_currency_snapshots s WHERE s.change_id = p_change AND s.table_name = 'store_settings' AND t.creator_id = s.row_id; UPDATE public.store_settings SET currency = v_change.previous_currency, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET restored_at = now() WHERE id = p_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'currency', v_change.from_currency, 'counts', v_counts); END $fn$;
REVOKE ALL ON FUNCTION public.store_currency_targets() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_currency_restore(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_currency_targets() TO service_role;
GRANT EXECUTE ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.store_currency_restore(uuid, uuid) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('176', '176_store_currency.sql', '5fb8d6d92a03988dde5a5d25abb4ba48386afbb000d9b854d8dd62645258a4ec') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 177_translation_jobs.sql
/* Translate with AI in the background. `store_translation_jobs`: one row per store and language while Storelib AI translates its website into it (Settings › Languages, the translation sheet), so the work goes on after the page is closed, a refresh shows where it is, and a second press joins the running job instead of starting another. `status` is running, done or failed; `done` and `total` are the language's texts that have a translation and all of them, for a progress bar that counts real work; `drafted` is what this job wrote; `lease_until` is how long the run that holds it may keep it, so a run cut off is picked up again by the next (/api/cron/translation-jobs) and never two at once. Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_translation_jobs ( creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, locale text NOT NULL CHECK (locale ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,4})?$'), status text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'failed')), done integer NOT NULL DEFAULT 0 CHECK (done >= 0), total integer NOT NULL DEFAULT 0 CHECK (total >= 0), drafted integer NOT NULL DEFAULT 0 CHECK (drafted >= 0), rounds integer NOT NULL DEFAULT 0 CHECK (rounds >= 0), error text CHECK (error IS NULL OR length(error) <= 500), started_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, PRIMARY KEY (creator_id, locale) );
CREATE INDEX IF NOT EXISTS store_translation_jobs_running_idx ON public.store_translation_jobs (lease_until) WHERE status = 'running';
ALTER TABLE public.store_translation_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_translation_jobs FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('177', '177_translation_jobs.sql', '18b0172c415ba12483c37e036aacc24d62831504f1716d509da7af07f36888ae') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 178_translation_memory.sql
/* Translation memory: every run of words an open translation model (LibreTranslate, or Hugging Face's opus-mt and NLLB) has translated, kept for good, so the same words are never sent twice: "Add to cart" into French is translated once for every store, a website translated again after a small edit sends only the new words, and a language translated after a failure picks up where it stopped. Keyed by the languages and the sha256 of the words; the words themselves are kept beside it for checking. Only website text that is already public goes in, never a customer's details. Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.translation_memory ( source_lang text NOT NULL CHECK (length(source_lang) BETWEEN 2 AND 12), target_lang text NOT NULL CHECK (length(target_lang) BETWEEN 2 AND 12), source_hash text NOT NULL CHECK (source_hash ~ '^[0-9a-f]{64}$'), source_text text NOT NULL CHECK (length(source_text) <= 20000), translated text NOT NULL CHECK (length(translated) <= 40000), provider text NOT NULL DEFAULT 'libretranslate' CHECK (provider IN ('gemini', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai')), created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (source_lang, target_lang, source_hash) );
ALTER TABLE public.translation_memory DROP CONSTRAINT IF EXISTS translation_memory_provider_check;
ALTER TABLE public.translation_memory ADD CONSTRAINT translation_memory_provider_check CHECK (provider IN ('gemini', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai'));
ALTER TABLE public.translation_memory ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.translation_memory FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('178', '178_translation_memory.sql', 'ed0097c2b24f1aba1a2479d6ec000d376159572fd3ffc7a9228d7d069bdd9e52') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 179_cache_invalidation_pings.sql
/* A store's caches are cleared when its products change in the database, whoever changed them: the product editor, the course builder and the OnePage's products tab write products straight from the browser, and a sale changes stock in a function, so no route was told and the website and Explore showed the old price or stock until their minute ran out. A trigger on products, product_variants, inventory_levels, product_collections and product_collection_items posts one small message per store, kind and product, per transaction, to Storelib's /api/internal/invalidate through pg_net, after the write commits; it never slows or stops the write, and does nothing until pg_net is enabled and the address and secret are set in the server only table storelib_cache_invalidation (one row: url, secret; the secret is the same value as the CACHE_INVALIDATE_SECRET environment variable on Vercel). Without pg_net the triggers are skipped with a notice; enable pg_net in Database > Extensions and run this part again. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.storelib_cache_invalidation (id boolean PRIMARY KEY DEFAULT true CHECK (id), url text CHECK (url IS NULL OR (url ~ '^https?://' AND length(url) <= 500)), secret text CHECK (secret IS NULL OR length(secret) BETWEEN 32 AND 200), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.storelib_cache_invalidation ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.storelib_cache_invalidation FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_cache_invalidation (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
CREATE OR REPLACE FUNCTION public.storelib_cache_ping() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE r jsonb; v_kind text := TG_ARGV[0]; v_creator uuid; v_product uuid; v_slug text; v_url text; v_secret text; v_key text; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RETURN NULL; END IF; SELECT c.url, c.secret INTO v_url, v_secret FROM public.storelib_cache_invalidation c WHERE c.id; IF coalesce(v_url, '') !~ '^https?://' OR coalesce(v_secret, '') = '' THEN RETURN NULL; END IF; BEGIN IF TG_OP = 'DELETE' THEN r := to_jsonb(OLD); ELSE r := to_jsonb(NEW); END IF; IF v_kind = 'product' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; v_product := nullif(r ->> 'id', '')::uuid; v_slug := r ->> 'slug'; ELSIF v_kind = 'variant' THEN v_product := nullif(r ->> 'product_id', '')::uuid; SELECT p.creator_id, p.slug INTO v_creator, v_slug FROM public.products p WHERE p.id = v_product; ELSIF v_kind = 'inventory' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; SELECT v.product_id, p.slug INTO v_product, v_slug FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = nullif(r ->> 'variant_id', '')::uuid; ELSIF v_kind = 'collection' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; IF v_creator IS NULL THEN SELECT c.creator_id INTO v_creator FROM public.product_collections c WHERE c.id = nullif(r ->> 'collection_id', '')::uuid; END IF; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; v_key := 'storelib_cache_ping.k' || md5(v_kind || ':' || v_creator::text || ':' || coalesce(v_product::text, '')); IF current_setting(v_key, true) = '1' THEN RETURN NULL; END IF; PERFORM set_config(v_key, '1', true); PERFORM net.http_post(url := v_url, body := jsonb_build_object('creatorId', v_creator, 'kind', v_kind, 'productId', v_product, 'slug', v_slug, 'op', TG_OP), params := '{}'::jsonb, headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret), timeout_milliseconds := 3000); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'storelib cache ping skipped: %', SQLERRM; END; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_cache_ping() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the products trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 179: products is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.products; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('product'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_variants trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_variants') IS NULL THEN RAISE NOTICE 'part 179: product_variants is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_variants; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('variant'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the inventory_levels trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.inventory_levels') IS NULL THEN RAISE NOTICE 'part 179: inventory_levels is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.inventory_levels; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.inventory_levels FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('inventory'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collections trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collections') IS NULL THEN RAISE NOTICE 'part 179: product_collections is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collections; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collections FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collection_items trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collection_items') IS NULL THEN RAISE NOTICE 'part 179: product_collection_items is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collection_items; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collection_items FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('179', '179_cache_invalidation_pings.sql', '6782ec428c895abef8920e6daf39916bf42010018170c2e29d8c0325a2e6dddc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 180_site_releases.sql
/* Every Publish kept as a release that never changes: `site_releases`, one row per publish of a website (its creator, its install, when, and a manifest of the live theme settings, every page's live sections and every live theme file by path with the sha256 of its text), `theme_file_blobs`, each file's text kept once by its sha256 however many releases and websites share it, and `site_live_releases`, which release a website is drawn from now. A trigger `site_live_release_forget` on `store_theme_custom_files`, `store_theme_settings` and `store_theme_pages` lets go of that pointer whenever a live file, setting or page changes any other way than a publish (a file deleted or renamed in the code editor, a live setting saved), so the website is then drawn from its rows exactly as before until the next Publish. Draft saves do not touch it. Server only: row level security on, nothing for visitors or signed in users. Changes no existing row. Needs the theme tables (RUN_CREATOR_PAGE_AND_SITES); without them it skips itself with a notice. Until it runs, Publish and the live website work exactly as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_file_blobs (sha256 text PRIMARY KEY CHECK (sha256 ~ '^[0-9a-f]{64}$'), content text NOT NULL, size integer NOT NULL DEFAULT 0 CHECK (size >= 0), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.theme_file_blobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.theme_file_blobs FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'part 180: store_theme_installs is missing, site_releases is skipped. Run the theme tables first, then this part again.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL, install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), manifest jsonb NOT NULL CHECK (jsonb_typeof(manifest) = 'object'), file_count integer NOT NULL DEFAULT 0 CHECK (file_count >= 0), total_bytes bigint NOT NULL DEFAULT 0 CHECK (total_bytes >= 0)); CREATE INDEX IF NOT EXISTS idx_site_releases_install_created ON public.site_releases (install_id, created_at DESC); ALTER TABLE public.site_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_releases FROM PUBLIC, anon, authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.site_releases') IS NULL THEN RAISE NOTICE 'part 180: site_releases is missing, site_live_releases is skipped.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_live_releases (install_id uuid PRIMARY KEY REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, creator_id uuid NOT NULL, release_id uuid REFERENCES public.site_releases(id) ON DELETE SET NULL, rev bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_site_live_releases_creator ON public.site_live_releases (creator_id); ALTER TABLE public.site_live_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_live_releases FROM PUBLIC, anon, authenticated; END $do$;
CREATE OR REPLACE FUNCTION public.site_live_release_forget() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$ DECLARE v_old uuid; v_new uuid; v_flag text; BEGIN IF to_regclass('public.site_live_releases') IS NULL THEN RETURN NULL; END IF; IF TG_OP <> 'INSERT' THEN v_old := OLD.install_id; END IF; IF TG_OP <> 'DELETE' THEN v_new := NEW.install_id; END IF; IF TG_ARGV[0] = 'file' THEN IF TG_OP = 'INSERT' AND coalesce(NEW.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'DELETE' AND coalesce(OLD.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'UPDATE' AND NEW.content IS NOT DISTINCT FROM OLD.content AND NEW.path IS NOT DISTINCT FROM OLD.path AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'settings' THEN IF TG_OP = 'UPDATE' AND NEW.settings IS NOT DISTINCT FROM OLD.settings AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'page' THEN IF TG_OP = 'UPDATE' AND NEW.sections IS NOT DISTINCT FROM OLD.sections AND NEW.page_key IS NOT DISTINCT FROM OLD.page_key AND v_old = v_new THEN RETURN NULL; END IF; END IF; IF v_old IS NULL OR v_new IS NULL OR v_old = v_new THEN v_flag := coalesce(current_setting('storelib.release_forgot', true), ''); IF position(coalesce(v_new, v_old)::text IN v_flag) > 0 THEN RETURN NULL; END IF; PERFORM set_config('storelib.release_forgot', v_flag || ',' || coalesce(v_new, v_old)::text, true); END IF; UPDATE public.site_live_releases SET release_id = NULL, rev = rev + 1, updated_at = now() WHERE install_id = v_old OR install_id = v_new; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.site_live_release_forget() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'part 180: store_theme_custom_files is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_custom_files; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF content, path, install_id ON public.store_theme_custom_files FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('file'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_settings') IS NULL THEN RAISE NOTICE 'part 180: store_theme_settings is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_settings; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF settings, install_id ON public.store_theme_settings FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('settings'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_pages') IS NULL THEN RAISE NOTICE 'part 180: store_theme_pages is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_pages; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF sections, page_key, install_id ON public.store_theme_pages FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('page'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('180', '180_site_releases.sql', '1bffcf1f0aff9d8c9f3edbd913ec0b4e3b928afcbd38f1264bf253dd085e1a76') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 184_community_analytics.sql
/* Community analytics, run after parts 81, 85, 87 and 102. What a community's Analytics in /app counts that nothing kept before. A visit to a community's page (one a visitor a day, part 87) now also keeps how the visitor arrived (a source such as Search, Instagram or Explore, and the site that sent them), the kind of device, the country, and whether they were already a member: four new columns on the server only table `community_view_days`, written by the new server only function `community_record_visit`, which counts the view exactly as `community_record_view` does. The nightly count adds each day's visitors and visitors who were not members to `community_daily_stats` (two new columns, empty until counted) and keeps the day's sources, sites, devices and countries as counts in the new server only table `community_daily_traffic`, so nothing about a visitor is kept past the three days part 87 keeps. A member who opens their community is written once a day to the new server only table `community_member_days` (the community, the member, the day), which is how active members are counted for a day, a week, a month or any period. The server only function `community_analytics` counts, per hour, day or month of the viewer's time zone, the joins, leaves, posts, comments, reactions, RSVPs, lessons completed, members who took part and members active, and for the period shown the top contributors, the busiest spaces, how many members who joined in each of the last six months are still in, and each program's progress. Two indexes, `community_feed_posts_community_created_idx` and `community_feed_comments_community_created_idx` (community, newest first), so those counts read only the period: building them holds new posts and comments back for a moment on a large community. No existing rows change. Until it runs, Analytics shows the figures the nightly count already keeps, without visits, sources, devices, countries, active members over time, top contributors, spaces, retention and program progress. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_view_days') IS NULL THEN RAISE NOTICE 'community analytics: there is no community_view_days table, run part 87 first.'; RETURN; END IF; ALTER TABLE public.community_view_days ADD COLUMN IF NOT EXISTS source text, ADD COLUMN IF NOT EXISTS referrer text, ADD COLUMN IF NOT EXISTS device text, ADD COLUMN IF NOT EXISTS country text, ADD COLUMN IF NOT EXISTS member boolean; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_view_days_facts_check') THEN ALTER TABLE public.community_view_days ADD CONSTRAINT community_view_days_facts_check CHECK ((source IS NULL OR char_length(source) BETWEEN 1 AND 40) AND (referrer IS NULL OR char_length(referrer) BETWEEN 1 AND 120) AND (device IS NULL OR device IN ('mobile', 'tablet', 'desktop')) AND (country IS NULL OR country ~ '^[A-Z]{2}$')); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_daily_stats') IS NULL THEN RAISE NOTICE 'community analytics: there is no community_daily_stats table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_daily_stats ADD COLUMN IF NOT EXISTS visitors integer, ADD COLUMN IF NOT EXISTS prospects integer; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_daily_stats_visitors_check') THEN ALTER TABLE public.community_daily_stats ADD CONSTRAINT community_daily_stats_visitors_check CHECK ((visitors IS NULL OR visitors >= 0) AND (prospects IS NULL OR prospects >= 0)); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_daily_traffic (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, day date NOT NULL, dimension text NOT NULL, key text NOT NULL, visitors integer NOT NULL DEFAULT 0, CONSTRAINT community_daily_traffic_pkey PRIMARY KEY (community_id, day, dimension, key), CONSTRAINT community_daily_traffic_dimension_check CHECK (dimension IN ('source', 'referrer', 'device', 'country')), CONSTRAINT community_daily_traffic_key_len CHECK (char_length(key) BETWEEN 1 AND 120), CONSTRAINT community_daily_traffic_visitors_check CHECK (visitors >= 0));
ALTER TABLE public.community_daily_traffic ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_daily_traffic FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_daily_traffic TO service_role;
CREATE TABLE IF NOT EXISTS public.community_member_days (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, day date NOT NULL, CONSTRAINT community_member_days_pkey PRIMARY KEY (community_id, day, user_id));
ALTER TABLE public.community_member_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_member_days FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.community_member_days TO service_role;
CREATE INDEX IF NOT EXISTS community_feed_posts_community_created_idx ON public.community_feed_posts (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_feed_comments_community_created_idx ON public.community_feed_comments (community_id, created_at DESC);
CREATE OR REPLACE FUNCTION public.community_record_visit(p_community uuid, p_visitor text, p_source text, p_referrer text, p_device text, p_country text, p_member boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_new integer; BEGIN IF p_community IS NULL OR p_visitor IS NULL OR char_length(p_visitor) NOT BETWEEN 16 AND 128 THEN RETURN false; END IF; INSERT INTO public.community_view_days (community_id, visitor_key, day, source, referrer, device, country, member) SELECT c.id, p_visitor, (now() AT TIME ZONE 'UTC')::date, CASE WHEN char_length(p_source) BETWEEN 1 AND 40 THEN p_source END, CASE WHEN char_length(p_referrer) BETWEEN 1 AND 120 THEN lower(p_referrer) END, CASE WHEN p_device IN ('mobile', 'tablet', 'desktop') THEN p_device END, CASE WHEN p_country ~ '^[A-Z]{2}$' THEN p_country END, p_member FROM public.communities c WHERE c.id = p_community ON CONFLICT (community_id, visitor_key, day) DO NOTHING; GET DIAGNOSTICS v_new = ROW_COUNT; IF v_new = 0 THEN RETURN false; END IF; UPDATE public.communities SET view_count = view_count + 1 WHERE id = p_community; RETURN true; END $f$;
REVOKE ALL ON FUNCTION public.community_record_visit(uuid, text, text, text, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_record_visit(uuid, text, text, text, text, text, boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.community_analytics(p_community uuid, p_from timestamptz, p_to timestamptz, p_tz text DEFAULT 'UTC', p_grain text DEFAULT 'day', p_detail boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_grain text := 'day'; v_fmt text; v_owner uuid; v_out jsonb; v_detail jsonb := '{}'::jsonb; v_end_month date; BEGIN IF p_community IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '800 days' THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; IF p_grain IN ('hour', 'day', 'month') THEN v_grain := p_grain; END IF; v_fmt := CASE v_grain WHEN 'hour' THEN 'YYYY-MM-DD"T"HH24' WHEN 'day' THEN 'YYYY-MM-DD' ELSE 'YYYY-MM' END; SELECT owner_user_id INTO v_owner FROM public.communities WHERE id = p_community; WITH act AS (SELECT kind, user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_activity WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND kind IN ('joined', 'left', 'post', 'comment', 'reaction', 'lesson_completed', 'course_completed')), posts AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_posts WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), comments AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_comments WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), reactions AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_reactions WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), rsvps AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_event_rsvps WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), days AS (SELECT user_id, CASE v_grain WHEN 'month' THEN to_char(day, 'YYYY-MM') ELSE to_char(day, 'YYYY-MM-DD') END AS b FROM public.community_member_days WHERE community_id = p_community AND day >= (p_from AT TIME ZONE v_tz)::date AND day <= ((p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date) SELECT jsonb_build_object('joined', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'joined' AND user_id IS DISTINCT FROM v_owner GROUP BY b) x), 'left', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'left' GROUP BY b) x), 'posts', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM posts GROUP BY b) x), 'comments', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM comments GROUP BY b) x), 'reactions', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM reactions GROUP BY b) x), 'rsvps', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM rsvps GROUP BY b) x), 'lessons', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'lesson_completed' GROUP BY b) x), 'contributors', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM act WHERE kind IN ('post', 'comment', 'reaction') AND user_id IS NOT NULL GROUP BY b) x), 'active', CASE WHEN v_grain = 'hour' THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM days GROUP BY b) x) END, 'totals', jsonb_build_object('contributors', (SELECT count(DISTINCT user_id) FROM act WHERE kind IN ('post', 'comment', 'reaction') AND user_id IS NOT NULL), 'posters', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'post' AND user_id IS NOT NULL), 'commenters', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'comment' AND user_id IS NOT NULL), 'reactors', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'reaction' AND user_id IS NOT NULL), 'active', (SELECT count(DISTINCT user_id) FROM days), 'courses', (SELECT count(*) FROM act WHERE kind = 'course_completed')), 'active_since', (SELECT min(day) FROM public.community_member_days WHERE community_id = p_community)) INTO v_out; IF p_detail THEN v_end_month := date_trunc('month', (p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date; v_detail := jsonb_build_object('top_contributors', (SELECT coalesce(jsonb_agg(x ORDER BY x.score DESC, x.user_id), '[]'::jsonb) FROM (SELECT u.user_id, sum(u.posts)::int AS posts, sum(u.comments)::int AS comments, sum(u.posts) * 2 + sum(u.comments) AS score FROM (SELECT author_id AS user_id, 1 AS posts, 0 AS comments FROM public.community_feed_posts WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to UNION ALL SELECT author_id, 0, 1 FROM public.community_feed_comments WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to) u GROUP BY u.user_id ORDER BY score DESC, u.user_id LIMIT 10) x), 'top_spaces', (SELECT coalesce(jsonb_agg(x ORDER BY (x.posts + x.comments) DESC, x.name), '[]'::jsonb) FROM (SELECT s.id, s.name, s.slug, (SELECT count(*) FROM public.community_feed_posts p WHERE p.space_id = s.id AND p.status = 'published' AND p.created_at >= p_from AND p.created_at < p_to)::int AS posts, (SELECT count(*) FROM public.community_feed_comments c JOIN public.community_feed_posts p ON p.id = c.post_id WHERE p.space_id = s.id AND c.status = 'published' AND c.created_at >= p_from AND c.created_at < p_to)::int AS comments FROM public.community_spaces s WHERE s.community_id = p_community AND s.archived_at IS NULL) x WHERE x.posts + x.comments > 0), 'cohorts', (SELECT coalesce(jsonb_agg(x ORDER BY x.month DESC), '[]'::jsonb) FROM (SELECT to_char(date_trunc('month', m.joined_at AT TIME ZONE v_tz), 'YYYY-MM') AS month, count(*)::int AS joined, count(*) FILTER (WHERE m.status = 'active')::int AS stayed, count(*) FILTER (WHERE m.status = 'active' AND greatest(m.last_seen_at, m.last_active_at) >= now() - interval '30 days')::int AS active FROM public.community_members m WHERE m.community_id = p_community AND m.role <> 'owner' AND m.joined_at IS NOT NULL AND m.joined_at AT TIME ZONE v_tz >= (v_end_month - interval '5 months') AND m.joined_at AT TIME ZONE v_tz < (v_end_month + interval '1 month') GROUP BY 1) x), 'programs', (SELECT coalesce(jsonb_agg(x ORDER BY x.started DESC, x.title), '[]'::jsonb) FROM (SELECT cc.id, coalesce(nullif(cc.title, ''), pr.title, 'Program') AS title, count(e.id)::int AS started, count(e.completed_at)::int AS completed, coalesce(round(avg(e.percent))::int, 0) AS percent, (SELECT count(*) FROM public.community_activity a WHERE a.community_id = p_community AND a.kind = 'lesson_completed' AND a.created_at >= p_from AND a.created_at < p_to AND a.target_id IN (cc.id::text, cc.product_id::text))::int AS lessons FROM public.community_courses cc LEFT JOIN public.products pr ON pr.id = cc.product_id LEFT JOIN public.courses co ON co.id = coalesce(cc.course_id, (SELECT c2.id FROM public.courses c2 WHERE c2.product_id = cc.product_id ORDER BY c2.created_at LIMIT 1)) LEFT JOIN public.course_enrollments e ON e.course_id = co.id AND EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = e.buyer_id AND m.status = 'active') WHERE cc.community_id = p_community AND coalesce(cc.status, 'published') = 'published' GROUP BY cc.id, cc.title, pr.title, cc.product_id LIMIT 20) x)); END IF; RETURN v_out || v_detail; END $f$;
REVOKE ALL ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('184', '184_community_analytics.sql', 'ffcb48cf432c715b31c848adf4ea22bf8bedd3ff1bb62ad1b643c87dd6131654') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 185_community_domains.sql
/* A connected domain can serve one community (round 31), run after part 22. Two new nullable columns on `custom_domains`, `target_type` ('community') and `target_id` (the community's id, so a renamed community keeps its domain), empty for every other domain; 'community' joins the allowed purposes; a check that a community domain names its community and is never primary, and that no other domain names anything; and one domain per community, held by a unique index. No existing row changes: all of them have empty targets and a purpose that was already allowed. Until it runs, Settings › Domains does not offer Community and the routes refuse it. Safe to run again. */
ALTER TABLE public.custom_domains ADD COLUMN IF NOT EXISTS target_type TEXT;
ALTER TABLE public.custom_domains ADD COLUMN IF NOT EXISTS target_id UUID;
ALTER TABLE public.custom_domains DROP CONSTRAINT IF EXISTS custom_domains_purpose_check;
ALTER TABLE public.custom_domains ADD CONSTRAINT custom_domains_purpose_check CHECK (purpose IN ('website', 'creator_page', 'community')) NOT VALID;
ALTER TABLE public.custom_domains DROP CONSTRAINT IF EXISTS custom_domains_target_check;
ALTER TABLE public.custom_domains ADD CONSTRAINT custom_domains_target_check CHECK ((purpose = 'community' AND target_type = 'community' AND target_id IS NOT NULL AND is_primary = false) OR (purpose <> 'community' AND target_type IS NULL AND target_id IS NULL)) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS custom_domains_one_per_target ON public.custom_domains (target_type, target_id) WHERE target_id IS NOT NULL;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('185', '185_community_domains.sql', 'cf8fc37d786bd7be59817e7b064c366971d71119b19ae548f46eb21328c50329') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 186_community_join_questions.sql
/* Questions before joining (round 32), run after part 81. A community's owner or admins write up to eight questions people answer when they join (a short answer, a paragraph, one choice, several choices or an email address, each required or not), kept in the new server only table `community_join_forms`, one row per community; what each person answered is kept in the new server only table `community_join_answers`, one row per community and person, with the words of each question as it was asked, so a question changed later does not change an answer already given. The join flow shows the questions, a request waits with its answers for an admin in Requests, and the answers can be downloaded. No existing row changes. Until it runs, joining asks nothing new and Settings shows that the questions need this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_join_forms (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, questions jsonb NOT NULL DEFAULT '[]'::jsonb, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_forms_pkey PRIMARY KEY (community_id), CONSTRAINT community_join_forms_questions_check CHECK (jsonb_typeof(questions) = 'array' AND jsonb_array_length(questions) <= 8 AND pg_column_size(questions) <= 32768));
ALTER TABLE public.community_join_forms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_forms FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_forms TO service_role;
CREATE TABLE IF NOT EXISTS public.community_join_answers (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, answers jsonb NOT NULL DEFAULT '[]'::jsonb, submitted_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_answers_pkey PRIMARY KEY (community_id, user_id), CONSTRAINT community_join_answers_check CHECK (jsonb_typeof(answers) = 'array' AND jsonb_array_length(answers) <= 8 AND pg_column_size(answers) <= 65536));
CREATE INDEX IF NOT EXISTS community_join_answers_submitted_idx ON public.community_join_answers (community_id, submitted_at DESC);
ALTER TABLE public.community_join_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_answers FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_answers TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('186', '186_community_join_questions.sql', '7090be8e994a23906b2beffd6652bcf66372812378d007614c9e0c2e16f0fab6') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 187_community_onboarding_checklist.sql
/* A new member's first steps (round 32), run after part 81. The welcome message needs member messages (part 83) and Chat on; without them it is not sent. A community's owner or admins choose a short list of first steps a new member sees on the feed (introduce yourself, add a line about yourself, read the rules, comment on a post, start a program, RSVP to an event, or a step of their own with a link), and a welcome message sent to each new member as a direct message from the person who runs it: both kept in the new server only table `community_onboarding`, one row per community. What each member has done is the new server only table `community_onboarding_progress`, one row per community, member and step, which also records that the welcome message was sent (once per member) and that the member hid the list. Steps a member does anyway (a post, a comment, a lesson, an RSVP) are read from `community_activity`, which gets an index by community, member and kind for it. No existing row changes. Until it runs, the feed shows the welcome alone, as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_onboarding (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, steps jsonb NOT NULL DEFAULT '[]'::jsonb, dm_enabled boolean NOT NULL DEFAULT false, dm_body text NOT NULL DEFAULT '', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_onboarding_pkey PRIMARY KEY (community_id), CONSTRAINT community_onboarding_steps_check CHECK (jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) <= 8 AND pg_column_size(steps) <= 16384), CONSTRAINT community_onboarding_dm_check CHECK (char_length(dm_body) <= 2000));
ALTER TABLE public.community_onboarding ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_onboarding FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_onboarding TO service_role;
CREATE TABLE IF NOT EXISTS public.community_onboarding_progress (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, step text NOT NULL, done_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_onboarding_progress_pkey PRIMARY KEY (community_id, user_id, step), CONSTRAINT community_onboarding_progress_step_check CHECK (step ~ '^[a-z0-9_]{1,40}$'));
ALTER TABLE public.community_onboarding_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_onboarding_progress FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_onboarding_progress TO service_role;
CREATE INDEX IF NOT EXISTS community_activity_member_kind_idx ON public.community_activity (community_id, user_id, kind);
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('187', '187_community_onboarding_checklist.sql', '19fe42e5fb23479e25f4d2b2a38c5eed4fc096f093f39612e4d6b4a39d83a7fa') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 188_community_scheduled_posts.sql
/* Scheduled posts and drafts (round 32), run after part 81. The people who run a community write a post now and choose when it goes up, or keep it as a draft: the new server only table `community_scheduled_posts`, one row per post waiting, with its space, title and words, when it goes up, and what happened (draft, scheduled, publishing, published with the post it became, or failed with the reason). Every five minutes the community job run publishes what is due through the ordinary post path, as its author, so members hear about it exactly as if it had been posted then; a row is taken by one run only (its status changes from scheduled to publishing in one update), and one that stopped part way is marked failed rather than posted twice. Two indexes: what is due, and a community's list. No existing row changes. Until it runs, Feed shows that scheduling needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_scheduled_posts (id uuid NOT NULL DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft', publish_at timestamptz, post_id uuid REFERENCES public.community_feed_posts(id) ON DELETE SET NULL, error text, attempts integer NOT NULL DEFAULT 0, claimed_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_scheduled_posts_pkey PRIMARY KEY (id), CONSTRAINT community_scheduled_posts_status_check CHECK (status IN ('draft', 'scheduled', 'publishing', 'published', 'failed')), CONSTRAINT community_scheduled_posts_when_check CHECK (status <> 'scheduled' OR publish_at IS NOT NULL), CONSTRAINT community_scheduled_posts_length_check CHECK (char_length(title) <= 200 AND char_length(body) <= 20000 AND (error IS NULL OR char_length(error) <= 500) AND attempts >= 0));
CREATE INDEX IF NOT EXISTS community_scheduled_posts_due_idx ON public.community_scheduled_posts (publish_at) WHERE status = 'scheduled';
CREATE INDEX IF NOT EXISTS community_scheduled_posts_list_idx ON public.community_scheduled_posts (community_id, status, publish_at);
ALTER TABLE public.community_scheduled_posts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_scheduled_posts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_scheduled_posts TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('188', '188_community_scheduled_posts.sql', '2e9c7de668bfb4a99aa3afe878ee06710cc3a8f1d2694bd6fd3c31d58b642c12') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

notify pgrst, 'reload schema';
select 'Storelib file 1 of 2 ran. Next file.' as done;
